[44482] = { ["id"] = 44482, ["name"] = "Recruiting Ebon Knights", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 726, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "Korgaz Deadaxe has been hard at work training a new generation of death knights. He has done an excellent job culling the ranks of weakness. Those who have survived the trials of death knight training are ready to join the ranks of the Ebon Blade. Korgaz is waiting for you on the upper level. I suggest you speak with him at your soonest convenience. New death knights will bolster our ranks and aid is in the war against the Burning Legion.", ["objectivesText"] = "Speak to Korgaz Deadaxe.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 11, ["flags"] = 1 } } },
[65118] = { ["id"] = 65118, ["name"] = "How to Glide with Your Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "Let us start with the basics. If you fly straight you will wear yourself out right now. Use gravity as an aid and aim slightly down to fly a long distance. The rings will give you the general angle that you should use for basic gliding. First, call upon your drake, or our Red Drake friend here can give you a lift. Then, fly through the rings and land at the target location. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Summon your skyriding mount, or mount the Red Drake . Then glide through the rings and land in the target area. Progress: Well done, 0xcp.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 188134, 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193287, ["x"] = 0.576, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 183141, ["x"] = 0.575, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1358, ["name"] = "Introduction to Dragonriding", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 15, ["flags"] = 0 } } },
[65120] = { ["id"] = 65120, ["name"] = "How to Dive with Your Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "Gliding will get you to where you want to go. But what if you want to get there faster? Diving after jumping from somewhere high will give you a speed boost. Fly through the rings to the target location. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Dive then glide through the rings and land in the target area. Progress: Well done, <name>.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193287, ["x"] = 0.576, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 183141, ["x"] = 0.575, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1358, ["name"] = "Introduction to Dragonriding", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 16, ["flags"] = 0 } } },
[65133] = { ["id"] = 65133, ["name"] = "How to Use Momentum with Your Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "Now what if there is an obstacle in your way? As long as you fly well, you can conserve your momentum and gain some height after a dive. When you dive this time you will find your flight path takes you below the landing area. By using your momentum you can regain lost height at the end of the course to still land in the target area. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Dive through the rings and land in the target area. Progress: Well done, <name>.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 188139, 188169, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193287, ["x"] = 0.576, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 183141, ["x"] = 0.575, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1358, ["name"] = "Introduction to Dragonriding", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 17, ["flags"] = 0 } } },
[65267] = { ["id"] = 65267, ["name"] = "Smash 'Em to Feathereens", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65267 }, ["description"] = "I was curious about these strange, winged creatures and attempted to introduce myself. I would have been eaten if not for Professor Chirpsnide and her large mechanical fowl! Could you help us deal with these \"Screechflight\"? The native bluefeather rocs are having a difficult time defending their nests from them. Also, I'd hate for any more introductions to go the way mine did with them...", ["objectivesText"] = "Kill 8 Screechflight Witherers and 10 Screechflight Hexclaws . Progress: The only thing I can thank these harpies for is giving me the chance to meet the professor!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 184591, ["x"] = 0.454667, ["y"] = 0.710667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 184591, ["x"] = 0.454667, ["y"] = 0.710667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.710667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[65279] = { ["id"] = 65279, ["name"] = "By Royal Decree", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65279 }, ["series"] = { 65302, 65306, 65594, 65595 }, ["description"] = "Idiot gnoll not understand crown. Only understand violence. Beat them up or I eat you.", ["objectivesText"] = "Kill 8 Brackenhide Warriors and 4 Brackenhide Shamans in Creektooth Den. Progress: GET WITH KILLING!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 188959, 189126, 189183 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.148667, ["y"] = 0.206667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65287] = { ["id"] = 65287, ["name"] = "Separating the Yolk", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65287 }, ["description"] = "I've deciphered the scroll and, surprise, it's bad news! The Screechflight aren't just eating the bluefeathers for sustenance. Turns out they've found a spell or two that transfers the rocs' innate strength to themselves upon consumption. Especially the eggs! Save as many of those roc eggs as you can down the cliffs from here. It'll stall the harpies long enough to put my plan into motion. And watch out for rogue elementals. The Cursewives' spell work has stirred them up!", ["objectivesText"] = "Collect 20 Bluefeather Eggs . Progress: Saving these eggs from the harpies is key to protecting these Bluefeathers from any further endangerment. As well as any future prey they plan on consuming next.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[65302] = { ["id"] = 65302, ["name"] = "Keys to the Kingdom", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65302 }, ["series"] = { 65279, 65306, 65594, 65595 }, ["description"] = "Need weapons for plan. Have good weapons, but locked up. Gnolls leave key in camp--protect weapon cache. Get pointiest sticks. They have most blood stains.", ["objectivesText"] = "Collect the key and use it to open the weapon cache. Progress: You bring weapons yet or you want me eat you?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 188959, 189126, 189183 }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.148667, ["y"] = 0.206667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65306] = { ["id"] = 65306, ["name"] = "Rot Rancher", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65306 }, ["series"] = { 65279, 65302, 65594, 65595 }, ["description"] = "Decay gross, smelly, and painful. Have idea but need ooze. GET OOZE!", ["objectivesText"] = "Collect 20 Smelly Ooze from the decaying rot. Progress: NEED MORE OOZE!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 188959, 189126, 189183 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.148667, ["y"] = 0.206667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65313] = { ["id"] = 65313, ["name"] = "A Roc-ing Appetite", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65313 }, ["description"] = "Segallia seems like a good egg, good with gadgets, but she panics easily. For example: When I sent her into the caves directly south of here, she was promptly run out of them by an unusually large harpy. Seems it was giving orders to the others as well. Could it be the matriarch of this brood? Perhaps a commander of some kind? Get in there and find out, <name>. And don't be afraid to ruffle a few feathers, if you know what I mean.", ["objectivesText"] = "Slay Hawthia Roc-Muncher .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[65371] = { ["id"] = 65371, ["name"] = "A Nest of Our Own", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65371 }, ["description"] = "The scroll you found is a command that all bluefeather eggs are to be brought to the harpy chef, Fry-Aerie. Apparently, the Screechflight's matriarch won't eat anything that hasn't been properly prepared and seasoned. So we'll bring her a special egg of our own. One that's EXPLOSIVELY delicious... and will explode when she eats it. Of course. How will you deliver it? In disguise! Slay the creatures on the lower cliffs, collect up this list of parts, and I'll whip you up a full-feathered outfit.", ["objectivesText"] = "Collect 20 Screechflight Talons , 6 Screechflight Staves, and 3 Creekborne Cores. Progress: Got everything I asked for yet?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[65373] = { ["id"] = 65373, ["name"] = "Plucking Parts", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65373 }, ["description"] = "Oh, no... I've made a huge mistake. Harleen entrusted me with the famed Feather-Plucker 3300, a phenomenal invention of her very own! I was planning to pluck roc feathers in the cave south of here for her research, but the harpies ambushed me and it broke into pieces as I was running out. Please retrieve the parts! They're probably strewn about like shed scales on the cave floor. I can put it back together. Definitely. Well, probably.", ["objectivesText"] = "Retrieve the 4 Feather-Plucker 3300 parts. Progress: I was so desperate to prove myself!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 184591, ["x"] = 0.454667, ["y"] = 0.710667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 184591, ["x"] = 0.454667, ["y"] = 0.710667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.710667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[65374] = { ["id"] = 65374, ["name"] = "It's Plucking Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65374 }, ["description"] = "Harleen told me she's making a disguise for you! How exciting! But she'll need some feathers from the roc hatchlings to complete the outfit. Luckily, I've just finished fixing up the Feather-Plucker 3300 ! The Screechflight are capturing roc hatchlings on the lower cliffs to raise and breed for themselves. Use the Plucker to yank the hatchlings out of danger. It'll automatically pluck some of their feathers for you as well! Two birds with one Plucker? I should say so!", ["objectivesText"] = "Pluck 6 Hatchling Feathers . Progress: Professor Chirpsnide tells me that I've got a knack for gadgets! If I wasn't part of the Dracthyr military, do you think I could've worked in a Goblin city?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 184591, ["x"] = 0.454667, ["y"] = 0.710667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 184591, ["x"] = 0.454667, ["y"] = 0.710667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.710667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[65435] = { ["id"] = 65435, ["name"] = "The Dragon Isles Await", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 1, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 72256 }, ["series"] = { 65437 }, ["description"] = "Heroes of the Horde, I bring news. The Dragon Isles are awakening! The Isles went dormant in the wake of the Sundering. But now, at long last, they have called my kin and me home. While the Isles hold many wonders, it is also a perilous land. We will require the aid of our mortal allies to reclaim our legacy. I am about to present the Aspects' invitation to the Horde Council in Orgrimmar. Meet me there and we shall see what they have to say.", ["objectivesText"] = "Meet Ebyssian in Orgrimmar.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 205458 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.126 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 2761, 5967 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 0, ["flags"] = 0 } } },
[65436] = { ["id"] = 65436, ["name"] = "The Dragon Isles Await", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 70050, 72240 }, ["series"] = { 66577 }, ["description"] = "Wondrous news, my friend! The Dragon Isles are awakening! My people left our lands dormant in the wake of the Sundering. But now, at long last, we feel the call to home. While the Isles hold many wonders, there are perils as well. We will require the aid of our mortal allies in order to reclaim our legacy. Meet me in Stormwind. I must present the Aspects' invitation to the Alliance.", ["objectivesText"] = "Meet Wrathion in Stormwind.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 192493, 199109, 199211, 199337, 199686, 199836, 199837, 199838, 199839, 202188, 205456 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 189569, ["x"] = 0.618, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 189569, ["x"] = 0.618, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 2761, 5967 }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 4, ["flags"] = 0 } } },
[65439] = { ["id"] = 65439, ["name"] = "Whispers on the Winds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 72256 }, ["description"] = "Hello, $p. It's been a while, and I wish we had more time to catch up. But you see, I've just had a rather enlightening... no, make that foreboding... yes, a foreboding conversation with an old friend. Sometimes a revelation can be both, after all. I really must tell you of what I've learned.", ["objectivesText"] = "Speak with Archmage Khadgar outside Orgrimmar. Progress: Our journey begins with you.", ["rewardGold"] = 25270, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 3, ["flags"] = 0 } } },
[65444] = { ["id"] = 65444, ["name"] = "To the Dragon Isles!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 72256 }, ["series"] = { 69944, 70198 }, ["description"] = "Our preliminary expedition has made landfall in the Dragon Isles . Thanks to the efforts of those brave Dragonscale Expedition members, we've established a protected landing site in the Dragon Isles and made contact with the dragonflight's embassy. Are you prepared to accompany us on our next voyage to the Dragon Isles ?", ["objectivesText"] = "Ride the Defiant Dragonscale to the Dragon Isles from the zeppelin tower outside Orgrimmar.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 197010, 197144, 197358, 197360, 197363, 197369, 197374, 197386, 197395, 197402, 197614, 198863, 198865, 198866, 198867, 199472, 199473, 203353, 210469, 210501, 217109 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 197279, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 184841, ["x"] = 0.806, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1, 2022 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 11, ["flags"] = 0 } } },
[65451] = { ["id"] = 65451, ["name"] = "Practice Materials", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 69910, 69911, 69912, 69914, 69944, 70198, 72256, 72293 }, ["description"] = "These proto-drakes are unlike any I've seen before on Azeroth. Their scales appear to be naturally flame-resistant, stronger than steel, and don't lose flexibility in the process. Incredible. My artisans--all of them--are clamoring to get their hands on some of those scales to work with. Start with the whelps. The smaller scales should be more pliable until we've mastered our techniques with them.", ["objectivesText"] = "Collect 20 Primal Proto-Whelp Scales . Progress: Have you got the scales yet? The alchemists are getting antsy, and that always makes me nervous.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 189565 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184844, ["x"] = 0.806, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187236, ["x"] = 0.783, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.806, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 9, ["flags"] = 0 } } },
[65452] = { ["id"] = 65452, ["name"] = "Explorers in Peril", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 69910, 69911, 69912, 69914, 69944, 70198, 72256, 72293 }, ["description"] = "Don't mistake the expedition's scholarly pursuits as timidness, $p. We are not recluses studying books in far-off towers. We are adventurers, hunting down knowledge first-hand in every corner of Azeroth! That passion for adventure often leads us onto the path of perils and hazards, and a few expedition members have bitten off a little more than they could chew...", ["objectivesText"] = "Rescue 3 Dragonscale Expedition members in the Wild Coast. Progress: Are the expedition members safe?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 188213 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184841, ["x"] = 0.806, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 184841, ["x"] = 0.806, ["y"] = 0.276 }, { ["mapID"] = 2022, ["npcID"] = 184870, ["x"] = 0.766, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.806, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 7, ["flags"] = 0 } } },
[65453] = { ["id"] = 65453, ["name"] = "Primal Pests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 69910, 69911, 69912, 69914, 69944, 70198, 72256, 72293 }, ["description"] = "<Cindrethresh glances suspiciously at the proto-dragons lurking on the ridge behind her.> I'd swear that those proto-dragons edge closer to camp every time I turn my back... Those are not the dragons Ebyssian invited us here to meet. Proto-dragons are ruthless predators who cannot be reasoned with. We must be ruthless in return. Cull their numbers to keep their ambitions in check, or this expedition will be over before it begins.", ["objectivesText"] = "Kill 8 Primal Proto-drakes on the Wild Coast. Progress: Always keep an eye on the skies.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184859, ["x"] = 0.806, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187235, ["x"] = 0.784, ["y"] = 0.303 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.806, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 8, ["flags"] = 0 } } },
[65475] = { ["id"] = 65475, ["name"] = "Rolling in the Screech", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65475 }, ["description"] = "<You pull a scrap of parchment from the gooey, blood-soaked satchel of the Roc-Muncher. All you can make out is imagery of harpies devouring large eggs. You're positive the thick, unintelligible scratch marks will make plenty of sense to your favorite senior ornithologist, Harleen Chirpsnide .>", ["objectivesText"] = "Bring the Screechflight Scroll to Harleen Chirpsnide in the Bluefeather Cliffs. Progress: Back from the caves already?", ["rewardGold"] = 29325, ["rewardXP"] = 2735, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 189361 } },
[65486] = { ["id"] = 65486, ["name"] = "Picture Perfect", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65486 }, ["series"] = { 69855, 69869, 69870, 72525 }, ["description"] = "Sorry if ya be waitin' long. Sometimes I get lost in de telescope. Do ya ever find da world be easier understood from a distance? No interference, just nature goin' about its business without us... < Akunda the Cataloger sighs.> I see Coralie gave ya a camera. Good. Take a ride down the river with Fren, and take photographs of some wildlife in dey natural habitats for me to study.", ["objectivesText"] = "Ride the Cataloger's Raft with Fren and take pictures of local wildlife. Progress: Fren will row the raft for ya. Don't worry, she's da very best!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185651, ["x"] = 0.498, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185651, ["x"] = 0.498, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[65490] = { ["id"] = 65490, ["name"] = "Explosive Excrement", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65490 }, ["objectivesText"] = "Fill Professor Chirpsnide's Auto-Excre-Collector.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[65594] = { ["id"] = 65594, ["name"] = "Making a Mountain Out of a Gnoll Hill", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65594 }, ["series"] = { 65279, 65302, 65306, 65595 }, ["description"] = "Stupid decay thinks it in charge, but me in charge. We kill it now. Me turned ooze into friends.", ["objectivesText"] = "Destroy 3 Decay Totems. Progress: IT'S SO BOUNCY!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 188959, 189126, 189183 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.148667, ["y"] = 0.206667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65595] = { ["id"] = 65595, ["name"] = "One Bad Apple", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65595 }, ["series"] = { 65279, 65302, 65306, 65594 }, ["description"] = "Rot starve gnolls. Rot hurt friends. We kill rot now. Is what Mon-Arks do.", ["objectivesText"] = "Kill the Root of Decay .", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 188959, 189126, 189183, 198090, 198671 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.148667, ["y"] = 0.206667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65686] = { ["id"] = 65686, ["name"] = "To the Azure Span", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "Greetings, <name>! Pakina and I are here on behalf of the Kirin Tor looking for aid. The Kirin Tor are working to safeguard the wild arcane magic located all throughout the Azure Span . Kalecgos, the Aspect of the blue dragonflight and one of our leaders, needs aid in reclaiming the Azure Oathstone there as well. If you're willing to help, keep traveling along the road to find Glania of the Blessed Ones . She can direct you to where you can help the most.", ["objectivesText"] = "Meet with Glania of the Blessed Ones within the Azure Span .", ["rewardGold"] = 5350, ["rewardXP"] = 515, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891, 197989 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185599, ["x"] = 0.716, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185603, ["x"] = 0.414, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 2023, 2024 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 0, ["flags"] = 0 } } },
[65687] = { ["id"] = 65687, ["name"] = "Punching Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65687 }, ["description"] = "Some of the other disciples are... very mean. < Ingot rubs a fresh wound on his snout.> It used to not be like that, but when Cygenoth came, he said \"We should value strength above all else\". Now everybody fights all the time. I try to fight back, but their hides are too thick... and I'm too small. But not you! You must fight bullies all the time. Maybe you can help?", ["objectivesText"] = "Slay 12 Worldbreaker Dragonkin . Progress: The Worldbreakers aren't all bullies. Promise!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 190612, 194368 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185627, ["x"] = 0.384, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185627, ["x"] = 0.384, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[65688] = { ["id"] = 65688, ["name"] = "Meeting Kalecgos", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "I fear we will have to split our attention. The Primalist threat to the east must be handled. I must ask you travel to the Azure Archives in my stead to aid Kalecgos in reclaiming the Azure Oathstone. You'll need to pick up a few supplies to help you with whatever is happening there. Speak with our portal quartermaster, they ought to have something that can aid you along the way. Good luck, <name>. Kalecgos will appreciate the aid.", ["objectivesText"] = "Get the Bag of Helpful Goods , then meet Kalecgos at the base of the Azure Archives. Progress: I'm relieved to have any help. I know Khadgar and the others must be quite busy with the Primalists.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192091, ["x"] = 0.466, ["y"] = 0.402 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185615, ["x"] = 0.408, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.402 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 8, ["flags"] = 0 } } },
[65689] = { ["id"] = 65689, ["name"] = "The Many Images of Kalecgos", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "Good to formally meet you, <name>. My name is Kalecgos , Archmage of the Kirin Tor and Aspect of the blue dragonflight. I'm having difficulty repairing the Azure Archives to reclaim the Azure Oathstone. I could use an extra pair of physical hands. I'm currently up in the archives themselves. I was able to reactivate the pylon outside, which should allow you to traverse up here.", ["objectivesText"] = "Use the Crystal Pylon to reach the Azure Archives. Progress: Glad to see you've made it.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185615, ["x"] = 0.408, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185622, ["x"] = 0.408, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 7, ["flags"] = 0 } } },
[65690] = { ["id"] = 65690, ["name"] = "A Cultist's Misgivings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65690 }, ["description"] = "Another outsider arrived yesterday. She called herself an \"emissary\" for the red dragonflight and asked for an audience with our leader, the Voice of Neltharion. But the Voice got terribly mad. He said that the Earth-Warder was testing us, and that we had to execute her! I know we're not supposed to trust outsiders, but we don't have to kill them! Please, help me save her.", ["objectivesText"] = "Locate Ayasanth in Smoldering Perch.", ["rewardGold"] = 3575, ["rewardXP"] = 710, ["rewardItems"] = { 190612 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185627, ["x"] = 0.384, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185628, ["x"] = 0.388, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[65691] = { ["id"] = 65691, ["name"] = "The Shadow of His Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65691 }, ["description"] = "The Voice of Neltharion resides below, spreading lies amongst his followers. He appears to be dragonspawn like me. but his Draconic is clumsy--fit for the unscaled. I suspect duplicity: an illusion, perhaps. If we can subdue him, I'm certain the truth will out.", ["objectivesText"] = "Confront Cygenoth , Voice of Neltharion.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 190612, 194385, 194387, 194388, 194390, 194395, 194396, 194397, 194420 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185628, ["x"] = 0.388, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185628, ["x"] = 0.388, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[65702] = { ["id"] = 65702, ["name"] = "Driven Mad", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "The Azure Archives was once a place where the blue dragons would gather to discuss magic. Now I am the only one of my kind here. This place controls the ley lines beneath the Azure Span , but it and its servants have gone out of control. I believe if we bring order to this place that I can then reclaim the Azure Oathstone. The various constructs and elements are brimming with unstable arcane energy that needs to be redirected. Destroy them and collect what you can.", ["objectivesText"] = "Recover 40 Unstable Arcane Energies. Progress: The archives are in a perpetual state of recreation for most of its guardians. We need to fix its flow.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891, 197622, 198037 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185622, ["x"] = 0.408, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185622, ["x"] = 0.408, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 9, ["flags"] = 0 } } },
[65709] = { ["id"] = 65709, ["name"] = "Arcane Pruning", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "We cannot activate the oathstone in the Azure Archives until we fix the issue with the out of control ley energy here. Two out of the three draconic runes that are meant to control it are being choked by unstable arcana. I apologize that this falls to you, given Khadgar's responsibilities and the lack of my brethren appearing. There should be a ley scepter within that bag of helpful goods you have. Use it to help repair the runes nearby.", ["objectivesText"] = "Look through the Bag of Helpful Goods for the Ley Scepter , then use it to repair 2 platforms. Progress: The ley scepter should allow you to properly align and configure the runes nearby.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185623, ["x"] = 0.406, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185623, ["x"] = 0.406, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 10, ["flags"] = 0 } } },
[65711] = { ["id"] = 65711, ["name"] = "Stealing Its Thunder", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65711 }, ["description"] = "It's you! Thank Ohn'ahra. I was pretending to be hurt to fool the next brute who dared come in here. Ugh--the hoof lickers put some binding spell on me. I'll figure it out. They've got Lizi in the cave. Please save her. I'll figure out how to free myself. Do what you have to do.", ["objectivesText"] = "Kill the Storm Extractors and rescue Lizi the Thunderspine in Kaighan Camp. Progress: Anyone whose laid a hoof on Lizi will pay!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 23211, 23246, 23247, 23326, 23327, 23435, 34684, 38218, 38219, 38220, 192743, 211279 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65750] = { ["id"] = 65750, ["name"] = "Eight-Legged Menace", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65750 }, ["description"] = "<class>! I require your aid if you're willing... This joint expedition was intended to study the unique arachnids inhabiting the area, but, as you can see, our plan has gone awry. What we originally assumed was an evolutionary adaptation is instead a Primalist perversion of the natural order! I take my responsibilities as a conservationist seriously, but the time for studying live specimens has passed. We can't let their perversion spread. We can study their corpses instead. Will you help us?", ["objectivesText"] = "Kill 10 Shiverweb Creepers or Shiverweb Crawlers and 3 Primalist Tenders in Shiverweb Vale. Progress: Is it done?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191042, 191044 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185778, ["x"] = 0.516, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185778, ["x"] = 0.516, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65751] = { ["id"] = 65751, ["name"] = "Platform Adjustments", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "It seems the last of the arcane disruption is up here. I'll continue adjusting the ley energies. Use some of the arcana you recovered to dispel the disruptions here.", ["objectivesText"] = "Dispel 3 Unstable Arcane Energies at the top of the Azure Archives. Progress: Do you need anything?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186184, ["x"] = 0.4, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186184, ["x"] = 0.4, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 12, ["flags"] = 0 } } },
[65752] = { ["id"] = 65752, ["name"] = "Arcane Annoyances", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "A large number of mana wyrms are absorbing the wild arcane magic coming out from the archives. The rate that they're doing it is causing the ley lines to be thrown off balance... which is preventing the Azure Oathstone from being reclaimed. I will use some of the unstable arcana you collected to form a hook of sorts. Use it to slay several of the wyrms. The brief delay will be enough for me to adjust the energies below.", ["objectivesText"] = "Slay 6 Feasting Wyrms . Progress: These wyrms will learn to feast somewhere else.", ["rewardGold"] = 58650, ["rewardXP"] = 4115, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891, 198013 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186184, ["x"] = 0.4, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186184, ["x"] = 0.4, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 13, ["flags"] = 0 } } },
[65758] = { ["id"] = 65758, ["name"] = "Grungir the Explorer", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65758 }, ["description"] = "<name>! My Explorers' League counterpart, Grungir Ironspout , wasn't among those you rescued. He had fought his way free originally, but once he saw how few of us made it out, he turned around and headed right back in! Alone! The oaf is as brave as he is impulsive and does not deserve whatever fate has befallen him. Please... find him.", ["objectivesText"] = "Find Grungir Ironspout .", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 191042, 191044 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185778, ["x"] = 0.516, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65760] = { ["id"] = 65760, ["name"] = "Reporting for Duty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "I've only read of the djaradin in books. Ancient rivals to the dragons, powerful giants with mastery over earth and lava... dedicated wholly to hunting dragons to extinction. < Sendrax furrows her brow at the distant volcano.> My instructor said that they hadn't been seen since the dragons left as they slumbered deep in the earth. If they've awoken, every whelpling on the isles is in danger! We should hurry to Commander Lethanak at the Dragonheart Outpost.", ["objectivesText"] = "Meet commander Lethanak at the Dragonheart Outpost. Progress: Our ancient enemies have risen from their slumber... and wasted no time.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 193874 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193363, ["x"] = 0.762, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186584, ["x"] = 0.712, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 0, ["flags"] = 0 } } },
[65769] = { ["id"] = 65769, ["name"] = "Icy Webs", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65769 }, ["description"] = "Many of my friends and colleagues were captured when the arachnids and their Primalist masters attacked. I saw them being bound in frozen webbing and dragged away to a fate I dare not consider. Please free any of them that you can!", ["objectivesText"] = "Free 6 Cocooned Survivors in Shiverweb Vale.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191042, 191044 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185778, ["x"] = 0.516, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185778, ["x"] = 0.516, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65770] = { ["id"] = 65770, ["name"] = "A Promise Is A Promise", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65770 }, ["description"] = "The animals are comfortable around you. That's a good indicator of your spirit. Actually... can you keep a secret? I want to introduce you to my friend. Nobody else knows about her. You have to promise me first that you'll keep this between us. My Ohn would exile me from the plains if she found out.", ["objectivesText"] = "Promise Initiate Radiya to keep her secret.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 30932, 30943, 30984, 30999, 31000, 31417, 88417, 116067, 139506, 139705, 192743, 204076, 208658, 211279, 237812, 245721, 245722, 245723, 245724 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190022, ["x"] = 0.5272, ["y"] = 0.6568 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65778] = { ["id"] = 65778, ["name"] = "Screechflight Potluck", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65778 }, ["description"] = "Are you ready to put those acting chops of yours to good use, <name>? What? You don't have any chops? Then it's a good thing I've made you an im-PECK-able Screechflight disguise out of all the materials you just gathered! Segallia and I still need time to finish building the final \"egg\" that will take out the matriarch, but I've made a smaller, prototype version for you to try out on the chef. And don't worry! You'll be 12% safer from these explosions under all the feathers!", ["objectivesText"] = "Wear your disguise and use the Prototype \"Egg\" on the Matriarch's Personal Chef. Progress: Old Monte Gazlowe once invited me over and cooked dinner to impress me. To be honest, it smelled a lot like whatever is coming from that cave over there.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[65779] = { ["id"] = 65779, ["name"] = "Into the Plains", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65780, 65783, 70174 }, ["description"] = "The green dragonflight has returned to their gardens in the nearby plains. Queen Alexstrasza wishes for you to make contact with Merithra of the Dream. The centaur of those plains are fierce hunters. To reach the Emerald Gardens, you will need to establish diplomacy with them first. Be respectful, but show no weakness.", ["objectivesText"] = "Meet the Shikaar scout in the Ohn'ahran Plains . Progress: <Tomul eyes you up and down with reserved curiosity.> State your business in the plains.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192469, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185878, ["x"] = 0.482, ["y"] = 0.885 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.885 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 0, ["flags"] = 0 } } },
[65780] = { ["id"] = 65780, ["name"] = "Proving Oneself", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65779, 65783, 70174 }, ["description"] = "A gift from dragons may impress some centaur, but Clan Shikaar must see how well you hunt. One of our hunting parties just brought down a proto-dragon infused with the power of flame. Prove your worth by aiding in the kill.", ["objectivesText"] = "Slay the Blazing Proto-Dragon . Progress: You look like you can handle yourself, but looks can be deceiving.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 197680, 197692, 197695, 197697, 197698, 197701, 197706, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.254333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 1, ["flags"] = 0 } } },
[65782] = { ["id"] = 65782, ["name"] = "Under Lock and Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65782 }, ["description"] = "When we heard rumors of a Deathwing cult, Majordomo Selistra ordered me to bring these erstwhile scaleborn back into the fold. We'd hoped it was a simple misunderstanding. Clearly, we were wrong. Their leader must be dealt with--but first I need out of this cage. Find the key and bring it to me.", ["objectivesText"] = "Acquire the Worldbreaker Cell Key and free Ayasanth . Progress: I must admit: this cage has gotten rather tiresome.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 77532, 171441, 173065, 190612 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185628, ["x"] = 0.388, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185628, ["x"] = 0.388, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[65783] = { ["id"] = 65783, ["name"] = "Welcome at Our Fire", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65779, 65780, 70174 }, ["description"] = "You have fought alongside our hunters and earned a place at our fire. Our khan is at our hunting post in the swamp, readying our upcoming caravan. I will notify her of your arrival and purpose. Surely you can find your way on your own.", ["objectivesText"] = "Meet with Scout Tomul at Timberstep Outpost.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.254333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 2, ["flags"] = 0 } } },
[65791] = { ["id"] = 65791, ["name"] = "Life-Binder on Duty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "Soon the Life Pools will be full once again. Thank you for your part in this, <name>, it means more than I can ever hope to express. Go, find the Life-Binder by the oathstone. Tell her that we are ready for the eggs.", ["objectivesText"] = "Meet Alexstrasza by the Ruby Oathstone.", ["rewardGold"] = 31900, ["rewardXP"] = 710, ["rewardItems"] = { 194399 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185905, ["x"] = 0.622, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 49, ["flags"] = 0 } } },
[65793] = { ["id"] = 65793, ["name"] = "Black Wagon Flight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "With the oathstone empowered once more, we must now transport the future of our kind to the Life Pools. It is the right of every true dragonflight to have their eggs nurtured by its waters. Unfortunately, our enemies will be watching the skies, now that we have revealed ourselves. We will make the final leg of the journey on foot to avoid their scrutiny. Meet me near the Obsidian Bulwark, <class>. As the Life-Binder's champion, you are welcome to join me in this.", ["objectivesText"] = "Escort the eggs to the Life Pools.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 194362, 194363, 194364 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185894, ["x"] = 0.242, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190740, ["x"] = 0.578, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 46, ["flags"] = 0 } } },
[65794] = { ["id"] = 65794, ["name"] = "A Charge of Care", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "You have my thanks, <class>, and my condolences for having to deal with those two for as long as you did. The red dragonflight is charged with the preservation and nurturing of all dragons, even those we may tire of at times. With the return of the Black Dragonflight's eggs, dragonkind is united as it has not been in thousands of years. I believe this is what will restore our ruby oathstone. Speak with me when you are ready to bring the eggs to the Obsidian Lifepool.", ["objectivesText"] = "Witness the Black Dragon Eggs rejoin the Life Pools.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194347, 194348, 194349, 194380 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185905, ["x"] = 0.622, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193377, ["x"] = 0.615, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 50, ["flags"] = 0 } } },
[65795] = { ["id"] = 65795, ["name"] = "Next Steppes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["description"] = "The green dragonflight requires your aid now, hero. My sister's daughter and her flight have entered the Emerald Dream in an attempt to empower their own oathstone, but we have heard nothing since their slumber began. Seek out the centaur that rule over the Ohn'ahran Plains. You may well need their connection to the land and its spirits if you are to rouse the greens. They are a proud and territorial people who do not suffer insult lightly. Speak with our ambassador and he will prepare you.", ["objectivesText"] = "Meet Ambassador Taurasza in the Rubyscale Outpost.", ["rewardGold"] = 29325, ["rewardXP"] = 710, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193377, ["x"] = 0.615, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185878, ["x"] = 0.482, ["y"] = 0.885 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 53, ["flags"] = 0 } } },
[65802] = { ["id"] = 65802, ["name"] = "Supplies for the Journey", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["description"] = "<As Sansok Khan signs, Okir vocalizes for her.> While you travel with us, you must pull your weight. Unruly gorlocs have been raiding our medical supplies recently, and we must restock. Gather the orange blooms around the outpost so we can create more poultices. There are supplies around the outpost that need to be brought to the caravan as well. I would like you to gather them while you are out. Once you have everything, bring it to Tomul.", ["objectivesText"] = "Collect 5 Camp Provisions from around Timberstep Outpost and 4 Feralbloom Pods from the nearby woods. Progress: Don't bother me until you have the caravan provisions.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191048, 191054, 191055, 191100, 191101, 191102, 191103, 192810, 192811, 192812, 197657, 197659, 197660, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 181217, ["x"] = 0.778, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 5, ["flags"] = 0 } } },
[65803] = { ["id"] = 65803, ["name"] = "Toward the City", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["description"] = "The Khural is a time of discussion amongst clans. Stories are shared. While there are many centaur clans across the plains, we are all Maruuk. The caravan is ready to go. As Maruukai is some distance away, we will make stops. When you are ready to leave, find me at the caravan. Don't keep us waiting.", ["objectivesText"] = "Travel alongside the Shikaar caravan to Wanderer's Steppe.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.254333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 6, ["flags"] = 0 } } },
[65804] = { ["id"] = 65804, ["name"] = "For Food and Rivalry", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["description"] = "Maruuk travel from all across the plains to attend the Khural, and the gathering lasts many days. Feeding that many centaur is no simple feat. Clan Shikaar's hunters provide meat for all of the shared meals. It is our tradition to hunt on our way to Maruukai. You must pull your weight as well.", ["objectivesText"] = "Collect 30 Fresh Game Meat from wildlife in Wanderer's Steppe. Progress: Our youngest hunters are passionate and determined. Be sure they don't show you up.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.254333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 7, ["flags"] = 0 } } },
[65805] = { ["id"] = 65805, ["name"] = "Connection to Ohn'ahra", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65940, 66848 }, ["description"] = "The wind is restless here, <name>. Ohn'ahra is reaching out. I must answer her call. I need reagents for my ritual: reeds from the riverbanks, feathers from the tails of mallards, and the heart of a salamanther. Gather these materials from the river so that I may heed her voice.", ["objectivesText"] = "Collect 4 River Reeds , 8 Fowl Tailfeathers , and a Salamanther Heart from the river banks. Progress: Ohn'ahra's song is fleeting. We must work quickly.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 184595, ["x"] = 0.778, ["y"] = 0.293 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 184595, ["x"] = 0.778, ["y"] = 0.293 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.293 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 10, ["flags"] = 0 } } },
[65806] = { ["id"] = 65806, ["name"] = "Maruukai", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["description"] = "<Okir vocalizes as Sansok Khan signs.> Maruukai rests beside a mountain near this grove. Our journey is almost over. The Khural is a time of truce amongst the Maruuk, but Ohn Seshteng's omen is troubling. We must stay on our guard.", ["objectivesText"] = "Travel into Maruukai.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 181217, ["x"] = 0.778, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191283, ["x"] = 0.6075, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 12, ["flags"] = 0 } } },
[65832] = { ["id"] = 65832, ["name"] = "Dwarven Antifreeze", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65832 }, ["description"] = "I'm in a wee bit of a pickle, $Uladdie:lassie;. The Primalist frost lickers stuck me in this overgrown ice cube and the only reason I'm nae frozen solid yet is me secret stash o' the good stuff. Sadly, me less secret stashes got nicked when tae thieving scum jumped me. I'm runnin' low! Would ye do a dwarf a kindness and fetch me flasks afore me blood turns tae ice? Oh, and $Uladdie:lassie;, if ye do haftae pull one out o' some spider's unmentionables, dinnae tell me. I'd rather nae know.", ["objectivesText"] = "Find 6 Flasks of Dwarven Antifreeze . Progress: I can feel ma wee piggies freezin'!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191042, 191044 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65833] = { ["id"] = 65833, ["name"] = "Primalist Tampering", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65833 }, ["description"] = "The Primalists are infusin' spiders with elemental ice and are fixin' to use 'em as shock troops tae overrun the dragons' defenses in the Span. We cannae let that happen. The three frosty lookin' ones are in charge. Take 'em out and bring me the runestones they're using tae focus the primal magic and we can see about cuttin' off the flow.", ["objectivesText"] = "Retrieve the three Frostcallers' Runestones. Progress: Did ye get all three?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191042, 191044, 191135, 191136, 191137 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65834] = { ["id"] = 65834, ["name"] = "Kill the Queen", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65834 }, ["description"] = "Here we go! A lil' formal education, a lil' educated guessin', a touch o' re-chiselin' runes, and we got ourselves a magic un-infuser! Defuser? Out-fuser? Whatever! It'll do somethin' unpleasant tae the queen, o' that I'm pretty sure. And she's got tae go if we're aimin' tae stop the threat. Squashin' the lil' ones will only slow 'em down. Ye got tae cut 'em off at the source.", ["objectivesText"] = "Slay the Shiverweb Queen . Progress: She's in the cave over yonder. Giant spider. Cannae miss 'er.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191042, 191044, 198353 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65836] = { ["id"] = 65836, ["name"] = "Show of Storm", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65836 }, ["description"] = "<Watu stands up easily, as if his injury was gone.> I--I--I stuck the shard into myself. Nothing hurts anymore. I feel good. Great. Immense. Olekk still isn't back. Something must have gone awry. He should have never gone without me!", ["objectivesText"] = "Regroup with Watu in the Sagecrest Pines.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193890, 193892, 194031 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.599 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65838] = { ["id"] = 65838, ["name"] = "Breaching the Brackenhide", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "If the gnolls here have discovered decay magic, the ley line and even the land itself are in grave danger. My mirror images are spread too thin to withstand elemental disruption of this scale. Please enter the forest and investigate the decay. I'll work with our new tuskarr friends to find a place I can maintain my image. Then, I will meet you deeper in the forest. We must put a stop to this!", ["objectivesText"] = "Investigate Brackenhide Outskirts. Progress: Can you sense the disruption of magic all around us?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.1825, ["y"] = 0.3695 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 28, ["flags"] = 0 } } },
[65841] = { ["id"] = 65841, ["name"] = "Stop the Spread", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65841 }, ["objectivesText"] = "Brackenhide decay spread contained", ["rewardGold"] = 12000, ["rewardXP"] = 6175, ["rewardItems"] = { 25568, 25569, 25570, 191928, 194115, 194119, 194120, 194121, 194431 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Brackenhide decay spread contained", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65844] = { ["id"] = 65844, ["name"] = "Cut Out the Rot", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "This decay must have rotted these gnolls' brains as well as their bodies! Destructive as they are, gnolls are native to this land--just like us. But we already saw them spreading decay to the Big Tree Tribe. At this rate, they'll consume the Span and destroy themselves. We can't let this happen. It's a shame... but put an end to them.", ["objectivesText"] = "Kill 5 Rotting Treants and 10 Brackenhide Rotflingers . Progress: Er, please, do tell... Did you see any interesting effects of the decay on any gnolls you observed? The effect on their social structure must be enormous... Ah, we should stay on task.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186181, ["x"] = 0.167, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186181, ["x"] = 0.167, ["y"] = 0.406 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.167, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 29, ["flags"] = 0 } } },
[65845] = { ["id"] = 65845, ["name"] = "Echoes of the Fallen", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "There are tuskarr here! My friends, my people--my family. They left for a hunt not a week ago. Already they're too decayed to recover. Their spirits are here still. They linger in rage and regret. Kaqiata , Lutokk , Tuyuki ... Please, <name>, take this totem and place it near their remains. It'll contact their spirits... and help them find peace.", ["objectivesText"] = "Place Brena's Totem near 5 tuskarr corpses to contact their spirits. Progress: Some of my fallen kin were able to take Karkut's hand into the next world. Others weren't. I feel their presence like a weight. Lutokk was going to wed in the next moon. Tuyuki wanted to sail to Northrend to reconnect with our distant kin. Popoak was a great hunter, and Hanu's cousin. His kills made for the best soups. Nomurok was so young. This was his first hunt. Kaqiata was little Rowie's only blood family left. Now who'll teach him to fish?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431, 197408, 198001 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186179, ["x"] = 0.178, ["y"] = 0.380667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186179, ["x"] = 0.178, ["y"] = 0.380667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.178, ["y"] = 0.380667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 30, ["flags"] = 0 } } },
[65846] = { ["id"] = 65846, ["name"] = "Ley Litter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "The ley line is here--I can feel it! But first, we must stop the gnolls. That ancient will be their greatest weapon. There are some ley crystals the gnolls have gathered. Thankfully, they don't seem to understand the power that the crystals hold. Bring me as many as you can. They'll empower my mirror image and help me summon something useful from the Archives to take that monster down!", ["objectivesText"] = "Collect 7 Ley Crystals from Brackenhide Outskirts. Progress: I'm sorry I can't be of more help in this form. I can feel the decay sapping my image's strength. I hope once we reach the ley cavern, Gleamcove as the tuskarr call it, I'll be able to teleport here fully.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.1825, ["y"] = 0.3695 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 31, ["flags"] = 0 } } },
[65847] = { ["id"] = 65847, ["name"] = "Realignment", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "Now for this ley line. It looks like my fears were correct -- the decay has spread into the line itself. We'll need to purge the decay and speed along the healing process, but I can't channel enough energy with my mirror image alone. Focus yourself on this ley crystal here. My connection with you will help me teleport here physically. Then, I will be strong enough.", ["objectivesText"] = "Focus on the Ley Crystal, then destroy 3 Decay Infections . Progress: While the decay here is lessened, it's still thick enough to cause trouble teleporting safely.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186177, ["x"] = 0.146667, ["y"] = 0.437333 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.1825, ["y"] = 0.3695 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 33, ["flags"] = 0 } } },
[65848] = { ["id"] = 65848, ["name"] = "Tome-ward Bound", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "We must stop that tree! With these ley crystals, I can finally help. Speak with me when you are ready. I'll open a portal into the Azure Archives and try to bring out something useful. Stand back, it may be rather unstable.", ["objectivesText"] = "Speak with Kalecgos to open the portal, then use what he summons to take out the Brackenhide Putrifiers and then destroy the Twisted Ancient . Progress: This should be interesting!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431, 198012 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.1825, ["y"] = 0.3695 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 32, ["flags"] = 0 } } },
[65849] = { ["id"] = 65849, ["name"] = "To Iskaara", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "Thank you, <name>, for all your help. My family is safe because of you. Now, we can finally return to Iskaara and see old Ponoliak taken back to the sea. He was my mentor, and a fine chieftain. Please, you must join us! A celebration of the Cycle of the Sea is something all can share in.", ["objectivesText"] = "Meet Brena in Iskaara.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 21100, 21746, 191928, 194115, 194119, 194120, 194121, 194431, 199473, 201705, 201709, 201712, 201713, 201714, 201717, 201718, 204379 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186179, ["x"] = 0.178, ["y"] = 0.380667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186480, ["x"] = 0.13, ["y"] = 0.499 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.178, ["y"] = 0.380667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 34, ["flags"] = 0 } } },
[65850] = { ["id"] = 65850, ["name"] = "The Cycle of the Sea", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "Thank you, <name>. I have learned what I need for now from our new friends. The funeral ceremony for their former chieftain is about to start. Given how kind and hospitable the Iskaarans have been to us, it seems only right that we join them before departing back to the Archives. Speak with Brena and let her know we are ready when they are.", ["objectivesText"] = "Speak with Brena to witness the funeral ceremony. Progress: It is good to slow down, now and then. And interesting to see the tuskarr's traditions. It has been long since the blue dragonflight has had traditions such as these.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431, 197990 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189793, ["x"] = 0.132, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186177, ["x"] = 0.146667, ["y"] = 0.437333 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.132, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 36, ["flags"] = 0 } } },
[65852] = { ["id"] = 65852, ["name"] = "Straight to the Top", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "There appears to be something sapping the arcane energies at the apex of the tower. Now that you've stabilized the energies down here, you should be able to \"ride\" the arcane magics in the area. Look in that bag of yours for something called an arcane stepping stone , and use it to meet me at the top.", ["objectivesText"] = "Look through the Bag of Helpful Goods for the Arcane Stepping Stone , then use at an arcane focus point to reach the top of the Azure Archives. Progress: It's a long way down from here. Be careful.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 191979, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185622, ["x"] = 0.408, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186184, ["x"] = 0.4, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 11, ["flags"] = 0 } } },
[65854] = { ["id"] = 65854, ["name"] = "Reclaiming the Oathstone", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "Fine work, friend. It seems we've managed to repair the leylines within the Azure Archives. Back when the blue dragonflight was united, I would tell my brothers and sisters to never doubt the strength of mortals. Meet me at the oathstone to the south of here. I will reclaim it, and then be on my way to Thaldraszus.", ["objectivesText"] = "Witness Kalecgos reclaim the Azure Oathstone.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186184, ["x"] = 0.4, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 14, ["flags"] = 0 } } },
[65855] = { ["id"] = 65855, ["name"] = "Aiding Azure Span", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "The oathstone's energy cannot be reclaimed until the ley lines within the Azure Span are repaired. Some ley lines may only be reachable by those of Kalecgos's skills... but you may still be of aid. If they still yet survive, seek out the tuskarr. They lived here in my times and have a deep knowledge of the land. Speak with one of our arcane aids to return to your allies.", ["objectivesText"] = "Return to Noriko the All-Remembering in Camp Antonidas. Progress: What can I do for you?", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891, 197989 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 15, ["flags"] = 0 } } },
[65864] = { ["id"] = 65864, ["name"] = "Catch the Caravan", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "You should catch up with Brena . Her caravan passed through no more than a few hours ago. They were collecting our late chieftain's most prized possessions for a funeral to honor him. Given that the caravan was heavily burdened, she can't be far ahead.", ["objectivesText"] = "Catch up with Brena near the Big Tree Hills. Progress: I've got you, Hanu.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190225, ["x"] = 0.456, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186224, ["x"] = 0.352, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 17, ["flags"] = 0 } } },
[65866] = { ["id"] = 65866, ["name"] = "Snap the Traps", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "The hills ahead are littered with insidious bladejaw traps. With a keen eye, you should be able to locate them. Very carefully spring the traps using this old tuskarr trick: a long stick. Note that while stepping on them is another way to set the traps off, I wouldn't recommend it. Once enough have been removed, find Hanu . Elder Poa and I will catch up when we can.", ["objectivesText"] = "Spring 5 Bladejaw Traps.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191810, ["x"] = 0.352, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186618, ["x"] = 0.342, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 19, ["flags"] = 0 } } },
[65867] = { ["id"] = 65867, ["name"] = "Howling in the Big Tree Hills", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "The gnolls that attacked our caravan were led by three lieutenants. Durgun was flanked by a dozen hyenas. Kerwal cackled maniacally each time we tried to pursue him and fell for one of his steel-jawed traps. Bakra taunted us, mercilessly. To have a hope in recovering what was stolen, they must be slain.", ["objectivesText"] = "Slay Durgun, Kerwal, and Bakra. Progress: < Hanu stares at you intently.>", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190, 197388, 197998, 198015, 198023, 198030 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191810, ["x"] = 0.352, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186618, ["x"] = 0.342, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 20, ["flags"] = 0 } } },
[65868] = { ["id"] = 65868, ["name"] = "Those Aren't for Chewing", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "I found one of Ponoliak's funerary offerings , mishandled and then discarded by these Shadepaw gnolls... It has bite marks all over it! This offering, and others like it, are needed for the memorial ceremony for the recently deceased Iskaara chieftain. It's a travesty that something so sacred should be employed as a chew toy. Please keep an eye out for more offerings.", ["objectivesText"] = "Recover 8 Funerary Offerings . Progress: < Hanu leans forward and gazes into your pack hopefully.>", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 188809, ["x"] = 0.352, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186618, ["x"] = 0.342, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 18, ["flags"] = 0 } }, ["startItems"] = { 191108 } },
[65869] = { ["id"] = 65869, ["name"] = "Another Ambush", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "A tragedy. And potentially the first of many more. Find out what Akiun knows, then examine anyone who fell in the attack. I have my hunches about what happened here. Let's see if the clues support my theory. Meanwhile, I'll try to reassure my rattled friends.", ["objectivesText"] = "Speak to Akiun and examine 4 nearby corpses. Progress: We must pinpoint the source of this gnoll aggression, before they can do any more damage.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187721, ["x"] = 0.286, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189708, ["x"] = 0.288, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 26, ["flags"] = 0 } } },
