[65995] = { ["id"] = 65995, ["name"] = "The Obsidian Citadel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "<At a glance, this seems to be internal communications between djaradin camps. The words 'Obsidian Citadel' leap out at you. Perhaps Wrathion would be interested in seeing this.>", ["objectivesText"] = "Give the Qalashi Plans to Wrathion . Provided item:", ["rewardGold"] = 17450, ["rewardXP"] = 1415, ["rewardItems"] = { 193874 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194772, ["x"] = 0.626, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 6, ["flags"] = 0 } }, ["startItems"] = { 193874 } },
[65996] = { ["id"] = 65996, ["name"] = "Veteran Reinforcements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "Commander Lethanak was insightful, as always. We will need the help of our most veteran guards to stop their threat. Rallying them was the perfect task for a young cadet like Sendrax, but she may need support. Sendrax's path will take her towards the west, which may have been overwhelmed by this rising threat. They will need aid as well. Take this concoction and give them your support.", ["objectivesText"] = "Help the injured guards and find Sendrax. Progress: We are all in this together, <name>. The safety of the isles is at stake.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 193874, 193917 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186767, ["x"] = 0.626, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190155, ["x"] = 0.55, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 7, ["flags"] = 0 } } },
[65997] = { ["id"] = 65997, ["name"] = "Chasing Sendrax", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "Cadet Sendrax came through here not long ago. She relayed Commander Lethanak's orders for all drakonid to rally back at the Life Pools. Our whole defensive regiment set off in that direction not long after. But our scouts were out on patrol in the old ruins, so she headed in there to rally them too.", ["objectivesText"] = "Find Sendrax in the Life-Binder Conservatory ruins. Progress: Keep low, <name>.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 193874 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190155, ["x"] = 0.55, ["y"] = 0.308 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187406, ["x"] = 0.552, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 8, ["flags"] = 0 } } },
[65998] = { ["id"] = 65998, ["name"] = "Future of the Flights", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "There is no higher charge given to a drakonid upon their graduation than to defend every single dragon egg with their lives. It's why we train. Why we exist. I can no longer hide and observe, $p. By stealing and infusing these eggs, the Primalists threaten the entire future of the dragonflights! We are vastly outnumbered, but will you stand by my side? Will you fight to save the dragonflights?", ["objectivesText"] = "Rescue the Ruby Dragon Eggs. Progress: Such cruelty and selfishness... I cannot even fathom.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193874 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187406, ["x"] = 0.552, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 9, ["flags"] = 0 } } },
[65999] = { ["id"] = 65999, ["name"] = "Red in Tooth and Claw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "Commander Lethanak warned us recruits that he had received reports of the Storm-Eater, Raszageth, escaping her prison. It seems her servants have followed in her wake, threatening all we hold dear. They move quickly. These ruins were reported to be abandoned during the last patrol. We must stop the Primalists here. For the Life-Binder, and for all of the dragonflights!", ["objectivesText"] = "Kill 15 Primalist invaders. Progress: The dragonflights will prevail against the Primalists.", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 193874, 194369 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187406, ["x"] = 0.552, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 10, ["flags"] = 0 } } },
[66000] = { ["id"] = 66000, ["name"] = "Library of Alexstrasza", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "<The pages on this book are charred. The Primalists seem to be burning the ancient tomes found here, putting the dragonflights' very history in peril. It's as if the Primalists want to erase the dragonflights from history. Save what you can.>", ["objectivesText"] = "Save 4 works of cultural significance. Progress: I smell burning parchment on the wind...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192745, 192753, 192754, 192755, 192756, 192757, 193874 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 11, ["flags"] = 0 } } },
[66001] = { ["id"] = 66001, ["name"] = "A Last Hope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "A whole brood of whelplings, lost... < Sendrax straightens her back and sticks her chin up.> There is one more location we have not checked yet. The large ritual site where that proto-dragon dropped off the eggs. Let us charge their cruel defenses together, $p, and save what we can.", ["objectivesText"] = "Rescue the last Infused Dragon Egg.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193874, 194338, 194381, 194382, 194383, 246863 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186795, ["x"] = 0.55, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 12, ["flags"] = 0 } } },
[66003] = { ["id"] = 66003, ["name"] = "Rings To Bind Them", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66003 }, ["description"] = "The djaradin here have become bold, binding flame elementals and letting them rampage through the area. The wildlife has fled, and the elementals are dangerously close to our camps. Luckily, I have been able to construct a small bastion of stone to stand against this fiery tide the djaradin have unleashed... and we will not fall! Gather the magical rings that bind these flame elementals. We shall use them to bolster our defenses against the flame elementals.", ["objectivesText"] = "Gather 12 Molten Binding Rings . Progress: Have you gathered all the rings I asked for?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191278, 194384 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187609, ["x"] = 0.374, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187609, ["x"] = 0.374, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.374, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
