[66005] = { ["id"] = 66005, ["name"] = "Medallion of a Fallen Friend", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66005 }, ["description"] = "<This chewed up hunk of metal was once a beautiful ornament of great importance to a Shikaar centaur. Khasar may know more about the owner.>", ["objectivesText"] = "Return the Medallion of a Fallen Friend to Khasar . Provided item:", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 191127, 191143, 191541, 198792, 198793, 198794, 198795 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.8215, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["startItems"] = { 191127 } },
[66006] = { ["id"] = 66006, ["name"] = "Return to Roscha", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66006 }, ["description"] = "Baba is rested, and Roscha's supplies are recovered. We can return without upsetting her further. Take some boxes when you go. I will send warriors for the rest.", ["objectivesText"] = "Return the supplies to Farrier Roscha . Progress: What took you so long?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191127, 191143, 191541, 198792, 198793, 198794, 198795 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186650, ["x"] = 0.844, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.8215, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66007] = { ["id"] = 66007, ["name"] = "Free Air", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "The Primalists are using these massive orbs here to hold off Kalecgos . At this rate, Kalecgos will be too injured to continue the fight. If he falls, I won't be able to fend off Raszageth. The empowered gem you hold should allow you to disguise yourself as an elemental to sneak ahead. Use the gem to destroy the orbs. That should give Kalecgos room to unleash his power. I will focus my attention on shielding the tower from Raszageth.", ["objectivesText"] = "Destroy 4 Lava Beacons .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 192478, 192479, 194705 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186779, ["x"] = 0.768, ["y"] = 0.394 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186862, ["x"] = 0.784, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.768, ["y"] = 0.394 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 46, ["flags"] = 0 } } },
[66009] = { ["id"] = 66009, ["name"] = "In Defense of Vakthros", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "It's time, <name>. The Primalist forces in the air are dwindling now that you've handled things on the ground. Raszageth is calling in one of her lieutenants to reinforce the Primalist forces, thanks to your efforts. I need you to handle this monster while I push forward to fight Raszageth and help Khadgar. Look for my magic during your fight. I will do what I can to aid you. It is time for Raszageth to face the fury of the Aspect of magic!", ["objectivesText"] = "Defeat Korthrox the Destroyer .", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 192478, 192479, 194705, 197603, 198000, 198014, 198022, 198031 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186862, ["x"] = 0.784, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193837, ["x"] = 0.78, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.784, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 47, ["flags"] = 0 } } },
[66011] = { ["id"] = 66011, ["name"] = "In Memory of Ysera", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66011 }, ["description"] = "Oh, no! Now I think I understand. Theramus ...he misses Ysera, and she can't come back. Come! I suspect I know where he went. We won't bother him further, but it'll be good to tell him that we're sorry, and that we'll give him the space he wants. We are here for each other, within the nature all around us.", ["objectivesText"] = "Find Theramus again. Progress: We appreciate you sticking around, <race>. You've been a great help.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191083, 191084, 191085, 191086, 191134, 191568, 199693, 201874 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185726, ["x"] = 0.246, ["y"] = 0.632571 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187270, ["x"] = 0.248, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.632571 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66012] = { ["id"] = 66012, ["name"] = "The Sealed Door", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["series"] = { 66013 }, ["description"] = "Our scouts have been combing the Dragon Isles for anything of interest. They've returned much of note, but one discovery stands out amongst the rest--a door. A door forged by the titans, and sealed against the world. No one has yet managed to find their way through to the artifacts that surely lie within. But then, no mystery has endured under the discerning gaze of the Reliquary. With the help of the Explorers' League, this challenge will be simple, I am certain.", ["objectivesText"] = "Travel to the Sealed Door in Thaldraszus and speak to Naleidea.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186869, ["x"] = 0.478, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 1, ["flags"] = 0 } } },
[66013] = { ["id"] = 66013, ["name"] = "Investigate the Door", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["series"] = { 66012 }, ["description"] = "Here we are. If we're going to get past this door, we need to understand who locked it, and how. Take a look around and see if you can find anything that might give us the answers we seek.", ["objectivesText"] = "Search the area for clues. Progress: What an intriguing discovery. What do you imagine is on the other side?", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 2, ["flags"] = 0 } } },
[66015] = { ["id"] = 66015, ["name"] = "The Blue Dragon Oathstone", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "The Azure Span has stabilized for now and more blue dragons have arrived... just in time. It's time to return to the Azure Archives and reclaim the oathstone. I would request your presence there, <name>. You've been a great boon throughout this ordeal.", ["objectivesText"] = "Accompany Kalecgos to claim the Blue Dragon Oathstone. Progress: I'm quite relieved you all prevented the complete annihilation of the Azure Span . Shall we continue?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 192478, 192479, 194705, 198011 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187034, ["x"] = 0.782, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 49, ["flags"] = 0 } } },
[66016] = { ["id"] = 66016, ["name"] = "Clan Teerai", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66019 }, ["description"] = "<As Sansok Khan signs, Okir vocalizes for her.> Clan Teerai is the clan of our Khanam Matra, our direct connection to the Maruuk ancestors. They are the holders of our traditions, and our storytellers. To understand the Maruuk, you must understand Clan Teerai. One of the Khanam Matra's daughters, Qariin Dotur , is preparing a meal for our ancestors. Aid her. She will teach you about our people.", ["objectivesText"] = "Report to Qariin Dotur .", ["rewardGold"] = 7410, ["rewardXP"] = 345, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191283, ["x"] = 0.6075, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186941, ["x"] = 0.592, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6075, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 13, ["flags"] = 0 } } },
[66017] = { ["id"] = 66017, ["name"] = "Clan Ohn'ir", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66020 }, ["description"] = "<As Sansok Khan signs, Okir vocalizes for her.> The mystics of our lands, like Ohn Seshteng , belong to Clan Ohn'ir. The clan is not made up of families, but rather of centaur from across the plains with an innate connection to Ohn'ahra. They spend their lives building that connection and honing their skills. Eventually, they receive assignments to advise different clans and protect our lands. Ohn Seshteng went to speak with her khan about the omen she received. Join her to learn about the Ohn'ir.", ["objectivesText"] = "Meet Ohn Seshteng at the mystic pools.", ["rewardGold"] = 7410, ["rewardXP"] = 345, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191283, ["x"] = 0.6075, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191595, ["x"] = 0.63, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6075, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 14, ["flags"] = 0 } } },
[66018] = { ["id"] = 66018, ["name"] = "Clan Nokhud", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["description"] = "<As Sansok Khan signs, Okir vocalizes for her.> Clan Nokhud is the newest to rise to power. Their late khan, Jhakan, raised a mighty army to seize territory from their predecessors. Such is the way of our people. While Jhakan had earned his respect, his son has not. Balakar killed his father and took control of the clan. They have grown ever more insular since. But to know the Maruuk, you must know them.", ["objectivesText"] = "Accompany Tomul to Guard Bahir.", ["rewardGold"] = 7410, ["rewardXP"] = 345, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191283, ["x"] = 0.6075, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191485, ["x"] = 0.607333, ["y"] = 0.402667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6075, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 15, ["flags"] = 0 } } },
[66019] = { ["id"] = 66019, ["name"] = "Honoring Our Ancestors", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66016 }, ["description"] = "Our ancestors walk beside us upon the winds of Ohn'ahra, guiding and protecting us. All Maruuk, dead and living, gather under truce at the Khural. The scent of this meal calls the ancestors to our fire. When they arrive, the Khural begins.", ["objectivesText"] = "Help Qariin Dotur cook a meal for the ancestors. Progress: The Maruuk have returned to this spot for generations upon generations. We walk alongside our ancestors.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186941, ["x"] = 0.592, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186941, ["x"] = 0.592, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 17, ["flags"] = 0 } } },
[66020] = { ["id"] = 66020, ["name"] = "Omens and Incense", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66017 }, ["description"] = "I shared with Tigari Khan the omen we received before entering Maruukai. She expressed her concern, as the wind felt cold to her as well. We cultivate certain flowers here, blooms that can be ground and burned to elicit a trancelike effect. They are used to deepen our connection to an omen. I request that you collect some so that we may make an incense to burn. With my khan's help, perhaps we can learn more of Ohn'ahra's plight.", ["objectivesText"] = "Collect 5 Sweetsuckle Blooms , grind them into Sweetsuckle Incense , then aid Ohn Seshteng in the ritual. Progress: Tigari Khan is most well-versed in reading omens. With her aid, we can learn more about this omen.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191595, ["x"] = 0.63, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191595, ["x"] = 0.63, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 18, ["flags"] = 0 } } },
[66021] = { ["id"] = 66021, ["name"] = "Unwelcome Outsider", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["description"] = "Hah! Look at you. Weak. Just like those puny hunters that brought you here. You want to know the Nokhud? We speak through battle. Our battle ritual is called \"the tabarr\". We train. We spar. And it hardens us. Now there is no weakness in our clan. Enough talk. Go spar.", ["objectivesText"] = "Defeat 6 Nokhud centaur.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186940, ["x"] = 0.604, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191485, ["x"] = 0.607333, ["y"] = 0.402667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 19, ["flags"] = 0 } } },
[66022] = { ["id"] = 66022, ["name"] = "The Khanam Matra", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66023, 66969 }, ["description"] = "I cannot linger in centaur lands; I must return to the gardens as soon as I am able. The Khanam Matra has agreed to hear our plea for aid. She awaits my arrival at the top of the krutal, the central building of Maruukai. Though I must speak with her on my own at first, you are more than welcome to join us.", ["objectivesText"] = "Report to Khansguard Akato to join Gemisath 's audience with the Khanam Matra. Progress: The Khanam Matra is waiting for you.", ["rewardGold"] = 37050, ["rewardXP"] = 1385, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194927, ["x"] = 0.605, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186942, ["x"] = 0.602, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 22, ["flags"] = 0 } } },
[66023] = { ["id"] = 66023, ["name"] = "Trucebreakers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66022, 66969 }, ["description"] = "Balakar disgraces his clan. He leads them into the storm, blinded by his lust for power. Their betrayal reveals their fragility. Cut them down.", ["objectivesText"] = "Kill 10 Nokhud forces. Progress: To attack the Khanam Matra... it is a rejection of our ways.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186942, ["x"] = 0.602, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186942, ["x"] = 0.602, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 23, ["flags"] = 0 } } },
[66024] = { ["id"] = 66024, ["name"] = "Covering Their Tails", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["description"] = "The Nokhud drool over war stories of our kind's ancient past. In truth they are weak, playacting children. And with one strike of lightning, they have severed their connection to Ohn'ahra. Well! If they will walk the path of corruption to seek war, then we will indulge them. Of course, Bahir was left in command to cover his escape. Her blood will soon stain the ground.", ["objectivesText"] = "Slay Guard Bahir . Progress: <Sarest surveys the battlefield, eyes narrowed.>", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 191160, 194964, 197405, 197646, 197647, 197648, 197685, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191485, ["x"] = 0.607333, ["y"] = 0.402667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.607333, ["y"] = 0.402667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 24, ["flags"] = 0 } } },
[66025] = { ["id"] = 66025, ["name"] = "The Nokhud Threat", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["description"] = "Clan Nokhud's army is taking Maruukai. Let us discuss our next moves in the khan chambers. We must keep the Maruuk safe.", ["objectivesText"] = "Discuss next steps.", ["rewardGold"] = 7410, ["rewardXP"] = 345, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 25, ["flags"] = 0 } } },
[66026] = { ["id"] = 66026, ["name"] = "Urgent Action Required", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "The source of these attacks must be the Brackenhide. We've fought with the Brackenhide gnolls for generations, but until now they've been nothing more than a nuisance. We have no choice but to take urgent action against the gnolls. Their foul decay will destroy the Azure Span , including whatever you're searching for. Meet us outside Brackenhide. We will need all the help we can get.", ["objectivesText"] = "Meet Brena at Brackenhide.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190, 198016 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189708, ["x"] = 0.288, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186179, ["x"] = 0.178, ["y"] = 0.380667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 27, ["flags"] = 0 } } },
[66027] = { ["id"] = 66027, ["name"] = "Calling the Blue Dragons", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "I can no longer be afraid of reuniting the blue dragons, <name>. It is better for us to be a family... than a fragment of our former selves. Even if I cannot reclaim the oathstone, I can still use its power to send a message to all of the blue dragons. It is time they received word... from their Aspect.", ["objectivesText"] = "View Kalecgos call back the blue dragonflight. Progress: Stand back, <name>.", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["rewardItems"] = { 192478, 192479, 194705 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186280, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186280, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 38, ["flags"] = 0 } } },
[66028] = { ["id"] = 66028, ["name"] = "To the Future!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "I have tracked Chronormu and Eternus to a potential future. I know not what you will find there, only that it is dark and chaotic. Soridormi has taken some of our timewalkers ahead to that future in order to hold our connection to that time stable. Her considerable power will be needed to keep the portal open, so she must rely on your talents. Soridormi will be able to direct you further once you meet her there. Hurry, <name>. Find Chronormu.", ["objectivesText"] = "Travel to the Primalist Future.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 59039, 59040, 59041, 59042, 59043, 65461, 65462, 65463, 65464, 71083, 95589, 134123, 139904, 139928, 139941, 139958, 139964, 139988, 139996, 140021, 143488, 181501, 181502, 181503, 181507, 181625, 181626, 181645, 181647, 181649, 181650, 181652, 181653, 181654, 181661, 181662, 181663, 181679, 181680, 181682, 181694, 184194, 184305, 184772, 184773, 184774, 184775, 184776, 190456, 192454, 192749, 194521, 195199, 195220, 200893, 200894, 200895, 208067, 208937, 211279, 211366, 237812, 254335 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2085, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 30, ["flags"] = 0 } } },
[66029] = { ["id"] = 66029, ["name"] = "Temporal Tuning", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "Chronormu and Eternus are falling though time, but I sense them stop every so often. These brief moments are our opportunity to find them. < Nozdormu conjures a small chrono crystal .> I have imbued this crystal with power as well as my own temporal resonance. They have gone to a... troubling possible future. Find them and use it. Hopefully you can fix their position in time before they slip away again.", ["objectivesText"] = "Use Chrono Crystal on Eternus and Chromie in the Primalist Future to stop them from falling through time.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192454, 192749, 194521 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 31, ["flags"] = 0 } } },
[66030] = { ["id"] = 66030, ["name"] = "Resistance Isn't Futile", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13992, ["mapID"] = 2085, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "The temporal ripples have caused trouble for the people here. Enemies appear where they were not, or are far stronger than they should be. These changes are small, but they are disastrous. I ask you to help the resistance fighters here. Heal their wounds so that they may fight once more. Set their timeline back on its correct course, as if it had never interacted with our own. It is not much, but it is what we can do for them.", ["objectivesText"] = "Heal resistance fighters in the Primalist Future. Progress: Have you assisted the resistance?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192454, 192467, 192749, 194521 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13992 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2085, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 32, ["flags"] = 0 } } },
[66031] = { ["id"] = 66031, ["name"] = "Making Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 2085, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "I guess I shouldn't be surprised to find myself here. This is not the Azeroth I wanted, but it's the one I have. We're fighting to preserve what's left and take the world back, but your arrival has caused some trouble. We use the essence of those elementals out there to fuel our protections and keep ourselves safe. See that shield? That's the only thing keeping us from discovery and annihilation and you drained our resources. Bring back some of that essence and we may survive another day.", ["objectivesText"] = "Collect Elemental Essence for the survivor's camp. Progress: Have you collected what we need?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192454, 192749, 194521, 195185 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2085, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 33, ["flags"] = 0 } } },
[66032] = { ["id"] = 66032, ["name"] = "Return to the Present", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13992, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "This timeline is dark and chaotic. The disruption here has been severe. I shall remain in this timeline a moment more to help sort out what remaining ripples may appear. Return to Nozdormu . He will want to know of our success, even if it was less complete than we would like.", ["objectivesText"] = "Return to Nozdormu in the Present.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 192454, 192749, 194521 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13992 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 34, ["flags"] = 0 } } },
[66035] = { ["id"] = 66035, ["name"] = "Murloc Motes", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14092, ["mapID"] = 2092, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "An alternate timeline born from murlocs??! Forgive my selfishness, but would you obtain a few stray motes of temporal energy while you locate Ambassador Chronomu? Just walk into them and your staff should do the rest. I will examine the data later. When we are not in the middle of venturing through rips in Azeroth's varied realities.", ["objectivesText"] = "Drain 12 Temporal Motes. Progress: I have no doubt we shall succeed against the Infinite this day, and studying this foreign energy will be our reward!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192454, 192749, 194521, 195210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14092 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2092, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 37, ["flags"] = 0 } } },
[66036] = { ["id"] = 66036, ["name"] = "Mugurlglrlgl!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14092, ["mapID"] = 2092, ["storyline"] = { 66036, 67053, 70135, 70373, 71026, 71143 }, ["description"] = "Mrglgulglrrlglgul! Grurguglullgurl! Gruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl. Mgrgulllglll gurl gugll. <You aren't certain what's being said, but there are lots of stabbing motions. It seems like this murloc wants you to kill something.>", ["objectivesText"] = "Murglgulglrrlglgul! Progress: Murglgulglrrlglgul!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 158149, 192454, 192749, 194521, 195210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14092 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2092, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 38, ["flags"] = 0 } } },
[66037] = { ["id"] = 66037, ["name"] = "Back to Reality", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14092, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "We were able to increase Ambassador Chronormu's connection to our time. I am certain when we find her again, we will be able to finish the ritual. For now, let us return to our present and a world with... significantly fewer murlocs.", ["objectivesText"] = "Return to Nozdormu in the Present.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 192454, 192749, 194521 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14092 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 42, ["flags"] = 0 } } },
[66038] = { ["id"] = 66038, ["name"] = "Race Through Time!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13996, ["mapID"] = 2089, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "<name>, we must act quickly to catch up to Ambassador Chronormu, and I mean that quite literally. Zera and I will do what we can to speed our progress, but it is imperative we avoid entangling with this time period as much as possible. To do so will slow us down and we may not be able to catch the Ambassador before she is lost to even Nozdormu's magic. We haven't a moment to lose! (Accepting this quest will begin a timer)", ["objectivesText"] = "Race through time, following Chromie and Eternus's Path.", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 192454, 192749, 194521 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13996 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2089, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 44, ["flags"] = 0 } } },
[66039] = { ["id"] = 66039, ["name"] = "Chromie Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13996, ["mapID"] = 2089, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["series"] = { 66040, 66221 }, ["description"] = "This... This is the Black Empire. We have traveled very far into the past, indeed. Look! I see Ambassador Chronormu and Eternus! We need to hurry and complete the ritual. Even my curiosity is not enough to wish to see where they might travel to next.", ["objectivesText"] = "Find Chromie and Complete the Temporal Stabilization Ritual.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 64482, 192454, 192749, 194521 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13996 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2089, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 45, ["flags"] = 0 } } },
[66040] = { ["id"] = 66040, ["name"] = "Back to the Future", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13996, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["series"] = { 66039, 66221 }, ["description"] = "We're not going to fall through time anymore but we're far in the past. Waaaaay far in the past. \"The Titans Haven't Visited Azeroth Yet\" far in the past. Getting home is going to be... tricky. But we dragons can do it! We're going to need you to keep those Black Empire minions off our backs though. It shouldn't take too long! I think. Probably. Don't worry about it! Just keep those creepy monsters away and we'll handle the rest! Easy!", ["objectivesText"] = "Defend your allies against the Black Empire until the temporal portal is created. Progress: This has been an... unexpected turn of events.", ["rewardGold"] = 842700, ["rewardXP"] = 8200, ["rewardItems"] = { 21671, 192454, 192749, 194521, 195220 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13996 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 46, ["flags"] = 0 } } },
[66044] = { ["id"] = 66044, ["name"] = "Taking the Walls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "Sabellian and the other dragons are holding back the djaradin for now. We must act quickly to secure the high towers and ensure our victory. You and I shall clear the siege arbalests that threaten us from above. Let me know when you are ready.", ["objectivesText"] = "Eliminate the three Siege Arbalests and Champion Choruk . Progress: Are the Arbalests and Champion Choruk defeated?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186933, ["x"] = 0.29, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 196265, ["x"] = 0.264, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 38, ["flags"] = 0 } } },
[66048] = { ["id"] = 66048, ["name"] = "Best Plans and Intentions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "Attacking the djaradin controlling the Obsidian Citadel will be no easy task. Even with Wrathion and his Blacktalon forces, this will be a fierce battle. Wrathion may be confident, but... I am not so certain. Perhaps we can speak to those helping to plan the strategy, and see if we can find any room for improvement.", ["objectivesText"] = "Review the plans with the various members of Wrathion 's forces. Progress: Can you improve our odds of success?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192795, ["x"] = 0.424, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186274, ["x"] = 0.424, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 34, ["flags"] = 0 } } },
[66049] = { ["id"] = 66049, ["name"] = "Obsidian Oathstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "When Neltharion became the Earth-Warder, he swore an oath to protect this world, <name>. To safeguard the deep places of the earth and, with his flight, to serve as Azeroth's defenders. The Obsidian Oathstone represents that promise. We must activate the stone and let the Dragon Isles know that the black dragonflight has returned! Follow me, <name>.", ["objectivesText"] = "Locate the Obsidian Oathstone. Progress: Have you seen the Oathstone?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 196265, ["x"] = 0.264, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187045, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.264, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 39, ["flags"] = 0 } } },
[66055] = { ["id"] = 66055, ["name"] = "A Shattered Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "The Oathstone is damaged! There are pieces missing. Do what you can to recover the fragments... maybe there is a way to fix the stone!", ["objectivesText"] = "Recover 12 Oathstone Fragments . Progress: Have you found the missing fragments of the Oathstone?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191131, 192548, 194358, 194359, 194360, 194361 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.315333, ["y"] = 0.635333 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 40, ["flags"] = 0 } } },
[66056] = { ["id"] = 66056, ["name"] = "Forging a New Future", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "The forge of the Earth-Warder is the most powerful of all the dragon forges in existence. Our ancestors used it to create the strongest weapons and armor to defend Azeroth. Within the hearth of that forge is the power necessary to reform the shattered fragments of the Oathstone. Let us go and prepare the forge for the work to be done.", ["objectivesText"] = "Prepare the Earth-Warder's forge. Progress: Have you finished the work we require?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.315333, ["y"] = 0.635333 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 41, ["flags"] = 0 } } },
[66057] = { ["id"] = 66057, ["name"] = "Restoring the Faith", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "The shattered fragments have been reformed. We are ready to repair the Oathstone. Go now and help Wrathion complete the repairs.", ["objectivesText"] = "Repair the Obsidian Oathstone.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 191131, 192548, 194339, 194340, 194341, 194342 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187495, ["x"] = 0.245, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.315333, ["y"] = 0.635333 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 42, ["flags"] = 0 } } },
[66071] = { ["id"] = 66071, ["name"] = "Flying Rocs", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66071 }, ["description"] = "The name is Professor Harleen Chirpsnide , infamous ornithologist extraordinaire! I came here to study the mythical bluefeather rocs of the Dragon Isles, but I suppose we've got bigger fowl to fry. I bet these harpies flew in from Kalimdor when the Isles opened up. They're highly invasive and feasting like a pack of ogres at the Bilgewater Casino buffet. Let's give the native rocs here a fighting chance. Take this medical kit and use it to get the injured ones back on their feet.", ["objectivesText"] = "Assist 8 Injured Bluefeather Rocs . Progress: Don't worry about using up my supplies. I'm good pals with the clerks at the Expedition's reimbursement office.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66078] = { ["id"] = 66078, ["name"] = "Sharp Practice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "For years I have fostered the Blacktalon, teaching and encouraging them to pursue the same heights you have reached. They may not have achieved the same lofty goals as yourself, but they are accomplished in their own right. They've made me proud. Each would be honored if you test their skills. I think you will see some of yourself in them.", ["objectivesText"] = "Test the skills of 8 Blacktalon Assassins and Avengers. Progress: Have you tested them and found them worthy?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186274, ["x"] = 0.424, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186274, ["x"] = 0.424, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 33, ["flags"] = 0 } } },
[66079] = { ["id"] = 66079, ["name"] = "Wrathion Awaits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "These eggs represent a new generation of dragonkind. They must be protected and fostered. Yet... my heart aches, and I worry for Wrathion . I fear his stubborn determination will lead to folly. You have been a trusted friend over the years, <name>. Perhaps you can go in my place, and help him. Seek him out at the Obsidian Bulwark. And please, watch over him. There are so few of his flight left.", ["objectivesText"] = "Meet with Wrathion at the Obsidian Bulwark.", ["rewardGold"] = 6380, ["rewardXP"] = 175, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187115, ["x"] = 0.46, ["y"] = 0.782 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186274, ["x"] = 0.424, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 31, ["flags"] = 0 } } },
[66080] = { ["id"] = 66080, ["name"] = "Temporal Difficulties", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "Hello, <class>. You're right on time! Some trouble up at the temple is causing the timeways to destabilize and spill out into the valley. Not only that, but a bunch of Timewalkers are missing! We've asked for extra help, but one of the new recruits hasn't arrived yet. Can you look for her? Be careful though, time's in a massive state of flux around the valley. There's no knowing what dangers are around!", ["objectivesText"] = "Find the missing recruit in the Flowing Forest in Thaldraszus .", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["rewardItems"] = { 192602, 192809, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187877, ["x"] = 0.575, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187098, ["x"] = 0.562, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 15, ["flags"] = 0 } } },
[66081] = { ["id"] = 66081, ["name"] = "Time is Running Out", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "With the bronze temple under attack temporal energy is seeping out everywhere. The Timewalkers placed collectors all through this forest trying to gather all the errant magic. Anything collected can also be used as extra power! Which is a good thing, this crisis is draining all our resources. I was supposed to retrieve the collectors, but I still need a moment to catch my breath. Could you get them for me?", ["objectivesText"] = "Collect 8 Temporal Collectors in the Flowing Forest of Thaldraszus . Progress: Were you able to find them all?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192602, 192809, 195207, 195209, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187098, ["x"] = 0.562, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187098, ["x"] = 0.562, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 17, ["flags"] = 0 } } },
[66082] = { ["id"] = 66082, ["name"] = "Time in a Bottle", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "Great! The Timewalker staff intact! But, it is definitely drained. I know! You can recharge it using the temporal energy coalescing around the wildlife here. Unfortunately, that means defeating affected creatures in the forest. The energies were making them dangerous and unstable, and we would have had to cull the population after anyhow... Sometimes you have to sacrifice for the greater good. Could you help? I still need a minute.", ["objectivesText"] = "Collect time energy from slain time-charged wildlife within the Flowing Forest of Thaldraszus .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192602, 192809, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187098, ["x"] = 0.562, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187098, ["x"] = 0.562, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 18, ["flags"] = 0 } } },
[66083] = { ["id"] = 66083, ["name"] = "Feels Like the First Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "Shepherding the timeways is a dangerous duty. Though you are not a Timewalker, Ambassador Chronormu believes you will be of great help. But to ensure your safety we must properly train you. Unfortunately, all our instructors are still missing. I will do my best to help. Let us see how we both do. I know the Ambassador Chronormu is counting on the both of us.", ["objectivesText"] = "Speak with Andantenormu and participate in Timewalker training.", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["rewardItems"] = { 192602, 192809, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187877, ["x"] = 0.575, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187877, ["x"] = 0.575, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 19, ["flags"] = 0 } } },
[66084] = { ["id"] = 66084, ["name"] = "Times Like These", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "Despite that small hiccup during training, I believe you are prepared enough to aid us here. The distortions in the valley are allowing different time periods to cross over into ours. We are unsure why these timelines connect which is quite alarming. We need more information. Please, see if you can find anything about the creatures pouring in from different timelines. I am sure their passage will have left some sort of residue. By studying it we can hopefully find a way to get ahead of this crisis.", ["objectivesText"] = "Collect 100 Temporal Residue from time-lost enemies in the Shifting Sands. Progress: While it is unfortunate this is all happening, I am eager to discover new chronologies to study.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192602, 192809, 195212, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187877, ["x"] = 0.575, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187877, ["x"] = 0.575, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 20, ["flags"] = 0 } } },
[66085] = { ["id"] = 66085, ["name"] = "If We Could Turn Back Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "A proper Timewalker never leaves a crisis half-resolved. Why wait and study when we have the tools we need already? Since you have my original staff, I found a spare for me to use. I am sure no one will miss it. This is my plan: we team up on those rifts together and save the day! All the days, really. Sorry, I still get confused about the time stuff. What do you say? The task should be simple enough, right?", ["objectivesText"] = "Close the Time Rifts in the Shifting Sands with Siaszerathel .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192602, 192809, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187098, ["x"] = 0.562, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187098, ["x"] = 0.562, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 21, ["flags"] = 0 } } },
[66087] = { ["id"] = 66087, ["name"] = "Closing Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "These incursions push the durability of this timeline to the point of breaking. If only we had our full contingent of Timewalkers! Though you are a novice with the staff, I am told that you have managed to help us out greatly. With an extra push, I believe you may further aid our cause. Normally, I would put you through a full training but the times are... unorthodox. Take this scroll of advanced knowledge and use it to push back the invaders! Be swift though, the effects are only temporary.", ["objectivesText"] = "Assist the Timewalkers by slaying time-lost enemies, buffing bronze allies, returning lost artifacts, and closing time rifts in the Shifting Sands. Progress: Every incursion threatens to weaken this timeline.", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 158075, 192602, 192809, 194520, 195196, 195197, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190929, ["x"] = 0.575, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190929, ["x"] = 0.575, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 22, ["flags"] = 0 } } },
[66094] = { ["id"] = 66094, ["name"] = "The Ruins of Szar Skeleth", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "According to the watcher's logs, the stone of Insight can be found in a draconic tower on a river in the center of the Ohn'ahran Plains. That should be Szar Skeleth. Be careful. We can be sure the Sundered Flame won't let us just walk in and take it. Once you get there, rendezvous with Toddy. Then we can retrieve the stone.", ["objectivesText"] = "Meet up with Toddy near Szar Skeleth in the Ohn'ahran Plains.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191159, ["x"] = 0.4, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2023, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 6, ["flags"] = 0 } } },
[66100] = { ["id"] = 66100, ["name"] = "Supplying in Weight", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66100 }, ["series"] = { 66448, 71219 }, ["description"] = "I really screwed up this time. I only stepped away from the campsite for a moment, but I barely returned in time to see the tarasek snatching up everything I had not bolted down. Those supplies were expensive, and I can't exactly ask for help getting more! My sister Nori thinks I'm inept enough as it is. If you are sure you want to head through the valley, would you mind keeping an eye out for any stray bags of supplies?", ["objectivesText"] = "Collect 6 bags of Waywatcher Supplies . Progress: <Alvi glances in your direction, clearly panicked. The missing supplies seem to be the last thing on her mind at the moment.>", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191308, 191317, 191405, 191852 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 191753, ["x"] = 0.546, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 }, { ["mapID"] = 2025, ["npcID"] = 191753, ["x"] = 0.546, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66101] = { ["id"] = 66101, ["name"] = "From Such Great Heights", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66101 }, ["description"] = "Toddy and Naleidea have requested a survey report of the surrounding area immediately. Luckily, I have acquired an enchanted telescope and surveyor's disc that will help us scout out nearby areas from the safety of the clouds. Unluckily, I am deathly afraid of heights and cannot bring myself to set foot on the contraption. You are not afraid of heights, are you?", ["objectivesText"] = "Use the Surveyor's Disc to bounce into the sky and scout the area. Progress: Good luck up there. I much prefer the ground under my feet.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187257, ["x"] = 0.758, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187257, ["x"] = 0.758, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66104] = { ["id"] = 66104, ["name"] = "Forensic Ecology", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66104 }, ["description"] = "I'm at my wits end, <name>. Tharu and I have made our way through nearly all the corpses only to stumble at the end because we cannot agree on a methodology. If only he would just listen to me! < Ecologist Iskha sighs.> The stress of the situation is getting to us both. I don't even have a firm hypothesis yet. You look like you have a strong stomach. Will you take over on these last two gorlocs? You can borrow my scalpel.", ["objectivesText"] = "Dissect the gorloc corpses. Progress: Don't worry, you'll get used to the smell after a while.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191546, 191549 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186410, ["x"] = 0.744, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186410, ["x"] = 0.744, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.744, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66105] = { ["id"] = 66105, ["name"] = "A Scalpel of a Solution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66105 }, ["description"] = "I believe we are gathering enough data safely from here but... Tharu is an exceptional ecologist and prefers we take action. Still, the ecosystem is fragile, and we may damage it if we are not careful. I do however agree we don't have much time. It might be worth indulging him. A little. Culling the rampaging elementals ought to buy us time without impeding our research. Be sure to cull them in equal numbers--we don't want to throw things further out of balance.", ["objectivesText"] = "Kill 5 Rampaging Water and 5 Rampaging Wind . Progress: Is it done? Can I finally get Tharu off my back about this?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191546, 191549, 194350, 194351 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186410, ["x"] = 0.744, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186410, ["x"] = 0.744, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.744, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66106] = { ["id"] = 66106, ["name"] = "Don't Be So Shellfish", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66106 }, ["description"] = "I was a fool to doubt Iskha when he insisted there was more to this. He wouldn't be my mate if he wasn't always two steps ahead of me. We can make it up to him--by taking action, of course. If it's shells that are causing all this elemental chaos, why don't you go into their camp and take those shells right out of their slimy hands? Bring back piles of the wind and water shells, enough for Iskha to research to his heart's content.", ["objectivesText"] = "Collect 15 Water-Infused Shells and 15 Wind-Infused Shells from Soggymaw and Windyfin Gorlocs. Progress: That ought to show them.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191546, 191549 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186428, ["x"] = 0.745, ["y"] = 0.421 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186428, ["x"] = 0.745, ["y"] = 0.421 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.745, ["y"] = 0.421 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66107] = { ["id"] = 66107, ["name"] = "Wildlife Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66107 }, ["description"] = "It doesn't take an ecologist to see that the wetlands are in real trouble. But Iskha's got us stuck here examining dead creatures when we ought to be stopping them from dying in the first place! The red dragonflight is about preserving life--not dissecting it! I love Iskha, and he's good at what he does, but if we wait until he's done puttering, there won't be any wetlands left to save. I'll manage his overthinking. You get out there, get your boots muddy, and rescue some wildlife.", ["objectivesText"] = "Rescue the wildlife of the Restless Wetlands.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191546, 191549 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186428, ["x"] = 0.745, ["y"] = 0.421 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186428, ["x"] = 0.745, ["y"] = 0.421 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.745, ["y"] = 0.421 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66108] = { ["id"] = 66108, ["name"] = "A Sledgehammer of a Solution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66108 }, ["description"] = "While I'm glad Tharu now sees my point of view, I'm also grateful he had you rescue wildlife while I was dawdling. The situation is much more dire than anticipated; he was right to take action. With what we've learned, I fear this elemental bombardment won't stop until we've dealt with the gorlocs. If I were Tharu and thinking actionably, I would go straight for their leaders. Without anyone to rally around, the fighting should dissipate and no longer threaten the wetlands.", ["objectivesText"] = "Slay Sogglmoggl , King of the Soggymaw and Whirglgurgl , King of the Windyfin. Progress: This should buy us some room to breathe while we clean up this mess.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191546, 191549, 194411, 194412 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186410, ["x"] = 0.744, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186410, ["x"] = 0.744, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.744, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66110] = { ["id"] = 66110, ["name"] = "Give Peace a Chance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66110, 66111, 66704, 70371, 71025, 71144 }, ["description"] = "Aka'Magosh, $p. This expedition is under the protection of both the Horde and the Alliance. Our instructions are clear: give aid to any members of the Dragonscale Expedition regardless of their other allegiances. The Alliance's representatives, Captain Garrick and her son Henry, stand guard on the other side of camp. I fought with Captain Garrick against the scourge. She is honorable and will serve the Expedition well. Go offer her your assistance. Show her that the Horde honors its agreements.", ["objectivesText"] = "Introduce yourself to the Alliance representatives.", ["rewardGold"] = 715, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184452, ["x"] = 0.762, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 184449, ["x"] = 0.766, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 10, ["flags"] = 0 } } },
[66111] = { ["id"] = 66111, ["name"] = "Encroaching Elementals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66110, 66111, 66704, 70371, 71025, 71144 }, ["description"] = "The crafters, artisans, and explorers of the Dragonscale Expedition are ill-suited to the vigors of battle. But not you and I, $p. Here in the Dragon Isles, let us use that strength to protect those who can't protect themselves. Clear out the elementals encroaching from the north, so the expedition can focus on their noble pursuits.", ["objectivesText"] = "Kill 15 primal elementals in Wingrest Embassy.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184449, ["x"] = 0.766, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 184449, ["x"] = 0.766, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 11, ["flags"] = 0 } } },
[66112] = { ["id"] = 66112, ["name"] = "Always Be Crafting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66112 }, ["description"] = "Have ye ever seen such powerful elementals?! <Grun cheers.> I hear the guards grumblin' 'bout havin' to fight 'em all the time, but they're missin' the big picture... Bigger elementals means bigger craftin' components! While you're out there clearin' the elementals for our safety or whate'er it is ye be doin', be sure to pick up pieces of the biggest ones ye can find. I want tae try makin' somethin' out of 'em!", ["objectivesText"] = "Collect a Primal Molten Core . Progress: I'm gonna build a grand helmet first... No, a hammer... No, a BIG hammer!", ["rewardGold"] = 7150, ["rewardXP"] = 1415, ["rewardItems"] = { 190386, 194548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187261, ["x"] = 0.764, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187261, ["x"] = 0.764, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66114] = { ["id"] = 66114, ["name"] = "For the Benefit of the Queen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "We safeguard our precious eggs to protect the future of all dragonflights. The Primalists do not simply threaten pain or anguish with their actions. They threaten us with extinction. I must inform our queen at once.", ["objectivesText"] = "Ride with Majordomo Selistra to the Ruby Lifeshrine.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186795, ["x"] = 0.55, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187290, ["x"] = 0.622, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 13, ["flags"] = 0 } } },
[66115] = { ["id"] = 66115, ["name"] = "The Mandate of the Red", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "Our calling is care and compassion. We aid the other flights not only for their own sake, but for the sake of dragonkind as a whole. Perhaps speaking with the dragonspawn here at the Ruby Lifeshrine will help you understand us further.", ["objectivesText"] = "Talk to the tenders at the Ruby Lifeshrine. Progress: The red dragonflight preserves the future of us all.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 188139, 192436, 194034, 194343, 194344, 194345, 194346, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187290, ["x"] = 0.622, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189260, ["x"] = 0.626, ["y"] = 0.704 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 22, ["flags"] = 0 } } },
[66116] = { ["id"] = 66116, ["name"] = "The Primary Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "There are far too many vulnerable eggs to secure. If the enemy breaks through, all is lost! I am sure our guards are mustering on the field to push them back. Speak to Commander Lethanak , and he will use your strength where it will be most helpful.", ["objectivesText"] = "Find Commander Lethanak at the Flashfrost Assault. Progress: I need all the help I can get.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190293, ["x"] = 0.595, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187119, ["x"] = 0.594, ["y"] = 0.758 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 25, ["flags"] = 0 } } },
[66117] = { ["id"] = 66117, ["name"] = "Clear the Battlefield", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66117 }, ["objectivesText"] = "Stop the primalist assault", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Stop the primalist assault", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66118] = { ["id"] = 66118, ["name"] = "Basalt Assault", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "Raszageth and her Primalists have summoned towering earth elementals to break our walls. They must be stopped!", ["objectivesText"] = "Destroy 4 Enraged Cliffs in the Flashfrost Assault. Progress: They will do anything they can to destroy our walls!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 188139, 192436, 194034, 194366, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187119, ["x"] = 0.594, ["y"] = 0.758 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187119, ["x"] = 0.594, ["y"] = 0.758 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.758 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 26, ["flags"] = 0 } } },
[66119] = { ["id"] = 66119, ["name"] = "Ruby Life Pools: Primalist Invasion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14063, ["mapID"] = 2022, ["storyline"] = { 66119 }, ["description"] = "The Primalists have torn their way into our home. We were not prepared for such an intense attack... several got through. One of our drakonid ventured in to follow them, but he has not reported his findings. I fear the worst. I will stand guard. No more shall breach our walls while we draw breath, but you must stop those who made it inside. Go!", ["objectivesText"] = "Enter the Ruby Life Pools and stop the Primalist attack. You can enter the Ruby Life Pools solo by queuing for it in Follower Dungeons. Progress: They will destroy our future if we cannot stop them.", ["rewardGold"] = 1123600, ["rewardXP"] = 2830, ["rewardItems"] = { 193750, 193751, 193753, 193757, 193763, 193765 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187145, ["x"] = 0.598, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187145, ["x"] = 0.598, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 14063 } }, ["questType"] = "dungeon" },
[66121] = { ["id"] = 66121, ["name"] = "Egg Evac", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "The Primalists have stolen our eggs for their perverse rituals! They must be stopped. Help us recover our eggs before it is too late. Mark each egg as you find them, $p. I will ensure they are safely extracted from the area.", ["objectivesText"] = "Rescue 4 eggs from the Flashfrost Enclave.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187129, ["x"] = 0.595, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191895, ["x"] = 0.536, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 28, ["flags"] = 0 } } },
[66122] = { ["id"] = 66122, ["name"] = "Proto-Fight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "These proto-dragons detest us. They believe we are a twisted version of dragonkind that is manipulated and chained by the Titans. They do not understand. Which is why they feel safe even as they throw their forces at our walls. They are mistaken. Take this spear, $p. Kill our enemies.", ["objectivesText"] = "Defeat 3 proto-dragons in the Flashfrost Enclave. Progress: They intend to harm our dragons. They deserve no mercy.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406, 199822 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187119, ["x"] = 0.594, ["y"] = 0.758 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187129, ["x"] = 0.595, ["y"] = 0.76 }, { ["mapID"] = 2022, ["npcID"] = 191895, ["x"] = 0.536, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.758 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 27, ["flags"] = 0 } } },
[66123] = { ["id"] = 66123, ["name"] = "Cut Off the Head", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "Jadzigeth , one of Raszageth's foul lieutenants, proudly leads the Primalists here. Let us show them all what happens to those who stand against us.", ["objectivesText"] = "Defeat Jadzigeth in the Frostflash Enclave. Progress: There is no other path.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 188139, 192436, 194034, 194354, 194355, 194356, 194357, 197365, 197378, 197380, 197406, 237812, 263374, 263375, 263376, 263378 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191895, ["x"] = 0.536, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191895, ["x"] = 0.536, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 29, ["flags"] = 0 } } },
[66124] = { ["id"] = 66124, ["name"] = "Exeunt, Triumphant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "From what I saw, the queen fell back to the Wild Hatchery. It is an outpost to keep watch over the proto-drakes in the area... I only hope that its defenses are enough. We must head there at once!", ["objectivesText"] = "Escape the Frostflash Enclave with Majordomo Selistra . Progress: My queen...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191895, ["x"] = 0.536, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187278, ["x"] = 0.462, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 30, ["flags"] = 0 } } },
[66128] = { ["id"] = 66128, ["name"] = "Next Steps", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2025, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "These stones are an incredible discovery, even if their intended use is never realized. But before we try them out, we have a process to adhere to. They must be examined and cataloged, and reports sent and received to both the Reliquary and Explorers' League headquarters. Let's meet back at basecamp. We can go over what's next.", ["objectivesText"] = "Meet with Toddy and Naleidea in the Explorer's tent at the Dragonscale Basecamp in the Waking Shores. Progress: Oh ye wouldn't believe the plans I have to get into that facility!", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190865, ["x"] = 0.644, ["y"] = 0.15 }, { ["mapID"] = 2023, ["npcID"] = 191159, ["x"] = 0.4, ["y"] = 0.674 }, { ["mapID"] = 2024, ["npcID"] = 193350, ["x"] = 0.538, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187276, ["x"] = 0.472, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.15 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023, 2024, 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 10, ["flags"] = 0 } } },
[66134] = { ["id"] = 66134, ["name"] = "Azeroth Pest Control", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66134 }, ["description"] = "You there! Hatchling! Lend me a hand, won't you? These podlings are ripping up all my plants! All kinds of elementals have invaded the gardens, and they seem to be... affecting the wildlife. It's like their energy has driven these podlings mad! More mad than usual! I've got my hands full with just these three. Please! Before they rip up all my flower beds.", ["objectivesText"] = "Kill 8 Agitated Seedlings in the Gardens. Progress: I'm too old to be fighting podlings!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66135] = { ["id"] = 66135, ["name"] = "The Gardener's Apprentice", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66135 }, ["description"] = "Basilton! Lord Basilton, where are you? My executive assistant and apprentice, Lord Basilton, has gone missing! He loves to explore, but he's even worse at defending himself than I am. I'm a gardener, not a warrior! Could you please go find that layabout? I need him here so I can think. He's usually in the shed, digging through piles of junk. Be careful though. He can be a bit prickly at first.", ["objectivesText"] = "Search for Lord Basilton in the Garden Shed by cleaning up Piles of Junk. Progress: At my age, an executive assistant is a necessity.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66136] = { ["id"] = 66136, ["name"] = "Elemental Extract", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66136 }, ["description"] = "A huge fire elemental destroyed the pond a few days ago. I think it's behind all this ruckus, but it's too big to fight. We need to weaken it somehow. But don't count Old Gryrmpech out just yet, I have a plan! Water elementals decided to make themselves at home in the Blue flight's gazebo. If you can collect enough essence from them, we might be able to use their magic against them. Fight fire with fire, right? Well, fight fire with water, I guess. Anyway, you should probably get going.", ["objectivesText"] = "Collect 5 Watery Essence in the Gardens. Progress: In all my years, I've never seen so many elementals in one place. So why did it have to be my gardens?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 30262, 30263, 30264, 30516, 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66137] = { ["id"] = 66137, ["name"] = "Lashing Out", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66137 }, ["description"] = "I'm sure the podlings aren't the only wildlife acting like hooligans. Alexstrasza's tree has always been a thorn in my side. Her life magic draws all sorts of plants and animals to it, good and bad. And guess who has to take care of the bad ones? Old Gryrmpech , that's who! Aspects above, I'm getting too old for this. The stewards aren't trained in combat, so it is up to you to take care of the Life-Binder's weed problem.", ["objectivesText"] = "Kill 10 Invasive Deathblossoms and Lasher Weedlings in the Gardens.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66138] = { ["id"] = 66138, ["name"] = "Like Sands Through the Hourglass", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66138 }, ["description"] = "Like the rest of the gardens, Nozdormu's hourglass has had to weather the elemental unrest. Turbulent wind elementals came through and scattered the magical sand contained within. Without this sand, Nozdormu's influence here is greatly diminished. As a steward-in-training, I have been tasked with overseeing the hourglass at all times. If you would collect the sand in my stead, I would be eternally grateful.", ["objectivesText"] = "Collect 8 Piles of Windswept Time Sand in the Gardens. Progress: I can rest easy knowing Nozdormu has already foreseen your success.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187310, ["x"] = 0.352, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187310, ["x"] = 0.352, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66139] = { ["id"] = 66139, ["name"] = "Flame at Last", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66139 }, ["description"] = "Alright, youngling, I've placed all the water elemental essences in this jar for you. If you just toss it at the big one, it should work. I mean, when has water not worked against fire? It's foolproof. The heat, uh, isn't good for my joints, so I'll just stay here. I trust you can handle it. Good luck, young one!", ["objectivesText"] = "Use the Concentrated Essence of Water to defeat the Blazing Inferno in the Gardens. Progress: You remind me of myself, when I was your age. Nothing could stand in the way of Gryrmpech !", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66141] = { ["id"] = 66141, ["name"] = "Broken Traditions, Broken Bodies", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66141 }, ["description"] = "My fellow furbolg are no longer themselves. They have done... bad things. Now, they have become worse things. Furbolg has never fought furbolg! My brother and I escaped them. I came here looking for help. He remains by our clan's den. Help us before our clan is lost!", ["objectivesText"] = "Meet Garz and Narn on the way to Rustpine Den.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187301, ["x"] = 0.632, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187308, ["x"] = 0.634, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66147] = { ["id"] = 66147, ["name"] = "Crystals in the Water", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66147 }, ["description"] = "We might not look it this moment, but we are professionals. The Expedition entrusted us with finding a clutch of rare crystals in the area--a geological survey if you will. I'm still collecting myself after the gorloc attack. Would you be a dear and go look for these crystals? Bring samples back if you can.", ["objectivesText"] = "Collect 4 Crystal Samples in Gorloc Shore. Progress: Fieldwork is exhausting.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187156, ["x"] = 0.076, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187156, ["x"] = 0.076, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.076, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66148] = { ["id"] = 66148, ["name"] = "Former Furbolg Family", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66148 }, ["description"] = "Primalists came. They offered us new strength: the command of the elements. I did not think Stoneheart would accept their gifts. Our clan did not need power. He thought nothing of the cost. His terrible decision cannot be unmade. The magic has corrupted my clan--like disease rots a root. My heart breaks, but culling the corrupted is the only way.", ["objectivesText"] = "Kill 15 Rustpine furbolg and elementals, then meet Narn further in Rustpine Den. Progress: It must be done.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187308, ["x"] = 0.634, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187534, ["x"] = 0.608, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66149] = { ["id"] = 66149, ["name"] = "Elemental Influence", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66149 }, ["description"] = "Narn says not all the Rustpines followed Stoneheart or the Primalists. Some resisters are held against their will. Totems spewing rock and mud restrain them... to force them to obey. Shatter the totems. Set them free!", ["objectivesText"] = "Destroy 3 Primalist Earthbind Totems, then meet Narn further in Rustpine Den. Progress: My friends do not deserve this fate.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187308, ["x"] = 0.634, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187534, ["x"] = 0.608, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66150] = { ["id"] = 66150, ["name"] = "Rescuing Radza", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66150 }, ["description"] = "Radza Thunderclaw is our Spiritkeeper. She holds true our traditions and history. Primalist beliefs go against everything our clan holds true. I knew she would defy Stoneheart! Stoneheart will do anything to bring her to heel. No one is chieftain without Radza's blessing! Narn says Khargall Fivefangs , the Chieftain's guard, is trying to break her. If Radza dies, our clan dies with her. Go aid her, <name>, and be ready. He will not let her go without a fight.", ["objectivesText"] = "Rescue Radza Thunderclaw .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187308, ["x"] = 0.634, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187616, ["x"] = 0.609, ["y"] = 0.509 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66151] = { ["id"] = 66151, ["name"] = "His Stone Heart", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66151 }, ["description"] = "We howl with grief for our chieftain, yet he lives. What remains of Stoneheart is in the cave ahead. Many tried to reason with him. He killed them--and almost killed Narn. He is a monster! This is the goal of the primalists. They would turn us into stone and flame to serve them. There is no Rustpine left in him. He must be destroyed before others meet the same fate.", ["objectivesText"] = "Kill Stoneheart . Progress: Our chieftain wanted power to protect the clan... but it took everything from us.", ["rewardGold"] = 280900, ["rewardXP"] = 5145, ["rewardItems"] = { 184373, 184374, 190454, 191983, 191984, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192001, 192003, 192004, 192005, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192037, 197931, 198002, 198003, 198004, 198006, 198009, 198034, 198490, 198529, 198532, 198695, 205423, 209837, 217242 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187616, ["x"] = 0.609, ["y"] = 0.509 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187616, ["x"] = 0.609, ["y"] = 0.509 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.609, ["y"] = 0.509 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66152] = { ["id"] = 66152, ["name"] = "Nowhere to Go", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66152 }, ["description"] = "We cannot stay here. I do not know what to do... where to go next... We will return to your Camp Nowhere. The tuskarr should know what happened at Rustpine. If we tell our story and keep it, maybe it will not happen again...", ["objectivesText"] = "Meet Garz at Camp Nowhere.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187535, ["x"] = 0.61, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 188897, ["x"] = 0.632, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66154] = { ["id"] = 66154, ["name"] = "Salivatory Samples", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66154 }, ["description"] = "<The gaunt undead pinches the bridge of his nose and sighs heavily.> This is going to reflect very poorly on my record. Somehow in a single day we've managed to stir up the local gorlocs, lose half of our equipment, and are now down a dwarf. In this situation, protocol dictates that we be as efficient as possible. Go thin out some of our toothy antagonists and bring me their saliva for further testing while you're at it. Only the good stuff, mind you.", ["objectivesText"] = "Collect 12 Saliva Samples in Gorloc Shore. Progress: Have you secured the samples?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187136, ["x"] = 0.076, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187136, ["x"] = 0.076, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.076, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66155] = { ["id"] = 66155, ["name"] = "Ruriq's River Rapids Ride", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66155 }, ["description"] = "I did not expect my brother's approval... but it is welcome, all the same. The time has come! Let's see if our hard work has paid off! Join me in The Fallstrider, <name>, and we shall take off down the river, catching fish for Iskaara as we go!", ["objectivesText"] = "Ride the Fallstrider down the river. Progress: With all of our hard work together, I'm certain our trip will be successful.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191091, 191092, 191199, 197607, 198428, 199826, 199827, 199828, 199829 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 }, { ["mapID"] = 2024, ["npcID"] = 190287, ["x"] = 0.342, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4515, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66159] = { ["id"] = 66159, ["name"] = "A Message Most Dire", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66244 }, ["description"] = "Kalecgos would not speak of what happened in the Azure Span till you arrived. Whatever he has to share gives me a terrible sense of foreboding, <name>.", ["objectivesText"] = "Speak with Alexstrasza at the Seat of the Aspects within Valdrakken.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 1, ["flags"] = 0 } } },
[66163] = { ["id"] = 66163, ["name"] = "Nowhere to Hide", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "Welcome to Valdrakken, <race>. The climate in the city has been a bit warm of late, and I do not mean the weather. The Primalists are skulking about, fomenting dissent among the citizens of our city. Our foes are crafty. They have been disguising themselves as citizens of our city to hide from the Scalesworn. They know how to avoid my guards but will not suspect an outsider. Take this Dragon's Eye gem, it should help you see through their disguises. Go reveal and kill these infiltrators!", ["objectivesText"] = "Kill 6 Primalist Infiltrators within Valdrakken. Progress: Have you taken care of our infiltrator problem?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 158149, 191269, 192758, 192759, 198859, 211279 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5676, ["y"] = 0.4108 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 2, ["flags"] = 0 } } },
[66164] = { ["id"] = 66164, ["name"] = "Fishy Fingers", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66164 }, ["description"] = "Now that Mordigan's off licking rocks, we can get to the crux of the problem... Those perfidious fishmen have pilfered my parts! We weren't in this dinky little village for more than an hour and WHAM! Gorloc were swarming all over us! Rowe was yelling, Aelnara was screaming, and I'm flailing around with my wrench like a madgnome! See if you can't salvage the situation and get some of my parts back!", ["objectivesText"] = "Recover 5 Stolen Parts in Gorloc Shore. Progress: This is sub-optimal.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187198, ["x"] = 0.076, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187198, ["x"] = 0.076, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.076, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66166] = { ["id"] = 66166, ["name"] = "Eyes and Ears", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "The Primalists have been spewing their propaganda among the citizens of Valdrakken. Our enemies are too wily to say anything in the presence of my Scalesworn, but perhaps you might be able to get close enough to eavesdrop on their conversations. I have marked locations on your map for further investigation. You may want to visit the Transmogrifier to see about changing your look to avoid any suspicion. Take this enchanted stone, as long as you have it on hand we will be able to communicate.", ["objectivesText"] = "Locate Clues within Valdrakken, and visit the Transmogrifier to learn how to change your appearance. Progress: Well, find anything useful?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 195204, 195205, 198859 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5676, ["y"] = 0.4108 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 3, ["flags"] = 0 } } },
[66167] = { ["id"] = 66167, ["name"] = "Southern Exposure", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "Based on your discoveries I suspect the Primalists are attacking Commander Eranog's Garrison at South Hold. But, my Scalesworn cannot leave the city as that would be exactly what the Primalists are hoping for. I need your help again, <name>. Travel to South Hold, see what kind of forces we are facing, and if possible make contact with the garrison guardians there.", ["objectivesText"] = "Travel to South Hold Gate in search of making contact with the garrison guardians.", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5676, ["y"] = 0.4108 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 4, ["flags"] = 0 } } },
[66169] = { ["id"] = 66169, ["name"] = "Vengeance, Served Hot", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "The Primalists caught us completely unawares. <Velomir spits in disgust.> My fellow guardians were ripped apart by these monsters. I would have joined them in death if you had not shown up when you did. Off in the distance I can still hear the sounds of battle. Perhaps others still live, maybe even Commander Eranog. Lend me your aid. I need you to cause a distraction so I can sneak to a position closer in. Killing a few of these so called \"Magmasworn\" would be perfect.", ["objectivesText"] = "Kill 12 Magmasworn Primalists within South Hold Gate. Progress: Do you have a bodycount for me, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 197110, 198859 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.826667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 5, ["flags"] = 0 } } },
[66173] = { ["id"] = 66173, ["name"] = "Hall of Samples", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66173, 66174, 66546, 66547, 66636, 67722, 69097, 71152 }, ["description"] = "Did you hear what that console said? There's a hall full of samples. Ancient titan machinery? Specimens from other worlds? Only Tyr knows what's in there! Let's change that.", ["objectivesText"] = "Explore the Hall of Samples. Progress: Do ye wonder what else the titans captured as \"samples?\"", ["rewardGold"] = 295000, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192820, ["x"] = 0.55, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 193374, ["x"] = 0.572, ["y"] = 0.526 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1374, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1374, ["name"] = "In the Halls of Titans", ["orderIndex"] = 4, ["flags"] = 0 } } },
[66174] = { ["id"] = 66174, ["name"] = "Hall of the Aspects", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66173, 66174, 66546, 66547, 66636, 67722, 69097, 71152 }, ["description"] = "The Hall of the Aspects, eh? Why would Tyr seal something like this away? Was he hidin' something? The implications are staggering--hopefully we'll find some answers in there.", ["objectivesText"] = "Explore the Hall of the Aspects. Progress: Let's pop through that transporter before Naleidea gets cold feet!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192820, ["x"] = 0.55, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1374, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1374, ["name"] = "In the Halls of Titans", ["orderIndex"] = 3, ["flags"] = 0 } } },
[66175] = { ["id"] = 66175, ["name"] = "Field Experiment", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66175 }, ["description"] = "Thanks to you, our geological survey is now operating at nearly 96% efficiency! <LOU-C furrows her eyebrows.> Those are rookie numbers. Help me run the samples you collected through my Geoscanner 289-07 . It should give us a baseline as to what exactly is going on at the plateau.", ["objectivesText"] = "Help LOU-C run her tests in Whaler's Nook. Progress: For science!", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187198, ["x"] = 0.076, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187198, ["x"] = 0.076, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.076, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66177] = { ["id"] = 66177, ["name"] = "No Dwarf Left Behind", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66177 }, ["description"] = "The salt levels here are off the charts! We need to find Mordigan and get him out of there. He must be dangerously dehydrated by now. He's only been gone a couple hours. See if you can't determine which path the grumpy old dwarf took!", ["objectivesText"] = "Follow Mordigan Ironjaw's path through Gorloc Shore.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187198, ["x"] = 0.076, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 188030, ["x"] = 0.108, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.076, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66178] = { ["id"] = 66178, ["name"] = "A Day in the Groves", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "Rymek was sent here by the blue flight to learn about and protect our gardens. I am glad for their support. We are few in number, and our losses have been great. The blue dragonflight commands powerful magic, so we can learn a great deal from each other. Come. Let us demonstrate the green dragonflight's important role here in the Dragon Isles.", ["objectivesText"] = "Meet Merithra and Rymek at the Leafy Repose in the Emerald Gardens.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 192547, 192555, 192558, 192744 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186955, ["x"] = 0.298, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187525, ["x"] = 0.332, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 0, ["flags"] = 0 } } },
[66179] = { ["id"] = 66179, ["name"] = "Seeds for the Future", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "The Primalists' attack left its mark on the Emerald Gardens. I wish to see it grow and flower once again. In this part of the garden, we have an overabundance of lashers. Their seeds can be used by the Sisters of the Garden to cultivate vegetation in those damaged glades. Thin out the lashers to collect their seeds, and then give those seeds to the Sisters. They sometimes struggle to inflict harm on any creature, even when it is in the best interest of the gardens overall.", ["objectivesText"] = "Collect seeds from various Lashers and give them to Sisters of the Garden . Progress: Have you collected the seeds?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744, 254335 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187525, ["x"] = 0.332, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187525, ["x"] = 0.332, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 1, ["flags"] = 0 } } },
[66180] = { ["id"] = 66180, ["name"] = "Wake the Ancients", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "There are many ways to keep the gardens safe, and we have allies to help us. A few Ancients rest dormant in these glades. They are giant trees sworn to defend the forest and the creatures within. Use this fragment of my breath to wake them.", ["objectivesText"] = "Use Merithra 's Borrowed Breath to wake Ancient Guardians in the Emerald Gardens.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744, 257244, 257245, 257246 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187525, ["x"] = 0.332, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187525, ["x"] = 0.332, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 2, ["flags"] = 0 } } },
[66181] = { ["id"] = 66181, ["name"] = "A Frenzied Defender", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "I have noticed that these gardens have rather diverse defenses, from the dragons to the drakonid and ancients... and even the wildlife! But there is one defender that seems to have become rather too zealous in its protectiveness. It even tried to swoop at me when I arrived! And since we know something has been killing within these groves, it cannot hurt to be too cautious. Unfortunately, this creature must be slain before it can do more damage.", ["objectivesText"] = "Slay the Frenzied Grovetalon . Progress: Have you found and put down that overzealous bird?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189850, ["x"] = 0.284, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189850, ["x"] = 0.284, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 3, ["flags"] = 0 } } },
[66182] = { ["id"] = 66182, ["name"] = "Gerithus's Research", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "The green dragonflight has many duties, not solely in the tending of the garden. We also defend the Emerald Dream, and some extend their attention even further. My son Gerithus , for example, has always had interest in all kinds of magic. You and Rymek should seek him out, to see what he is working on and help where you can.", ["objectivesText"] = "Meet Gerithus deeper in the Emerald Gardens.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 192547, 192555, 192558, 192744 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187525, ["x"] = 0.332, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189849, ["x"] = 0.284, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 4, ["flags"] = 0 } } },
[66183] = { ["id"] = 66183, ["name"] = "Emerald Tears", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "We may've only recently returned to the Emerald Gardens, relatively speaking, but we carry our long-lasting feelings with us. Many of us are still reeling from the death of Ysera, my grandmother. Including myself. I wish I had gotten to spend more time with her and to learn more from her. What amazing things she's seen in her life! In places like the Emerald Gardens, when we shed tears, they can crystalize and carry great power within them. I have an idea for how this galvanized grief could help us.", ["objectivesText"] = "Collect 8 Emerald Tears . Progress: Have you collected some of the Emerald Tears in the garden?", ["rewardGold"] = 295000, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744, 257266, 257267, 257268 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189849, ["x"] = 0.284, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189849, ["x"] = 0.284, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 5, ["flags"] = 0 } } },
[66184] = { ["id"] = 66184, ["name"] = "Anchors to Life", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "Based on my research, I believe there's a way to reestablish Ysera's ties to the Emerald Dream, so we can bring her closer to Azeroth. When Ysera died, the Winter Queen used her own power to restore her in Ardenweald. For now, she's bound there, but I think if we can just get Ysera over into the Emerald Dream, we can use these anchors to keep her there. But I'm getting ahead of everything. First, we have to infuse these anchors with the power of those Emerald Tears.", ["objectivesText"] = "Empower the Inert Anchors with the Emerald Tears. Progress: There is so much potential within ourselves.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744, 257286 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189849, ["x"] = 0.284, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189849, ["x"] = 0.284, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 6, ["flags"] = 0 } } },
[66185] = { ["id"] = 66185, ["name"] = "Across the Weald", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "It is time. I know I said that I was fine, but ever since Solethus' death, it's like I've been missing something essential. I am alive, and he is not. That feels... wrong. But there might be a way I can set things right. Ysera is the only one who can help us get control of Ancient Bough again. I think I can help bring her back. It's getting harder and harder to cross over. We need to make this count. Tyrande and Malfurion will meet us there.", ["objectivesText"] = "Meet Somnikus at the Grove of Awakening in Ardenweald.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 193221, 201437, 201439, 201779 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187594, ["x"] = 0.284, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 187634, ["x"] = 0.458, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 1565, 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 7, ["flags"] = 0 } } },
[66186] = { ["id"] = 66186, ["name"] = "The Price", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["series"] = { 66188 }, ["description"] = "I am eager to return to the Emerald Dream and defend the gardens from the Incarnates and their followers. But I cannot leave Ardenweald yet, not with my bond to the Winter Queen. I dare not ask anyone to do this, unless they accept the consequences. As I did. But there is one who could take my place.", ["objectivesText"] = "Witness the decision.", ["rewardGold"] = 140450, ["rewardXP"] = 2465, ["rewardItems"] = { 57549, 57571, 57572, 57574, 83736, 83737, 83738, 83739, 83740, 88035, 88036, 88037, 88038, 88039, 88040, 88041, 88042, 88043, 131459, 193221, 201437, 201439, 201779, 232883, 257288 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 187634, ["x"] = 0.458, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 187636, ["x"] = 0.455, ["y"] = 0.623 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 8, ["flags"] = 0 } } },
[66187] = { ["id"] = 66187, ["name"] = "Mad Mordigan & The Crystal King", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66187 }, ["description"] = "I've scouted the perimeter. If Mordigan's anywhere, he's inside this cave. <Muffled curses and insults echo out from the cave entrance.> He's definitely inside this cave. LOU-C said these crystals have dangerous dehydrating properties. See if you can't separate him from his... geological finds. And try not to hurt him too much. He's fairly respected in his field.", ["objectivesText"] = "Decrystallize Mordigan Ironjaw in Gorloc Shore.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 191202, 191680, 192203, 193052, 197381, 201033, 201294 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 188030, ["x"] = 0.108, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 188030, ["x"] = 0.108, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.108, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66188] = { ["id"] = 66188, ["name"] = "Storm's Rest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["series"] = { 66186 }, ["description"] = "Let us go into the Grove of Awakening. The Winter Queen is the only one who can transfer this bond from Ysera to me. I have faith that she will agree. She aided Ysera in a time of desperate need, and now Ysera can help us in turn. If the Winter Queen agrees, I expect that I will not be able to remain awake for long. The weight of the bond will be heavy to bear. In time, I hope that I may wake again and gaze upon the fully grown might of the new tree.", ["objectivesText"] = "Activate the Globes of Rebirth in the Grove of Awakening. Progress: I long to see the twisting green expanse of the Dream once again.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 193221, 201437, 201439, 201779 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 187636, ["x"] = 0.455, ["y"] = 0.623 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 188348, ["x"] = 0.455, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.623 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 9, ["flags"] = 0 } } },
[66189] = { ["id"] = 66189, ["name"] = "Step Into the Life", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "We mustn't delay. I can feel the energies of rebirth surging in me. I am ready to cross back into the Emerald Dream. From the realms of Death into Life. Follow me through the gate of Awakening, and we will race across the Dreamway to Ancient Bough. I expect there will be some resistance within, so be on your guard.", ["objectivesText"] = "Fight your way across the Emerald Dreamway with Ysera and enter Ancient Bough.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 167873, 193221, 201437, 201439, 201779, 257302, 257303, 257304 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 188348, ["x"] = 0.455, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187646, ["x"] = 0.186, ["y"] = 0.518 }, { ["mapID"] = 2023, ["npcID"] = 207216, ["x"] = 0.188, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1565, 2023 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 10, ["flags"] = 0 } } },
[66191] = { ["id"] = 66191, ["name"] = "And Yet So Far", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "I cannot slip into the Dream here as I once did. With the bough defenses activated, we are essentially blocked from the grove. But I'm afraid it only gets worse, <name>. I believe Rymek did not merely trick us to gain access to the Dream. I suspect he is looking for something within it... something precious and powerful that I swore to protect. Not even Gerithus or Somnikus knew of its existence, but now, my hand is forced. You must know the truth.", ["objectivesText"] = "Speak to Merithra .", ["rewardGold"] = 154900, ["rewardXP"] = 2465, ["rewardItems"] = { 192547, 192555, 192558, 192744 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187561, ["x"] = 0.22, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187561, ["x"] = 0.22, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 13, ["flags"] = 0 } } },
[66196] = { ["id"] = 66196, ["name"] = "A Quack For Help", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66196 }, ["description"] = "<This duckling flails around frantically inside the bubble, quacking in fright.> <Maybe the ecologists would know how to help it?>", ["objectivesText"] = "Bring the Bubbled Duckling back to the Ecologists' Camp. Progress: <Tharu coos at the bubbled duckling .> Shh, don't cry, little one. Us big strong ecologists will keep you safe! And <name> too of course.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187439, ["x"] = 0.8, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186428, ["x"] = 0.745, ["y"] = 0.421 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.8, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66201] = { ["id"] = 66201, ["name"] = "Hooves of War", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "Balakar will marshal his forces for war. I will do the same, but we are outnumbered. The dragons have asked for our aid, and we can use their help to even the odds. To answer their call for an alliance, I must blow the Horn of Drusahl, but I need Ohn'ahra's blessing. Will you help me? Go to Teerakai and deliver my declaration of war to my lieutenant, Jebotai. He will marshal my forces and direct you to the mystics who can find Ohn'ahra.", ["objectivesText"] = "Deliver the Khanam Matra's message to Khansguard Jebotai at Teerakai. Progress: What do you want, outsider?", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 192472, 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187787, ["x"] = 0.418, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 26, ["flags"] = 0 } } },
[66210] = { ["id"] = 66210, ["name"] = "Gather the Family", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "Your friend Kalecgos wishes to speak of ley lines, but preparations must be made for the funeral. While I meet with him, could you gather the final offerings from around Iskaara and place them in the funeral boat alongside dear old Ponoliak? I hope you take a moment to enjoy the town, as well! My people will welcome you warmly, especially after your help in Brackenhide.", ["objectivesText"] = "Collect 4 Funeral Offerings from around Iskaara, then place them in the funeral boat. Progress: Did you get yourself a bowl of soup?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186480, ["x"] = 0.13, ["y"] = 0.499 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186480, ["x"] = 0.13, ["y"] = 0.499 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.13, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 35, ["flags"] = 0 } } },
[66211] = { ["id"] = 66211, ["name"] = "Brackenhide Hollow: To the Source", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13991, ["mapID"] = 2024, ["storyline"] = { 66211 }, ["description"] = "We cannot thank you enough for your aid pushing back the Brackenhide gnolls. But they continue to gather, using their foul decay magic from some source deep within Brackenhide Hollow. Worse, we have not heard from the tuskarr in that area for weeks, now. I fear something terrible is happening there. We must protect our home. Please, gather your forces, find our people, and see what you can do about the decay!", ["objectivesText"] = "Enter Brackenhide Hollow and confront Decatriarch Wratheye . You can access Brackenhide Hollow solo by queuing for it in Follower Dungeons. Progress: We must save our people, and stop the spread of decay!", ["rewardGold"] = 1123600, ["rewardXP"] = 8230, ["rewardItems"] = { 193666, 193671 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186480, ["x"] = 0.13, ["y"] = 0.499 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186480, ["x"] = 0.13, ["y"] = 0.499 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.13, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13991 } }, ["questType"] = "dungeon" },
[66213] = { ["id"] = 66213, ["name"] = "The Weave of a Tale", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66213 }, ["description"] = "My dearest wife, Poa, is an excellent storyteller. But it's been thirty years, and she tells the same ones over and over again! Please, <class>, talk to Poa and give her a new story to tell. What's that? Tell her a story about your adventures? Don't be ridiculous -- I don't want to hear about that! The greatest stories are always about fish. Tell a story about fish, even if you have to make one up!", ["objectivesText"] = "Tell Elder Poa a fishy tale. Progress: I'm waiting...", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186446, ["x"] = 0.124, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186446, ["x"] = 0.124, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.124, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66217] = { ["id"] = 66217, ["name"] = "WANTED: Krojek the Shoreprowler", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66217 }, ["description"] = "We've been watching the great shark we know as Krojek for many years now, waiting for the best time to hunt him down. His hunting ground has meandered closer and closer to the shore. That means the time is now. Gather your hunting party and take him out!", ["objectivesText"] = "Kill Krojek the Shoreprowler .", ["rewardGold"] = 842700, ["rewardXP"] = 6175, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186568, ["x"] = 0.127333, ["y"] = 0.494667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186568, ["x"] = 0.127333, ["y"] = 0.494667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.127333, ["y"] = 0.494667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "group" },
[66218] = { ["id"] = 66218, ["name"] = "Scampering Scamps", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66218, 66223, 76276 }, ["description"] = "Hello again. Could you do me and Norukk a favor? Our kids, Neelo and Nau, left to play. They know they should be back by now. I am occupied, so please find them. I doubt they are in danger; my kids know how to take care of themselves.", ["objectivesText"] = "Find Neelo and Nau. Progress: Neelo and Nau can fend for themselves. But they know they are supposed to be home helping by now.", ["rewardGold"] = 170800, ["rewardXP"] = 2060, ["rewardItems"] = { 192153 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186186, ["x"] = 0.128, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187674, ["x"] = 0.117, ["y"] = 0.477 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.128, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 273, ["title"] = "Lorewalking: Training", ["questLineID"] = 5740, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5740, ["name"] = "11.1.7 Lorewalking - Training (LAS)", ["orderIndex"] = 1, ["flags"] = 0 } } },
[66221] = { ["id"] = 66221, ["name"] = "Moving On", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["series"] = { 66039, 66040 }, ["description"] = "With the Bronze Oathstone restored, Alexstrasza can proceed with her plan. Travel to Valdrakken, <name>. She will want to hear of your success.", ["objectivesText"] = "Speak with Alexstrasza at the Seat of the Aspects in Valdrakken. Progress: I thank you, <name>.", ["rewardGold"] = 842700, ["rewardXP"] = 8200, ["rewardItems"] = { 192454, 192749, 194521, 195213 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 47, ["flags"] = 0 } } },
[66222] = { ["id"] = 66222, ["name"] = "The Calm Before the Storm", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "The Nokhud are powerful and have many allies. It will take all we have to withstand them. <name>, you have the Khanam Matra's trust. Her orders were to rally our friends and prepare our people. I need your help. Seek Hojin to mobilize the remaining khansguard. Alert Scout Khenyug to possible Nokhud incursions. Inform Agura to expect wounded, and tell Gensai to prepare our provisions. As for the mystics, I believe they left recently. I will see if any remain in Teerakai.", ["objectivesText"] = "Communicate Jebotai's orders to the townsfolk of Teerakai. Progress: It is rare for us to meet outsiders. It is even more rare to have them helping us, as you are. Thank you.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 193051, 197649, 197650, 197651, 197652, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187787, ["x"] = 0.418, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187787, ["x"] = 0.418, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 27, ["flags"] = 0 } } },
[66224] = { ["id"] = 66224, ["name"] = "Mystic Mystery", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "I'm sorry, I've failed to commune with Ohn'ahra. You will need someone else to fulfill the Khanam Matra's request. Several days ago, my fellow mystics were called to Ridgewater Retreat on an urgent request from Tigari Khan. They should still be there. Meet me outside of town. The least I can do is show you the way.", ["objectivesText"] = "Meet up with Boku and travel to Ridgewater Retreat. Progress: <name>, you're alright! Thank Ohn'ahra. Oh! These are my totems.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186290, ["x"] = 0.368, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187795, ["x"] = 0.492, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 30, ["flags"] = 0 } } },
[66225] = { ["id"] = 66225, ["name"] = "Toting Totems", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "Boku asked why I sent a message calling all mystics to Ridgewater Retreat. I sent no such message. Balakar purposefully drew my mystics into a trap to cripple Clan Ohn'ir. But there may be a second reason. The Nokhud are gathering mystic totems, as many as they can find. These totems are blessed by Ohn'ahra. The Nokhud motives in this are unclear, but we cannot allow them to take Ohn'ahra's gifts. Recover as many totems as you can.", ["objectivesText"] = "Gather 8 Bundles of Totems from the Nokhud at Ridgewater Retreat. Progress: The totems are infused with Ohn'ahra's wind magic. Yet the Nokhud have abandoned her teachings. What are they up to?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195316, ["x"] = 0.494, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190648, ["x"] = 0.494, ["y"] = 0.632 }, { ["mapID"] = 2023, ["npcID"] = 195316, ["x"] = 0.494, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 32, ["flags"] = 0 } } },
[66226] = { ["id"] = 66226, ["name"] = "Emotional Support Companions", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66226 }, ["description"] = "Please don't hurt me... What? You're here to help? You must save the animals! The Nokhud attacked without warning. We all fled for our lives! I barely escaped death by diving into the lake. The animals! We left them behind. Please, I beg you, rescue the creatures. Who knows what cruelty the Nokhud have in store for them.", ["objectivesText"] = "Rescue the innocent creatures from the Nokhud at Ridgewater Retreat. Progress: As initiates, we practice our healing arts by rehabilitating wounded creatures. Four creatures were under our care. However many you can rescue will be a relief.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193059, 193060, 193061, 193062, 198039 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187796, ["x"] = 0.47, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187796, ["x"] = 0.47, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66227] = { ["id"] = 66227, ["name"] = "Some Good Fishing", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66227 }, ["description"] = "Another pair of hands! I could use some help catching enough fish to bring home for a meal. These Kirin Tor seem concerned about something called magical anomalies in the area, whatever that means. You're all welcome to stay here as long as you pitch in and help out. Grab a fishing pole and start fishing. Many hands make light work!", ["objectivesText"] = "Catch 3 blue-tailed minnows within Khuri 's Fishing Spot. Progress: Let me know if you need a few tips.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191646, 194730, 194966, 194969, 194970, 198225, 202207 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185608, ["x"] = 0.414, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185608, ["x"] = 0.414, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66228] = { ["id"] = 66228, ["name"] = "Camp Antonidas", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "The Kirin Tor have our main camp set up to the south of here: Camp Antonidas. I believe Noriko and Khadgar are there now gathering adventurers to aid Kalecgos in reclaiming the Azure Oathstone. If you wish to help in our endeavours, go there.", ["objectivesText"] = "Meet Noriko the All-Remembering in Camp Antonidas.", ["rewardGold"] = 7410, ["rewardXP"] = 515, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185603, ["x"] = 0.414, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 4, ["flags"] = 1 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 1, ["flags"] = 1 } } },
[66230] = { ["id"] = 66230, ["name"] = "A Sketchy Request", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66230 }, ["description"] = "The tarasek took everything they could get their claws on, including my scouting ledger. These overgrown lizards hoard trinkets and trophies by the dozens. I am sure that they stashed my ledger away somewhere. Could you keep an eye out for it as you work your way through the pass? Oh, and <name>? If you do manage to find it, please do not look inside. The contents are sort of... personal.", ["objectivesText"] = "Retrieve Alvi's \"Ledger\" and return it to Waywatcher Alvi . Progress: Did you find anything else, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191308, 191317, 191405, 191852 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 191753, ["x"] = 0.546, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66232] = { ["id"] = 66232, ["name"] = "Afront 'Till A Salt", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66232 }, ["description"] = "We don't mind accommodating you and your friends in our little place--not that anyone asked-- but would you be a good neighbor and nab me some crystal flakes if you're going up to the springs? We use 'em to preserve all kinds of things. It's a crucial part of keeping food around here. The larger gorlocs are absolutely covered in the stuff. Maybe get some flakes off them?", ["objectivesText"] = "Gather 120 Crystal Flakes in Gorloc Shore. Progress: Now that you mention it, I'm actually pretty hungry.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191309 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186212, ["x"] = 0.074, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186212, ["x"] = 0.074, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.074, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66236] = { ["id"] = 66236, ["name"] = "Catching Wind", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "The Nokhud are collecting totems. The Primalists are capturing ohuna. And Ohn'ahra is silent. Whatever the Nokhud plans are, we must foil them. You and Boku must travel to Windsong Rise. Our enemies are likely there already. Search for Ohn'ahra there. If her children are in danger, she will undoubtedly go to them, and we must help. The Windmother is powerful, but I fear what these Primalists are capable of.", ["objectivesText"] = "Meet Boku at Windsong Rise.", ["rewardGold"] = 16980, ["rewardXP"] = 345, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190648, ["x"] = 0.494, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187804, ["x"] = 0.58, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 33, ["flags"] = 0 } } },
[66239] = { ["id"] = 66239, ["name"] = "Spreading Decay", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "< Brena turns Kargpaw's totem over and over in her thick hands.> Kargpaw is a pawn. He isn't the source of this rot. We must find it, before the decay spreads further. The closest tuskarr presence from here is a trading outpost, just across the bridge on the way to Iskaara. We should check in with them... and quickly.", ["objectivesText"] = "Meet Brena at the trading outpost.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186228, ["x"] = 0.344, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187721, ["x"] = 0.286, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 25, ["flags"] = 0 } } },
[66242] = { ["id"] = 66242, ["name"] = "Weather Control", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "This unnatural storm is heavy with magic. By the looks of it, the Nokhud are learning to manipulate the sacred essence of Windsong Rise to create storm elementals. Some have had more success than others... <Boku gestures to the unfortunate Nokhud initiate nearby still smoking from lightning burns.> <name>, we can't allow them to continue.", ["objectivesText"] = "Kill 8 Stormbound Essences and 6 Stormcaller Initiates . Progress: The Nokhud will regret abandoning Ohn'ahra for the Primalists!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187804, ["x"] = 0.58, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187809, ["x"] = 0.606, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 34, ["flags"] = 0 } } },
[66245] = { ["id"] = 66245, ["name"] = "Remember the Fallen", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "So many of my comrades have fallen. Please... Collect their identifying signets so that their names may not be forgotten.", ["objectivesText"] = "Collect 8 South Hold Garrison Signets . Progress: How goes your task, hero? Did you find any signets?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.826667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 7, ["flags"] = 0 } } },
[66246] = { ["id"] = 66246, ["name"] = "The Fog of Battle", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "The Primalist attack came suddenly and with no warning. My unit attempted to find our leader, Commander Eranog, but before we could get to the other side of the garrison we were cut off. In the battle my unit leader, Sergeant Tagrik, held off three Primalists by himself as Kaora, Mikor, and myself battled at his side. Their screams are the last thing I remember before I fell. Please, <race>, if you see any signs of my unit let me know what happened to them.", ["objectivesText"] = "Search for the members of Guardian Velomir 's unit in the South Hold Gate. Progress: Have you found what happened to my unit? I fear the worst, but I have hope that they survived.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.826667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 6, ["flags"] = 0 } } },
[66247] = { ["id"] = 66247, ["name"] = "Slightly Used Weapons", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "This spear appears to be in good shape, given the condition of its former owner. Guardian Velomir mentioned to keep an eye out for useful materials, perhaps a few more of these spears can be obtained from the Magmasworn.", ["objectivesText"] = "Gather 6 Magmasworn Spears . Progress: Find anything worthwhile out there?", ["rewardGold"] = 99850, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 195219, 198859 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.826667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 8, ["flags"] = 0 } } },
[66248] = { ["id"] = 66248, ["name"] = "Tying Things Together", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "This coil of heavy rope seems to be in good condition. Guardian Velomir said to keep an eye out for useful materials, perhaps if you can find a few more coils he might find them useful.", ["objectivesText"] = "Gather 5 Coils of Heavy Rope . Progress: What is it, friend? Did you find something?", ["rewardGold"] = 262100, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.826667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 9, ["flags"] = 0 } } },
[66249] = { ["id"] = 66249, ["name"] = "Clear the Sky", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66250, 66251, 66252 }, ["description"] = "You did well to gather those spears and rope. With them, we can ensure those haughty Primalists will no longer rule the skies! There is a platform up the stairway with several Siege Scorpions . If you use the rope to string their bows and use the spears as ammunition, you should be able to strike the Magmasworn's dragons in the air! Once cleared, the path up the spire will be safe and we can continue our search for Commander Eranog.", ["objectivesText"] = "Control a Siege Scorpion and then use it to clear the skies of Magmasworn Trueborn .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 197126, 198859 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190558, ["x"] = 0.405, ["y"] = 0.854 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.826667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 10, ["flags"] = 0 } } },
[66250] = { ["id"] = 66250, ["name"] = "Where's The Chief?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66249, 66251, 66252 }, ["description"] = "This is the only part of the fortress we haven't yet searched, <name>. If Commander Eranog is anywhere, it has to be here. <Velomir glances towards the nearby doorway.> Let us see what we can find out.", ["objectivesText"] = "Accompany Guardian Velomir and inspect the Lookout Tower within South Hold Gate.", ["rewardGold"] = 101100, ["rewardXP"] = 2735, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190558, ["x"] = 0.405, ["y"] = 0.854 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190562, ["x"] = 0.402, ["y"] = 0.852 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.854 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 11, ["flags"] = 0 } } },
[66251] = { ["id"] = 66251, ["name"] = "Fire Fighter", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66249, 66250, 66252 }, ["description"] = "Commander Eranog has betrayed us and left this beast in charge. You have done so much for me already, but I can not handle that monster in my current state. Please, do this one last thing for me and help ensure that South Hold Gate does not fall to these Primalists. We must kill their leader! Help me, <name>.", ["objectivesText"] = "Kill Magmatalon .", ["rewardGold"] = 404400, ["rewardXP"] = 6830, ["rewardItems"] = { 191269, 192758, 192759, 195222, 198048, 198859, 200454, 204075, 204673, 204735, 204745, 204746, 204748, 204749, 204750, 204751, 204752, 204754, 204756, 204762, 204763, 204764, 204765, 204766, 204771, 204772, 204773, 204774, 204777, 204778, 204779, 204780, 204782, 204783, 204784, 204785, 204786, 204787, 204789, 204897 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190562, ["x"] = 0.402, ["y"] = 0.852 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190562, ["x"] = 0.402, ["y"] = 0.852 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.852 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 12, ["flags"] = 0 } } },
[66252] = { ["id"] = 66252, ["name"] = "Reporting In", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66249, 66250, 66251 }, ["description"] = "The Primalists threat has been diminished, <name>. Forces from Valdrakken will be headed in soon, and can clean up any remnants. You should head back to the city and inform Captain Drine of what has happened. She will be interested to know what occurred here with Commander Eranog. Thank you again, <name>, for everything.", ["objectivesText"] = "Return to Valdrakken and report to Captain Drine .", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190562, ["x"] = 0.402, ["y"] = 0.852 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.852 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 13, ["flags"] = 0 } } },
[66254] = { ["id"] = 66254, ["name"] = "Pessimistic Mystic", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "War? Dragons? You need me to contact Ohn'ahra? I can't. I can't hear Ohn'ahra at all. I'm just an initiate, and it seems like Ohn'ahra has withdrawn her blessings from me. Maybe I'm not good enough... <Boku starts digging through a satchel.> When my mentor assigned me to this clan, she gifted me with these totems. She said they would empower me if ever I doubted myself. Will you help me place them? I will try to call upon Ohn'ahra one more time.", ["objectivesText"] = "Place the Empowerment Totems around Boku.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186290, ["x"] = 0.368, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186290, ["x"] = 0.368, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 29, ["flags"] = 0 } } },
[66256] = { ["id"] = 66256, ["name"] = "Eagle-itarian", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "We've discovered why the Nokhud want mystic totems. They can be used to capture the Children of Ohn'ahra. Though the Nokhud have stolen the totems, the Primalists are the ones behind this blasphemy. The Children of Ohn'ahra are sacred ohuna, blessed by the Windmother herself. Please, <name>, free any ohuna you see! And if you come across any Primalists... <Boku trails off, but his expression is one of grim determination.>", ["objectivesText"] = "Free 6 Children of Ohn'ahra and eliminate 6 Primalists at Windsong Rise. Progress: The Children of Ohn'ahra bear the spirits of the honored dead to the beyond.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187804, ["x"] = 0.58, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187809, ["x"] = 0.606, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 35, ["flags"] = 0 } } },
[66257] = { ["id"] = 66257, ["name"] = "Fowl Sorcery", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "It is said that Ohn'ahra infused the spear of our ancestor, Maruuk, with her power. Balakar Khan must have told the Primalists about that legend. They have stolen the magic from Ohn'ahra's children, polluted it with storm sorcery, and infused it into ballista bolts. Why would the Nokhud need such weapons? We shouldn't wait to find out. These storm bolts are being loaded into wagons for transport. Take my totems and place one atop each wagon you come across. My wind magic will smash them to pieces.", ["objectivesText"] = "Use Boku's Wind Totem to destroy the Nokhud wagons. Progress: You might want to run after placing a totem.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187804, ["x"] = 0.58, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187809, ["x"] = 0.606, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 36, ["flags"] = 0 } } },
[66258] = { ["id"] = 66258, ["name"] = "Oh No, Ohn'ahra!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "That Primalist is restraining Ohn'ahra, but just barely. She doesn't seem to notice us. Tigari Khan would say, \"Even the slightest breeze can topple a teetering stone.\" If I can disrupt her spell, even just a little, Ohn'ahra might be able to break free. Keep the guards distracted. I have an idea.", ["objectivesText"] = "Defeat enemies as Boku tries to free Ohn'ahra.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187809, ["x"] = 0.606, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 195024, ["x"] = 0.614, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 37, ["flags"] = 0 } } },
[66259] = { ["id"] = 66259, ["name"] = "A Storm of Ill Tidings", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "<name>, we need to tell the Khanam Matra everything that's happened, including the capture of Ohn'ahra. You must go to Maruukai as quickly as you can. You'll have to go alone. I was hurt in the fall, and I'd just slow you down. Don't worry about me. I'll catch up later. Go!", ["objectivesText"] = "Deliver your report to the Khanam Matra in Maruukai. Progress: Well? Speak.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 193051, 197846, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195024, ["x"] = 0.614, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 38, ["flags"] = 0 } } },
[66262] = { ["id"] = 66262, ["name"] = "Waste Water Cleanup", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66262 }, ["description"] = "First things first--I need my base of operations back! But the elementals running amok around here have made it very difficult to gain even a toehold. And of course it is those wretched gnolls' fault. The gnolls have dumped so much refuse, offal, and Light knows what else into the lake that the local elementals have started to go berserk. Be a dear and clean up a few of the more revolting messes before things come to a head. And, more importantly, before they stain my robes permanently!", ["objectivesText"] = "Clean 6 Rotting Piles from the lake. Progress: Ugh, the smell is horrific.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191424, 191736 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66263] = { ["id"] = 66263, ["name"] = "A Precision Approach", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66263 }, ["description"] = "Gnolls are awful creatures. Smelly. Always scratching, laughing at you. And there are multitudes here and more are constantly arriving. We, and by that I mean you, could reap them like wheat for days and never get anywhere. They can't be suffered to stay here. We must strike at the heart of the snake! Remove their leadership and they'll be paralyzed with indecision and despair. What do you mean why are we doing this? Isn't it obvious? They're gnolls! What more reason could one need?", ["objectivesText"] = "Kill Flayfist . Progress: Did I mention I'm allergic to gnoll fur? My throat gets itchy just thinking about them.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191424, 191736 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66264] = { ["id"] = 66264, ["name"] = "Disarmed and Docile", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66264 }, ["description"] = "There's a frankly unnerving amount of weaponry being waved about up there. Relieving them of some should help calm things down. Or at least calm my nerves. What are they going to do without weapons, after all? Attack you with their bare hands? Ha!", ["objectivesText"] = "Acquire 15 Gnawbone Armaments . Progress: Surely they're just lying about?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191424, 191736, 198407, 200563 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66265] = { ["id"] = 66265, ["name"] = "Who's Next?", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66265 }, ["description"] = "Aha! Well, it seems that another gnoll has stepped up to assume command. Just as I expected. Yes. Having a trusted vice-warlord to ensure continuation of government makes perfect sense now, doesn't it? We'll just have to hit them a little harder to tumble their bureaucracy, hm? What? Am I going to take this moment to reflect on whether I'm rushing to judgement on these gnolls? Ridiculous! They're gnolls! Quickly now! Kill Cracktooth before the iron cools off or they arrange for an election!", ["objectivesText"] = "Kill Cracktooth .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 35929, 35930, 35931, 35937, 133818, 191424, 191736, 226166, 237812 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66266] = { ["id"] = 66266, ["name"] = "Filthy Mongrels", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66266 }, ["description"] = "Those flea-bitten Hyena Mongrels the gnolls breed have got to go! Not only do they have no manners at all--you would not believe the places I've seen them relieve themselves--but they may very well be able to sniff me out despite my exemplary illusions. Do the well-mannered world a favor and remove them from it.", ["objectivesText"] = "Slay 3 Hyena Matriarchs and 12 Hyena Mongrels .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191424, 191736 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66267] = { ["id"] = 66267, ["name"] = "M.E.T.A.", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66267 }, ["description"] = "Those fiends! Pillaging and murder are one thing, but animal abuse? I'll not stand for it. The gnolls have set out traps for animals to catch and feed to their slavering hyena mutts. Find a way to free their fluffy captives and show the ruffians how a mage ethically treats animals! Of course this makes ethical sense in light of my recent actions. What exactly are you trying to insinuate?", ["objectivesText"] = "Free 6 abused animals.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 87399, 108439, 191424, 191736, 194963, 211279, 223871, 223872, 223873, 223874, 223875, 223876, 223877, 257187, 257188, 257189, 257190, 262610, 263463 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 198202, ["x"] = 0.234, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.234, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66268] = { ["id"] = 66268, ["name"] = "Third Try's the Charm", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66268 }, ["description"] = "What? Another one's seized power? Whatever happened to abhorring a vacuum? Or at least waiting for a respectful period of mourning to pass in order to keep up appearances? Do they have no decency? No sense of propriety? No respect for a well-crafted plan? I made charts! Deal with this Bloodclaw fellow. I need a moment. And I don't need your nagging comments, thank you very much!", ["objectivesText"] = "Kill Bloodclaw . Progress: All according to plan!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191424, 191736 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66269] = { ["id"] = 66269, ["name"] = "Just To Be Sure", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66269 }, ["description"] = "Just... kill anyone who looks like they might be magically inclined. Or has organizational skills. Or looks overly ambitious. Really, just use your best judgement on this one. Your \"best judgement\" is to stop speaking to me? Come on, <class>! They're... up to something nefarious, obviously!", ["objectivesText"] = "Slay 12 Stormfang elementalists. Progress: Don't they know they've been outwitted?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191424, 191736 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66270] = { ["id"] = 66270, ["name"] = "Whack-a-Gnoll", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66270 }, ["description"] = "Oh, Light... there are more on their way! How could this happen? All my careful planning! The days spent hiding in this rancid lake! The assassinations! This should have thrown them into chaos and caused their settlement to crumble, but we've barely slowed them down! Maybe... maybe you're right, <name>. I've been wrong all along... No! Impossible! We're in too deep now anyway. Go...deal with these new arrivals. I need time to collect myself.", ["objectivesText"] = "Defeat the would-be warlords. Progress: What are you waiting for?", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 191424, 191736, 197385, 198036, 198432 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66278] = { ["id"] = 66278, ["name"] = "One Drakonid's Junk", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66278 }, ["description"] = "<A glistening pocket watch lays amongst the many piles of junk. Maybe Gryrmpech will know what to do with it.>", ["objectivesText"] = "Bring the pocket watch to Gryrmpech in the Gardens. Provided item:", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 191473, 191548, 191676, 194098 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66279] = { ["id"] = 66279, ["name"] = "New Kid on the Clock", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66279 }, ["description"] = "Oh yeah, this pocket watch belongs to one of the stewards that help me tend to the gardens. He's one of Nozdormu's. Orizmu , I think? I can't keep all these kids straight. Most days he stands next to that hourglass near Alexstraza's tree without moving. Or blinking. Nozdormu's bunch have always been strange, if you ask me. But, he'll be grateful you brought this to him.", ["objectivesText"] = "Take the pocket watch to Orizmu in the Gardens. Progress: Walking all the way down to the sundial is too much effort for my old bones.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 191473, 191548, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187310, ["x"] = 0.352, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66299] = { ["id"] = 66299, ["name"] = "The Awaited Egg-splosion", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66299 }, ["description"] = "Our prototype worked! Excellent! Now it's time for the main course. This time, YOU are the chef. With some necessary adjustments, you'll suit up in your disguise again. Then you'll take our masterpiece EGG-splosive, dunk it in this rancid stew here, head up to the matriarch's cave, plate it for her, and glide back down with the blasts detonating behind you! If all things go as planned, she'll be toast. Because of the explosion. Which will burn her to toasty bits.", ["objectivesText"] = "Slay the Screechflight Matriarch. Progress: Careful with that chef's hat. It's bound to be a collector's item one day!", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763, 191891, 197133 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66320] = { ["id"] = 66320, ["name"] = "The Flow of Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "The threads of time flow like a river, with many bends and branches. Occasionally, those flows can be changed. However, any anomaly left unresolved may doom our destiny to a false timeline. We are quickly approaching one of those anomalies. I have sent Chronormu to the Shifting Sands to investigate and correct any issues to the one true timeline. I foresee that your assistance will be invaluable. Please lend us your aid and meet with Chronormu.", ["objectivesText"] = "Travel to the Shifting Sands and speak with Chromie .", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 192602, 192809, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187100, ["x"] = 0.574, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 14, ["flags"] = 0 } } },
[66327] = { ["id"] = 66327, ["name"] = "Chasing the Wind", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "We must take a moment to pause and consider our strategy. We need Ohn'ahra's blessing to sound the Horn of Drusahl and summon the green dragons. Without their aid, we cannot win this war. The Nokhud already outnumber the other clans, and their forces are bolstered by the Primalists. And now Koroleth has captured our Windmother! We must therefore find Ohn'ahra before the Nokhud can launch their final attack and encircle Maruukai. I will send all of our scouts. I only hope we can find her in time.", ["objectivesText"] = "Listen to Scout Tomul 's report. Progress: We should depart as quickly as possible. You may ride Taivan and accompany us, or meet us at the Horn of Drusahl.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 39, ["flags"] = 0 } } },
[66328] = { ["id"] = 66328, ["name"] = "Green Dragon Down", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "Those dragons went down over the plains to the west. We must get to them quickly before the Nokhud do. We would not want them to think of all Maruuk as their enemies because of Balakar's actions.", ["objectivesText"] = "Meet the Khanam Matra at the watering hole. Progress: The dragons need our help, outsider. We should hurry!", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.7375, ["y"] = 0.4305 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 42, ["flags"] = 0 } } },
[66329] = { ["id"] = 66329, ["name"] = "Blowing of the Horn", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "Why would they have brought Ohn'ahra here? Unless... <name>! I do not think Balakar intends to destroy the Horn. I think this is a trap! We must find a way past this wind, quickly!", ["objectivesText"] = "Witness Balakar and Koroleth's plans. Progress: No, Balakar!", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.7375, ["y"] = 0.4305 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 41, ["flags"] = 0 } } },
[66331] = { ["id"] = 66331, ["name"] = "The Primalist Front", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "The Khanam Matra sent word that she and her forces have arrived in the Emerald Gardens. They've located Koroleth and her Primalists. It appears a massive enemy invasion is gathering on a beach to the north. Wisely, she has several scouts watching strategic locations around the battlefield. Go and collect their reports, then meet me and my forces at the battlefront. Glory awaits us in battle, and, if we succeed, there will be vengeance.", ["objectivesText"] = "Speak to Scout Tomul, Ari and Belika, Ohn Seshteng , and Merithra in the Storm Scar. Progress: Every moment we delay, our enemies advance. We must move quickly, <name>.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188106, ["x"] = 0.282, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188601, ["x"] = 0.239, ["y"] = 0.457 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 45, ["flags"] = 0 } } },
[66333] = { ["id"] = 66333, ["name"] = "Justice for Solethus", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "So long as a single green dragon draws breath, these Primalists will not defile the Ancient Bough without a fight. We are eager to do our part in this battle, but as long as those dragonkiller ballistae are on the field, we cannot approach. The Nokhud's strongest warriors guard them, so you will need to take down the warriors as well. Destroy the ballistae and Nokhud Warmongers . Eliminate this threat, and the green dragons will turn the tide of battle.", ["objectivesText"] = "Kill 3 Nokhud Warmongers and destroy 3 Dragon-Killer Ballistae. Progress: Make haste, mortal. I will not commit dragons to battle while those ballistae remain.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 194549, 197375, 197661, 197662, 197663, 197664 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189599, ["x"] = 0.256, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 46, ["flags"] = 0 } } },
[66335] = { ["id"] = 66335, ["name"] = "Deconstruct Additional Pylons", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "With those vile weapons destroyed, the green dragonflight can join the fray in force. We are much more familiar with the situation on the ground. We need to light up some targets, so Merithra and her dragons can strike from above. Merithra gave me these enchanted seeds. Place them near the Primalist pylons . We will use their light to call in attacks from airborne dragons.", ["objectivesText"] = "Mark the Primalist Pylons with Enchanted Seeds. Progress: I would appreciate if you did not stand so close to me with those enchanted seeds. Thank you.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 194549, 197375 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 47, ["flags"] = 0 } } },
[66336] = { ["id"] = 66336, ["name"] = "The Isle of Emerald", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "Your part in this has not escaped me, mortal. It is in large part due to your bravery that we were able to defeat the Primalists. I have invited the centaur to join me under the Ancient Bough. You, along with the Khanam Matra and her people, are welcome in our home. Follow this path through the archway across the water and into the trees beyond. I will wait for you there.", ["objectivesText"] = "Meet Merithra in the Ancient Bough.", ["rewardGold"] = 16980, ["rewardXP"] = 345, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188150, ["x"] = 0.256, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188181, ["x"] = 0.222, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 50, ["flags"] = 0 } } },
[66337] = { ["id"] = 66337, ["name"] = "Stormbreaker", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "<name>, to me! We are within reach of victory! The Primalist ranks are broken, and their war is all but through. Everything we have achieved hinges on this final battle against the Primalist leader, Koroleth . Let us finish this, you and I! Together! To battle, <brother/sister>!", ["objectivesText"] = "Defeat Koroleth .", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 194549, 197375 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188150, ["x"] = 0.256, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 49, ["flags"] = 0 } } },
[66339] = { ["id"] = 66339, ["name"] = "The Nokhud Offensive: The Wind Belongs to the Sky", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66339 }, ["description"] = "Is this the end of your time with us, <name>, or will you aid us once again? My scouts report that Balakar has withdrawn into his stronghold, where he is holding Ohn'ahra. This is unacceptable! Meanwhile, his Nokhud raiders storm across the plains wreaking havoc. While we engage them in battle, you could infiltrate the Nokhud stronghold and rescue Ohn'ahra. Will you do this for us?", ["objectivesText"] = "Defeat Balakar Khan and rescue Ohn'ahra in The Nokhud Offensive. You can access The Nokhud Offensive solo by queuing for it in Follower Dungeons.", ["rewardGold"] = 1123600, ["rewardXP"] = 5530, ["rewardItems"] = { 193676, 193677, 193679, 193685, 193686, 193692, 193697, 212757 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188601, ["x"] = 0.239, ["y"] = 0.457 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.239, ["y"] = 0.457 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "dungeon" },
[66340] = { ["id"] = 66340, ["name"] = "Into the Azure", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "We have done our part. Though I must remain here to watch over the Oathstone and guide the green dragonflight, know that you leave here with our gratitude and faith. I have received word the Kirin Tor are seeking help in claiming the Azure Oathstone. Helping them with their Oathstone will bring us one step closer to healing Azeroth. Find Pakina and Masud the Wise of the Kirin Tor. They will instruct you further. Safe journey and pleasant dreams, <name>.", ["objectivesText"] = "Meet Masud the Wise in the Forkriver Crossing.", ["rewardGold"] = 24100, ["rewardXP"] = 345, ["rewardItems"] = { 71086, 190769, 191784, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188181, ["x"] = 0.222, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185599, ["x"] = 0.716, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.222, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 50, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 52, ["flags"] = 0 } } },
[66344] = { ["id"] = 66344, ["name"] = "With the Wind at Our Backs", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "So the Primalists have recruited Clan Nokhud as allies. We have held off the Primalists until now, but the Nokhud have brought a new weapon: a dragonkiller ballista. I fear Solethus will not be the last dragon to fall to its foul storm magic. Come. I will take you to the dragons' haven at Shady Sanctuary. You can tell me what you know of the Nokhud while the Khanam Matra gathers her forces. We must prepare for our next move.", ["objectivesText"] = "Ride with Gerithus and Merithra .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188156, ["x"] = 0.724, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188106, ["x"] = 0.282, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.724, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 43, ["flags"] = 0 } } },
[66352] = { ["id"] = 66352, ["name"] = "What the Enemy Knows", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66352 }, ["description"] = "It is vital that we determine the Sundered Flame's mission in these ruins and how it relates to the arcane surge. We'll do this the old fashioned way: reconnaissance and espionage. The ruins are overrun with Sundered Flame devotees. I am sure some of them carry orders that may illuminate their mysterious goals. Use any means necessary to obtain these documents.", ["objectivesText"] = "Find Sundered Flames documents and bring them to Lathos. Progress: Have you found anything yet, <name>?", ["rewardGold"] = 210675, ["rewardXP"] = 3085, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189166, ["x"] = 0.65, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189166, ["x"] = 0.65, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66353] = { ["id"] = 66353, ["name"] = "R.A.D. Anomalies", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66353 }, ["description"] = "There is a LOT of arcane energy here... But! The R.A.D. can help with that! It's an awesome device--it's right in the name: \"Rannan's Awesome Device!\" It detects AND dispels arcane energy. Here... hold it! Do you feel the POWER in your hands? No? Well, now that you've got it, take it and dispel those anomalies!", ["objectivesText"] = "Use the R.A.D. to dispel three arcane anomalies. Progress: Go! Go! That arcane energy is not going to dispel itself.", ["rewardGold"] = 210675, ["rewardXP"] = 3085, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189171, ["x"] = 0.65, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189171, ["x"] = 0.65, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66354] = { ["id"] = 66354, ["name"] = "The Spark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "The forge is ready. All it needs now is flame. Place the damaged Oathstone fragments upon the forge, and Wrathion shall provide the spark to ignite the process.", ["objectivesText"] = "Reform the damaged parts of the Oathstone. Progress: Have the fragments been reformed?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 9363, 71083, 185717, 190456, 191131, 192548, 232875 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.315333, ["y"] = 0.635333 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 43, ["flags"] = 0 } } },
[66356] = { ["id"] = 66356, ["name"] = "Irontree", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66356 }, ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 256903 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["db2VignetteID"] = 5078, ["db2VignetteName"] = "Irontree" },
[66368] = { ["id"] = 66368, ["name"] = "Island In A Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66368 }, ["description"] = "There has been little time to rest. The elementals' assault is relentless! A moment of respite would be welcome and allow me to craft more wards for our defense. See what you can do to thin out the onslaught on our perimeter.", ["objectivesText"] = "Eliminate 10 Blazing Manifestations and Melter Igneous . Progress: They must be culled.", ["rewardGold"] = 1404500, ["rewardXP"] = 1415, ["rewardItems"] = { 191837 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187609, ["x"] = 0.374, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187609, ["x"] = 0.374, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.374, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66369] = { ["id"] = 66369, ["name"] = "The Earthen Ward", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66369 }, ["description"] = "I have empowered a ward using the rings you collected. It has gathered the very stones of the earth around it and created a Living Earthen defender to protect this territory. Test the Earthen Ward to ensure it's functional.", ["objectivesText"] = "Activate the Earthen Ward. Progress: Was the test successful?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191837 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187609, ["x"] = 0.374, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187609, ["x"] = 0.374, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.374, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66391] = { ["id"] = 66391, ["name"] = "To the Ruins!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66391 }, ["description"] = "Are you interested in hearing about my invention, the R.A.D.? No? Well, I'll tell you anyway--because it found something. Today it detected a HUGE SURGE of arcane energy from the Karnthar Ruins. Lathos thinks the Sundered Flame are to blame. It's the PERFECT opportunity to showcase the R.A.D.! Wanna come? It's going to be awesome.", ["objectivesText"] = "Meet Rannan and Lathos in the Ruins of Karnthar.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 30253, 30254, 30255, 94219, 191265, 191909, 192110, 192475, 211279, 237812 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 188144, ["x"] = 0.635, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189171, ["x"] = 0.65, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66392] = { ["id"] = 66392, ["name"] = "Rallying Nature's Allies", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "We cannot give into despair now. We must push forward. We must think of another way through the barrier. First, we need our allies. Countless elementals summoned by Rymek are pouring through the portal. We will need an army that can move in the Dream like we can, or one that can be brought in easily. Rally the druids and centaur in Shady Sanctuary. It is time to call upon their oaths to preserve the grove.", ["objectivesText"] = "Muster the druids and gather the empowered anchors in Shady Sanctuary. Progress: Are you ready to cross to Ardenweald?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193221, 201437, 201439, 201779, 257299 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187561, ["x"] = 0.22, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187594, ["x"] = 0.284, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 14, ["flags"] = 0 } } },
[66393] = { ["id"] = 66393, ["name"] = "To Somnikus", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "Somnikus has been melancholy and agitated since the death of his son. Though we have all endured loss, I cannot imagine what I would feel were something like that to happen to Gerithus. Go with Rymek to the isle, and see if there's anything we can do. Somnikus suspects that the Primalists are on the verge of another attack. I fear that he may do something rash. Do not worry. Because of your help with the Emerald Oathstone, you can cross the barrier easily.", ["objectivesText"] = "Meet Somnikus with Rymek near the Oathstone in Ancient Bough.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 192547, 192555, 192558, 192744 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187509, ["x"] = 0.284, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186469, ["x"] = 0.22, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 15, ["flags"] = 0 } } },
[66394] = { ["id"] = 66394, ["name"] = "Thin the Veil", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "There must be a way to lower the barrier from within this grove. I sense several points around us that strengthen it. If you can deactivate enough of those, we should be able to lower it the rest of the way so the others may join us.", ["objectivesText"] = "Deactivate Barrier Moorings in Ancient Bough. Progress: Have you found the barrier moorings ?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 141680, 193221, 201437, 201439, 201779, 237812, 257305, 257306, 257307, 257308 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187646, ["x"] = 0.186, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187646, ["x"] = 0.186, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 16, ["flags"] = 0 } } },
[66395] = { ["id"] = 66395, ["name"] = "The Chittering Rocks", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "Merithra needn't worry about me. I'm fine. My son's death... I'm fine. If you really want to help put my mind at ease, there is something you could do. I suspect Primalists will try to invade these lands again. Unlike last time, I doubt they'll attack the Ancient Bough directly. They know we'd defeat them. See those rocks over there? Those off-color, slightly smelly rocks? I hear something moving underneath them. Perhaps Primalists are lurking nearby! Could you investigate? Squash whatever you find.", ["objectivesText"] = "Investigate Suspicious Permafrost and slay Glacial Tunnelers . Progress: I can hear them skittering around under the rocks. Who'd dare to summon creatures like that so close to the portal?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744, 257287 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186469, ["x"] = 0.22, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186469, ["x"] = 0.22, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 17, ["flags"] = 0 } } },
[66396] = { ["id"] = 66396, ["name"] = "Guarded Appreciation", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "I know it can be quite exhausting work to defend such an important locale. And often, we drakonids and dragonspawn get very little thanks for our dedication. I wish to bestow some of my own appreciation to the guards here in Ancient Bough. Here, offer them these gifts from me, as a sign of friendship. I hope my heartfelt gesture properly expresses my gratitude.", ["objectivesText"] = "Give 6 guards Rymek's Gift . Progress: Have you given the guards my gifts?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744, 257290, 257291, 257293 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189857, ["x"] = 0.22, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189857, ["x"] = 0.22, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 18, ["flags"] = 0 } } },
[66397] = { ["id"] = 66397, ["name"] = "Our Full Strength", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "We need reinforcements, and quickly. But Merithra cannot yet join us in the grove because of the barrier. We will need to manage both from here within the Dream. Slay these Primalists and take anything you need from them, so we can melt those ice prisons and free the grove guards.", ["objectivesText"] = "Free Emerald Scaleguards and Wardens. Progress: That was too cold. Close. Too close.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193221, 201437, 201439, 201779 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187646, ["x"] = 0.186, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188763, ["x"] = 0.194, ["y"] = 0.503 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 19, ["flags"] = 0 } } },
[66398] = { ["id"] = 66398, ["name"] = "The Emerald Dragonflight", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "If we are to eradicate the Primalists from the Emerald Dream, the one place we must secure is Lunedane. According to my son, that is where Rymek has gone. It is the last line of defense for the nascent Tree. There, an ancient artifact shields the Tree from being found. And, it is powerful enough to expel all our enemies at once. I do not know if my mother has the power to command and use it anymore. But we will deal with that once we have found and stopped Rymek. Fly with us, as one.", ["objectivesText"] = "Speak to Gerithus , and fly with Merithra and Ysera to Lunedane.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193221, 201437, 201439, 201779, 257300 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187660, ["x"] = 0.188, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188787, ["x"] = 0.22, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 20, ["flags"] = 0 } } },
[66399] = { ["id"] = 66399, ["name"] = "We'll Cross that Bridge", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "We have to do something about this snow! If we're to give you proper support against Rymek and his minions, we can't have our wings freezing off. I sense powerful Frost Cores nearby. They're probably sustaining this blizzard. If you can destroy them, we can take out Rymek's minions in short order. And Somnikus is out there too. He flew off for Rymek like a dragon possessed. We need to get to him as soon as we can.", ["objectivesText"] = "Destroy the Frost Cores and reach Somnikus . Progress: Everything hurts.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193221, 201437, 201439, 201779, 257309, 257310, 257311, 257312 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188787, ["x"] = 0.22, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188840, ["x"] = 0.208, ["y"] = 0.796 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 21, ["flags"] = 0 } } },
[66400] = { ["id"] = 66400, ["name"] = "Winter's Fall", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "< Somnikus struggles to breathe as he slowly freezes.> I managed... to stop him from reaching the tree. I hope it was enough. Rymek must fall, now. It is up to you. Tell Ysera and Merithra that I am sorry... for being a foolish old dragon.", ["objectivesText"] = "Defeat Rymek .", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 193221, 201437, 201439, 201779, 257313, 257314, 257315, 257316 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188840, ["x"] = 0.208, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188847, ["x"] = 0.198, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.208, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 22, ["flags"] = 0 } } },
[66401] = { ["id"] = 66401, ["name"] = "The Dreamer", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "We have fought so hard to reach this point, and only one thing remains. The power in Lunedane will only respond to someone who can command the Emerald Dream from within. I had thought that it could only be my mother, but... I see how she has changed. I do not know if that difference is better, but it is real and I must acknowledge that. Come, let us face this moment together.", ["objectivesText"] = "Unleash the power of the Dream Locus .", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193221, 201437, 201439, 201779, 237812, 257317, 257318, 257319, 257320, 257321, 257322, 257323, 257324, 257325, 257327, 269986 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188847, ["x"] = 0.198, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188848, ["x"] = 0.196, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 23, ["flags"] = 0 } } },
[66402] = { ["id"] = 66402, ["name"] = "Like Mother, Like Daughter", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "From the moment I stepped into the Dream again, I knew that things were different. But now that we have beaten Rymek and his Primalists, I must consider all of the implications of what has happened. My daughter has worked to keep the green dragonflight together after my death. It is only fitting that she be the one to ascend now. Merithra must lead the Emerald Flight.", ["objectivesText"] = "Witness the ascension of Merithra . Progress: I am ready. I must be.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 193221, 201437, 201439, 201779 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188850, ["x"] = 0.198, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188848, ["x"] = 0.196, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 24, ["flags"] = 0 } } },
[66409] = { ["id"] = 66409, ["name"] = "Pressing Matters", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "The chieftain is not taking visitors. Whether Iskaara sent you or not, we're dealing with our own share of trouble right now. We don't need outsiders bringing more of it. If you want our time, make yourself useful and help our guards. The djaradin have been attacking us from across the river. Flameshaper Lorak is behind the assault. He may not look like much as far as djaradin go, but he's got more brains than the rest of them. Deal with him and bring back proof. Then we'll talk.", ["objectivesText"] = "Collect a trophy from Flameshaper Lorak at Scalecracker Keep. Progress: If that weapon's just for show, tell us now so we don't waste time.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188301, ["x"] = 0.544, ["y"] = 0.381 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188301, ["x"] = 0.544, ["y"] = 0.381 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 2, ["flags"] = 0 } } },
[66410] = { ["id"] = 66410, ["name"] = "Worst Impressions", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "<Hakota turns the trophy over in his hand before clasping it. He grimaces.> So this is what we've been reduced to. An outsider does more work for us in a day than our chieftain has in weeks. Come. I will take you to him. Maybe this will be the kick in the stern that he needs.", ["objectivesText"] = "Speak to Tutaqan . Progress: What do you seek to take from us?", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188301, ["x"] = 0.544, ["y"] = 0.381 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 3, ["flags"] = 0 } } },
[66411] = { ["id"] = 66411, ["name"] = "Troubled Waters", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "It saddens me to see our chieftain like this, but our needs cannot wait. The river has provided for us for generations. But as the djaradin push forward, the waters recede, and the creatures fight with each other for space and resources. Without guards, our anglers cannot venture far to fish. Our food stores dwindle by the day. You do not seem to need protection though. Take this net to help gather any fish you can from the river. Meat from the nearby crabs would also be welcome.", ["objectivesText"] = "Gather 10 Warmwater Riverfish and 6 Succulent Snapper Meat . Progress: The river was once beautiful and its bounty plentiful. I pray that its gifts will return to us one day.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188283, ["x"] = 0.540667, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188283, ["x"] = 0.540667, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.540667, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 4, ["flags"] = 0 } } },
[66412] = { ["id"] = 66412, ["name"] = "Carry On, Basilton", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66412 }, ["description"] = "There is one more thing this old drakonid would like to ask you, before you leave. Back when Lord Basilton and I first met, we would go on all sorts of adventures together. I think that's why he wanders off. He misses exploring. I can't do that for him anymore. But you can! You can take him to see places I never would have dreamed of, I can tell. However, we should ask Basilton what he thinks first.", ["objectivesText"] = "Speak with Basilton in the Gardens. Progress: Let's see what Basilton thinks.", ["rewardGold"] = 7410, ["rewardXP"] = 685, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66413] = { ["id"] = 66413, ["name"] = "Encroaching Heat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66413 }, ["description"] = "<This fish has clearly been dead for some time. Upon closer inspection, you notice that it appears to have been boiled--probably while still alive in the river. Unujaak back at the village might be interested in this.>", ["objectivesText"] = "Take the Half-Boiled Fish to Elder Unujaak .", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 191859, 194966, 194967, 194968, 194969, 198438, 199830, 201784, 201785, 201786, 201787 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188283, ["x"] = 0.540667, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.540667, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["startItems"] = { 191859 } },
[66414] = { ["id"] = 66414, ["name"] = "All But One", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "I have seen what you've done for the village. In easier times, I would have handled it, but... < Tutaqan glances towards the river, then back to you.> Some of our ottuks went missing recently. We believe they swam too close to the djaradin's territory. Several were recovered. None of them alive. Few in one piece. We could not find my ottuk, Ipko. She has been my hunting partner for many years. If she... <He shakes his head.> Please... aid me. If you search the river, I will search the shore.", ["objectivesText"] = "Find Ipko. Progress: I shouldn't have let her wander so far...", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 12122, 25610, 25611, 25612, 38739, 39038, 39068, 39104, 39807, 39857, 39860, 39868, 43171, 43172, 43173, 43174, 43176, 59650, 59651, 59652, 64533, 64534, 64535, 64536, 64537, 64538, 64539, 64540, 64541, 64542, 67414, 71083, 78960, 78961, 78962, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82513, 91806, 140238, 141951, 155564, 158585, 158587, 158628, 158630, 166846, 166970, 166971, 167556, 168752, 179620, 179623, 179773, 180847, 180901, 180902, 180903, 180904, 180943, 181176, 181177, 181178, 181181, 181182, 181183, 181184, 181187, 181189, 181192, 181193, 181195, 181196, 181198, 181200, 181203, 181204, 181212, 181215, 181218, 181334, 181368, 181377, 181467, 181498, 181506, 181545, 181546, 181547, 181548, 181550, 181569, 181576, 181577, 181589, 181591, 181603, 181612, 181703, 181708, 181842, 181877, 182126, 182338, 182460, 182480, 182486, 182495, 182504, 182513, 182584, 182648, 182736, 182750, 183476, 183482, 183500, 183502, 183744, 183830, 184147, 184150, 184294, 184363, 184587, 184765, 184767, 184768, 184777, 184839, 184843, 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783, 211279, 237812, 246697 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 7, ["flags"] = 0 } } },
[66415] = { ["id"] = 66415, ["name"] = "The Only Way Past Is Through", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "Unujaak told you to come, didn't he? He was the one who helped me find Ipko when I became a hunter--or, rather, helped Ipko find me. They choose and we are chosen. He is hurting. Everyone is hurting because of me. I know that they need me to lead, but I have been half of a leader without her. If I couldn't protect her, how can I protect all of Uktulut? <He takes a deep breath.> I cannot forgive myself. But I cannot let that weight keep me from putting at least one foot on the path I must walk.", ["objectivesText"] = "Help Tutaqan find a new ottuk companion. Progress: I knew this would happen one day, though it does not blunt the pain.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 10, ["flags"] = 0 } } },
[66417] = { ["id"] = 66417, ["name"] = "Salvaging Supplies", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "Bah! I can't believe Tutaqan's still moping around when we need him to command his guards and hunters! We used to trade with the Iskaara at our pier, but that's gone belly up with the djaradin closing in and scaring off our traders. Half of last month's supplies and most of our boats are still lost out in the shallow river. The guards and hunters want to help, but they've got no weapons. You look like you can protect yourself, so get out there and grab something I can make spears with!", ["objectivesText"] = "Collect 8 Whalebone Fragments and 30 Waterlogged Wood . Progress: Once our guards and hunters have new weapons, I can pull together a group to gather the rest of the wreckage.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188285, ["x"] = 0.539, ["y"] = 0.383 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188285, ["x"] = 0.539, ["y"] = 0.383 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.539, ["y"] = 0.383 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 5, ["flags"] = 0 } } },
[66422] = { ["id"] = 66422, ["name"] = "The Expedition Continues!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66422 }, ["description"] = "An ancient site, an organization with inscrutable motivations--even Rannan's R.A.D and its analyses... It all stirs the explorer in me. We must discover more about what's going on here. There are stairs to the south leading up to a tower. We shall press on.", ["objectivesText"] = "Meet Rannan and Lathos by the tower.", ["rewardGold"] = 24100, ["rewardXP"] = 515, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189166, ["x"] = 0.65, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189236, ["x"] = 0.656, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66423] = { ["id"] = 66423, ["name"] = "Worries and Validations", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66423 }, ["description"] = "The deaths of these Sundered Flame underscore how dangerous the Ruins of Karnthar are. But Rannan believes that with some tinkering the R.A.D. can still quell the energies here. Again, we're treating the symptoms and not the root cause. Search the ruins for clues and see if you can discern their original function. And make haste, <name>. We may not have much time.", ["objectivesText"] = "Find clues about the origin of the ruins. Progress: Were you able to learn anything about the ruins?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189236, ["x"] = 0.656, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189236, ["x"] = 0.656, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66425] = { ["id"] = 66425, ["name"] = "Arcane Overload", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66425 }, ["description"] = "There! Finished! May I present to you... the R.A.D.D.E.R! DUN DUN DUUUUN! I have calibrated it to the frequency of the energy surrounding the dragon consoles and inscribed a glyph of dispel magic on it. The R.A.D.D.E.R. will dispel the arcane energy and shut down the dragon console , but the glyph will weaken after each use. Pretty handy, isn't it? I detect four of these consoles in our vicinity. Go shut them down!", ["objectivesText"] = "Help Rannan dispel the arcane bubbles. Progress: Were you able to dispel all the arcane bubbles with the R.A.D.D.E.R.?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 188845, ["x"] = 0.656, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 188845, ["x"] = 0.656, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66427] = { ["id"] = 66427, ["name"] = "A Looming Menace", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66427 }, ["description"] = "The arcane wounds I suffered cannot be healed in the field. I am afraid that they are too grave for me to fight. I must ask your help again, <name>. You have to find Tharohn and stop her from overloading more consoles. Doing so would buy Rannan a few precious moments to calibrate the R.A.D. ... R.A.D.D.E.R... whatever he's calling it now. Maybe then we can thwart the Sundered Flame's machinations.", ["objectivesText"] = "Kill Tharohn. Progress: Do not waste a moment. We are on borrowed time.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189792, ["x"] = 0.684, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189792, ["x"] = 0.684, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66428] = { ["id"] = 66428, ["name"] = "Friendship For Granted", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66428 }, ["description"] = "Alright! The R.A.D.D.E.R.E.R is calibrated and ready to go--for you! Why am I not using it? Simple! You have to think of and consider all the possibilities. Let's say it blows up. Who would fix it if I am injured, unconscious, or dead? Could you imagine? Now, go dispel the barrier so we can return to camp and get Lathos patched up. I'll be... standing back.", ["objectivesText"] = "Use the R.A.D.D.E.R.E.R to dispel the arcane barrier. Progress: Is this day going to get any better?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189791, ["x"] = 0.685, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189791, ["x"] = 0.685, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66429] = { ["id"] = 66429, ["name"] = "I Will Remember", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66429 }, ["description"] = "I... I need a few moments, please. Go back to Camp Nowhere, $p. I will meet you there.", ["objectivesText"] = "Meet Rannan outside of Camp Nowhere.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191265, 191909, 192110, 192475, 202198, 202199 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189791, ["x"] = 0.685, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193337, ["x"] = 0.636, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66431] = { ["id"] = 66431, ["name"] = "In Mourning", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "This did not need to happen. Those cowardly djaradin... slaughtering our ottuks and leaving them for their twisted beasts to pick clean... I do not take Tutaqan 's grief lightly, but I worry for the future of our people if he dwells in darkness and grief for too long. We need to act. It looks like he was headed to the overlook above us. You have done him a great favor this day. He may be open to any good will you can show him. Please, see what can be done.", ["objectivesText"] = "Attempt to help Tutaqan . Progress: Please leave me be.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188283, ["x"] = 0.540667, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.540667, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 9, ["flags"] = 0 } } },
[66435] = { ["id"] = 66435, ["name"] = "Site Salvage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66435 }, ["description"] = "I've worked with many elementals as a shaman, but I've never seen any this aggressive! The Expedition discovered a titan vault here, but a barrier protects the inner chamber. When we tried to dispel the barrier, I think we triggered some kind of security system... There were suddenly angry elementals everywhere! Many explorers were working in the dig site when the elementals attacked. Many of them are trapped, and NONE of them are fighters. Please go down into the dig site and help them retreat!", ["objectivesText"] = "Rescue 5 Beleaguered Explorers in Life Vault Ruins. Progress: I am only a consultant for the Expedition, but I care for the explorers I've met here. We can't leave any of them behind!", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188735, ["x"] = 0.66, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66436] = { ["id"] = 66436, ["name"] = "Unearthed Troublemakers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66436 }, ["description"] = "The earth elementals are not just trying to repel us, they're destroying artifacts and equipment, too! It's as though they've been programmed to destroy anything titan... We're holding them off, but we can't continue to study this site while they're here. Please help us push them back so we can have some exploring room!", ["objectivesText"] = "Kill 12 Earth Elementals in the Life Vault Ruins. Progress: The elementals caught us by surprise! Be careful!", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562, 194407, 194408, 194409, 194410 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188735, ["x"] = 0.66, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66437] = { ["id"] = 66437, ["name"] = "A Key Element", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66437 }, ["description"] = "<This orb of earth thrums with energy.> < Elementalist Taiyang might know what to do with it.>", ["objectivesText"] = "Return the Orb of Primal Stone to Elementalist Taiyang in the Life Vault Ruins. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.663, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["startItems"] = { 191904 } },
[66438] = { ["id"] = 66438, ["name"] = "Lofty Goals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66438 }, ["description"] = "Air is a powerful element. It cuts through stone and fills sails to take us where we need to go. My hypothesis is that air will be the most effective at removing this barrier. It's simple, really. My scouts report they've found the Orb of Primal Gales . Scout Ri'tal can lead you to it. You can find them near Hornswog Hollow. Quickly!", ["objectivesText"] = "Find Scout Ri'tal in Hornswog Hollow. Progress: Have you found the scout?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 182694, 182695, 191904, 192480, 192524, 192545, 192546, 192562 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188503, ["x"] = 0.666, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66439] = { ["id"] = 66439, ["name"] = "Rapid Fire Plans", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66439 }, ["description"] = "Elemental orbs, eh? If there's earth, there's bound to be fire! The primalists over near tae hornswog nests are reshapin' tae land with lava. If anyone has an interest in tae Orb o' Primal Flames, it'd be them! Take them out and see if they have anythin' useful!", ["objectivesText"] = "Collect Primal Flame Fragments from Primalist Forces in Hornswog Hollow. Progress: Acadia had a lead on the Orb of Primal Flames . Have you found it?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188053, ["x"] = 0.666, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66440] = { ["id"] = 66440, ["name"] = "Closure", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "I do not know what to say. I had no idea that the chieftain's pain ran so deep. It makes sense. Ottuks are not pets to our people--especially not to hunters like our chieftain. They are our friends, our companions... and members of our families. Ipko was Tutaqan 's first and only ottuk. Uktulut hunters hold this bond to be sacred. I will see that her passage to the place of our ancestors is a peaceful one.", ["objectivesText"] = "Speak to Tutaqan . Progress: This is all I can do.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188283, ["x"] = 0.540667, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.540667, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 8, ["flags"] = 0 } } },
[66441] = { ["id"] = 66441, ["name"] = "Distilled Effort", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66441 }, ["description"] = "The Orb of Primal Stone is a fortuitous find, but Acadia and Tae'shara have conflicting hypotheses regarding the barrier. I have my own hypothesis. Perhaps with more elemental orbs an answer will become clear. One of the explorers saw an oversized water elemental in a nearby cave. Defeat the elemental, and perhaps you will find another orb.", ["objectivesText"] = "Kill Acequian in the cave east of the Life Vault Ruins. Progress: Did the elemental have another orb?", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562, 194367 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.663, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66443] = { ["id"] = 66443, ["name"] = "Calling the Hunting Party", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "<The resounding call of a hunting horn rumbles from the center of the village, calling the Uktulut hunters to attention. You should investigate.>", ["objectivesText"] = "Investigate the reason for the hunting call. Progress: This could be our only chance to hit them where it hurts!", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188301, ["x"] = 0.544, ["y"] = 0.381 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188301, ["x"] = 0.544, ["y"] = 0.381 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 11, ["flags"] = 0 } } },
[66444] = { ["id"] = 66444, ["name"] = "While the Iron Is Hot", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "I spoke to our lookouts on the way down. They say this djaradin-- Zhurtan the Riverboiler --has begun his heinous ritual southwest of here, close to the waterfalls where many of our ottuks build their nests. If they're boiling the river upstream from us now, I assume they've decided to be done with us more quickly. We would be forced to starve or retreat. We will do neither. They've prodded us like cowards afraid of a true fight. So let's bring the fight to them this time, shall we?", ["objectivesText"] = "Slay Zhurtan the Riverboiler . Progress: We have your back, as you have ours.", ["rewardGold"] = 561800, ["rewardXP"] = 6155, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 12, ["flags"] = 0 } } },
[66447] = { ["id"] = 66447, ["name"] = "Beyond the Barrier", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66447 }, ["description"] = "Now that the barrier is down, let us explore the vault!", ["objectivesText"] = "Investigate the Life Vault in the Life Vault Ruins. Progress: There's a lot to examine in the vault, but we should start small to be safe first!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562, 194371, 194372, 194376, 194393, 194416 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 197860, ["x"] = 0.665, ["y"] = 0.559 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190354, ["x"] = 0.661, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66456] = { ["id"] = 66456, ["name"] = "A Poisonous Palette", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66456 }, ["description"] = "I may not be great at my job, but at least I paid attention when I was learning how to do it. Every Waywatcher worth her scales knows how to make a proper antidote. I just need enough poison to mix it properly. Nori said the tarasek who attacked her had spears coated with the stuff. Find them and bring their spears to me. If my hunch is correct, I'll be able to make an antidote with the residue from the spearheads. I just hope we have enough time.", ["objectivesText"] = "Gather 8 Envenomed Spears . Progress: Please hurry, <name>. I am keeping Nori stable for now, but the poison is still spreading.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191308, 191317, 191405, 191852 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.557, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66457] = { ["id"] = 66457, ["name"] = "Ending the Blue Period", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66457 }, ["description"] = "The Embertooth all follow an oversized brute that I've taken to calling Bluescale . He has always been the aggressive sort, but until now he's always kept his pack of scavengers away from the main roads. Sure, they were territorial, but hostile? Not until now. Bluescale has to be responsible for this sudden escalation. Find him and take him down.", ["objectivesText"] = "Slay Bluescale . Progress: Be careful, <class>. Bluescale is tougher than your average Tarasek scavenger.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191308, 191317, 191405, 191852 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.557, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66458] = { ["id"] = 66458, ["name"] = "Legacy of Tyr: Secrets of the Past", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 66458, 70048, 70049, 70050, 70055 }, ["description"] = "To stop Raszageth from freeing the other Incarnates, the power of the Aspects must be restored. Inconveniently, the Titans are rather preoccupied and Keeper Tyr is long dead. Queen Alexstrasza has suggested a plan. In the depths of the Badlands lies a Titan facility called Uldaman. Apparently allies of Tyr may have hidden a disc of his memories there. Word is that the place has been overrun by troggs. Gather your allies, head to Uldaman, and seize the disc in the name of the Dragon Queen!", ["objectivesText"] = "Enter Uldaman: Legacy of Tyr in the Badlands and recover the disc. Progress: Did you retrieve the disc?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 192493, 199109, 199211, 199337, 199686, 199836, 199837, 199838, 199839, 201302, 201303, 201304, 201305, 201306, 201307, 201308, 201309, 202188 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 189569, ["x"] = 0.618, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 189569, ["x"] = 0.618, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 0, ["flags"] = 0 } } },
[66459] = { ["id"] = 66459, ["name"] = "The Field of Ferocity: Terror of the Swamp!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66459 }, ["series"] = { 70444 }, ["description"] = "Welcome one and all to the Fields of Ferocity! While this sparring field is used for traditional events, the centaurs have graciously allowed me to set up shop off-season. They say it tests their strength and brings them honor. You want to take home the title of champion? Well then, let me know when you're ready and you can take on the introductory competition.", ["objectivesText"] = "Defeat Maneet . Progress: Speak with Gurgthock to start the round, then defeat the first competitor of the Field of Ferocity.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
[66460] = { ["id"] = 66460, ["name"] = "The Field of Ferocity: Lord of Decay!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66460 }, ["description"] = "I tried to get one of those nasty gnolls for this gauntlet. Unfortunately, none of my associates know how to speak with them. We did manage to catch one of their freaky creations though. That should serve as a good opponent! Let me know when you want to start the second round!", ["objectivesText"] = "Defeat Nightrot . Progress: Well, what are you waiting for? Speak with Gurgthock to start the round, then defeat the second competitor of the Field of Ferocity.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
[66461] = { ["id"] = 66461, ["name"] = "The Field of Ferocity: Foe from the Volcano!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66461 }, ["description"] = "One of the first volunteers for this competition hails from the Waking Shores. A big djaradin fellow, not quite as angry as his kin. He just seems to enjoy the sport of fighting. Hey, that works for me.", ["objectivesText"] = "Defeat Ceeqa the Peacetaker . Progress: Ceega has a famous entrance. You need to speak with Gurgthock to start the round, then defeat the third competitor of the Field of Ferocity.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
[66462] = { ["id"] = 66462, ["name"] = "The Field of Ferocity: Lost in the Dream!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66462 }, ["description"] = "You know, for it being the Dragon Isles, I haven't seen too many dragons. We did get a duo of dragonkin that requested to be signed up for this competition together though. They seem plenty eager to prove themselves though, so good luck!", ["objectivesText"] = "Defeat Sherath and Taresh . Progress: You need to speak with Gurgthock to start the round, then defeat the fourth competitors of the Field of Ferocity.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
[66463] = { ["id"] = 66463, ["name"] = "The Field of Ferocity: Elemental Revenge Round!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66463 }, ["description"] = "We're changing the roster at the last minute. Some Primalist bigwig wants to join in on the competition to face you. And I'm not saying no to an angry elemental dragon. I'm sure you'll be fine. If not, then... well, you signed the waiver, right?", ["objectivesText"] = "Defeat the Primalist champion. Progress: You need to speak with Gurgthock to start the round, then defeat the fifth competitor of the Field of Ferocity.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
[66464] = { ["id"] = 66464, ["name"] = "The Field of Ferocity: Master of the Hunt!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66464 }, ["description"] = "This is it. You and your pals have hit the big time. A match against the champ, Huntmaster Amaa herself. Don't pat yourself on the back just yet. She's ruthless. It was nice knowing you. After she kills you, can I have your stuff?", ["objectivesText"] = "Defeat Huntmaster Amaa . Progress: You need to speak with Gurgthock to start the round, then defeat the final competitor of the Field of Ferocity. Good luck.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 197677, 197679, 197684, 197690, 197693, 197699, 197703, 197903 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
[66465] = { ["id"] = 66465, ["name"] = "Cache and Release", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66465 }, ["description"] = "Even with their leader gone, the Tarasek are unlikely to stop using their poison-tipped spears simply because we ask them nicely. I cannot risk even one of these weapons being used on an unsuspecting traveler. They will all need to be destroyed. If you did not see any in the caches by the pools, then the Embertooth are likely keeping their spears closer to the source. No one else will get hurt because of my carelessness. Enter the cave and destroy any weapon caches that you find.", ["objectivesText"] = "Destroy 8 Poisoned Spear Stashes .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191308, 191317, 191405, 191852, 197122 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.557, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66467] = { ["id"] = 66467, ["name"] = "Art Imitates Life", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66467 }, ["description"] = "The last time I was in this cave, I sketched a massive flower that dripped a vile, viscous sap. It's one of my best drawings, I couldn't forget it if I tried. That sap is what's stuck to these tarasek spears, I'm sure of it. They must have started harvesting it to envenom their weapons. The plant is beautiful; it will be a shame to kill it. Still, we can't let the tarasek keep harvesting it. <name>, please cull the plant and put a stop to this whole mess.", ["objectivesText"] = "Slay the Greater Venomsprout .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191308, 191317, 191405, 191852, 195186, 195187, 195188, 195189 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.557, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66468] = { ["id"] = 66468, ["name"] = "What Once Was Ours", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66468 }, ["series"] = { 66470, 66471, 66472, 66473, 71179 }, ["description"] = "<Thadezus scoffs at your approach.> Are you a mortal of action, or are you going to get out of our way, <class>? I have lost many good soldiers to those Primalists up ahead. We have an idea of what they are planning, but we must first rout the enemy and rescue those serving under me.", ["objectivesText"] = "Defeat the Primalists occupying the Gelikyr Overlook. Progress: Have you stopped the Primalists, or do I need to do this myself?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192795, 192808, 197097, 200670, 200671, 200672 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189174, ["x"] = 0.526, ["y"] = 0.672 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66470] = { ["id"] = 66470, ["name"] = "The Forward Push", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66470 }, ["series"] = { 66468, 66471, 66472, 66473, 71179 }, ["description"] = "< Sharnax scratches her chin.> The commander was right. The Primalists are calling reinforcements from the elemental planes. < Sharnax smirks.> It would be a shame if something happened to their gateways, <class>.", ["objectivesText"] = "Obtain Misttouched, Earthen, and Iceforged gateway stones , and close the 3 elemental gateways. Progress: We need to close those gateways.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 1010, 1011, 10547, 156940, 192795, 192808, 200670, 200671, 200672 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.646667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66471] = { ["id"] = 66471, ["name"] = "Prime Planning", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66471 }, ["series"] = { 66468, 66470, 66472, 66473, 71179 }, ["description"] = "The commander ordered me to establish a forward base and dispatch any resistance. It wasn't until I did all the dispatching that I realized something. < Sharnax lets out a long sigh.> The Primalists were talking about Tyrhold. Unless you are exceptionally skilled at interrogation, I need you to discover their plans.", ["objectivesText"] = "Collect 7 Primalist Orders from the nearby Primalists in the upper terrace of Gelikyr Overlook. Progress: Do you have something we can show the commander?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192795, 192808, 200670, 200671, 200672 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.646667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66472] = { ["id"] = 66472, ["name"] = "Primal List", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66472 }, ["series"] = { 66468, 66470, 66471, 66473, 71179 }, ["description"] = "The gateways closed, the elementals slain, and the Primalists stopped... for now. < Sharnax laughs.> Is there anything we cannot do, <class>? I guess only time will tell. Take the plans back to the commander. I am certain he will be glad to see we have been successful.", ["objectivesText"] = "Deliver the Bundle of Primalist Orders to Commander Thadezus on the bridge at the Gelikyr Overlook. Progress: <Thadezus stares at you.> What do you want, <class>?", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["rewardItems"] = { 192795, 192808, 200537, 200670, 200671, 200672 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189174, ["x"] = 0.526, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.646667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66473] = { ["id"] = 66473, ["name"] = "The Land Awakens", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66473 }, ["series"] = { 66468, 66470, 66471, 66472, 71179 }, ["description"] = "The fiends in this cave were too much for me. < Sharnax lets out a labored cough.> I have seen what you can do. I need you to slay these elementals before they reach their full potential. We cannot allow the Primalists to take control of Tyrhold!", ["objectivesText"] = "Defeat the Primordial Wrath and Primordial Hail in the Gelikyr Overlook. Progress: < Sharnax coughs.> Is it done?", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 192795, 192808, 197103, 200670, 200671, 200672 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.646667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66488] = { ["id"] = 66488, ["name"] = "WANTED: Frigellus", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66488 }, ["description"] = "<The page's script glows with a soft blue light.> Previously a cherished plaything of Malygos, the elemental Frigellus suffered from his master's neglect. While this once-happy settlement crumbled apace, the churlish and playful creature grew warped and twisted by the evils that plague this land. Please see that it is safely neutralized. Bring word of your success to Custodian Cynegos .", ["objectivesText"] = "Kill Frigellus near Camp Antonidas. Progress: Return to Custodian Cynegos in Camp Antonidas.", ["rewardGold"] = 842700, ["rewardXP"] = 6175, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189952, ["x"] = 0.46, ["y"] = 0.382 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.382 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "group" },
[66489] = { ["id"] = 66489, ["name"] = "Setting the Defense", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66489 }, ["description"] = "Custodian Cynegos and I were just discussing the impact the Primalist attack has had on the plans to assault the Cobalt Assembly, and I had an idea. <Celeste withdraws a wand from the folds of her robes.> Take my wand and empower their weapons! A little bit of fire should do the trick...", ["objectivesText"] = "Empower Azure Defenders in Camp Antonidas. Progress: Have they been sufficiently enchanted?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 192471 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192335, ["x"] = 0.46, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192335, ["x"] = 0.46, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66493] = { ["id"] = 66493, ["name"] = "Send It!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66493 }, ["description"] = "<You hear muffled muttering coming from the other end of the portal.> Hey! Hey you! I have some mail for our apprentices in the field: care packages, gifts, things they've ordered via magical courier... Standard fare, really. Mind doing me a favor and handing them out?", ["objectivesText"] = "Throw packages to Kirin Tor Apprentices in Camp Antonidas. Progress: How's your arm? Don't forget to stretch, or you might hurt yourself.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 197107 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 188915, ["x"] = 0.46, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 188915, ["x"] = 0.46, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66500] = { ["id"] = 66500, ["name"] = "Ways of Seeing", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66500 }, ["description"] = "We're not doing anything! We're not doing anything! Hang on a minute... You look like a pretty important <race>... Want in on a secret? Turns out there's magical art in these ruins. And we can see it! <Scrumpy proudly sticks out his chest.> I can show you how to see 'em too! Just... don't tell Noriko yet.", ["objectivesText"] = "Uncover ancient images in Camp Antonidas. Progress: Noriko told us to stay out of trouble. Not sure how to do that to be honest.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200926 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189198, ["x"] = 0.476, ["y"] = 0.402 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189198, ["x"] = 0.476, ["y"] = 0.402 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.402 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66503] = { ["id"] = 66503, ["name"] = "For The Love of Others", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66503 }, ["description"] = "Ah, I see my apprentices have roped you into their little games. <Noriko chuckles.> It appears they--and you--have stumbled onto something. The purpose behind these ruins is slowly revealing itself to us, and there's more than faded images and song... Something calls out from atop this tower. I see the intrigue in your eyes. Go. You have my permission. See what you can see.", ["objectivesText"] = "Investigate the top of the Ruined Tower in Camp Antonidas. Progress: Remembrance is a gift--and a burden.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 198676, 200926 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66523] = { ["id"] = 66523, ["name"] = "Tending the Forge", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66523 }, ["description"] = "If you're looking for an instructor, I'm sorry to say I... Ah, you're not an apprentice! My apologies. Allow me to introduce myself. I am Custodian Vernagos , one of the caretakers of these ruins. More specifically, the task of restoring this workspace to its former glory has fallen upon my very tired shoulders. Would you be able to lend a hand? All the reagents I need are nearby: ice elemental cores, embercones, hornswog leather... Fairly standard, easily gathered stuff. What say you?", ["objectivesText"] = "Gather reagents for the forge by collecting hornswog hides, dormant embercones , and calving cores around Camp Antonidas. Progress: Fresh air and magical relics. What more could one ask for? Ha!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 192473, 192474, 192776 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189208, ["x"] = 0.46, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189208, ["x"] = 0.46, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66524] = { ["id"] = 66524, ["name"] = "Amateur Protography", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66524 }, ["description"] = "So, you want to be a seasoned cataloger like me? You've come to the right place! The Wild Preserve is teeming with knowledge waiting to be found and filed! And how do I do that you ask? Why, with my handy Catalog-izer 3000 Dragon Isles edition--now with improved motion capture! To gain experience, photograph a proto-dragon egg, a whelp learning to fly, and a hunting proto-drake. Meet me at the ancient, proto-dragon skeleton west of here, and I'll assess your photos.", ["objectivesText"] = "Take pictures of proto-dragons.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192465 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187705, ["x"] = 0.484, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193740, ["x"] = 0.39, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66525] = { ["id"] = 66525, ["name"] = "Competitive Protography", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66525 }, ["description"] = "Well, now that you've cut your teeth on some starter shots, how about we move onto something a little spicier? I spotted a gorgeous proto-drake flying around the area behind us. Beautiful horns, scales crackling with electricity... Probably the work of the Primalists, no doubt, but art is art! See if you can get a picture of the proto-drake and some of its eggs. You might have to climb up a bit to get a good shot!", ["objectivesText"] = "Photograph an Infused Proto-Dragon Egg and an Infused Proto-Drake. Progress: If you get in a fight with the Primalists, make sure you keep that camera pristine! It's my only prototype!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192465 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193740, ["x"] = 0.39, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193740, ["x"] = 0.39, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66526] = { ["id"] = 66526, ["name"] = "Preserving the Wilds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66526 }, ["description"] = "The Wild Preserve is one of the few areas where proto-dragons thrive. But the Primalists are disrupting their nesting grounds by sending sorties to capture and experiment on proto-whelps and proto-drakes. Show them no mercy. Locate these Primalist poachers, wipe them out, and free their captives. The proto-dragon species depends on it.", ["objectivesText"] = "Free 5 Captured Proto-Whelps or Captured Proto-Drakes. Progress: If we want these creatures to survive, we must protect them.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192465 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193954, ["x"] = 0.39, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193954, ["x"] = 0.39, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66527] = { ["id"] = 66527, ["name"] = "Professional Protography", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66527 }, ["description"] = "I haven't trained a photographer as good as you... that's still alive, that is. It's a dangerous profession. Speaking of dangerous, our final target is a large proto-dragon we believe may be one of the next apex predators in this preserve. Let's get up close and personal and take a picture!", ["objectivesText"] = "Use the Vertical Enhancement Apparatus and photograph the Slumbering Proto-Dragon. Progress: Don't worry, <name>. You're much more competent than the last person I sent up there.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192465 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193740, ["x"] = 0.39, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193740, ["x"] = 0.39, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66528] = { ["id"] = 66528, ["name"] = "King Without a Crown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66528 }, ["description"] = "This ancient proto-dragon must have been a glorious creature when it was alive--perhaps the largest the Wild Preserve has ever seen. But it wasn't enough. Observe the skeleton more closely, so we may learn the story of its final moments.", ["objectivesText"] = "Investigate the Proto-Dragon Skeleton. Progress: An incredible specimen--and a reminder of our origins.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192465 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193954, ["x"] = 0.39, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193954, ["x"] = 0.39, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66529] = { ["id"] = 66529, ["name"] = "A Thousand Words", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66529 }, ["description"] = "With all that we've learned here, I can't imagine moving on without a memento. Would you be kind enough to take my picture next to the proto-dragon fossils?", ["objectivesText"] = "Photograph Dervishian near the Proto-Dragon Skeleton. Progress: It should only take a moment.", ["rewardGold"] = 7150, ["rewardXP"] = 1415, ["rewardItems"] = { 192465 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193954, ["x"] = 0.39, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189484, ["x"] = 0.388, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66546] = { ["id"] = 66546, ["name"] = "Retrieve the Discs", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66173, 66174, 66546, 66547, 66636, 67722, 69097, 71152 }, ["description"] = "The discs in here represent the sum of this facility's knowledge. We need to retrieve them! I'll bring the barrier down with this console. It'll be on ye to retrieve the discs.", ["objectivesText"] = "Retrieve the three discs. Progress: Can ye imagine the knowledge that these discs hold?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 192768 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192820, ["x"] = 0.55, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192967, ["x"] = 0.544, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1374, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1374, ["name"] = "In the Halls of Titans", ["orderIndex"] = 6, ["flags"] = 0 } } },
[66547] = { ["id"] = 66547, ["name"] = "It Belongs in a Museum... Eventually", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66173, 66174, 66546, 66547, 66636, 67722, 69097, 71152 }, ["description"] = "Waves of titan security, escaped proto-dragons, keys that turn you into constructs... I'll just say it. I've never had so much fun in my LIFE! Although Naleidea will probably say this is where the real fun begins. We're sitting on a trove of confidential titan data, thanks to the effort ye put in! When ye can, come meet us at camp and we'll compare notes.", ["objectivesText"] = "Meet Toddy back at the Dragonscale Expedition camp. Progress: Thanks again for a once-in-a-lifetime experience!", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 201782 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192967, ["x"] = 0.544, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192980, ["x"] = 0.472, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1374, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1374, ["name"] = "In the Halls of Titans", ["orderIndex"] = 7, ["flags"] = 0 } } },
[66553] = { ["id"] = 66553, ["name"] = "Hollow Up", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66553 }, ["description"] = "The Winterpelt are a special case among the furbolgs. I'd categorize 'em as a wee bit \"isolationist.\" They are ghosts in the hollow, their pelts blendin' in with tha snow. Usedta keep to themselves, but now they're outright aggressive. They attacked our camp with nae provocation! Somethin' must be wrong to drive 'em to it. I can't ask 'em what happened--yet--but maybe ye can find some clues in their village?", ["objectivesText"] = "Uncover 6 clues in Winterpelt Hollow.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 3270, 3272, 3273, 25628, 25629, 25630, 57139, 112509, 112510, 112511, 112528, 123852, 131387, 189544, 190189, 190342, 190343, 190345, 190346, 190348, 190350, 190351, 190352, 190353, 190355, 190356, 190357, 190358, 190359, 190360, 190361, 190363, 190365, 190366, 190368, 190369, 190605, 190632, 190633, 190635, 192423, 192424, 192426, 192427, 192429, 192440, 192450, 193666, 193671, 236957, 260864, 260865, 260866, 260867 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66554] = { ["id"] = 66554, ["name"] = "Aggressive Self-Defense", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66554 }, ["description"] = "With the Winterpelt all in a tizzy, I don't imagine they'll appreciate ya poking around up there. Don't be afraid to defend yourself if they start somethin'. A firm reminder that ya mean business might knock some sense back into 'em. Try not to kill anyone though, will ya? I know how ya adventurin' types can get.", ["objectivesText"] = "Defeat 6 Winterpelt furbolgs.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66555] = { ["id"] = 66555, ["name"] = "Bear With Me", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66555 }, ["description"] = "Aye, sounds like a right mess up there--like a storm blew through and wrecked the whole place. I can see why they'd be up in arms, but why attack us? This would be a lot easier if we could just talk it out, but the Winterpelt are famously tight-lipped and don't seem to speak any of the common branches of Furbolg-ish. Furbolgian? Eh, ye know what I mean. I don't suppose ya happened to have a nice chat with any of 'em while ye were checking in on them, did ye?", ["objectivesText"] = "Assist Sonova's translation. Progress: Are ye even listenin'?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66556] = { ["id"] = 66556, ["name"] = "Ice Cave Ya Got There", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66556 }, ["description"] = "Well, yer accent is atrocious, and ten-thousand years o' isolation an' linguistic drift hasn't done us any favors, but I think I got a rough impression at least. The common thread in what they were tryin' to say was somethin' aboot a \"bad cave wind\" or an \"evil storm cave.\" That, or their laundry was too Thursday? Look, this isn't like learnin' Gnomish; there're goin' to be some hiccups. I'm pretty sure aboot the cave though, so let's start there.", ["objectivesText"] = "Investigate the cave. Progress: That's the best I got. Ye try translatin' this stuff if ye don't like it.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 197627, 197988 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66558] = { ["id"] = 66558, ["name"] = "Rowie", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66558 }, ["description"] = "You were the one that came back with the others from Brackenhide, weren't you? Then you probably know what happened to Kaqiata... Her son, Rowie , has been distraught ever since Brena and the others returned without her. I'll stay here in case he comes back, but could you look for him? I think he ran off towards the ice cave to the east. He said something about trying to fight the yeti in there!", ["objectivesText"] = "Find Rowie . Progress: I have to prove myself!", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189533, ["x"] = 0.137, ["y"] = 0.483 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186542, ["x"] = 0.155333, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.137, ["y"] = 0.483 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66559] = { ["id"] = 66559, ["name"] = "Back To Camp", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66559 }, ["description"] = "I saw Mordigan run out of there like a dwarf possessed. I'll go chase him down and make sure he gets back to the others in one piece. If you hug the cliff and jump down the waterfalls, you should be able to avoid stirring up any more of the gorlocs. See you back at camp.", ["objectivesText"] = "Return to Examiner Rowe in Whaler's Nook.", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 188030, ["x"] = 0.108, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187136, ["x"] = 0.076, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.108, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66582] = { ["id"] = 66582, ["name"] = "Power Procurement", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["series"] = { 66595, 66597, 66598, 70215 }, ["description"] = "In normal circumstances, the capture of energy is not problematic. However, the energy we require is massive and unstable. This enchanted vessel should provide a safe means of transport. There is a region to the southwest filled with energy-laden creatures. The anomalous energy within these creatures is powerful, but unstable. Capture their energy and return it to me. Then we may embark on the remainder of this journey together.", ["objectivesText"] = "Gather energy within the vessel for Warpcaster Delandra at Camp Antonidas. Progress: Have you collected what we discussed?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192448, 198538, 198605 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4968, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 0, ["flags"] = 0 } } },
[66586] = { ["id"] = 66586, ["name"] = "Legacy of Tyr: Secrets of the Past", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 1, ["storyline"] = { 66586, 69923, 69925, 69944, 69992 }, ["description"] = "To stop Raszageth from freeing the other Incarnates, the Aspects' power must be restored. But this will not be an easy task. The Titans are silent and Keeper Tyr is long dead. Queen Alexstrasza has devised a plan. In the Badlands lies a Titan facility called Uldaman. She believes Tyr's companions hid a disc of his memories inside its depths. Take your allies to Uldaman and find the disc for the Dragon Queen. Let us hope Tyr's knowledge can be used to re-empower the Aspects.", ["objectivesText"] = "Enter Uldaman in Badlands. Discover the cause of the disturbances. Progress: Has the exploration been a success?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 199211, 201302, 201303, 201304, 201305, 201306, 201307, 201308, 201309 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.126 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 5, ["flags"] = 0 } } },
[66595] = { ["id"] = 66595, ["name"] = "Dormant Discovery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["series"] = { 66582, 66597, 66598, 70215 }, ["description"] = "<Nevermind how this curious parchment ended up in your bags. What's important are the contents of the message.> Members of the Dragonscale Expedition: Your assistance is required! Report to the Rubyscale Outpost at once! <Before the signature can be read, the magical lettering inscribed on the note dissipates into a cloud of white and blue-tinted dust, leaving behind an empty page and a deliciously flowery scent in the air.>", ["objectivesText"] = "Deliver the message to Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 198538 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 198538 } },
[66596] = { ["id"] = 66596, ["name"] = "Whispers on the Winds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 1, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 70050, 72240 }, ["description"] = "Hello, $p. It's been a while, and I wish we had more time to catch up. But you see, I've just had a rather enlightening... no, make that foreboding... yes, a foreboding conversation with an old friend. Sometimes a revelation can be both, after all. I really must tell you of what I've learned.", ["objectivesText"] = "Speak with Archmage Khadgar in Stormwind. Progress: Our journey begins with you.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 192493, 199109, 199211, 199337, 199686, 199836, 199837, 199838, 199839, 202188 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 189569, ["x"] = 0.618, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 7, ["flags"] = 0 } } },
[66597] = { ["id"] = 66597, ["name"] = "This Old Stone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["series"] = { 66582, 66595, 66598, 70215 }, ["description"] = "This stone behind me is just one piece of, what do ye call it--ancient technology--we stumbled upon here in the Isles. But, we're not entirely sure what they are just yet. Baffling, really. We've sent word to some friends to see if they can help. In the meantime, perhaps ye can figure out how tae use it?", ["objectivesText"] = "Inspect the Etched Ancient Monolith. Progress: So. Is there more to it, or is it really just a heaping hunk o' stone?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 198538 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 2, ["flags"] = 0 } } },
[66598] = { ["id"] = 66598, ["name"] = "Nightborne Know-How", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["series"] = { 66582, 66595, 66597, 70215 }, ["description"] = "Ancient symbols aren't really me thing. However... <Thaelin searches through his belongings, eventually pulling out a map. At the top of the parchment appears the name Antonidas, scribbled in large, sloppy letters.> Ah hah! Here it is! Bit of a trek, but a few of those old magic users can be found... here. <Pointing to a spot on the map.> Maybe they have somethin' tae offer.", ["objectivesText"] = "Locate Warpcaster Delandra at Camp Antonidas in The Azure Span.", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 198538 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 2022, 2024 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 3, ["flags"] = 0 } } },
[66612] = { ["id"] = 66612, ["name"] = "Crabtender's Quandry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66612 }, ["description"] = "The crabs are in danger! This particular bunch has been through a rough season. Their previous habitat was ransacked by the Primalists, and then I led them to this area only for gorlocs to invade! I thought they would be safe here, but the gorlocs only nurture aggression in their crabs, leading them to an early demise! Please, defeat some of the gorlocs so the crabs can escape!", ["objectivesText"] = "Kill 12 gorlocs in Cliffdrip Camp. Progress: These crabs deserve better than to serve a gorloc!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 196827, ["x"] = 0.596, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 196827, ["x"] = 0.596, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66622] = { ["id"] = 66622, ["name"] = "Wayward Tools", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66622 }, ["description"] = "This is terrible! My *hic* tools seem to have run off when I wasn't looking. I can't *hic* stand the thought of them all alone out there, no doubt scared out of their minds! Would you round them up for me? Just be patient and *hic* try to soothe their nerves and I'm sure they'll warm right up to you!", ["objectivesText"] = "Rescue 6 Wayward Tools . Progress: Did you *hic* find them?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186755, ["x"] = 0.655, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186755, ["x"] = 0.655, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66635] = { ["id"] = 66635, ["name"] = "Reunited, Once Again", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "That should be enough. I can sense the others just on the outside of the grove, ready to enter the Dream. When you're ready, speak to me and I will break the ice walls and bring down the dome. I hope that my changes will not dishearten the flight. We will not be done, but we will be all together again.", ["objectivesText"] = "Speak with Ysera to lower the barrier.", ["rewardGold"] = 16980, ["rewardXP"] = 615, ["rewardItems"] = { 193221, 201437, 201439, 201779 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187646, ["x"] = 0.186, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187660, ["x"] = 0.188, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 11, ["flags"] = 0 } } },
[66636] = { ["id"] = 66636, ["name"] = "The Other Side", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66173, 66174, 66546, 66547, 66636, 67722, 69097, 71152 }, ["description"] = "We've finally figured out the placement of the third stone--and ye get to do the honors! I've affixed the stone to what's left of the watcher's staff. Just climb the scaffolding there, hold it up, and watch the show!", ["objectivesText"] = "Open the door with the watcher staff. Progress: When I get back tae Stormwind, my name is going into the book beside the greatest explorers of our time. Move over Brann, Toddy's here to stay!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 1804, 1805, 1806, 1807, 184374, 184519, 195042 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 191838, ["x"] = 0.542, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192820, ["x"] = 0.55, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1374, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1374, ["name"] = "In the Halls of Titans", ["orderIndex"] = 2, ["flags"] = 0 } } },
[66646] = { ["id"] = 66646, ["name"] = "Quelling Causalities", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "The Infinite has forced the energies of time to aggression. This is not good. Please slay any time elementals you encounter while assisting Ambassador Chronormu. I will remain here and help her hold Eternus in place.", ["objectivesText"] = "Kill Time Elementals. Progress: Did any of them escape to the past? I wonder if we would realize if they did? Hmmm.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192602, 192809, 195179, 195180, 195182, 195214, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186433, ["x"] = 0.595, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186433, ["x"] = 0.595, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 26, ["flags"] = 0 } } },
[66647] = { ["id"] = 66647, ["name"] = "Elemental Unfocus", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "Kalecgos and I are under heavy fire in the skies above the mountain. The Primalists are unrelenting and their army endless. Soon, Kalecgos and I may be overrun by their forces. But I have a plan. At the base of the mountain is a disturbed orc named Ruvin Stonegrinder. The Kirin Tor fought her numerous times. She holds a device that can absorb and redirect elemental energies. Take it from her, then meet me further in.", ["objectivesText"] = "Recover the Elemental Focus . Progress: The Elemental Focus should prove useful if you can recover it.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 192478, 192479, 194705, 198017, 198026 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186305, ["x"] = 0.7, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186688, ["x"] = 0.744, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 43, ["flags"] = 0 } } },
[66651] = { ["id"] = 66651, ["name"] = "Up to No-khud", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66651 }, ["series"] = { 66652 }, ["description"] = "The Nokhud and Ukhel clans have overtaken the Eternal Kurgans. Their purpose can only be malign. Our most esteemed ancestors are buried there. I sent Initiate Zorig to investigate. He still has not returned. He is capable, but lacking in confidence. Please help him put a stop to their foul activities!", ["objectivesText"] = "Meet Initiate Zorig at the Eternal Kurgans.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191901, 192496, 193257, 193676, 193677, 193679, 193685, 193686, 193692, 193697, 194447, 197359, 197653, 197889, 197891, 197897, 197899, 198073, 198074, 198075, 200100, 200115, 200251, 212757 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188224, ["x"] = 0.408, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188225, ["x"] = 0.39, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66652] = { ["id"] = 66652, ["name"] = "Return to Mender", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66652 }, ["series"] = { 66651 }, ["description"] = "I can't see what they're doing from here, but I fear they're desecrating the kurgans. Please go to the nearest tomb, and see if you can stop the ritual they're performing. And if you find anything that may tell us their purpose here, please bring it back to me.", ["objectivesText"] = "Investigate the Ukhel ritual at the nearby mound. Progress: Did you stop the ritual? Any clues as to what it was about?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191901, 192496, 193257, 194447, 198073, 198074, 198075, 200100, 200115 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188225, ["x"] = 0.39, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188225, ["x"] = 0.39, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66655] = { ["id"] = 66655, ["name"] = "Reagents of De-Necromancy", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66655 }, ["description"] = "I fear the spirits will be unable to find their tombs, even if we release them from the Ukhel's grip. The Ukhel are also raising the ancestors' animal companions who guided and protected them in life. Bring me the skulls of those animals, and the sacred soil disturbed by these enemies. Combined, these reagents should help the ancestors find peace.", ["objectivesText"] = "Gather 4 Intact Skulls from risen companions and 6 Clumps of Sacred Soil . Progress: Do you have the reagents? We must free the ancestors before Clan Ukhel takes them away from the Kurgans.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191901, 192496, 193257, 194447, 198073, 198074, 198075, 200100, 200115 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188225, ["x"] = 0.39, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189858, ["x"] = 0.338, ["y"] = 0.654 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66656] = { ["id"] = 66656, ["name"] = "Definitely Eternal Slumber", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66656 }, ["description"] = "The ancestors are gripped by this dark magic. They will fight before they follow. The Ukhel raised our fiercest warriors and hunters. Stopping them will be no easy task. I'm going to come along and help. It's time I put my mother's spear back to use. Once they are defeated, use this totem I've crafted to help the subdued spirits find their way back to the kurgans.", ["objectivesText"] = "Defeat each renowned centaur spirit, then use Zorig's Totem of Respite to release them. Progress: Hurry. We must free these spirits.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 191901, 192496, 193257, 194447, 198073, 198074, 198075, 200100, 200115 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189858, ["x"] = 0.338, ["y"] = 0.654 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.654 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66657] = { ["id"] = 66657, ["name"] = "And Stay Dead!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["storyline"] = { 66657 }, ["description"] = "Tombcaller Arban has holed up in the largest kurgan, where the first Maruuk ancestors were laid to rest. Stop Arban before he raises Maruuk and Teera!", ["objectivesText"] = "Enter the main kurgan and defeat Tombcaller Arban . Progress: He'll have no tomb of his own when this is done.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 191901, 192496, 193257, 194447, 197892, 197895, 197900, 198073, 198074, 198075, 200100, 200115 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66658] = { ["id"] = 66658, ["name"] = "The Nokhud Offensive: Founders Keepers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66658 }, ["description"] = "Teera and Maruuk's weapons were removed before we stopped Tombcaller Arban. Our greatest ancestors may fight again in these plains... for the Nokhud. Go to the Nokhud Offensive. Find Maruuk and Teera. When you have subdued them, bring their weapons back to the Teerakai burial mound. We will lay them back to rest with the honor they deserve, in a place we can protect more easily.", ["objectivesText"] = "Enter the Nokhud Offensive, defeat Teera and Maruuk, and place their weapons in the Teerakai kurgan. Progress: Were you able to defeat the legendary spirits of our founders?", ["rewardGold"] = 1123600, ["rewardXP"] = 5530, ["rewardItems"] = { 191901, 192496, 193257, 194421, 194447, 197359, 197889, 197891, 197897, 197899, 198073, 198074, 198075, 200100, 200115 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190068, ["x"] = 0.406667, ["y"] = 0.607333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.406667, ["y"] = 0.607333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "dungeon" },
[66660] = { ["id"] = 66660, ["name"] = "On Your Mark... Get Set...", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "< Nozdormu 's gaze is unfocused.> The further they fall, the faster they travel. They punch holes through the fabric of time which send out great ripples. You will need to be swift to catch them. < Nozdormu 's focus sharpens and shifts to you.> I will send my timewalkers to help you navigate the timeways and speed your efforts. Avoid entangling with the temporal locals and do not stop until you have found Chronormu! Go. We have precious little time.", ["objectivesText"] = "Join Andantenormu and Siazerathel in the past.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 192454, 192749, 194521 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2090, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 43, ["flags"] = 0 } } },
[66671] = { ["id"] = 66671, ["name"] = "Path to Nowhere", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66671 }, ["description"] = "Ye look like a willin' and able adventurer! How would ye like to help out the Dragonscale Expedition? We've got ourselves a lovely camp in the middle of a nice bit of wilderness. There's plenty for ye to do if ye'd like to take the trip over there. Talk to me sis, Maddy, when ye get there. She'll get ye all settled in.", ["objectivesText"] = "Meet Maddy Scattershot at Camp Nowhere within the Azure Span .", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190001, ["x"] = 0.456, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187800, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66673] = { ["id"] = 66673, ["name"] = "Speak to Koranos", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "The Watchers have observed much over the years. Many of them are lost to the vagaries of time, but we still have Koranos.", ["objectivesText"] = "Speak to Koranos in Valdrakken. Progress: Koranos has been here since the beginning. If he doesn't have answers, he should be able to point you in the right direction.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193070, 193072, 197958, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 3, ["flags"] = 0 } } },
[66675] = { ["id"] = 66675, ["name"] = "Aspect Power", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66847, 67073, 70437, 72380 }, ["description"] = "The Mother Oathstone is an ancient gift bestowed to our flights by the Titans. If what we have learned is true, I might be able to reactivate it and in doing so restore our aspectral powers. Though we are unsure of the outcome, if this has the slightest chance of working I must attempt it. <name>, I would appreciate if you would join me in this.", ["objectivesText"] = "Assist Alexstrasza at the Mother Oathstone.", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 190454, 197921 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187658, ["x"] = 0.574, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192455, ["x"] = 0.574, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1333, ["name"] = "The Mother Oathstone", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 49, ["flags"] = 0 } } },
[66680] = { ["id"] = 66680, ["name"] = "Counting Sheep", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66680 }, ["description"] = "How frustrating. A rabid stag did this while my brother Olekk and I were scouting. <Watu gestures at his bloody leg and winces.> Are you here to help? After the primalists attacked, our herd of argali scattered into the pines. Their wool and milk are essential to the camp's functions. Take this whistle, which commands Wish to herd the argali back home. Sondo the butcher has her favorite treats if she needs extra encouragement.", ["objectivesText"] = "Befriend Wish with food, and use Wish's Whistle to save 5 Lost Argali in the Sagecrest Pines. Progress: Make haste. Argali are a favorite snack for the local--well, local everything.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193890, 193892, 194031 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.599 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66681] = { ["id"] = 66681, ["name"] = "Tempests Abound", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66681 }, ["description"] = "If you're venturing out into the pines, please slay any stormtouched animals. This is not easy for me to ask, but they're clearly in pain, unable to be helped, and spreading the aggression. I suspect it's the primalists' doing. It must be coming from their outpost nearby, where I saw a strange magical altar at work. I'm going to go investigate again. If I'm not back by the time you return, Scout Watu can brief you on additional tasks. We're grateful for any help.", ["objectivesText"] = "Kill 8 Stormtouched Beasts in Sagecrest Pines.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193890, 193892, 194031 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190024, ["x"] = 0.825, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66683] = { ["id"] = 66683, ["name"] = "Last Resort Analysis", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66683 }, ["description"] = "<Watu mumbles to himself, eyes closed and arms crossed.> Of course I get gored by a stag, of all creatures. Now I'm just another one who needs help. My brother will get all the credit, and no one back home will be surprised. <Watu looks up.> What? What's that you've got there? Glowing rocks? I'll look at one, but take the rest to somebody else. I'm a hunter, not an archaeologist. <Watu snorts, glaring at his leg.> Maybe this is a sign for me to switch jobs. Go on, you've proven more useful than I.", ["objectivesText"] = "Inquire about the Stormtouched Shards in Pinewood Post. Progress: <A strange look has overcome Watu. He barely registers your presence, infatuated with turning the shard over in his hands.> You see how it glows, like new lightning?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193890, 193892, 194031 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.599 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66684] = { ["id"] = 66684, ["name"] = "Storm Chasing", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66684 }, ["description"] = "<Watu rips the shard out and gasps for air.> I...completely lost control. Olekk was right. This terrible magic has to be the primalists' doing. Please, stop them! I must get my brother back to camp.", ["objectivesText"] = "Destroy the Primalists' source of storm magic. Progress: Go with haste! That kind of power must be kept in check.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193890, 193892, 194031, 197887, 197893, 197896, 197901 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.599 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66687] = { ["id"] = 66687, ["name"] = "Land of the Apex", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66687 }, ["description"] = "You should know of Rellen, the Learned, who gave centaur the tools to survive a merciless land. His memory requires offerings from worthy beasts. Take care, traveler. They are not as dangerous as they were eons past, but they're still the plains' apex predators.", ["objectivesText"] = "Collect 10 Shadespinner Webs, 2 Slyvern Talons , and 2 Thunderspine Scales . Progress: Have you returned with the offerings?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193202, 193206, 193207, 193483 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66688] = { ["id"] = 66688, ["name"] = "Signs of the Wind", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66688 }, ["description"] = "When the elements, true primals of the world, challenged the centaur, Himia met them with our given gift. The wind. A singing stone stands strong in the plains. There, you can offer tokens of the wind to evoke her memory. Such tokens may be found all around us--a bird's feather, a plant spore, a river's reeds.", ["objectivesText"] = "Gather wind tokens and give them to the Offering Vessel near the singing stone. Progress: The singing stone is a morning's ride from here.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193202, 193206, 193207, 193483 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66689] = { ["id"] = 66689, ["name"] = "More Than A Rock", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66689 }, ["description"] = "<The shards are smooth and slightly hot to the touch. Lightning sparks deep within their core.> <Maybe Watu or Olekk would know more.> <The thought of parting with the shard fills you with compulsion to hold the shard close. To keep it forever.>", ["objectivesText"] = "Show the Stormtouched Shards to Watu.", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 193890, 193892, 194031 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.599 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["startItems"] = { 194031 } },
[66690] = { ["id"] = 66690, ["name"] = "The Nokhud Offensive: The Final Ancestor", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13982, ["mapID"] = 2023, ["storyline"] = { 66690 }, ["description"] = "You've proven yourself an ally to us, with genuine interest in our values and way of life. There is one more ancestor I'd like to tell you about, but it will be dangerous. Kill the traitorous Balakar, leader of Nokhud, son of none. He wears a precious medallion at all times. Bring it back to me, and I will be forever in your debt.", ["objectivesText"] = "Defeat Balakar Khan and collect the Medallion of the Ancestors in the Nokhud Offensive. You can access The Nokhud Offensive solo by queuing for it in Follower Dungeons. Progress: Balakar never parts with the pendant. You'll have to kill him.", ["rewardGold"] = 1123600, ["rewardXP"] = 5530, ["rewardItems"] = { 193202, 193206, 193207, 193483, 200251 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13982 } }, ["questType"] = "dungeon" },
[66699] = { ["id"] = 66699, ["name"] = "Ask the Locals", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "Kalecgos is wise to seek the tuskarr's counsel. They have generations of experience with this land. Many are resting here on their way to their various camps across the Span. Ask around! One of them must know about local ley lines.", ["objectivesText"] = "Speak to tuskarr around Camp Antonidas. Progress: I'd offer you a bowl, but you appear to be in a hurry.", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190225, ["x"] = 0.456, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 16, ["flags"] = 0 } } },
[66700] = { ["id"] = 66700, ["name"] = "The Black Locus", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66700 }, ["description"] = "It really is quite enticing, isn't it? The Locus was too much for the Sundered Flame. However, it fits just right in my hands. Funny, that. <Adenedal shakes his head.> Perhaps not. Not this day. Not again. Take it from me. It is not my burden to bear. Good bye, dear friend.", ["objectivesText"] = "Bring the Black Locus to the Telemancer Aerilyn . Progress: Do you have something to show me?", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 193355, 193357, 193375, 193601, 197407, 198078, 198079, 198354, 200278 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191154, ["x"] = 0.662, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190089, ["x"] = 0.66, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66703] = { ["id"] = 66703, ["name"] = "Snowball Effect", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66703 }, ["description"] = "Snowhide gnolls smart. They know you put food on ice, food is good longer. But just ice no good. Magic ice be better! This be the work of shamans. And they put Frostbite here, so he starve to death next to delicious tuskarr meat. If <race> want help tuskarrs, time running out. But Frostbite knows how to break the spell. Why Frostbite help? He no like shamans either.", ["objectivesText"] = "Retrieve 3 Snowhide Totems from the Snowhide Shamans in the Azure Span . Progress: Tuskarr friends don't look so good, <race>.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193617 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189625, ["x"] = 0.584, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189625, ["x"] = 0.584, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66704] = { ["id"] = 66704, ["name"] = "Mugurlglrlgl!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14092, ["mapID"] = 2092, ["storyline"] = { 66110, 66111, 66704, 70371, 71025, 71144 }, ["description"] = "Mrglgulglrrlglgul! Grurguglullgurl! Gruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl. Mgrgulllglll gurl gugll. <You aren't certain what's being said, but there are lots of stabbing motions. It seems like this murloc wants you to kill something.>", ["objectivesText"] = "Murglgulglrrlglgul! Progress: Murglgulglrrlglgul!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 195210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14092 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2092, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 39, ["flags"] = 0 } } },
[66709] = { ["id"] = 66709, ["name"] = "Field Medic 101", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66709 }, ["series"] = { 66708 }, ["description"] = "<It's hard to say how long this wounded tuskarr has been lying here alone in the forest, but he won't last much longer without help.>", ["objectivesText"] = "Help Old Grimtusk recover from his wounds. Progress: Of course, take your time. That's what you young pups do best.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193372, 193617 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189963, ["x"] = 0.586667, ["y"] = 0.402667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189963, ["x"] = 0.586667, ["y"] = 0.402667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.586667, ["y"] = 0.402667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66715] = { ["id"] = 66715, ["name"] = "The Extraction", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66715 }, ["description"] = "Right now the most important thing is to bring back my people. Preferably in one piece. And as much as it pains me to say this, I'm in no condition to fight them on my own. Will you help us?", ["objectivesText"] = "Rescue tuskarr from the Snowhide Camp in the Azure Span . Progress: You look strong, little <race>. Are you?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 30262, 30263, 30264, 30516, 183744, 184843, 193617 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189963, ["x"] = 0.586667, ["y"] = 0.402667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189625, ["x"] = 0.584, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.586667, ["y"] = 0.402667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66724] = { ["id"] = 66724, ["name"] = "The Gleamfisher", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66724 }, ["description"] = "I am sorry you have been dragged into this, traveler. My brother tends to get... carried away. This is only the latest of his follies. But this one might get him killed. He won't listen to me. He probably won't listen to you, either. Our ancestor, Kauriq the Gleamfisher, though, is the center of his fixation. She may be able to. Please catch some Gleamfish and bring them here. I shall use them to help us commune with her spirit, which lingers in this stone.", ["objectivesText"] = "Retrieve 3 Gleamfish and place them in the offering basket. Progress: Not all my ideas have worked out, but that doesn't mean this one won't!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191091, 191092, 191199, 194324 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186386, ["x"] = 0.4536, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4536, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66730] = { ["id"] = 66730, ["name"] = "True Survivors", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66730 }, ["description"] = "I know we're pretty banged up, but we can't forget why we're here. Our people are counting on us, and I don't plan on letting them down. We've got to find a temporary place for ourselves in these savage parts, and I know just the place. Now quit whining and MOVE IT.", ["objectivesText"] = "Find and speak with Old Grimtusk at the Frozen Lake in the Azure Span .", ["rewardGold"] = 74100, ["rewardXP"] = 4115, ["rewardItems"] = { 193617 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189963, ["x"] = 0.586667, ["y"] = 0.402667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.586667, ["y"] = 0.402667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66734] = { ["id"] = 66734, ["name"] = "Leave Bee Alone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66734 }, ["description"] = "Oh, thank the Life-Binder! Someone with empty hands! These gardens are normally a lovely playground for our whelps, but the bees have multiplied uncontrollably. The blooms returned with vigor--and so have the bees. The whelps are terrified, the dragons are annoyed, and just yesterday one was stung and-- < Vaeros takes a deep breath to center himself then looks at you pleadingly.> Will you please gather up the bees and relocate them to the lake? Take this smoke diffuser ; it will calm them down.", ["objectivesText"] = "Use the Smoke Diffuser to calm and gather 8 Bothersome Bees, then release them near the lake. Progress: Try not to be too rough with the bees. They are doing their best. We all are.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918, 194404, 194405, 194415 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190525, ["x"] = 0.574, ["y"] = 0.668667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190525, ["x"] = 0.574, ["y"] = 0.668667 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.668667 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66735] = { ["id"] = 66735, ["name"] = "Just a Trim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66735 }, ["description"] = "The bees scaring the whelps is not the only problem. While pollination is usually a good thing, the recent swarm has caused the flora to grow out of control. Would you mind taking my gardening shears and cutting back the shrubs? Some have already begun to sprout dangerous lashers, but I hope we can stop more from doing so. An ounce of prevention is worth a pound of cure, after all. And I could... very much use some prevention right now, <name>.", ["objectivesText"] = "Prune 5 Overgrown Shrubs. Progress: If you use my gardening shears on anything other than plants, I will be very cross with you.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190525, ["x"] = 0.574, ["y"] = 0.668667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190525, ["x"] = 0.574, ["y"] = 0.668667 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.668667 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66737] = { ["id"] = 66737, ["name"] = "A Better Start", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66737 }, ["description"] = "Vaeros is diligent, but whelps have a way of finding trouble. Not mine, of course--but I suppose not every dragon rears their clutch to understand the gravity of their station. While I am loathe to encourage outdoor play over study, I will help you safeguard the garden more effectively. Take these seeds and plant them nearby. When mature, the blooms produce a fragrance that insects find disagreeable. The gardeners can help you--and maybe my bronze brethren, if you mind your manners.", ["objectivesText"] = "Plant seeds in 6 Fertile Soil patches and allow them to mature. Progress: Do remember to be courteous to our bronze companions, lest they toss you into a timeline without luxurious stationery and herbal tea. < Adazius sighs wistfully.> What a terrible existence that would be.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918, 194418, 194419 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190533, ["x"] = 0.552, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190533, ["x"] = 0.552, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66779] = { ["id"] = 66779, ["name"] = "Heir Apparent", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "As Neltharion's heir and leader of the only surviving flight of black dragons, I was not expecting to find myself in competition for my birthright. Particularly not against a self-important whelp younger than you, mortal. Nevertheless, if you need more than these self-evident facts, feel free to speak with members of my flight. There's no need to take my word on the subject.", ["objectivesText"] = "Speak with Sabellian 's followers. Progress: My flight awaits.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185894, ["x"] = 0.242, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185894, ["x"] = 0.242, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 44, ["flags"] = 0 } } },
[66780] = { ["id"] = 66780, ["name"] = "Claimant to the Throne", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "I have dedicated myself to saving Azeroth from destruction time and time again, and this fool thinks he can just swoop in and claim the title of aspect? I think not. Talk to my people, <name>. See what they have to say about me and what I have done for this world.", ["objectivesText"] = "Speak with Wrathion 's followers. Progress: Their loyalty is unquestionable.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187495, ["x"] = 0.245, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187495, ["x"] = 0.245, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 45, ["flags"] = 0 } } },
[66781] = { ["id"] = 66781, ["name"] = "A Matter of Taste", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66781 }, ["description"] = "The disrespect around here! A couple smelly gorlocs steal bits from our equipment and we have to shut it all doon... Ha! I've been lickin' rocks since before ye were a wee babe! Did nae need nae fancy gnomish gadgetry. Bring me a rock, and I'll prove it!", ["objectivesText"] = "Find a rock for Mordigan Ironjaw to lick in Whaler's Nook. Progress: Find a good rock yet?", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190691, ["x"] = 0.076, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190691, ["x"] = 0.076, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.076, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66783] = { ["id"] = 66783, ["name"] = "Renewal of Vows", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "Centuries ago, I made a vow of friendship and cooperation with the first centaur. Although much has changed, I feel it is time for us to renew that vow again. A recitation was composed to help future generations of centaur remember their bond with the green dragonflight. Each verse must be answered with an offering from the khans. I hope the centaur can still remember the original meanings. The choice of gift is critical. Choose the right offering, and our allegiance is bound.", ["objectivesText"] = "Help Sansok Khan, Tigari Khan, Khanam Matra Sarest, and Merithra exchange gifts. Progress: The recitation is as follows: From the hunters who value skill above all, a rite of passage: a first. From the mystics who commune with the wind, her lightest touch: a lift. From the descendants of the matriarch, a drop of unbroken progeny: a line.", ["rewardGold"] = 842700, ["rewardXP"] = 4150, ["rewardItems"] = { 194549, 197375, 197672 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188181, ["x"] = 0.222, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188181, ["x"] = 0.222, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.222, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 51, ["flags"] = 0 } } },
[66784] = { ["id"] = 66784, ["name"] = "Starve the Storm", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "You fight well for one who must balance on only two legs! It matters not how hard we fight so long as the Primalists continue to draw reinforcements. We must close that portal, the Storm Corridor! Fight your way into the nearby cavern and slay the Primalist Storm-Summoners holding it open. I will aid you if I am able.", ["objectivesText"] = "Kill Primalist Storm-Summoners to close the Storm Corridor Portal. Progress: All this is pointless if that portal remains open!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 194549, 197375 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 48, ["flags"] = 0 } } },
[66785] = { ["id"] = 66785, ["name"] = "The Last Eggtender", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "I understand your concern, <class>, but all will be rectified shortly as it seems that we are about to have company. Feel free to stay and witness what transpires. It should be quite cathartic. Do speak with our egg tender when you have a moment, though. She will no doubt need the support.", ["objectivesText"] = "Speak with Mother Elion .", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190740, ["x"] = 0.578, ["y"] = 0.672 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 47, ["flags"] = 0 } } },
[66788] = { ["id"] = 66788, ["name"] = "Egg-cited for the Future", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "I can scarcely believe it! Eggs of the Black Dragonflight! After all this time! But look at the state of this place! It will not do at all! Nothing is too good for these eggs. Though with those two blowhards squabbling like children for the Life-Binder's favor, you can bet they have not spared a thought for us! You, though, will not leave an old egg tender all alone, will you?", ["objectivesText"] = "Help Mother Elion restore the area. Progress: We are not done yet, young one.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 48, ["flags"] = 0 } } },
[66814] = { ["id"] = 66814, ["name"] = "The Judgment of Tyr", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "Welcome to the Veiled Ossuary. Originally built to house and memorialize the dead. Now the likely location of the stone we've come to call the Judgment of Tyr . We haven't received reports of any overt Sundered Flame presence here, but the expedition has learned that they prefer to strike unawares. Be on your guard, <name>.", ["objectivesText"] = "Recover the Judgment of Tyr . Progress: All I ever wanted was to study. Instead, I'm sifting through rubble and getting chased by draconic ghosts.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190855, ["x"] = 0.622, ["y"] = 0.182 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190865, ["x"] = 0.644, ["y"] = 0.15 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.182 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 9, ["flags"] = 0 } } },
[66825] = { ["id"] = 66825, ["name"] = "A Ruby Lifecalling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66825 }, ["description"] = "$p! How fortunate you are here! We are about to begin a Lifecalling Ceremony and would be honored if you assisted us. A dragonspawn's Calling is very special. Some become masterful gardeners; others care for particular wildlife. These young dragonspawn have finished their training and are ready to take on their first Callings. I know they would be thrilled to have you participate. When you're ready, please present each of the items on this table to them.", ["objectivesText"] = "Participate in the Lifecalling Ceremony at the Ruby Lifeshrine. Progress: Ah, I remember my first calling like it was yesterday...", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191025, ["x"] = 0.618, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191025, ["x"] = 0.618, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66827] = { ["id"] = 66827, ["name"] = "Flowers of our Labor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66827 }, ["description"] = "The legend says she only sings it for those who prove their devotion to life. I've been tending this garden for years... And I think my plants and I are finally ready. I'll start setting up by the pool here. You can help me with the harvest! Gather seed pods from beneath bushes, dragonflowers from sunny fields, and dragonfruit high in the trees. You can borrow my old rake to help with those. And watch out--sometimes the foliage can be feisty!", ["objectivesText"] = "Collect 5 Ripened Dragonfruit , 5 Fragrant Dragonflowers and 5 Lush Seed Pods from around the garden to offer to the Dragon Spirit. Progress: < Akora talks nervously to herself.> Just remember the mantras... Fruit that is sweet, is harbored from heat. Tilling early the soil, saves future toil. If a tree should bare fruit, don't forget its roots...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190866, ["x"] = 0.602, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190866, ["x"] = 0.602, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66828] = { ["id"] = 66828, ["name"] = "Huddle at the Hollow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66828 }, ["description"] = "I've never seen Akora this upset. Usually she's as sunny as her flowers, but that legend means a lot to her. She talks about it all the time. Hm... < Keshki fidgets with their glasses.> I don't know a lot about plants, and I don't think frogs would cheer up anyone but me... But north of here there's a quiet spot where I do my thinking: Hornswog Hollow. Maybe we can find something to cheer her up there? Or, uh, try to formulate a plan to help?", ["objectivesText"] = "Meet Keshki at Hornswog Hollow.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190868, ["x"] = 0.602, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191011, ["x"] = 0.652, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66830] = { ["id"] = 66830, ["name"] = "Hornswoggled!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66830 }, ["description"] = "Oh, those hornswogs make me so mad! < Keshki stomps her foot angrily, knocking her glasses askew> They're big, greedy bullies! Just because the place is named after them doesn't mean they get to jump all around and eat everything smaller than them! Here, use my jar of fireflies --it's a frog-minder's best friend. It'll calm the frogs enough that you can collect them, and we can get them out of harm's way. And if any hornswogs get in your way, don't be afraid to bully them back!", ["objectivesText"] = "Use Keshki 's Jar of Fireflies to lure 8 Bullied Frogs to safety. Progress: Frogs are gentle creatures! It's not fair to push them around like this!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191011, ["x"] = 0.652, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191011, ["x"] = 0.652, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66831] = { ["id"] = 66831, ["name"] = "Home Is Where the Frogs Are", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66831 }, ["description"] = "All the frogs are rounded up, <name>! I guess we're, uh, taking the frogs to Akora anyway. They'll be safe at the Life Pools until the hornswogs get bored and move on. Um, well, I guess we didn't find anything to cheer up Akora. I hope she understands...", ["objectivesText"] = "Meet Keshki back at the Life Pools to release the rescued frogs. Progress: Honestly? I'm just glad the frogs are safe.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 193064, 193826, 193918, 197399 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191011, ["x"] = 0.652, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190868, ["x"] = 0.602, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66834] = { ["id"] = 66834, ["name"] = "Rellen, the Learned", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66834 }, ["description"] = "Bring your offerings to the central den. You may witness the legend of Rellen, the Learned, who gave centaur our livelihood as we know it.", ["objectivesText"] = "Make your offerings in the offering den and witness each of Rellen's teachings. Progress: The offering den is in the center of Teerakai.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193202, 193206, 193207, 193483 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66837] = { ["id"] = 66837, ["name"] = "Nothing for Breakfast", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66837 }, ["description"] = "My brother Valdo was supposed to order more supplies. But it's been a week and nothing has come. I'm not surprised. The lazy oaf probably took a nap instead! Now we're short on food, and I'm too busy to hunt on top of my chores--and Valdo's! Would you hunt for us? The meat of the vorquin striders and striped bruffalon south of here would keep the kitchen open until I can order supplies.", ["objectivesText"] = "Collect meat from the vorquin striders and striped bruffalon south of Three-Falls Lookout. Progress: Did you get some vorquin meat ? Any bruffalon flanks? Great! I was ready to put fillet of boot on the menu...", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193219, 194030 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190315, ["x"] = 0.188, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190315, ["x"] = 0.188, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66838] = { ["id"] = 66838, ["name"] = "It's Cold Up Here", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66838 }, ["description"] = "Being a good innkeeper means anticipating guests' needs. Unfortunately, I didn't anticipate how cold the nights would be here. Oops? My guests are going to need blankets--and good, thick ones. Maybe bear pelts will do? There are some large bears in the forest just east of here. If you bring me some of their pelts, I'll pay you for them! Please? Think of the adventurers and their cold, cold feet...", ["objectivesText"] = "Collect thick bear pelts from thickmane bears. Progress: Huh? Oh! You're back already? Sorry, I got kind of involved in my card game... Do you have the pelts?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190315, ["x"] = 0.188, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190315, ["x"] = 0.188, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66839] = { ["id"] = 66839, ["name"] = "It's Brew Time!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66839 }, ["description"] = "The gang had some time off and was hankerin' for a pint, so we bellied up to the inn. But, ach! I can nae believe it! They didna have any brew! What kind o' inn is that? One ran by the Stonehinges--that's what kind! So we're takin' matters into our own hands! The forest to the east has flowers and herbs that we could use to brew some sweet mead. Feel like helpin' me and doin' some flower pickin'? There'd be somethin' in it for ye!", ["objectivesText"] = "Gather Blood Berries , Bronze Horn Berries , and Dragon Foil Blossoms . Progress: Ye get a nice mead-brewin' bouquet yet?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193351, 193352, 193356 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190672, ["x"] = 0.19, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190672, ["x"] = 0.19, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.19, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66840] = { ["id"] = 66840, ["name"] = "Water Safety", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66840 }, ["description"] = "My greatest responsibility is to make sure everyone has access to clean drinking water. With the gnolls to the east dealing with the decay, I must make sure that the camp is safe. I don't want to alarm anyone by personally taking samples, but I feel testing is necessary. Bring me samples from the three nearby waterfalls, and I will reward you handsomely.", ["objectivesText"] = "Bring three water samples to Manny Read .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193569 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190679, ["x"] = 0.185, ["y"] = 0.236 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190679, ["x"] = 0.185, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.185, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66841] = { ["id"] = 66841, ["name"] = "A Shard of the Past", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66841 }, ["description"] = "I've seen ye runnin' in and out of the camp helpin' people. Ye think ye could help ol' Gannar too? I surveyed the area, and somethin' caught me old eyes. I think 'tis an ancient potsherd or a jar or somethin' just down south of here at the edge of that waterfall. Now, I am not much of a swimmer, but I'll give ye some coin and you can deliver the findings to Thanessa Silverbloom .", ["objectivesText"] = "Recover and bring the artifact to Thanessa Silverbloom . Progress: You must be <name>. Gannar said you were running some sort of an errand for him?", ["rewardGold"] = 210675, ["rewardXP"] = 3085, ["rewardItems"] = { 193382 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190666, ["x"] = 0.192, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190652, ["x"] = 0.186, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.192, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66843] = { ["id"] = 66843, ["name"] = "Out of Lukh", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["storyline"] = { 66843 }, ["description"] = "Ach! Have ye seen me assistant, Lukh? The kid wanted a moment to look 'round, but he's been gone for an hour! I told him it ain't safe here and to nae walk far, but the kid has a head as thick as a ram's. I can nae say I blame him. it's pretty out here, and he has a thing for flowers. Could ye help me find 'em? They need me and the wagon back at Three-Falls Lookout!", ["objectivesText"] = "Find Lukh's whereabouts. Progress: Well? Where is he? Did ye find 'em yet? We have to go! That collapsed cave at Three-Falls Lookout won't clear itself!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66844] = { ["id"] = 66844, ["name"] = "The Great Shokhari", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66844 }, ["description"] = "Of all da animals I have seen here, Shokahri, da great sky vixen, be da most proud. It be a shame she preyed on a gnoll shaman, cause now she be crazed with decay. When I saw her eating one of her kits, I knew something was not right. I took da kits away and brought them here, but Shokhari attacked me, swiping me good. I almost didn't make it. Shokhari must be put down. If da decay rots more of her mind, she be coming for us soon.", ["objectivesText"] = "Kill Sky Vixen Shokhari . Progress: Shokhari got a taste for our flesh now. It be a matter of time before she come to Three-Falls Lookout. Ya must end her suffering!", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 193619 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190892, ["x"] = 0.19, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190892, ["x"] = 0.19, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.19, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66845] = { ["id"] = 66845, ["name"] = "Legendary Foil", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66845 }, ["description"] = "Last night, I was lying in my bedroll, tossing and turning, when an unnatural chill filled the inn. Then, out of nowhere I saw... the ghost of a draconid! It went through my luggage then vanished into thin air! But the true horror is that when I woke up... the ghost had taken my most beloved card! Would you be so kind as to track down the ghost and get my card back? It is my most prized possession.", ["objectivesText"] = "Find the draconid ghost and retrieve the legendary card. Progress: Please, you have to find my legendary card! It was a family heirloom given to me as a young cub. It means the world to me!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190799, ["x"] = 0.188, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190799, ["x"] = 0.188, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66846] = { ["id"] = 66846, ["name"] = "The Heart of the Deck", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66846 }, ["description"] = "The day the Dragon Isles began their slumber was the day of my very last match. Fate was cruel, and I lost my strongest card before I could compete. Guo-Hee's card, you see, was mine. I do not know how her ancestors came upon it. Alas, I cannot claim it as my own as it has been in her family for centuries. That was a foolish mistake on my part. Perhaps you and I could craft a card together? A truly unique card... Yes! Will you help me? Speak to me once you are ready.", ["objectivesText"] = "Help the apparition craft a new card. Progress: The card we create must be powerful as well. I will need your assistance in creating it!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191741, ["x"] = 0.188, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 191741, ["x"] = 0.188, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66847] = { ["id"] = 66847, ["name"] = "Vault of the Incarnates: Fury of the Storm-Eater", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66675, 67073, 70437, 72380 }, ["description"] = "No! We locked the Incarnates away to save this world and now Raszageth seeks to free them! She cannot succeed, <name>. All life on Azeroth is in grave danger if you do not stop her! I shall return to Nozdormu at the Seat of the Aspects to plan for whatever is to come. Khadgar and Kalecgos are already inside with a contingent of allies. Join them to put an end to Raszageth. Good luck, champion.", ["objectivesText"] = "Enter the Vault of the Incarnates and defeat Raszageth. Progress: Have you stopped Raszageth? We cannot let her plans go unchecked, <name>.", ["rewardGold"] = 842700, ["rewardXP"] = 8200, ["rewardItems"] = { 190454, 197921 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190902, ["x"] = 0.724, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.724, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "raid", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2522, ["db2PoiUiMapID"] = 2135, ["questLines"] = { { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 52, ["flags"] = 0 } } },
[66848] = { ["id"] = 66848, ["name"] = "Omens on the Wind", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65805, 65940 }, ["description"] = "Ohn'ahra does not speak in language as we do. Her voice carries through the very winds. We mystics are trained to feel her presence, follow her call, and interpret her messages. I have used the materials you gathered to bind totems to this particular call. Aid me in a ritual to center her voice, then I will interpret her song.", ["objectivesText"] = "Aid Ohn Seshteng in her ritual. Progress: Ohn'ahra's voice is all around us. You just have to listen.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 197637, 197687, 197688, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 184595, ["x"] = 0.778, ["y"] = 0.293 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 184595, ["x"] = 0.778, ["y"] = 0.293 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.293 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 11, ["flags"] = 0 } } },
[66879] = { ["id"] = 66879, ["name"] = "Hornstrider Havoc", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66879 }, ["description"] = "Hornstriders! They've got bone-breaking beaks, fast legs for getting away from danger, and they can eat anything in the Isles. This Calling's the easiest around! It's just me and my favorite big birds spending time together. And if anything comes up, I know how to wrangle all of the Isles' critters. Would you mind following me to the hornstrider plateaus up north? I wouldn't mind an extra pair of hands while getting set up.", ["objectivesText"] = "Meet Dazakros in the Overflowing Rapids.", ["rewardGold"] = 5865, ["rewardXP"] = 175, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191176, ["x"] = 0.618, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191280, ["x"] = 0.576, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66892] = { ["id"] = 66892, ["name"] = "Deluge Dilemma", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66892 }, ["description"] = "Elementals are killing the hornstriders! I know how to wrangle large critters, but I never thought I'd have to go toe-to-toe with an elemental! These aren't anything like baby thunder lizards... < Dazakros sighs, distressed.> Please knock down a few of them elementals. Hornstriders have a lot more sense than we give them credit for. They'll fight back if they have the means to!", ["objectivesText"] = "Kill 12 Water Elementals in Overflowing Rapids. Progress: If fighting elementals is anything like wrangling lizards, just give those soggy good-for-nothing's a solid knock to the nose and they'll fall in line!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191280, ["x"] = 0.576, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191280, ["x"] = 0.576, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66893] = { ["id"] = 66893, ["name"] = "Beaky Reclamation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66893 }, ["description"] = "I may not know anything about water elementals, but I do know hornstriders! I've thrown together a salve that'll keep the 'striders healthy and ready to fight. I've never had a chance to apply it to a real hornstrider, but I've done all the studying I can do. It's time to put on a brave face and lather them up!", ["objectivesText"] = "Heal 8 Injured Hornstriders in Overflowing Rapids.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918, 194434 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191280, ["x"] = 0.576, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191280, ["x"] = 0.576, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66931] = { ["id"] = 66931, ["name"] = "Who Brought the Ruckus?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "That was no ordinary quake.", ["objectivesText"] = "Discover the commotion at the Ruby Lifeshrine. Progress: What could that be?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187290, ["x"] = 0.622, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190293, ["x"] = 0.595, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 24, ["flags"] = 0 } } },
[66939] = { ["id"] = 66939, ["name"] = "Hunting the Huntmaster", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66939 }, ["description"] = "I heard from one of the guards in Camp Nowhere that there's a nasty piece of work mutilating the local wildlife. Calls itself a 'huntmaster'. Hunting is one thing, but I can't abide torturing any living thing. Besides, my wagon could use a good luck charm. <Nesingwary spits over the side.> Bring me back its paw.", ["objectivesText"] = "Hunt down Huntmaster Krakle around Imbu's Shield. Progress: How goes the hunt?", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 194430 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191205, ["x"] = 0.483556, ["y"] = 0.335778 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194590, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.483556, ["y"] = 0.335778 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66948] = { ["id"] = 66948, ["name"] = "The Emissary's Arrival", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["description"] = "I will admit that I have not left the Emerald Gardens in all my life, and as such, I have never met a centaur, let alone a mortal from the mainland. However, I am not here for a kindly visit, but rather to plead for the centaur's aid in securing our oathstone and protecting our charge. I am glad to see you are here to help as well. There is much to discuss.", ["objectivesText"] = "Learn about the situation in the Emerald Gardens. Progress: The Green Dragonflight has lost much over the years. We need the aid of mortals where possible.", ["rewardGold"] = 262100, ["rewardXP"] = 2765, ["rewardItems"] = { 191160, 194964, 197405, 197639, 197640, 197641, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194927, ["x"] = 0.605, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194927, ["x"] = 0.605, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 21, ["flags"] = 0 } } },
[66956] = { ["id"] = 66956, ["name"] = "Dragonhunter Igordan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["storyline"] = { 66956 }, ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2VignetteID"] = 5126, ["db2VignetteName"] = "Dragonhunter Igordan" },
[66957] = { ["id"] = 66957, ["name"] = "A Shadow In The Ice", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66957 }, ["description"] = "I've heard whispers while passing through Camp Antonidas. Talk of mutilated fauna being found across the icy steppes. Some nothing more than bloody splatters. Whatever it is, it's got the mages scared and made the local wildlife scarce. Poke around the top of the glacier. If I was a betting dwarf, I'd say that's where any apex predator worth its salt would stake its claim. Bring me a piece of it so we can soothe the Kirin Tor.", ["objectivesText"] = "Investigate the top of the glacier that overlooks Camp Antonidas. Progress: Be careful. Whatever this thing is, it's strong. And relentless.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 194439 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191205, ["x"] = 0.483556, ["y"] = 0.335778 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194590, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.483556, ["y"] = 0.335778 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66958] = { ["id"] = 66958, ["name"] = "Protect And Herd", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66958 }, ["description"] = "I was talking with some hunters out of Iskaara the other day, and they mentioned finding a grisly scene. Apparently, a particularly murderous rhino, Bloodhorn, has been goring the smaller bruffalon in the area. The bruffalon have enough competition in Azure Span without worrying about getting their herds thinned out by an invasive brute from out of town! Bring me his horn. I'd like to make a good impression on our Tuskarr friends!", ["objectivesText"] = "Hunt down Bloodhorn east of Iskaara. Progress: Remember: watch out for his hooves! That's how rhinos get you.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 2817, 10549, 57552, 131205, 194433 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191205, ["x"] = 0.483556, ["y"] = 0.335778 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194590, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.483556, ["y"] = 0.335778 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66960] = { ["id"] = 66960, ["name"] = "Klozicc the Ascended", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["storyline"] = { 66960 }, ["rewardGold"] = 74100, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2VignetteID"] = 5127, ["db2VignetteName"] = "Klozicc the Ascended" },
[66963] = { ["id"] = 66963, ["name"] = "Out For Delivery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66963 }, ["description"] = "I tried to tell Vevesi that I could pull the wagon out of the mud. But, no, he insisted on using magic to get it out... And now look what he's done. < Hauler Bennet sighs.> While I try to talk sense into Vevesi, can you run up the hill to the Basecamp and let Cataloger Wulferd know that he might need to ship another crate of camera supplies over from Boralus?", ["objectivesText"] = "Tell Cataloger Wulferd in the nearby basecamp that his supplies won't be arriving anytime soon.", ["rewardGold"] = 5865, ["rewardXP"] = 175, ["rewardItems"] = { 159, 2070, 4536, 22571, 28146, 28147, 28148, 30256, 30257, 30258, 60902, 60903, 60904, 67164, 67181, 67198, 67214, 69216, 69221, 69222, 131243, 131579, 131710, 142054, 192465, 199128, 208798, 237812, 264178 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191698, ["x"] = 0.485, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187705, ["x"] = 0.484, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66968] = { ["id"] = 66968, ["name"] = "Pruning The Pack", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66968 }, ["description"] = "<Nesingwary gestures to the side of the path.> See those imprints in the snow? Yeti tracks. Something must of riled them up to hunt this close to the road. See if you can't hunt down their pack leader. We don't want them to start ambushing travellers! If he's a particularly mean brute, collect his head. That should dissuade the others.", ["objectivesText"] = "Hunt down Yetor near Ronin's Shield. Progress: Careful, friend. Yeti hunt in packs.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 194440 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191205, ["x"] = 0.483556, ["y"] = 0.335778 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194590, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.483556, ["y"] = 0.335778 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66969] = { ["id"] = 66969, ["name"] = "Clans of the Plains", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66022, 66023 }, ["description"] = "While you wait for the emissary to arrive, Sansok Khan is interested to hear how meeting the clans went. She sent me to find you and tell you to meet her in the center of Maruukai to discuss.", ["objectivesText"] = "Report to Sansok Khan in Maruukai. Progress: < Sansok Khan smiles at you, welcoming you back.>", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191160, 194964, 197405, 197670, 197671, 197906, 197907, 198981 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191283, ["x"] = 0.6075, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6075, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 20, ["flags"] = 0 } } },
[66971] = { ["id"] = 66971, ["name"] = "The Face of Death", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66971 }, ["description"] = "Tell me, friend. Have you ever seen the face of death? <Nesingwary pauses for dramatic effect.> What am I saying? Of course you have. Death, after all, has many faces. I've heard tell from the Imbu tuskarr that one of its faces lives up in these hills. To even say its name is to invite a violent, frigid death: Frostjaw. <Nesingwary looks around warily.> Well, now you have to hunt it--for my sake at least!", ["objectivesText"] = "Hunt down Frostjaw north of Winterpelt Hollow. Progress: Don't dawdle about. I'm in mortal danger now!", ["rewardGold"] = 524200, ["rewardXP"] = 5145, ["rewardItems"] = { 194444 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191205, ["x"] = 0.483556, ["y"] = 0.335778 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194590, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.483556, ["y"] = 0.335778 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66972] = { ["id"] = 66972, ["name"] = "Old Stonetusk", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66972 }, ["description"] = "I have a grim task for you, $p. Not every kill is a measure of skill. Some are measures of kindness. There's an old bull mammoth wandering the forest east of Camp Antonidas. I saw him from a distance awhile back, and I hear his sad trumpeting every so often. Clearly he's in great pain. He's started crashing blindly through the undergrowth, and I'm worried he's becoming a danger to others. It'd make my old heart glad if you put a fellow weary soul to rest. Bring me his tusk so we can honor him.", ["objectivesText"] = "Put Old Stonetusk down near Camp Antonidas. Progress: Is it done?", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 194432 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191205, ["x"] = 0.483556, ["y"] = 0.335778 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194590, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.483556, ["y"] = 0.335778 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66997] = { ["id"] = 66997, ["name"] = "Nursery Direction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66997 }, ["description"] = "I'm so grateful that Lasztak has accepted the Calling of a Whelptender! Especially given how many of the precious little things are teething right now. Beyond that, the nursery gardens are admittedly facing challenges. The whelps are stressed and the tenders are--well, more stressed than usual. Please, whenever you have a spare moment, find me in the gardens below. We could use your help as well!", ["objectivesText"] = "Meet Vaeros in the gardens of the Ruby Life Pools.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191174, ["x"] = 0.618, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190525, ["x"] = 0.574, ["y"] = 0.668667 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66998] = { ["id"] = 66998, ["name"] = "Fighting Fire with... Water", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66998 }, ["description"] = "In all my years of tending to the lava elementals, I have never seen them act like this! We can barely keep them contained to the cave. Do you have a minute to spare? We'll hold the exit while you thin their numbers inside. Here, take this bottled water elemental with you. I always carry a few spare bottled water elementals when I'm looking after the lava elementals. Natural enemies make for good distractions!", ["objectivesText"] = "Kill lava elementals in the Erupting Cavern.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194441 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188297, ["x"] = 0.59, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188297, ["x"] = 0.59, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[67007] = { ["id"] = 67007, ["name"] = "Archival Assistance", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 67007 }, ["description"] = "<The crisp, clean lettering, written with an elegant touch, fades quickly into the parchment's wet, smudged ink and a smell reminiscent of spilled, fermented beverage.> ADVENTURE SEEKERS, ARCHIVAL ENTHUSIASTS-- The archives call to those who seek answers, yearn to discover, and those who wish to reveal secrets of the past, and perhaps, the future! This request is not for the faint of heart, nor those of wavering will. Only curious and brave adventurers need apply. - Kemora", ["objectivesText"] = "Speak with Kemora at the archives in Valdrakken .", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189973, ["x"] = 0.348, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[67033] = { ["id"] = 67033, ["name"] = "Assemble the Defenses", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "The Primalists have been hunting the Kirin Tor since we arrived in the Azure Span . They detest our practice of arcane magic. I'll send word to Kalecgos to return from the Azure Archives. In the meantime, we need to hold them off. It seems one of our main arcane defenses was destroyed in their initial attack. Bring the pieces back to me and I can reassemble it.", ["objectivesText"] = "Recover 3 pieces of the Arcane Blaster. Progress: Do you have the pieces? I remember exactly how it was assembled, so repairing it should not be a problem.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 4, ["flags"] = 0 } } },
[67035] = { ["id"] = 67035, ["name"] = "Preservation of Knowledge", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "Greetings, <race>. I am Althanus . I wish we could have met in a less... chaotic time. We were helping the Kirin Tor study the history of this place just a few moments before the Primalists attacked. I fear several tomes may still be out there, at risk of being destroyed in this dreadful assault. Please, you must recover these tomes! If they're destroyed, the history of this place will be lost.", ["objectivesText"] = "Find 4 Ancient Tomes scattered around Camp Antonidas. Progress: Do you have the tomes?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194513, 194514, 194515, 194516, 194517, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192222, ["x"] = 0.466, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192222, ["x"] = 0.466, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 5, ["flags"] = 0 } } },
[67036] = { ["id"] = 67036, ["name"] = "Wrath of the Kirin Tor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "I've assembled the pieces of the device you recovered. Place it near Khadgar and use it to repel the Primalists! We just need to hold out a little longer until Kalecgos arrives.", ["objectivesText"] = "Use the Arcane Blaster to help Khadgar defeat the primalists. Progress: Just hold out a little longer...", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891, 198010 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 6, ["flags"] = 0 } } },
[67047] = { ["id"] = 67047, ["name"] = "Warm Away These Shivers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 67047 }, ["description"] = "I believe the plant you're looking for has a fine, narrow stem and red leaves all about it. You'll be hard-pressed not to run into any of those dastardly crawlers while you're collecting flowers though. I'd advise you steer clear when you can, or ready a sharp weapon when you can't. And let your dragon friend know they can repay me in a cup or two of the stuff next time I'm in the city.", ["objectivesText"] = "Collect 12 Coldsnap Sagittate leaves. Progress: Steeped just right, coldsnap fills the drinker with warmth for hours to come.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194550, 200759, 200885, 200886, 246706 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185778, ["x"] = 0.516, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[67050] = { ["id"] = 67050, ["name"] = "Frostbite: Causes and Symptoms", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 67050 }, ["description"] = "Elements live in the totems, <race>. Release them and break the ice. Free your tuskarr friends!", ["objectivesText"] = "Place the totems to release the trapped tuskarr hunters in the Azure Span .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193617 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189625, ["x"] = 0.584, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189963, ["x"] = 0.586667, ["y"] = 0.402667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[67053] = { ["id"] = 67053, ["name"] = "Give Peace a Chance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66036, 67053, 70135, 70373, 71026, 71143 }, ["description"] = "Light be with you, $p. This expedition is under the protection of both the Horde and Alliance. Our orders are clear: give aid to any members of the expedition, regardless of their other allegiances. The Horde's representatives, Warlord Grimaxe and her daughter Shuja, stand guard on the other side of camp. I fought with Warlord Grimaxe against the scourge. She is noble and will serve this expedition well. Go offer her your assistance. Show her that the Alliance honors its commitments.", ["objectivesText"] = "Introduce yourself to the Horde representatives.", ["rewardGold"] = 1230, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184449, ["x"] = 0.766, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 184452, ["x"] = 0.762, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 8, ["flags"] = 0 } } },
[67063] = { ["id"] = 67063, ["name"] = "10,000 Years of Roasting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 67063 }, ["description"] = "Spices? Oh! Ya must be with da big 'ol dragon cook. Da one with a little duck chef on her head. Djaradin collect up a powder, Spicy Lava Spices , off da fiery elementals down below. Don' you look at me like dat! It's what da Djaradin be calling dem, not me! Good luck down there. I wouldn't go alone if was you.", ["objectivesText"] = "Collect 30 Spicy Lava Spices . Progress: I wish I could talk with one the Djaradin cooks. They must have their own rich culinary history! If only it did not include eating my fellow kin...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194551, 200887, 200888, 200889, 247223 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189207, ["x"] = 0.255, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.255, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "group" },
[67064] = { ["id"] = 67064, ["name"] = "Rambling Delight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 67064 }, ["description"] = "Oh, Rumiastrasza ! Myself and the dryad sisters, Celina and Felina, had a lovely evening cooking for her. The kelp we ate is a unique strain called Glimmering Ramblekelp. Swarms of frillfish devour them all along the coast. I wouldn't be surprised if they attack you while you're plucking their food from the sea floor. Please give the chefs my best when you see them. They're always welcome here in our sanctuary.", ["objectivesText"] = "Collect 10 Glimmering Ramblekelp Bulbs . Progress: I have been tantalized by the smell of fresh berries all day. It has been a most incredible afternoon, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194552, 200890, 200891, 200892 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186502, ["x"] = 0.285, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.285, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[67065] = { ["id"] = 67065, ["name"] = "Future-Fresh Fungi", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 67065 }, ["description"] = "A delicious mushroom? Alternate futures are not pantries to be raided for midmorning snacks. But still... I would be lying if I said I had never dreamed of eating Rumi and Morsel's cooking again. Very well! You have my permission to pass through the portal, though I advise you to find others to travel with. My wardens have mentioned these dark mushrooms to me before. Apparently, they never stay in the same place for very long. Make of that what you will.", ["objectivesText"] = "Capture 7 Time-Blasted Trufflettes from the Primalist Future. Progress: Morsel went so long with telling me about this amazing fungi! What else are you keeping from me, you wonderful little chef, you!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194553, 200893, 200894, 200895 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187025, ["x"] = 0.6045, ["y"] = 0.831 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6045, ["y"] = 0.831 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13647 } }, ["questType"] = "group" },
[67066] = { ["id"] = 67066, ["name"] = "Delights to Delve For", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 67066 }, ["description"] = "Rumi and Morsel? Gosh, that was quite a long time ago now. Eating a fish with a dragon and duck chef duo sounds like the beginning of a tale Elder Poa might tell for the younglings. We'd be hard-pressed to forget such a happening! The fish was a Savory Deviant Dealfish , a top Tuskarr favorite! They're rare, but found just off the coast here. Fair warning - it's azuretooth mating season. Those bloodthirsty fiends will take a chunk out of you for messing with their favorite snack.", ["objectivesText"] = "Collect a Savory Deviant Dealfish . Progress: Morsel is an incredible angler. He does not even require a fishing rod!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194554, 200896, 200897, 200898 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186212, ["x"] = 0.074, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.074, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[67067] = { ["id"] = 67067, ["name"] = "Navigating the Leapmaize", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 67067 }, ["description"] = "There's a dragon chef in Valdrakken ? Truly? I'll have to ask her to try my arclight bisque! It's an old family recipe. I know the plant you speak of. It grows around streams here, but it's caused some problems. The stalks of leapmaize seem to be a natural feeding ground for beetles and small salamanthars, which are, in turn, natural prey of the hornswogs. That's fine if you can spot them out in the open, but there's a few here that are incredibly stealthy. I'd watch my back if I were you.", ["objectivesText"] = "Collect 15 stalks of Wild Leapmaize . Progress: I met Morsel while he was roasting an enormous hornswog over an open pit of coals. The mangy leaper had followed him from the Hollows all the way to the Life Pools before he and a few guards worked together to defeat it. Of course, he shared the scrumptious meal with all of them in return!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 85500, 194555, 200899, 200900, 200901 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189400, ["x"] = 0.652, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[67068] = { ["id"] = 67068, ["name"] = "Anything But a Breeze", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 67068 }, ["description"] = "Breezehunters?! Oh, those falcons have been a problem. Just the other day, our stable master, Marren, almost fell to her death trying to tame one. She's pretty proud, so she blamed it on the breezehunter itself. Told me that if it didn't think her eggs were being attacked, it wouldn't have been so aggressive as to bully her off the cliff's edge. I guess that means that you might find the eggs you're looking for out there? It was to the east, just around the mountainside here.", ["objectivesText"] = "Collect a Breezehunter Egg . Progress: Looks like you made it back with a few scrapes as well as the egg! Worry not about your pride or anything of the like! Even a dragon of my size wouldn not want to take on a nest of them alone.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194556, 200902, 200903, 200904 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 196161, ["x"] = 0.858, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.858, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[67071] = { ["id"] = 67071, ["name"] = "What a Long, Sweet Trip It's Been", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 67071 }, ["description"] = "<name>! Just who Morsel and I were looking for! From the bottom of both of our winged-hearts, we thank you dearly. We started The Ruby Feast to share the Isles' culinary culture with all of Azeroth's races, and to learn from them too. We had you running from one end of our beloved continent to another, but you helped bring our dream vision of these gatherings to each honored visitor and guest here. As friends, we would like to give you a gift. Grab the top journal from our hoard behind the cauldron.", ["objectivesText"] = "Speak with Rumiastrasza . Progress: Our hoard is just behind the cauldron. Not to worry though, we lowered the sealing enchantment and deathly magical traps for you!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 197795, 198132, 202013 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[67073] = { ["id"] = 67073, ["name"] = "Red Dawn", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66675, 66847, 70437, 72380 }, ["description"] = "We've come so close to recovering our powers... should Raszageth succeed before our powers return, I fear that the timeways will bend to a dark future for all of Azeroth. We must not allow this to occur, <name>! Hurry, you must find and aid Alexstrasza before all is lost!", ["objectivesText"] = "Locate Alexstrasza.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 190454, 197921, 239135, 239136 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192455, ["x"] = 0.574, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190902, ["x"] = 0.724, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1333, ["name"] = "The Mother Oathstone", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 51, ["flags"] = 0 } } },
[67074] = { ["id"] = 67074, ["name"] = "The Gift of Silver", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 67074, 67075, 67076, 67077, 67078, 67079, 67081, 67084, 68794, 70703 }, ["description"] = "Shortly before his passing, Keeper Tyr gifted us with a dragon scale forged of purest silver. We kept it in the vaults of Valdrakken during our absence, but I believe it is time to share it once more. Though we have no idea the purpose for this memento, it has always been a symbol of unity and friendship to us. As a true ally to dragonkind, we would like to share it with you. Speak to me when you are ready, <name>.", ["objectivesText"] = "Speak to Alexstrasza to reveal Tyr's gift. Progress: What do you make of this, <name>?", ["rewardGold"] = 154900, ["rewardXP"] = 2465, ["rewardItems"] = { 197845, 197862, 197863, 198038, 198355 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1325, ["questLineOrder"] = 0 }, { ["id"] = 229, ["title"] = "Catching Up!", ["questLineID"] = 1325, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1325, ["name"] = "The Silver Purpose", ["orderIndex"] = 1, ["flags"] = 0 } } },
[67075] = { ["id"] = 67075, ["name"] = "The Magic Within", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 67074, 67075, 67076, 67077, 67078, 67079, 67081, 67084, 68794, 70703 }, ["description"] = "Intriguing. There are many mysteries living within this citadel that no one, save Keeper Tyr himself, understand. If we are to unlock this further we shall have to explore more of Tyrhold. I believe that the scale will draw out secrets stored within this place. However. there is one complication. The guardians of Tyrhold are still... unstable. They may take your exploration as disruption and try to interfere. Take this conduit. It will help you should the guardians prove troublesome.", ["objectivesText"] = "Draw out hidden magic from consoles around Tyrhold to uncover the mystery of the Silver Scale . Progress: What have you discovered?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 197862, 197863, 198038, 198355 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192480, ["x"] = 0.592, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192480, ["x"] = 0.592, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1325, ["questLineOrder"] = 0 }, { ["id"] = 229, ["title"] = "Catching Up!", ["questLineID"] = 1325, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1325, ["name"] = "The Silver Purpose", ["orderIndex"] = 3, ["flags"] = 0 } } },
[67076] = { ["id"] = 67076, ["name"] = "A Spark of Discovery", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 67074, 67075, 67076, 67077, 67078, 67079, 67081, 67084, 68794, 70703 }, ["description"] = "Though this spark is of peculiar origin, I sense it is familiar. I am not sure of its purpose, but I believe it may lead to your next step in unraveling this mystery. Follow it and see if you can learn more of its purpose, while I see what else I can discover in the meantime.", ["objectivesText"] = "Investigate the Titan Spark in Tyrhold.", ["rewardGold"] = 154900, ["rewardXP"] = 2465, ["rewardItems"] = { 197862, 197863, 198038, 198355 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192480, ["x"] = 0.592, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 193492, ["x"] = 0.611, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1325, ["questLineOrder"] = 0 }, { ["id"] = 229, ["title"] = "Catching Up!", ["questLineID"] = 1325, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1325, ["name"] = "The Silver Purpose", ["orderIndex"] = 4, ["flags"] = 0 } } },
[67077] = { ["id"] = 67077, ["name"] = "Memories of the Past", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 67074, 67075, 67076, 67077, 67078, 67079, 67081, 67084, 68794, 70703 }, ["description"] = "This place is where we last saw our friend, Tyr. We did not understand the circumstances by which he had to leave, only that it was for something important. Though it may be difficult for our hearts to bear, I believe this spark called us here to witness that time once more. With Nozdormu's aid we may relive that moment and see if there was some other clue Tyr left behind for us.", ["objectivesText"] = "Speak to Nozdormu to witness the memory of the past. Progress: Forgive me, <name>. This is still emotional for me.", ["rewardGold"] = 154900, ["rewardXP"] = 2465, ["rewardItems"] = { 62195, 62196, 62197, 62198, 131631, 131632, 197862, 197863, 198038, 198355 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192573, ["x"] = 0.612, ["y"] = 0.589 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192573, ["x"] = 0.612, ["y"] = 0.589 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.589 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1325, ["questLineOrder"] = 0 }, { ["id"] = 229, ["title"] = "Catching Up!", ["questLineID"] = 1325, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1325, ["name"] = "The Silver Purpose", ["orderIndex"] = 5, ["flags"] = 0 } } },
[67078] = { ["id"] = 67078, ["name"] = "Parting Instructions", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 67074, 67075, 67076, 67077, 67078, 67079, 67081, 67084, 68794, 70703 }, ["description"] = "<The echo speaks with an ancient voice.> To my dear friends, I apologize for my sudden departure. But, I promise that you are not without my aid. I know that you have come upon the time of great need, but to ensure this gift does not get misused I must ask you to perform a series of tasks. The first is simple: reactivate the forge within Tyrhold. The Silver Scale is the key.", ["objectivesText"] = "Place the Silver Scale at the forge in Tyrhold. Progress: You have a means to activate the forge?", ["rewardGold"] = 154900, ["rewardXP"] = 2465, ["rewardItems"] = { 197862, 197863, 198038, 198355 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192496, ["x"] = 0.610667, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192480, ["x"] = 0.592, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.610667, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1325, ["questLineOrder"] = 0 }, { ["id"] = 229, ["title"] = "Catching Up!", ["questLineID"] = 1325, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1325, ["name"] = "The Silver Purpose", ["orderIndex"] = 6, ["flags"] = 0 } } },
[67079] = { ["id"] = 67079, ["name"] = "Hard Lock Life", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 67074, 67075, 67076, 67077, 67078, 67079, 67081, 67084, 68794, 70703 }, ["description"] = "The security in the forge is stricter than in any other area of Tyrhold. This will be quite a challenge for us, <class>. Only certain units around the citadel have the capability to bypass this security, and the protocols to unlock require more than one code in case of corruption. These units will not want to relinquish their overrides, you may have to take them by force. Be careful, <name>.", ["objectivesText"] = "Retrieve the Primary Security Disc and Secondary Security Disc within Tyrhold. Progress: I hope we have not disrupted Tyrhold greatly. May the Keeper forgive us.", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 197862, 197863, 198038, 198355 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192480, ["x"] = 0.592, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192480, ["x"] = 0.592, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1325, ["questLineOrder"] = 0 }, { ["id"] = 229, ["title"] = "Catching Up!", ["questLineID"] = 1325, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1325, ["name"] = "The Silver Purpose", ["orderIndex"] = 7, ["flags"] = 0 } } },
[67081] = { ["id"] = 67081, ["name"] = "Halls of Infusion: An Infusion of Materials", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14082, ["mapID"] = 2025, ["storyline"] = { 67074, 67075, 67076, 67077, 67078, 67079, 67081, 67084, 68794, 70703 }, ["description"] = "<The image of Tyr speaks again.> You have reactivated the forge. The next task will not be as simple. Transcribed within the scale are schematics for something I require you to forge. I have entrusted one of my watchers, Irideus, with the necessary materials for this task. They are of special origin, and only few of them are left in existence. Seek Irideus within the Halls of Infusion, where I hope his careful watch has kept the facility operating in an orderly fashion.", ["objectivesText"] = "Retrieve 10 Ancient Titansteel Ingots and defeat the Primal Tsunami in the Halls of Infusion. Progress: Once you have retrieved the required materials you will be able to proceed.", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 197862, 197863, 198038, 198355 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192496, ["x"] = 0.610667, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192496, ["x"] = 0.610667, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.610667, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14082 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1325, ["questLineOrder"] = 0 }, { ["id"] = 229, ["title"] = "Catching Up!", ["questLineID"] = 1325, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1325, ["name"] = "The Silver Purpose", ["orderIndex"] = 8, ["flags"] = 0 } } },
[67084] = { ["id"] = 67084, ["name"] = "The Silver Purpose", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 67074, 67075, 67076, 67077, 67078, 67079, 67081, 67084, 68794, 70703 }, ["description"] = "<The echo of Tyr activates to your presence.> Your task is at hand, my friends. Cast the ingots into the fire and activate the forge. I have prepared the necessary procedures for you already. The Silver Scale holds the schematic. Its purpose shall reveal itself to you.", ["objectivesText"] = "Place the Ancient Titansteel Ingots into the forge and finish the task Tyr has left behind.", ["rewardGold"] = 929400, ["rewardXP"] = 7390, ["rewardItems"] = { 197862, 197863, 198038, 198355, 201781 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192496, ["x"] = 0.610667, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192573, ["x"] = 0.612, ["y"] = 0.589 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.610667, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1325, ["questLineOrder"] = 0 }, { ["id"] = 229, ["title"] = "Catching Up!", ["questLineID"] = 1325, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1325, ["name"] = "The Silver Purpose", ["orderIndex"] = 9, ["flags"] = 0 } } },
[67093] = { ["id"] = 67093, ["name"] = "An Anomalous Shrine", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 67093 }, ["description"] = "My research team located a strange sanctum nearby. We were able to make out some writing on the outside of it--titan runes, to be exact--which we believe reference Aman'Thul the Highfather, leader of the titans, in several places. We tried to inspect more closely but must have triggered the sanctum's defenses. A massive sand amalgam blocked us off and we narrowly made it out alive. We aren't certain what it's protecting, but it must be important. Can you investigate?", ["objectivesText"] = "Find a way to collect the relic hidden inside the Sand-Lost Sanctum, then return it to Nozdormu at the Seat of the Aspects in Valdrakken. Progress: This land is a sleeping giant. We ought to wake it with requisite caution.", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 194687, 195217, 195218 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192543, ["x"] = 0.602, ["y"] = 0.82 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.82 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[67094] = { ["id"] = 67094, ["name"] = "A Dryad's Work Is Never Done", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 67094 }, ["description"] = "It is wonderful to see Valdrakken so lively again, but there are so many things that have wilted under thousands of years of neglect - not the least of which are all of the adorable little city critters! Alas, we don't have enough dryads to go around tending to them all. Say, how would you like to be appointed Honorary Valdrakken Dryad? Some of the city's cutest little friends have gone far too long without their preferred snacks. Won't you help me tend to them?", ["objectivesText"] = "Help Thalendra feed the many small animals of Valdrakken . Progress: Tut tut, Junior Dryad! Those critters won't feed themselves! ...Or, well, they could I suppose. But where's the fun in that?", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["rewardItems"] = { 50446, 71076, 201838 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 192522, ["x"] = 0.728, ["y"] = 0.656 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 192522, ["x"] = 0.728, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[67100] = { ["id"] = 67100, ["name"] = "A Gift for Miguel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 67100, 67137, 67295, 67564, 69946, 69979 }, ["series"] = { 67564 }, ["description"] = "$p, could you do me a favor? I want to get a gift for my husband, Miguel. He means so much to me, but I've been so busy lately that I haven't had time to make him anything. Could you help me make him something high quality?", ["objectivesText"] = "Talk to Thomas about quality, then gather 3 Fiery Spirits near Hornswog Hollow for Miguel's gift. Progress: Miguel will love this!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 190456, 191784, 194714, 194715, 194727, 194728, 194729, 197860 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192574, ["x"] = 0.602, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192574, ["x"] = 0.602, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "profession", ["campaigns"] = { { ["id"] = 191, ["title"] = "Professions Onboarding Skip", ["questLineID"] = 1364, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1364, ["name"] = "Catching Up!", ["orderIndex"] = 0, ["flags"] = 0 } } },
[67111] = { ["id"] = 67111, ["name"] = "The Ailing Apprentice", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 67111 }, ["description"] = "This mission was a mistake from the beginning. Alia Sunsoar enlisted our aid to keep the Sundered Flame from acquiring a dangerous artifact. We had tracked it down to these ruins. But the Sundered Flame beat us here and the area is infested with ice spiders. Alia was badly poisoned, and I fear she will not last long without the antidote. I can make it, but I need venom glands from the nearby spiders. I'm afraid to leave her. Will you find some for me?", ["objectivesText"] = "Collect 5 Frozen Venom Glands . Progress: Do you have the venom glands I asked for?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196254, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196254, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[67137] = { ["id"] = 67137, ["name"] = "Professionally Equipped", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 67100, 67137, 67295, 67564, 69946, 69979 }, ["description"] = "Say, I heard from Haephesta that you're a working artisan as well. We'd like to get you set up with some professional equipment. Free of charge. That's what business partners are for, right? Talk to our tailor, Mahra Treebender , to get fitted.", ["objectivesText"] = "Speak with Mahra Treebender . Progress: Now, let us get you equipped.", ["rewardXP"] = 175, ["rewardItems"] = { 190456, 191239, 191784, 193035, 193479, 193482, 193485, 193486, 193487, 193529, 193534, 193539, 193612, 193615, 194714, 194729, 197860, 198243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192539, ["x"] = 0.598, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192674, ["x"] = 0.61, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "profession", ["campaigns"] = { { ["id"] = 191, ["title"] = "Professions Onboarding Skip", ["questLineID"] = 1364, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1364, ["name"] = "Catching Up!", ["orderIndex"] = 1, ["flags"] = 0 } } },
[67154] = { ["id"] = 67154, ["name"] = "Entropic Remnants", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 67154 }, ["description"] = "When an entity passes through the timeways, the sands of time can sometimes accumulate on their body. Typically, this sand dissipates in short order--but sometimes, the entropic fluctuations inherent in time travel can cause that sand to vitrify. In these cases, it becomes rather difficult to remove. I've ruined several good pairs of shoes this way. Vitrified sand can be quite powerful for our purposes. It would be in best interest to reclaim as much of it as we can.", ["objectivesText"] = "Collect 8 Vitrified Sand from creatures in the Shifting Sands. Progress: Have you had any luck? It's usually somewhat rare, but we've been seeing more of it lately.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 199064 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192543, ["x"] = 0.602, ["y"] = 0.82 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192543, ["x"] = 0.602, ["y"] = 0.82 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.82 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[67174] = { ["id"] = 67174, ["name"] = "Arcane Detection", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 67174 }, ["description"] = "Greetings! I am Miva Star-Eye , and I am conducting arcane investigations in this area. The Azure Span has magic all around it. Some of it is benign... while some can be quite dangerous. I've been tasked with ensuring no arcane energies reside in anything the tuskarr possess. We already had one incident in Camp Antonidas of a fishing box spontaneously combusting! Can you take my detector and examine a few objects here? I need to continue speaking with Julk over here.", ["objectivesText"] = "Investigate tuskarr objects in Khuri's Fishing Spot for signs of arcane magic. Progress: Let's hope there's nothing out of the ordinary here.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194899 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192750, ["x"] = 0.412, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192750, ["x"] = 0.412, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[67175] = { ["id"] = 67175, ["name"] = "How To Stop An Exploding Toy Boat", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 67175 }, ["description"] = "I am loathe to part a child from their toy, but it would be a great value to the Kirin Tor to study how it absorbed so much arcana. Then again... I do not want to slight our new tuskarr allies. I do have a wand that could dispel the magic... Let's speak with Toolk's mother, then decide what to do.", ["objectivesText"] = "Speak with Toolk's mother, then recover the toy boat. Progress: The wand should handle any dispelling if we're not too late.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194900 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192750, ["x"] = 0.412, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192750, ["x"] = 0.412, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[67177] = { ["id"] = 67177, ["name"] = "WANTED: Gorger", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 67177 }, ["description"] = "If you are going to be amongst the tuskarr, you would do well to lend a hand! As of late, a beast we call Gorger has been making its home nearby. More of its kind seem to be migrating to this area. This is something we can take advantage of. Kill the Gorger and bring me its horns. We'll need them for building supplies to expand this outpost.", ["objectivesText"] = "Slay Gorger and recover its horns. Progress: Do you have the horns?", ["rewardGold"] = 842700, ["rewardXP"] = 6175, ["rewardItems"] = { 194901 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192760, ["x"] = 0.414, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192760, ["x"] = 0.414, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "group" },
[67295] = { ["id"] = 67295, ["name"] = "That's My Specialty", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2022, ["storyline"] = { 67100, 67137, 67295, 67564, 69946, 69979 }, ["description"] = "So, you've started taking up a specialization, eh? 'Tis a glorious thing to have an exclusive skill you can call your own. As a member of the Artisan's Consortium, I would be delighted to help you on your journey to honing your specialization. Have you a minute to listen to my words of wisdom, and perhaps learn something to help you on your adventures?", ["objectivesText"] = "Talk to Miguel Bright about a professional specialization. Progress: Aye, that's the gist of it, anyhow.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 190456, 191784, 194714, 194729, 197860 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192539, ["x"] = 0.598, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192539, ["x"] = 0.598, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["campaigns"] = { { ["id"] = 191, ["title"] = "Professions Onboarding Skip", ["questLineID"] = 1364, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1364, ["name"] = "Catching Up!", ["orderIndex"] = 2, ["flags"] = 0 } } },
[67298] = { ["id"] = 67298, ["name"] = "The Wonders of the World", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2022, ["storyline"] = { 67298 }, ["description"] = "My husband Thomas has gained many insights from exploring these primal lands. Perhaps following in his footsteps would similarly inspire you?", ["objectivesText"] = "Find out how Thomas gains his artisan's insight. Progress: I could relax here forever.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 190456, 191784, 194714, 194729, 197860 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192539, ["x"] = 0.598, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 193548, ["x"] = 0.46, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13645 } }, ["questType"] = "profession" },
[67299] = { ["id"] = 67299, ["name"] = "Drakes be Gone", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 67299 }, ["description"] = "The primalists have been ceaselessly attacking our camp with their drakes! We've been able to keep them at bay with our shields, but we could use more aid in taking them out of the sky. Use one of our blasters to take those drakes down!", ["objectivesText"] = "Use an Arcane Blaster to defeat 5 proto-drakes .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189751, ["x"] = 0.658, ["y"] = 0.254 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189751, ["x"] = 0.658, ["y"] = 0.254 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.254 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[67564] = { ["id"] = 67564, ["name"] = "Artisan's Courier", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 67100, 67137, 67295, 67564, 69946, 69979 }, ["series"] = { 67100 }, ["description"] = "Adventurer, are you headed into the Lifeshrine? Would you mind taking this invoice to Thomas Bright ? He ordered a few custom-made bottles and our glassblower has finally returned with the price of materials required. He should be just down the path there, likely gushing to some poor soul about how great his husband is... I am sure he will pay you for your time.", ["objectivesText"] = "Deliver the Artisan's Consortium Invoice to Thomas Bright . Provided item:", ["rewardGold"] = 33960, ["rewardXP"] = 175, ["rewardItems"] = { 190456, 191784, 194714, 194729, 195357, 197860, 198790 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192574, ["x"] = 0.602, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "profession", ["campaigns"] = { { ["id"] = 191, ["title"] = "Professions Onboarding Skip", ["questLineID"] = 1364, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1364, ["name"] = "Catching Up!", ["orderIndex"] = 3, ["flags"] = 0 } } },
[67606] = { ["id"] = 67606, ["name"] = "A Dryadic Remedy", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 67606 }, ["description"] = "While you were gone, I heard from a dreamhare that one of the local ducklings is feeling rather down in the dumps. Luckily, I know exactly how to fix that! Whenever I'm feeling moody, I snack on something sweet and tasty! As an expert in cute, lovable creatures, I know that the same principle will surely apply here. This particular duckling is fond of a local dessert known as a Tasty Hatchling's Treat. Won't you find one and bring it to the poor dear? It's the dryadic thing to do, after all!", ["objectivesText"] = "Acquire a Tasty Hatchling's Treat and administer it to the Despondent Duckling. Progress: Well, friend? How fares our ailing avian ally?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 197769, 198106, 201838 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 192522, ["x"] = 0.728, ["y"] = 0.656 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 192522, ["x"] = 0.728, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[67700] = { ["id"] = 67700, ["name"] = "To the Dragon Isles!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 70050, 72240 }, ["series"] = { 70050, 70197 }, ["description"] = "Great news, $p! The spearhead of our expedition has made landfall in the Dragon Isles . Thanks to the efforts of yerself and other Dragonscale Expedition members, we've established a protected landing site and made contact with the dragonflight's embassy. Are ye prepared to accompany us on our next voyage to the Dragon Isles ?", ["objectivesText"] = "Ride the Rugged Dragonscale to the Dragon Isles from Stormwind Harbor.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 197010, 197144, 197358, 197360, 197363, 197369, 197374, 197386, 197395, 197402, 197614, 198398, 198863, 198865, 198866, 198867, 199472, 199473, 203353, 210469, 210501, 217109 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 189077, ["x"] = 0.228, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189022, ["x"] = 0.82, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 84, 2022 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 12, ["flags"] = 0 } } },
[67722] = { ["id"] = 67722, ["name"] = "Break on Through", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66173, 66174, 66546, 66547, 66636, 67722, 69097, 71152 }, ["description"] = "Toddy and Naleidea are preparing to head out. Meet at the Sealed Titan Facility in Thaldraszus. Apparently they've made a breakthrough. Be sure to bring any pertinent information back for cataloging!", ["objectivesText"] = "Meet Toddy and Naleidea outside the Sealed Titan Facility in Thaldraszus.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 38230, 38231, 38232 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 191838, ["x"] = 0.542, ["y"] = 0.554 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1374, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1374, ["name"] = "In the Halls of Titans", ["orderIndex"] = 1, ["flags"] = 0 } } },
[67724] = { ["id"] = 67724, ["name"] = "The Fending Flames", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 67724 }, ["description"] = "Kattigat and I came here to prove ourselves by stopping the Sundered Flame and recovering the Valthrux. Now we're stuck watching over this elf after she takes a few ice spider bites. We haven't even fought the Sundered Flame yet, and the spiders may do us in before we can! We need to keep them at bay. Thankfully, there's a natural way to repel them. Burning silk from their cocoons creates an aroma that repulses the spiders. Grab some silk and I'll throw it on the fire. It'll keep them away!", ["objectivesText"] = "Collect 4 Shiverweb Silk . Progress: Were you able to find any spider silk?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191715, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 191715, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[67772] = { ["id"] = 67772, ["name"] = "The Trouble with Taivan", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 67772 }, ["description"] = "Hello, friend. Welcome back to Maruukai. I am Selbekh, healer of Clan Teerai. Are you good with animals, <name>? Perhaps the influence of a newcomer is just what I need. Taivan here, while a very good companion, has become something of a burden on my clan. I'm afraid if we can't find a good use for him, I may have to send him away. Will you help me?", ["objectivesText"] = "Help Healer Selbekh prepare Taivan for training.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 198537 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 192621, ["x"] = 0.586, ["y"] = 0.361333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 192629, ["x"] = 0.714, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.361333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[67921] = { ["id"] = 67921, ["name"] = "The Hunting Hound", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 67921 }, ["description"] = "Go and hunt the nearby beasts with your giant bakar. The bigger, the better. I will observe from here, and decide if he is worthy of Shikaar training. Be warned, I will only accept the best.", ["objectivesText"] = "Hunt dangerous beasts with Taivan to prove he is worthy of training. Progress: Go and hunt the nearby beasts with your bakar. I will be watching.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 198537 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 192629, ["x"] = 0.714, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 192629, ["x"] = 0.714, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[68083] = { ["id"] = 68083, ["name"] = "Try Again, Taivan!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 68083 }, ["description"] = "Return to the Teerai and tell them that not even I can train Taivan to be a hunter. He simply does not have it in him. He is the most un-ferocious bakar I have ever seen, and I bet he would even try to make friends with the wild game if we let him! Hah!", ["objectivesText"] = "Return to Healer Selbekh in Maruukai and deliver the bad news.", ["rewardGold"] = 24100, ["rewardXP"] = 345, ["rewardItems"] = { 198537 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 192629, ["x"] = 0.714, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 192621, ["x"] = 0.586, ["y"] = 0.361333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[68084] = { ["id"] = 68084, ["name"] = "The Gentle Giant", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 68084 }, ["description"] = "If Taivan is really as \"un-ferocious\" as Jadar says he is, perhaps he'll be better suited as a herding bakar! The Aylaag are expert argali shepherds, and aren't so proud that they require lavish gifts to help another clan. Please send Taivan to Shepherd Tevatei at the Mallakh, a spot between two hills in the south-west where they train their bakar. Ohn'ahra, please let this work. If it doesn't, I'm all out of ideas.", ["objectivesText"] = "Send Taivan to Shepherd Tevatei at the Mallakh to be trained.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 198537 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 192621, ["x"] = 0.586, ["y"] = 0.361333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 192633, ["x"] = 0.49, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.361333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[68085] = { ["id"] = 68085, ["name"] = "Shaping a Shepherd", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 68085 }, ["description"] = "You want me to train your bakar in shepherding? Well, that's certainly what we do here, but I've never trained one quite so BIG before... The argali don't seem to be bothered by his presence, though, and they're very good judges of character. Trust me. I'm willing to give him a shot, but a herding bakar needs to not only be gentle, but smart, too. And if they aren't able to take charge of the herd, the argali won't obey them. It's harder than it looks! Go on and give it a try, I'll watch.", ["objectivesText"] = "Teach Taivan to herd argali at the Mallakh. Progress: Go on and try to command Taivan to herd the argali. I'll be able to tell if he has the potential for it or not.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 198537 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 192633, ["x"] = 0.49, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 192633, ["x"] = 0.49, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[68087] = { ["id"] = 68087, ["name"] = "Danger in Daruukhan", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 68087 }, ["description"] = "I guess there's nothing to be done but send you and Taivan back to Maruukai. Wait... who is that approaching? Not another stranger with a giant bakar, I hope!", ["objectivesText"] = "Talk to the Teerai Messenger to hear Selbekh's urgent request.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 198537 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 192633, ["x"] = 0.49, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 192621, ["x"] = 0.586, ["y"] = 0.361333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[68639] = { ["id"] = 68639, ["name"] = "Prowling Polar Predators", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 68639 }, ["description"] = "The species we've been sent to study is the frigidpelts. Their hunting grounds have been tainted by ley lines. Arcane energies leech into the water and into the plants... and into prey species like the slyvern. But unlike other organisms, the frigidpelts survive the process and gain power from it. They also become aggressive--which is a problem. Engage a few, and I will take notes on their strength and aggression. My report will help the Kirin Tor decide what to do for them.", ["objectivesText"] = "Slay 6 Infected Frigidpelts.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 197983, 198336, 198797, 200526 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192825, ["x"] = 0.646, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192825, ["x"] = 0.646, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[68640] = { ["id"] = 68640, ["name"] = "Sudden Isolation", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "We used to trade frequently with the Uktulut tribe in the Waking Shores , but they haven't been sending or accepting shipments for months now. Our letters have gone unanswered. Naturally, we suspect the worst. Their chieftain, Tutaqan, has always been the reasonable sort. Somewhat prone to strong emotions, but I can't imagine anything terrible could have happened under his leadership. Could you please check on them? If they need help, we'll happily provide.", ["objectivesText"] = "Attempt to make contact with the Uktulut tuskarr.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193006, ["x"] = 0.13, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188301, ["x"] = 0.544, ["y"] = 0.381 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.13, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2022, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 1, ["flags"] = 0 } } },
[68641] = { ["id"] = 68641, ["name"] = "Mossing the Mark", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 68641 }, ["description"] = "Poor girl... She must have gotten sick after eating something tainted. Luckily, my grandfather was a druid and taught me how to treat arcane-based illnesses. I don't have all the components on me, but we can make do with what's around. First, I will need some drakmoss. It is a rare lichen that only grows on dragon bones.", ["objectivesText"] = "Collect 5 Drakmoss Clumps . Progress: Have you gathered the moss?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 197983, 198336, 198797, 200526 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192830, ["x"] = 0.646, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192830, ["x"] = 0.646, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[68642] = { ["id"] = 68642, ["name"] = "Needles to Say", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 68642 }, ["description"] = "I want to help Sylvie, but I don't want to delay Cally any longer. To give Sylvie the medicine, I need arcane-infused quills from the crystalpine. I'm sure they won't mind if you pluck a few off! And mind the bakar! They eat crystalpine and might get mad at you touching it. If you do have to defend yourself, you can collect some spines from them as well. But... try not to do that, please.", ["objectivesText"] = "Collect 15 Arcane-Infused Quills . Progress: Be careful handling the quills! They are VERY sharp. Ask me how I know! <Steria sighs>", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 197983, 198336, 198797, 200526 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192830, ["x"] = 0.646, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192830, ["x"] = 0.646, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[68643] = { ["id"] = 68643, ["name"] = "Vitamins and Minerals", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 68643 }, ["description"] = "I suppose I should have expected that Steria would be upset at me asking you to fight animals... There are of course alternative research methods. Take these vials and collect some water from the nearby ice crystals. I theorize that they contain minerals infused with ley crystal energy--and may be fueling the outbreak here.", ["objectivesText"] = "Collect 4 Mineral Water Vials. Progress: Have you filled all the vials?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 197983, 198336, 198797, 200526 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192825, ["x"] = 0.646, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192825, ["x"] = 0.646, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[68644] = { ["id"] = 68644, ["name"] = "Sugar, Spice, and Everything Nice", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 68644 }, ["description"] = "There! Now I have all I need for Sylvie ! And just in time. I doubt she would have lasted much longer like this. But... I need someone to help me. I'd ask Cally but... would you mind assisting me again? Let me know when or if you're ready, <name>.", ["objectivesText"] = "Help treat Sylvie .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 197983, 198336, 198797, 200526 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192830, ["x"] = 0.646, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192830, ["x"] = 0.646, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[68794] = { ["id"] = 68794, ["name"] = "Ally of Dragons", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 67074, 67075, 67076, 67077, 67078, 67079, 67081, 67084, 68794, 70703 }, ["description"] = "Your aid to the Dragon Isles has not gone unnoticed, <name>. The Life-Binder herself wishes to show you something as a reward for your service to dragonkind. Go and speak to her at the top of the tower. All the Aspects await you.", ["objectivesText"] = "Speak to Alexstrasza at the Seat of the Aspects in Valdrakken.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 197862, 197863, 198038, 198355 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197478, ["x"] = 0.455, ["y"] = 0.5545 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1325, ["questLineOrder"] = 0 }, { ["id"] = 229, ["title"] = "Catching Up!", ["questLineID"] = 1325, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1325, ["name"] = "The Silver Purpose", ["orderIndex"] = 0, ["flags"] = 0 } } },
[68795] = { ["id"] = 68795, ["name"] = "Skyriding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "One thing you may have already discovered about this place: the Dragon Isles are vast. Some of the drakes have an intense interest in exploring every corner and secret hiding place in this renewed land, even those places that are not readily reached from the ground. They are eager for a second set of eyes to aid them in their journey, and in trade will gladly bear a rider across the lands. Speak with Lord Andestrasz , here in the Ruby Lifeshrine. He will explain more of what they intend.", ["objectivesText"] = "Speak with Lord Andestrasz in the Ruby Lifeshrine. Progress: All things come with practice.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187290, ["x"] = 0.622, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193287, ["x"] = 0.576, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1358, ["name"] = "Introduction to Dragonriding", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 14, ["flags"] = 0 } } },
[68796] = { ["id"] = 68796, ["name"] = "The Skytop Observatory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "Those are the basics of riding a drake! You are doing quite well. Now, I would like to introduce you to some of the others involved in this adventure. We have made a home for ourselves over at the Skytop Observatory. Celormu will be able to help guide you there. Speak to him when you feel ready to take to the skies! See you there!", ["objectivesText"] = "Travel to the Skytop Observatory in Waking Shores. Progress: Are you ready for adventure today?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193287, ["x"] = 0.576, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193359, ["x"] = 0.752, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1358, ["name"] = "Introduction to Dragonriding", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 19, ["flags"] = 0 } } },
[68797] = { ["id"] = 68797, ["name"] = "A New Set of Horns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 68797 }, ["description"] = "Just as mortals do, dragons care very much about their appearance. Your drake is able to change as well, according to what you find and experience. Speak to Glensera at the Rostrum of Transformation, and see for yourself!", ["objectivesText"] = "Meet Glensera and use the Rostrum of Transformation to customize your drake. Progress: Sometimes I wonder what I would look like with red hair. What do you think?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193359, ["x"] = 0.752, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193359, ["x"] = 0.752, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[68798] = { ["id"] = 68798, ["name"] = "Skyriding Talents and You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "Obviously, it is not just Glensera and myself that are invested in these adventurers. Lithragosa is also excited to help you hone your dragonriding skills, and you have already met Celormu which is excellent. Your next stop is to speak to Lithragosa , who can show you what skills you can learn!", ["objectivesText"] = "Speak to Lithragosa to see your Skyriding skills. Progress: Have you found the dragon glyph?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193359, ["x"] = 0.752, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193359, ["x"] = 0.752, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1358, ["name"] = "Introduction to Dragonriding", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 20, ["flags"] = 0 } } },
[68799] = { ["id"] = 68799, ["name"] = "Return to the Ruby Lifeshrine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "And this is just the beginning of your dragonriding journey! Keep your eyes open for new adventures and experiences throughout the Dragon Isles, and be sure to visit us in any of our outposts. For now, return to Alexstrasza to continue your exploration in these lands.", ["objectivesText"] = "Return to the Ruby Lifeshrine.", ["rewardGold"] = 7410, ["rewardXP"] = 175, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193359, ["x"] = 0.752, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187290, ["x"] = 0.622, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1358, ["name"] = "Introduction to Dragonriding", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 21, ["flags"] = 0 } } },
[68863] = { ["id"] = 68863, ["name"] = "A Lost Tribe", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "Hi, <name>! Murik wanted to talk to you about something real important back in Iskaara. You should go see what it is.", ["objectivesText"] = "Speak with Murik in Iskaara.", ["rewardGold"] = 29200, ["rewardXP"] = 615, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197631, ["x"] = 0.455, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193006, ["x"] = 0.13, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 0, ["flags"] = 0 } } },
[69093] = { ["id"] = 69093, ["name"] = "A New Mystery", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "< Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp. He eagerly tries to explain.> Sealed door. Titan secrets. Yes? < Doc Nanners nods excitedly, awaiting your response.>", ["objectivesText"] = "Speak with Naleidea Rivergleam in the Dragonscale Basecamp.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196643, ["x"] = 0.455333, ["y"] = 0.552667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186869, ["x"] = 0.478, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455333, ["y"] = 0.552667 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 0, ["flags"] = 0 } } },
[69094] = { ["id"] = 69094, ["name"] = "Saving Centaur", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 69094 }, ["description"] = "The treachery of the Nokhud knows no limits! Only craftsmen live in the village of Daruukhan. They stood no chance against the raiders. We desperately need your help, <name>. The Nokhud are still nearby, and we must tend to the wounded! Search the village, and carry any survivors you find to me. We will triage and stabilize who we can!", ["objectivesText"] = "Rescue injured centaurs in the village of Daruukhan. Progress: We're overwhelmed here! Please, save anyone you can!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 198537 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 192621, ["x"] = 0.586, ["y"] = 0.361333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 192621, ["x"] = 0.586, ["y"] = 0.361333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.361333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[69095] = { ["id"] = 69095, ["name"] = "Homeward Hound", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 69095 }, ["description"] = "We have everyone stabilized, thanks to you and Taivan , but many of these villagers will need to heal for a while longer in Maruukai. Why don't the two of you lead our train back? You are both the heroes of the day, after all!", ["objectivesText"] = "Ride Taivan back to Maruukai. Progress: We're ready to depart. Go ahead and mount Taivan when you're ready.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 198537 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 192621, ["x"] = 0.586, ["y"] = 0.361333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 192621, ["x"] = 0.586, ["y"] = 0.361333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.361333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[69096] = { ["id"] = 69096, ["name"] = "Taivan's Purpose", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 69096 }, ["description"] = "Do you see that young one, sitting by themselves over on the bank of the stream? <She points to the northeast, where you see a young-looking Centaur staring at the water.> Chimei lost both of their parents in the Nokhud attack. I have healed all of their physical wounds, but they have not eaten or said a word to anyone since we found them. They just sit and stare. This is beyond my skills, and I am at a loss. Will you try to talk to them, <name>?", ["objectivesText"] = "Try to comfort the centaur orphan Chimei . Progress: Any luck?", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 198537 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 192621, ["x"] = 0.586, ["y"] = 0.361333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 192621, ["x"] = 0.586, ["y"] = 0.361333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.361333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
