[69862] = { ["id"] = 69862, ["name"] = "Save a Slyvern", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 69862 }, ["description"] = "Now that she's healed, I think Sylvie wants to show us something. Our work isn't done yet, <name>! Let's see what's upsetting her.", ["objectivesText"] = "Find out what Sylvie is upset about. Progress: A cave? Wait, I can hear something inside!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 197983, 198336, 198797, 200526 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192830, ["x"] = 0.646, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192830, ["x"] = 0.646, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
