[69869] = { ["id"] = 69869, ["name"] = "A Cataloger's Paradise", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 69869 }, ["series"] = { 65486, 69855, 69870, 72525 }, ["description"] = "< Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp for training. He eagerly tries to explain.> Kind elf. Proud tiny-man. Many cameras. Yes? < Doc Nanners nods excitedly, awaiting your response.>", ["objectivesText"] = "Speak with Cataloger Coralie in the Dragonscale Basecamp.", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196643, ["x"] = 0.455333, ["y"] = 0.552667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187707, ["x"] = 0.485, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455333, ["y"] = 0.552667 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[69870] = { ["id"] = 69870, ["name"] = "Pictures with Purpose", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69870 }, ["series"] = { 65486, 69855, 69869, 72525 }, ["description"] = "Pictures bring people together, $p. Our catalogers are typically sent out in pairs for safety, and it has been lovely to see members of different factions and backgrounds working together in pursuit of knowledge on these incredible isles. One such eager duo is currently charting one of the central rivers of the Waking Shores . If you wish to aid our efforts, join them in cataloging the wildlife there.", ["objectivesText"] = "Meet Akunda the Cataloger and Gunner Fren near the Overflowing Rapids.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187707, ["x"] = 0.485, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185651, ["x"] = 0.498, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69872] = { ["id"] = 69872, ["name"] = "Vakril, the Strongest Tuskarr", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["storyline"] = { 69872 }, ["objectivesText"] = "Vakril defeated", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 197001, 200164, 201728 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Vakril defeated", ["amount"] = 1, ["type"] = 0, ["objectID"] = 193223, ["orderIndex"] = 0 } }, ["db2VignetteID"] = 5194, ["db2VignetteName"] = "Vakril, the Strongest Tuskarr" },
[69882] = { ["id"] = 69882, ["name"] = "Lord Epochbrgl", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 69882 }, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["db2VignetteID"] = 5203, ["db2VignetteName"] = "Lord Epochbrgl" },
[69888] = { ["id"] = 69888, ["name"] = "Unusual Suspects", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69888 }, ["description"] = "<name>, you're here. Good. Don't react, but our findings on the titan discs have just been stolen! Other than us, only the Sundered Flame know what we were up to in that facility. I need ye to take this device and scan some of the suspicious members that have joined us recently. Reveal the spy and recover the data if you can. We cannae allow it to fall into their hands!", ["objectivesText"] = "Scan Suspicious Explorers to reveal the spy. Progress: Be quick and be casual. Got it?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 197805, 201782 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187276, ["x"] = 0.472, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187276, ["x"] = 0.472, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69895] = { ["id"] = 69895, ["name"] = "Summoned Destroyer", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["storyline"] = { 69895 }, ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2VignetteID"] = 5213, ["db2VignetteName"] = "Summoned Destroyer" },
[69897] = { ["id"] = 69897, ["name"] = "Behavior Analysis \"Homework\"", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69897 }, ["description"] = "I need to talk to someone who knows proto-whelps. Like the ones that live in the Wild Preserve! Are they as angry as the big ones? Do they bite or breathe fire at you? What if I... er... you petted a proto-whelp? Would they know that you're nice and trying to help them? I'm asking for science, of course. Tyrgon always tells us to test our hippa... no... hypo... hmph! Hyppotatotoast... ugh! THEORIES! I think they would like petting and it would make them feel good. Could you test that for me?", ["objectivesText"] = "Pet 3 Sleeping Whelps and report back to Iyali . Progress: Do you think a whelp would feel better if I petted them? I always feel better when I get hurt and mom takes care of me. < Iyali looks around, avoiding eye contact.> I know I'm not supposed to touch the animals. It's for my homework on, uh, proto-whelp behavior. And it's due, uh, soon. So...", ["rewardGold"] = 37050, ["rewardXP"] = 710, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69898] = { ["id"] = 69898, ["name"] = "Scientific Meat-thod", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69898 }, ["description"] = "So, I have, uh, more homework... Professor Tyrgon's lessons are super tough! He wants us to find out what proto-whelps, uh, eat! Yeah... I already know the answer! It's riverbeast meat! Can you bring me a piece of riverbeast meat? Some riverbeast meat would be a great \"visual aid\" for my project. But it has to be a REALLY good piece, ok? Like... the ones from Pudgy Riverbeasts. One like a momma proto-drake would give their whelp to make them strong because, uh, it will make Mister Tyrgon happy.", ["objectivesText"] = "Collect 1 piece of Extra-Delicious Riverbeast Meat . Progress: Mom says food makes everyone happy. Maybe it will be friends with me then... I mean, we'll all be friends! And Professor Tyrgon won't give me a bad grade if I make Riverbeast meat part of my project!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69899] = { ["id"] = 69899, ["name"] = "Secret Research", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69899 }, ["description"] = "I know.. I am acting weird. I'm sorry! You probably guessed I am not being truthful. I can tell you my secret... if you like. But you will have to promise not to tell the adults!", ["objectivesText"] = "Help Iyali and their friends. Progress: We found this Injured Proto-Whelp in the Wild Preserve. There was an evil Primalist attacking Proto-Dragons and... they hurt this poor little whelpling! Please don't yell at us... We just wanted to help!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69900] = { ["id"] = 69900, ["name"] = "Identifying the Source", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69900 }, ["description"] = "Judging by what the children have said, we might have a primalist prowling the Wild Preserve. This calls for immediate investigation. According to what other researchers have observed, Primalists like to steal eggs and whelps to infuse them with power and corrupt them. Those that don't acclimate to the process suffer a slow death... not that the primalists seem to care... We need them out of the Preserve. Attend to that, and I will try to distract the children. They must not know of this.", ["objectivesText"] = "Slay the experimenting primalist in the Wild Preserve. Progress: Keep your voice down! Have you done what I asked?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69901] = { ["id"] = 69901, ["name"] = "Bring In the Expert", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69901 }, ["description"] = "Did Iyali say how long this creature has been suffering? If it's too injured to eat, we need to treat it quickly. Normally a Dragonscale Expedition camp would have everything I need to help this whelp, but getting supplies to the \"frontier\" here on the Dragon Isles has proven tricky. There have been significant delays in our supply routes. But, fear not. The land itself will provide! If you bring me Sunlight Flowers , I can craft a soothing balm that will calm the drake so I can heal it.", ["objectivesText"] = "Collect 5 Sunlight Flowers . Progress: Sunlight Flowers are very useful resource. Their petals and stalks have sedative properties which will ease the whelp's suffering while we heal it.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69902] = { ["id"] = 69902, ["name"] = "Theory in Practice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69902 }, ["description"] = "<name>, I require your assistance... I hope no one was expecting me to craft, subdue the whelp, heal, and teach these children all at once! Multitasking like that is certainly overrated. Now, you can start by using those flowers. I'll need a couple minutes to prepare myself to heal the proto-whelp. Hopefully, the children will find this incident... instructional.", ["objectivesText"] = "Assist Tyrgon to heal the creature. Progress: Where on earth did they get the idea we wouldn't help them? I need to investigate this further...", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69904] = { ["id"] = 69904, ["name"] = "Suspiciously Quiet", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 69904 }, ["description"] = "Can you spare a minute, $p? I haven't heard from my two apprentices, Scrumpy and Tucky, in some time. This is concerning. I sent them to fetch us supplies for the inn. They couldn't have strayed too far... Please find them, but I warn you... They're... quite the handful.", ["objectivesText"] = "Find Noriko's apprentices in Camp Antonidas.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 200926 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189198, ["x"] = 0.476, ["y"] = 0.402 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[69910] = { ["id"] = 69910, ["name"] = "Where is Wrathion?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 69910, 69911, 69912, 69914, 69944, 70198, 72256, 72293 }, ["description"] = "How unusual. Ebyssian told us that Wrathion would be awaiting our arrival along with an ambassador for Alexstrasza the Life-Binder, Queen of the Dragons. It isn't like a dragon to break a promise. At least this eager drakonid is here to greet us. Would you kindly inquire into when the others shall arrive?", ["objectivesText"] = "Ask Sendrax when the dragons are expected to arrive. Progress: Welcome to the Dragon Isles, friend! ... I think I may have already said that. No matter! I am just excited you are here!", ["rewardGold"] = 3575, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184870, ["x"] = 0.766, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 10, ["flags"] = 0 } } },
[69911] = { ["id"] = 69911, ["name"] = "Excuse the Mess", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65436, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 66577, 66589, 66596, 67700, 69910, 69911, 69912, 69914, 69944, 70050, 70122, 70123, 70124, 70125, 70197, 70198, 72240, 72256, 72293 }, ["description"] = "I wish I knew more about how to welcome you to the Dragon Isles, but I'm only the sentry. < Sendrax motions to the tower behind her.> You could try talking with Ambassador Fastrasz in the visitor center. He might be able to answer more of your questions before the dragons arrive. Mind your step in there. He was clearing out rubble last I saw.", ["objectivesText"] = "Help Ambassador Fastrasz restore the embassy. Progress: Ambassador Fastrasz will be eager to meet you.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198398 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 22, ["flags"] = 0 } } },
[69912] = { ["id"] = 69912, ["name"] = "My First Real Emergency!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65436, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 66577, 66589, 66596, 67700, 69910, 69911, 69912, 69914, 69944, 70050, 70122, 70123, 70124, 70125, 70197, 70198, 72240, 72256, 72293 }, ["description"] = "< Sendrax looks puzzled.> I have never known the majordomo to be late to anything, much less THIS late to something THIS important. Most unusual... < Sendrax perks up at a thought.> I could use my emergency signal flare to alert them to your arrival. Then they would come rushing to greet you immediately! I've never fired my emergency signal flare before, though...", ["objectivesText"] = "Convince Sendrax to fire her emergency signal flare to alert the dragons of your arrival.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198398 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193371, ["x"] = 0.762, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 23, ["flags"] = 0 } } },
[69914] = { ["id"] = 69914, ["name"] = "The Djaradin Have Awoken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65436, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 66577, 66589, 66596, 67700, 69910, 69911, 69912, 69914, 69944, 70050, 70122, 70123, 70124, 70125, 70197, 70198, 72240, 72256, 72293 }, ["description"] = "I wish we'd time for more pleasant introductions, but we can't all be Chronormu, can we? I am Selistra, majordomo to Alexstrasza the Life-Binder, Queen of the Dragons. Queen Alexstrasza asked me to convey her kindest regards and escort you to her at the Life Pools. But I'm afraid I must ask for your assistance before we go meet her. Our ancient rivals, the djaradin, have awoken from their slumber under the earth and have already assaulted a nearby outpost!", ["objectivesText"] = "Receive your orders from Majordomo Selistra . Progress: We must do whatever the majordomo asks of us.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198398 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193372, ["x"] = 0.762, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193363, ["x"] = 0.762, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 24, ["flags"] = 0 } } },
[69915] = { ["id"] = 69915, ["name"] = "Targeted Ads", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 69915 }, ["description"] = "Hi, hi, hi! You looking for a gig? We're doing a BIG opening sale for our new Crafting Order service, and we need to draw attention! But the wind took my flyers and I think some of the local goats ran off with them. Could you get my flyers back?", ["objectivesText"] = "Recover flyers from Forkriver and Meddlesome Goats. Progress: Whoo! Setting up a business is busy, busy, busy!", ["rewardXP"] = 2765, ["rewardItems"] = { 190456, 191233, 191237, 191240, 191241, 191242, 194125, 198091, 198225, 198245, 198346, 198347, 198348, 198715 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 193108, ["x"] = 0.72, ["y"] = 0.81 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 193108, ["x"] = 0.72, ["y"] = 0.81 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "profession" },
[69919] = { ["id"] = 69919, ["name"] = "A Craft in Need", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2023, ["storyline"] = { 69919 }, ["description"] = "You seem like a skilled crafter. Would you like to fill some crafting orders for fellow adventurers and get rich, rich, rich? I'll tell you the rules of working with the Artisan's Consortium, then you can pick up Crafting Orders at any crafting station on the Dragon Isles!", ["objectivesText"] = "Speak with Azley to learn about filling Crafting Orders. Progress: Business is busy, busy, busy!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 190456, 193479, 193529, 193534, 193538, 198091, 198346, 198347, 198348, 251321, 251322, 251324, 251326, 251327 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 193108, ["x"] = 0.72, ["y"] = 0.81 }, { ["mapID"] = 2112, ["npcID"] = 194026, ["x"] = 0.3552, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 193108, ["x"] = 0.72, ["y"] = 0.81 }, { ["mapID"] = 2112, ["npcID"] = 194026, ["x"] = 0.3552, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession" },
[69923] = { ["id"] = 69923, ["name"] = "A Primal Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 66586, 69923, 69925, 69944, 69992 }, ["description"] = "Raszageth has wasted no time building up her Primalist forces. The Kirin Tor have detected massive storms being unleashed at key points across Kalimdor and the Eastern Kingdoms. The Primalists are unleashing the elements to add to their strength. It seems they plan to cause chaos not only in the Dragon Isles, but in the lands of the Alliance and Horde as well. Seek out the enemy and study their methods. We have to stop them before it's too late.", ["objectivesText"] = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms. Progress: I'm afraid this is only the beginning.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192493, 199109, 199211 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 6, ["flags"] = 0 } } },
[69925] = { ["id"] = 69925, ["name"] = "Calming the Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 66586, 69923, 69925, 69944, 69992 }, ["description"] = "These Primalists are relentless, unleashing elemental devastation across the Eastern Kingdoms and Kalimdor. You must show the same determination, <name>. It is the only way to stop them. Find their next incursion, remove the enemies within the primal storm area before it is too late and foil their efforts. We must protect Azeroth!", ["objectivesText"] = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms. Progress: Our effort continues.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192493, 199211 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 7, ["flags"] = 0 } } },
[69932] = { ["id"] = 69932, ["name"] = "Every Life Counts", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 69932 }, ["series"] = { 72399 }, ["description"] = "Making potions for Gelikyr means that I don't have time for my other duties. A duck landed in my garden with a broken rib. I've tended to the wound, but her dressing needs replacing. And since you're so eager to help... < Szareth shoves a list of ingredients into your hand.> This is what you'll need. Bring the rest to me.", ["objectivesText"] = "Collect ingredients to replace Little Jetstream's dressings. Progress: Well?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 198040, 198042, 198406 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 193538, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 193538, ["x"] = 0.502, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[69933] = { ["id"] = 69933, ["name"] = "Curiosity's Price", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 69933 }, ["description"] = "Look across the ravine, <race>. Primalists attacked Gelikyr Post days ago, and the battle still rages. Those people need salves and stitching. I can make it for them, but my ingredients are running low. Since you've chosen to intrude upon my home, consider yourself volunteered. Go to my garden and find the largest vine you can. Snap it from the root, then bring it to me.", ["objectivesText"] = "Take a cutting from the Stubborn Vine. Progress: Be quick. A fresh ingredient is a potent ingredient.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 198040, 198042, 198406 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 193538, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 193538, ["x"] = 0.502, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[69934] = { ["id"] = 69934, ["name"] = "Bleeding Hearts", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 69934 }, ["description"] = "The potions are ready--now to deliver them. Take one crate to a small cave in the ravine below us. No one will be there to accept it, but you can trust it will be used well. Take another crate to the infirmary in Gelikyr Post. An old friend tends to the patients there. I... realize this is not your duty. Nor is it really mine. But you've been surprisingly helpful, and this medicine could save lives.", ["objectivesText"] = "Deliver the Medical Supplies. Progress: Excuse me, I don't have time to chat.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 198040, 198042, 198406, 198485 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 193538, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 193042, ["x"] = 0.516, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[69936] = { ["id"] = 69936, ["name"] = "Zambul, Head Vandal", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 69936 }, ["description"] = "Good work. Those desecrators cannot force any more of my ancestors to fight for them. But the brute yelling out their orders must be handled. That is their overseer, Zambul. He must be stopped. Take him down.", ["objectivesText"] = "Defeat Overseer Zambul . Progress: Did you give Zambul the end he deserves?", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 191901, 192496, 193257, 194447, 198073, 198074, 198075, 200100, 200115 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189858, ["x"] = 0.338, ["y"] = 0.654 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189858, ["x"] = 0.338, ["y"] = 0.654 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.654 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[69938] = { ["id"] = 69938, ["name"] = "Fishing Frenzy!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69938 }, ["objectivesText"] = "Fresh Fish Steaks", ["rewardXP"] = 1415, ["rewardItems"] = { 194510, 194701, 198070, 198350, 200076, 200077 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Fresh Fish Steaks", ["amount"] = 8, ["type"] = 1, ["objectID"] = 198350, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[69942] = { ["id"] = 69942, ["name"] = "Brackenhide Mysteries", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 69942 }, ["objectivesText"] = "Astral Essence", ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Astral Essence", ["amount"] = 5, ["type"] = 2, ["objectID"] = 379030, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[69944] = { ["id"] = 69944, ["name"] = "Chasing Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 66586, 69923, 69925, 69944, 69992 }, ["series"] = { 65444, 70198 }, ["description"] = "Well, that wizard certainly knows how to make an entrance, doesn't he? We won't be able to set sail until someone gets those elemental storms under control. Check-in with Storm Huntress Suhrakka . She's leading the expedition efforts to investigate the storms and can help outfit you with whatever gear you need. While you handle that, I'll coordinate the rest of the preparations. At least it'll give me some time to read a few more volumes on dragon history before we set sail.", ["objectivesText"] = "Speak with Storm Huntress Suhrakka at the zeppelin tower.", ["rewardGold"] = 715, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 197279, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 195899, ["x"] = 0.558, ["y"] = 0.124 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 8, ["flags"] = 0 } } },
[69946] = { ["id"] = 69946, ["name"] = "The Master of Their Craft", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2022, ["storyline"] = { 67100, 67137, 67295, 67564, 69946, 69979 }, ["description"] = "While I was traveling through these plains, I met an old centaur in a cave up north. They had clearly mastered their craft and had wisdom to spare. They helped me understand the knowledge I had gained from the Dragon Isles. If you're curious about specializing in your profession, seek out the wisdom of this master. Khadin was their name, of Clan Teerai.", ["objectivesText"] = "Seek out Master Khadin to learn their professional wisdom. Progress: Patience, young one. Rest in knowing that there is much to learn, and that is acceptable.", ["rewardGold"] = 210675, ["rewardXP"] = 2075, ["rewardItems"] = { 190456, 191784, 194714, 194729, 197860 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192574, ["x"] = 0.602, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 193110, ["x"] = 0.518, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["campaigns"] = { { ["id"] = 191, ["title"] = "Professions Onboarding Skip", ["questLineID"] = 1364, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1364, ["name"] = "Catching Up!", ["orderIndex"] = 4, ["flags"] = 0 } } },
[69962] = { ["id"] = 69962, ["name"] = "Corrupted Proto-Dragon", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["storyline"] = { 69962 }, ["rewardXP"] = 5465, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2VignetteID"] = 5235, ["db2VignetteName"] = "Corrupted Proto-Dragon" },
[69964] = { ["id"] = 69964, ["name"] = "Craggravated Elemental", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 69964 }, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["db2VignetteID"] = 5237, ["db2VignetteName"] = "Craggravated Elemental" },
[69965] = { ["id"] = 69965, ["name"] = "Quality Assurance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69965 }, ["description"] = "Are you looking for work, <class>? I represent a new trade company, the Artisan's Consortium, which matches artisans and clients through our crafting orders network. The Dragonscale Expedition placed an order for some enchanted mining tools. The tools are crafted, but we would like to test them before completing the order. We will pay you for your services, of course.", ["objectivesText"] = "Test Haephesta 's Tools on nearby geodes for the Artisan's Consortium. Progress: Do the tools work as intended?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192438, ["x"] = 0.764, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192438, ["x"] = 0.764, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "profession" },
