[70040] = { ["id"] = 70040, ["name"] = "Tumbling Through Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "When the magic of Bronze and Infinite collided, it sent Chronormu and Eternus into an uncontrolled tumble through time. As they fall, they rip the fabric of time itself, sending out countless ripples across time and space. We must locate them and bring them back. Only then will we be able to stop any further damage. I see that you will be the one to stop Chronormu's fall. I would ask that you to gather the allies you will need to save Chronormu, while I focus on her magic.", ["objectivesText"] = "Gather your allies and then speak with Nozdormu . Progress: Quickly. Even we do not have time to waste.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 192454, 192749, 194521 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 29, ["flags"] = 0 } } },
[70041] = { ["id"] = 70041, ["name"] = "The Storm-Eater's Fury", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "Raszageth is attempting to rip all the arcane magic out of the tower so she can destroy it! Kalecgos is doing what he can to hold her back, and I am using my magic to try to replenish the ley energy. I fear we will not last much longer. As we speak, more Primalists make their way up here to overwhelm us! Take my modified Arcane Disc . Hold off the incoming Primalists... and let us hope for a miracle.", ["objectivesText"] = "Ride Khadgar's flying disc and hold off the Primalist army.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190454, 192478, 192479, 194705, 197921 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193837, ["x"] = 0.78, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187034, ["x"] = 0.782, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.78, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 48, ["flags"] = 0 } } },
[70042] = { ["id"] = 70042, ["name"] = "Opportunities Abound", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70042 }, ["description"] = "Ya scared me, thought I was nabbed! Look at all the brave explorers ready to conquer the Dragon Isles... packs bulging with tools and equipment. We could get rich here! Check around see if you can grab a few items, and I'll cut you in on the profits.", ["objectivesText"] = "Acquire several items for Vish the Sneak . Progress: You find what we was looking for?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198133, 198134, 198135, 198139 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193838, ["x"] = 0.764, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193838, ["x"] = 0.764, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70048] = { ["id"] = 70048, ["name"] = "A Primal Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 66458, 70048, 70049, 70050, 70055 }, ["description"] = "Raszageth has wasted no time building up her Primalist forces. The Kirin Tor have detected massive storms being unleashed at key points across Kalimdor and the Eastern Kingdoms. The Primalists are unleashing the elements to add to their strength. It seems they plan to cause chaos not only in the Dragon Isles, but in the lands of the Alliance and Horde as well. Seek out the enemy and study their methods. We have to stop them before it's too late.", ["objectivesText"] = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms. Progress: I'm afraid this is only the beginning.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192493, 198352, 199109, 199211 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 1, ["flags"] = 0 } } },
[70049] = { ["id"] = 70049, ["name"] = "Calming the Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 66458, 70048, 70049, 70050, 70055 }, ["description"] = "These Primalists are relentless, unleashing elemental devastation across the Eastern Kingdoms and Kalimdor. You must show the same determination, <name>. It is the only way to stop them. Find their next incursion, remove the enemies within the primal storm area before it is too late and foil their efforts. We must protect Azeroth!", ["objectivesText"] = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms. Progress: Our effort continues.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192493, 198352, 199211 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 2, ["flags"] = 0 } } },
[70050] = { ["id"] = 70050, ["name"] = "Chasing Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 66458, 70048, 70049, 70050, 70055 }, ["series"] = { 67700, 70197 }, ["description"] = "So the handsome fellas are sendin' ye on a wee adventure, eh? That's fine. The expedition won't be able to set sail until someone gets those elemental storms under control anyway. Check-in with Storm Hunter William . He's leading the expedition efforts to investigate the storms and can outfit ye with whatever gear you need. I'll coordinate the rest of the preparations here while ye have all the fun out there. Ye'll owe me one, though!", ["objectivesText"] = "Speak with Storm Hunter William in Stormwind Harbor.", ["rewardGold"] = 715, ["rewardXP"] = 175, ["rewardItems"] = { 192493, 199109, 199211, 199337, 199686, 199836, 199837, 199838, 199839, 202188 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 189077, ["x"] = 0.228, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 195912, ["x"] = 0.25, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 10, ["flags"] = 0 } } },
[70058] = { ["id"] = 70058, ["name"] = "Friend on the Mend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70058 }, ["description"] = "Happy Duck got hurt while we were flying around... He was doing so good and then I... I hit a tree! < Lillistrasza gestures mournfully at the damaged duck plushie on her head.> His stuffing is falling out! His feathers are all bent! One of his eyes is gone! Noooo! You can help fix Happy Duck, right?", ["objectivesText"] = "Collect 5 Soft Ruby Feathers , 3 Scraps of Fabric , and 1 Glass Bead from around the Ruby Lifeshrine to help repair Happy Duck. Progress: Yes? Anything to help!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198343, 198344, 198345, 198857 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193955, ["x"] = 0.606, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192674, ["x"] = 0.61, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70061] = { ["id"] = 70061, ["name"] = "Training Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "The dragons were gone from the Isles for quite some time, $p. To tell the truth... some of our skills have atrophied as they were passed down from generation to generation. These whelps should be easy to teach, yet we are having some trouble wrangling them. Say. I have seen that even Majordomo Selistra trusts you with the most crucial tasks. Would you lend us your aid and help one of our young?", ["objectivesText"] = "Guide a whelp to eliminate 12 Agitated Weedlings , 6 Intrusive Pupstingers , and 1 Relentless Gust . Progress: Some whelps need more encouragement than the rest. Of course, we love them all.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194174, ["x"] = 0.622, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191768, ["x"] = 0.586, ["y"] = 0.519 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 23, ["flags"] = 0 } } },
[70062] = { ["id"] = 70062, ["name"] = "Some Call Me Bug Catcher", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70062 }, ["description"] = "Ah, young <race>, I could use your help. I have raised generations of life here. None more my favorite than the ducklings. But my body has grown old and weak... still that does not stop the cycle. I need you to catch food for my brood.", ["objectivesText"] = "Collect 6 Flyspawn Beetle Parts . Progress: There is a beginning and end to all creatures. It does not matter how long or how short.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 193484, 198460, 198847, 198848, 198856 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186503, ["x"] = 0.298, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186503, ["x"] = 0.298, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70064] = { ["id"] = 70064, ["name"] = "For Imbu!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite", "rare" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70064 }, ["objectivesText"] = "Imbu liberated", ["rewardGold"] = 105000, ["rewardXP"] = 5145, ["rewardItems"] = { 199646 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Imbu liberated", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["db2QuestInfoID"] = 136, ["db2QuestInfoName"] = "Rare Elite World Quest" },
[70068] = { ["id"] = 70068, ["name"] = "Cobalt Catastrophe", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite", "rare" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70068 }, ["objectivesText"] = "Sundered Flame disrupted", ["rewardXP"] = 5145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Sundered Flame disrupted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["db2QuestInfoID"] = 136, ["db2QuestInfoName"] = "Rare Elite World Quest" },
[70069] = { ["id"] = 70069, ["name"] = "Others Call Me Duck Herder", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70069 }, ["description"] = "My days grow shorter... Still my duties are not done. The brood should all be by the creek. I leave them there hoping they will grow more independent. Soon they will have to fend for themselves. Today they will rely on you. Please bring them the food you caught, and then the ducklings to me. Be wary of Pilot , she is always jumping off something.", ["objectivesText"] = "Feed 4 ducklings and return to Gracus . Progress: Be careful of Firequackers . He will bite your finger. A surprisingly strong bite for such a young duck.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193484, 198460, 198847, 198848, 198856 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186503, ["x"] = 0.298, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186503, ["x"] = 0.298, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70070] = { ["id"] = 70070, ["name"] = "But... I Am the Hero of Ducks", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70070 }, ["description"] = "Hold on... there is something... < Gracus looks around.> Firequackers! The boy must have gone down the river again! No matter how often I tell him, he always tries to play with the hornswogs! I need you to go check on him. I hope he didn't get swallowed again.", ["objectivesText"] = "Find Firequackers and make sure he gets to Gracus .", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193484, 198460, 198847, 198848, 198856 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186503, ["x"] = 0.298, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186503, ["x"] = 0.298, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70071] = { ["id"] = 70071, ["name"] = "Gathering the Magic", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 2024, ["storyline"] = { 70071 }, ["objectivesText"] = "Energy tapped into Magic Gathered Low Med High", ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Energy tapped into", ["amount"] = 1, ["type"] = 3, ["objectID"] = 196223, ["orderIndex"] = 0 }, { ["text"] = "Magic Gathered", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 1 }, { ["text"] = "Low", ["amount"] = 20, ["type"] = 0, ["objectID"] = 196192, ["orderIndex"] = 2 }, { ["text"] = "Med", ["amount"] = 10, ["type"] = 0, ["objectID"] = 196204, ["orderIndex"] = 3 }, { ["text"] = "High", ["amount"] = 5, ["type"] = 0, ["objectID"] = 196207, ["orderIndex"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[70122] = { ["id"] = 70122, ["name"] = "Explorers in Peril", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 69911, 69912, 69914, 70050, 70122, 70123, 70124, 70125, 70197, 72240, 72293 }, ["description"] = "Don't mistake the expedition's scholarly pursuits as timidness, $p. We are not recluses studying books in far-off towers. We are adventurers, hunting down knowledge first-hand in every corner of Azeroth! That same passion for adventure often leads us into the path of perils and hazards, and a few expedition members have bitten off a little more than they could chew... But, hey, the danger makes it more fun!", ["objectivesText"] = "Rescue 3 Dragonscale Expedition members in the Wild Coast. Progress: Are the expedition members safe?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 188213, 198398, 202081 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189022, ["x"] = 0.82, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187251, ["x"] = 0.793, ["y"] = 0.327 }, { ["mapID"] = 2022, ["npcID"] = 189022, ["x"] = 0.82, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.82, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 18, ["flags"] = 0 } } },
[70123] = { ["id"] = 70123, ["name"] = "Primal Pests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 69911, 69912, 69914, 70050, 70122, 70123, 70124, 70125, 70197, 72240, 72293 }, ["description"] = "<Azurathel glances suspiciously at the proto-dragons lurking on the ridge behind him.> I'd swear that those proto-dragons edge closer to camp every time I turn my back... Those are not the dragons Wrathion invited us here to meet. Proto-dragons are ruthless predators who cannot be reasoned with. We must be ruthless in return. Cull their numbers to keep their ambitions in check, or this expedition will be over before it begins.", ["objectivesText"] = "Kill 8 Primal Proto-drakes on the Wild Coast.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198398, 202081 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189035, ["x"] = 0.82, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187252, ["x"] = 0.793, ["y"] = 0.331 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.82, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 19, ["flags"] = 0 } } },
[70124] = { ["id"] = 70124, ["name"] = "Practice Materials", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 69911, 69912, 69914, 70050, 70122, 70123, 70124, 70125, 70197, 72240, 72293 }, ["description"] = "The proto-drakes here are unlike any I've seen before. Their scales appear to be naturally flame-resistant, stronger than steel, and don't lose flexibility in the process. Incredible. The artisans are clamoring to get their hands on some to work with. Start with the whelps. The smaller scales should be more pliable until we've mastered our techniques with 'em.", ["objectivesText"] = "Collect 12 Primal Proto-Whelp Scales . Progress: You got those scales yet?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198398, 202081 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189021, ["x"] = 0.82, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189058, ["x"] = 0.792, ["y"] = 0.331 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.82, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 20, ["flags"] = 0 } } },
[70125] = { ["id"] = 70125, ["name"] = "Where is Wrathion?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 69911, 69912, 69914, 70050, 70122, 70123, 70124, 70125, 70197, 72240, 72293 }, ["description"] = "Hm, wonder where Wrathion is? He said he'd be here waitin' for us with an ambassador for Alexstrasza the Life-Binder, Queen of the Dragons. It does nae seem like a dragon to break a promise. Well! At least this eager wee drakonid is here to welcome us. Can you talk to 'em and find out when the others are gonna arrive?", ["objectivesText"] = "Ask Sendrax when the dragons are expected to arrive. Progress: Welcome to the Dragon Isles, friend! ... I think I may have already said that. No matter! I am just excited you are here!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198398 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187251, ["x"] = 0.793, ["y"] = 0.327 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.793, ["y"] = 0.327 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 21, ["flags"] = 0 } } },
[70129] = { ["id"] = 70129, ["name"] = "Toejam the Terrible", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70129 }, ["description"] = "You're right, I'm not strong enough to take on this yeti... not alone! But you're here! The lair of the evil yeti, Toejam the Terrible , is just ahead. This cave is... big. Not scary! Maybe a little scary. Could you go in there and soften him up a bit? I'll... I'll be right behind you!", ["objectivesText"] = "Help Rowie slay Toejam the Terrible .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186542, ["x"] = 0.155333, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189533, ["x"] = 0.137, ["y"] = 0.483 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.155333, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70134] = { ["id"] = 70134, ["name"] = "Memories", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70134 }, ["description"] = "Thank you for listening to me, young one. I have a favor to ask. Don't worry. No more stories. When we left this place, I left a... time capsule of sorts. Would you... would you be able to retrieve it for me? We left it at the bottom of the Ruby Life Shrine, hidden behind one of the pillars. I hid it with a sigil. If you activate it, you should see my time capsule .", ["objectivesText"] = "Retrieve Veritistrasz 's time capsule . Progress: I find myself oddly... excited? Apparently I am looking forward to looking through the time capsule , how... Unexpected.", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 197361, 198430, 198661, 198979 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194076, ["x"] = 0.578, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194076, ["x"] = 0.578, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70135] = { ["id"] = 70135, ["name"] = "Encroaching Elementals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66036, 67053, 70135, 70373, 71026, 71143 }, ["description"] = "The crafters, artisans, and explorers of the Dragonscale Expedition are ill-suited to the vigors of battle. But not you and I, $p. Here in the Dragon Isles, let us use that strength to protect those who can't protect themselves. Clear out the elementals encroaching from the north, so that the expedition can focus on their noble pursuits.", ["objectivesText"] = "Kill 15 primal elementals in Wingrest Embassy. Progress: These elementals are unlike any I've seen before...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184452, ["x"] = 0.762, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 184452, ["x"] = 0.762, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 9, ["flags"] = 0 } } },
[70136] = { ["id"] = 70136, ["name"] = "Haven't Got Time For the Pain", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "Ugh... One moment... My first assignment... Unstable temporal energy seeping into the forest... Affecting the wildlife... Need to assess the impact and collect that magic for the Timewalkers... <Zera shakes her head a moment.> I was examining a pack of vorquin when I was attacked by a crazed bear overflowing with time magic. It caught me off guard. I barely escaped. Could you find my missing gear for me, <class>? Uh, you might also have to deal with that bear.", ["objectivesText"] = "Retrieve the Timewalker Staff , Timewalker Notes , and slay the Crazed Alpha in the Flowing Forest of Thaldraszus . Progress: Were you able to find the them?", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 192602, 192809, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187098, ["x"] = 0.562, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187098, ["x"] = 0.562, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 16, ["flags"] = 0 } } },
[70139] = { ["id"] = 70139, ["name"] = "Where There's a Ward, There's a Way", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70139 }, ["description"] = "This reservoir used to be protected by three warding stones placed by Tyr. They were meant to stabilize the elemental magic that is prevalent in the Dragon Isles. When you woke me, I sensed damage done to the west ward. I fear the Primalists may have done this to all of them. Still, we must assess the damage done in order to figure out what we should do next.", ["objectivesText"] = "Assess the damage done to the ward stones in Tyrhold Reservoir. Progress: We must find out the extent of the damage done to the warding stones. I can already feel the elemental energy growing out of control.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 193043 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189045, ["x"] = 0.496, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189045, ["x"] = 0.496, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70148] = { ["id"] = 70148, ["name"] = "Without Purpose", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70148 }, ["description"] = "Could I have a moment of your time? I'm worried about another dracthyr that passed through here. He asked my associates and me all kinds of questions, but seemed... disappointed with our answers. He called himself \" Talon Ethrethi \". I believe that makes him quite junior amongst your ranks? I got the sense that he could use a hand. Mind helping me keep the peace? I saw him talking with Kholmar over there.", ["objectivesText"] = "Search for Talon Ethrethi in Wingrest Embassy. Progress: Any news on this Ethrethi fellow?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192438, ["x"] = 0.764, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192438, ["x"] = 0.764, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70154] = { ["id"] = 70154, ["name"] = "A Gateway to Somewhere", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["description"] = "The enchantment will protect us from the unstable energy contained within. I will open the way to the nearest stone. Once you pass through, stay close. I shall need your assistance when we arrive to power up the device.", ["objectivesText"] = "Follow Warpcaster Delandra to the Waygate's location.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198538 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4968, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 4, ["flags"] = 0 } } },
[70156] = { ["id"] = 70156, ["name"] = "An Ancient Awakening", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["description"] = "The waygate sits just behind me. There is no way to tell how long we have until the waning enchantment on this vessel fades, or even worse, breaks. That amount of unstable energy being released could be catastrophic. Shall we continue?", ["objectivesText"] = "Empower the Waygate.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 198538, 198858 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4968, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2022, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 5, ["flags"] = 0 } } },
[70164] = { ["id"] = 70164, ["name"] = "A Tinker's Chance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 13 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70164 }, ["description"] = "If you have a moment, $p, I am close to a breakthrough! After the creche collapsed, I lost more than my ability to fight. I lost my identity as a dracthyr. Perhaps you can understand. I have always enjoyed putting things together and taking them apart, so Expedition seemed like a good fit for me. But this artifact is giving me some trouble. Would you ask Phosildral and Sibrit to review my notes? I want to prove I am a capable tinker... to them and to myself.", ["objectivesText"] = "Speak with Chronomancer Phosildral and Sibrit Clacketpage in the Life Vault Ruins. Progress: I almost have the orb where I want it, but I need just a little more time.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194136, ["x"] = 0.654, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 197543, ["x"] = 0.654, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70166] = { ["id"] = 70166, ["name"] = "The Joy of Painting", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70166 }, ["description"] = "Do you like my collection? These are all the work of the greatest painter that ever lived, Hudson . They're rare and probably valuable--he's a recluse and hasn't painted anything in awhile. Oh, but I'd love to meet him... Or to learn from him! You... seem like the bold type. Would you find him for me? H-here! Take some of my work with you. Maybe he'll be impressed! Or maybe he'll think I'm terrible... oh dear.", ["objectivesText"] = "Deliver Rauvros ' Painting of Introduction to Hudson . Provided item:", ["rewardGold"] = 74100, ["rewardXP"] = 4115, ["rewardItems"] = { 198476 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194415, ["x"] = 0.117, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194323, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.117, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70168] = { ["id"] = 70168, ["name"] = "Sad Little Accidents", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70168 }, ["description"] = "You came all this way... I'm sorry. My dear Hudson used to love painting. It was his life! I don't know what's caused this block. A few weeks ago on his way back from a painting trip, he took all his unfinished paintings and threw each away in a fit of rage. Please, traveler, if you don't mind... could you find them? They may just give him back the spark he needs. Hudson does not shy away from dangerous places to find the best vistas. I hope you are prepared.", ["objectivesText"] = "Recover Hudson 's Lost Paintings from the final bosses of the Ruby Life Pools, Nokhud Offensive, and Brackenhide Hollow dungeons. Progress: Go away.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 198474, 198480, 198482, 198484 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194425, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194323, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.083333, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "dungeon" },
[70169] = { ["id"] = 70169, ["name"] = "Even Trees Need Friends", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70169 }, ["description"] = "I know you and Ran are simply trying to be helpful. I don't think there's any helping me. My spark--my will to paint--is simply... gone. But Ran is right. I owe you at least to try. Bring this budding artist friend of yours to me.", ["objectivesText"] = "Speak with Rauvros . Progress: All I need is a chance to prove myself.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194323, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194415, ["x"] = 0.117, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.083333, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70170] = { ["id"] = 70170, ["name"] = "Beat the Demons Out of It", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70170 }, ["description"] = "He can be very stubborn, I'm afraid. But I can't just give up on him. We'll just have to try again! There are more paintings still out there he threw out. These were in even more dangerous locations, so I hope you are up for the challenge!", ["objectivesText"] = "Recover Hudson 's Lost Paintings from the final bosses of the Halls of Infusion, Algeth'ar Academy, Azure Vault, and Neltharus dungeons. Progress: What now?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 198474, 198512, 198513, 198514, 198515 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194425, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194323, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.083333, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "dungeon" },
[70171] = { ["id"] = 70171, ["name"] = "Happy Little Accidents", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70171 }, ["description"] = "< Ranpiata 's eyes look damp.> Is it me? Am I the reason he has lost his spark? He says he loves me, but... you heard how not painting makes him feel. I want what is best for him. If he is better off... I will go. There is one last piece he threw away. The last thing he tried to draw before giving up. I could not bear to see it go. I hid it away in our home. Please... bring it to him... as a memento.", ["objectivesText"] = "Find Hudson 's last piece. Progress: What a strange tuskarr. How does one get so stuck in their own head? Is this just what being an artist is like? Will that happen to me too? Oh dear.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 198474, 198516 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194425, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194415, ["x"] = 0.117, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.083333, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70172] = { ["id"] = 70172, ["name"] = "Mountain Mysteries", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70172 }, ["objectivesText"] = "Astral Essence", ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Astral Essence", ["amount"] = 6, ["type"] = 2, ["objectID"] = 380769, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[70174] = { ["id"] = 70174, ["name"] = "The Shikaar", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65779, 65780, 65783 }, ["description"] = "Sansok Khan is the most skilled hunter in our clan. Though she cannot hear, she proved her capabilities time and time again as both a hunter and a leader. She is a mentor to us all, a trusted leader, and a fierce defender of the Maruuk. It is an honor for you to speak with her.", ["objectivesText"] = "Meet Sansok Khan . Progress: < Sansok Khan regards you steadily.>", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 21100, 21746, 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 181217, ["x"] = 0.778, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.254333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 3, ["flags"] = 0 } } },
[70176] = { ["id"] = 70176, ["name"] = "Web Victims", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 2023, ["storyline"] = { 70176 }, ["objectivesText"] = "Victims Freed", ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Victims Freed", ["amount"] = 6, ["type"] = 0, ["objectID"] = 194620, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[70179] = { ["id"] = 70179, ["name"] = "A Two for One Deal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70179 }, ["description"] = "Greetings, adventurer! Say, you look like a capable person. Could you give me a hand? Azkra and I are charged with watching over this tower, which is in what I like to call \"an exciting state of pre-renovation.\" My problem is as we started repairs, the local earth elementals attacked us! So I thought \"Zefren, why not take care of the earth elementals and get some building materials at the same time?\" Which is where you come in! Could you help?", ["objectivesText"] = "Obtain Building Materials from the local Earth Elementals. Progress: I have to say, I'm quite looking forward to being able to work on this tower once again, I might even put in a little plaque commemorating your help! You are still planning to help, right?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198511 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194525, ["x"] = 0.544, ["y"] = 0.308 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194525, ["x"] = 0.544, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70180] = { ["id"] = 70180, ["name"] = "Jump-Start? Jump-Starting!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70845 }, ["description"] = "Some folks in the city claim this here device was created by the legendary Titan Watcher Tyr. Problem is we can't get it to work! We tried all the usual tricks, dissemblin', gyroscopin', a little mild electrocution. None of it sides the electrocution worked. Actually... I just had a great idea. See that gyrocopter over there? Hop in and let's see if we can give this titan thing a little more... juice.", ["objectivesText"] = "Help Greyzik power-up the mysterious device.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120, 208396 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196066, ["x"] = 0.845333, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.845333, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1368, ["name"] = "Spark of Ingenuity", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 0, ["flags"] = 0 } } },
[70181] = { ["id"] = 70181, ["name"] = "First Challenge of Tyr: Finesse", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["description"] = "<As you approach, the inscription on the statue emits a faint glow.> \"Wield the Keeper's power and carry its light to a better future for us all.\"", ["objectivesText"] = "Complete the first Challenge of Tyr in the Azure Span.", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 195827, ["x"] = 0.672, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1368, ["name"] = "Spark of Ingenuity", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 1, ["flags"] = 0 } } },
[70182] = { ["id"] = 70182, ["name"] = "The Sweet Taste of Victory", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70339, 70633 }, ["description"] = "There is great potential in small things. The Bottled Essence may feel light as a feather, but it holds immense power. Take it to the Engine of Innovation.", ["objectivesText"] = "Return to the Engine of Innovation in Valdrakken.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 195827, ["x"] = 0.672, ["y"] = 0.308 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1368, ["name"] = "Spark of Ingenuity", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 2, ["flags"] = 0 } } },
[70185] = { ["id"] = 70185, ["name"] = "Mysterious Beast", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["description"] = "<You find a large pawprint sunk into the dirt. Looking around, none of the nearby creatures have paws, let alone of that size. Perhaps the centaur will be impressed if you hunt this great beast.>", ["objectivesText"] = "Find and slay the beast, then bring back proof to Scout Tomul . Progress: Do you return from your hunt?", ["rewardGold"] = 148200, ["rewardXP"] = 3455, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 197674, 197675, 198517 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.254333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 8, ["flags"] = 0 } } },
[70195] = { ["id"] = 70195, ["name"] = "Taken By Storm", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "According to reports, the Nokhud were accompanied by an outsider wielding never-before-seen magic. This outsider tore through our ranks like a tempest. If the Nokhud have allies who can wreak this much havoc, we must find out as much as we can about them. I have sent my ohuna, Altan, to find this outsider. She has not flown back, and I am concerned. <name>, can you search for clues about this outsider and see what has become of Altan?", ["objectivesText"] = "Rescue Altan and search for clues about the outsider. Progress: I have my suspicions about the identity of these new Nokhud allies, but I must be sure.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 193051, 197642, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195316, ["x"] = 0.494, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190648, ["x"] = 0.494, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 31, ["flags"] = 0 } } },
[70196] = { ["id"] = 70196, ["name"] = "Pruning the Preserve", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70196 }, ["objectivesText"] = "Kill Proto-dragons", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Kill Proto-dragons", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[70197] = { ["id"] = 70197, ["name"] = "The Call of the Isles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 69911, 69912, 69914, 70050, 70122, 70123, 70124, 70125, 70197, 72240, 72293 }, ["series"] = { 67700, 70050 }, ["description"] = "Are ye ready for the adventure of a lifetime? I know I sure am! Our allies have gathered and supplies are loaded. So what're you waiting for? Meet me at the Stormwind docks. It's time to set sail for the Dragon Isles !", ["objectivesText"] = "Meet Toddy Whiskers at the Stormwind Harbor.", ["rewardGold"] = 7410, ["rewardXP"] = 175, ["rewardItems"] = { 198398, 200073, 201921, 201922, 201923, 201924 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 189077, ["x"] = 0.228, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 26, ["flags"] = 1 } } },
[70198] = { ["id"] = 70198, ["name"] = "The Call of the Isles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 69910, 69911, 69912, 69914, 69944, 70198, 72256, 72293 }, ["series"] = { 65444, 69944 }, ["description"] = "Our allies gather in Durotar. This is a very exciting time! Join us, <name>! It's time to set sail for the Dragon Isles !", ["objectivesText"] = "Meet Naleidea Rivergleam in Durotar.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 197279, ["x"] = 0.558, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 25, ["flags"] = 1 } } },
[70215] = { ["id"] = 70215, ["name"] = "Curiosity is Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["series"] = { 66582, 66595, 66597, 66598 }, ["description"] = "My hesitation to discuss these symbols was not for a lack of trust in you, but rather the unknown nature of these symbols and the stones upon which they reside. Yes, stones. Multiple, in fact. Scattered across the Isles. < Warpcaster Delandra glances at you. A hint of curiosity and excitement glows in her eyes.> You did not know. Very well. Your persistence and willingness to seek me out shows that you are keen to understand your recent discovery. Perhaps it is time we discuss this at length.", ["objectivesText"] = "Speak with Warpcaster Delandra at Camp Antonidas.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 181618, 198538 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4968, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 6, ["flags"] = 0 } } },
[70220] = { ["id"] = 70220, ["name"] = "Shady Sanctuary", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "We must inform the rest of the green dragonflight that the barrier to the Ancient Bough is under threat. Gerithus and I have much to discuss. <name>, I will place my mark upon you. The other dragons who see it will know that you are my trusted messenger. Go and rally my flight. They must know and prepare for the battle ahead.", ["objectivesText"] = "Speak to Guard-Captain Alowen , Sariosa , Sidra the Mender , and Viranikus . Progress: Go with my blessing.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188106, ["x"] = 0.282, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188106, ["x"] = 0.282, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 44, ["flags"] = 0 } } },
[70229] = { ["id"] = 70229, ["name"] = "Boku the Mystic", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "The mystics were called away to Ridgewater Retreat a few days ago, but one mystic remains. His name is Boku. He can be found on top of the hill at the Ohn'ahran shrine. He's just an initiate, but he should be able to commune with Ohn'ahra and acquire her blessing. With Ohn'ahra on our side, we might be able to win this war before it starts.", ["objectivesText"] = "Find Boku in Teerakai.", ["rewardGold"] = 7410, ["rewardXP"] = 345, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187787, ["x"] = 0.418, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186290, ["x"] = 0.368, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 28, ["flags"] = 0 } } },
[70239] = { ["id"] = 70239, ["name"] = "Untold Regrets", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70239 }, ["description"] = "Duroz is old, sick, and stubborn as a kodo. There was no stopping him getting on the airship to come here. Best I could do was come be his walking stick. I've seen him in pain enough times on the battlefield to know when he's hiding it. He's been getting worse every day out here. Can you help me get him to the potion makers? Ale's not doing the trick anymore. If you can carry our weapons, I can help him walk.", ["objectivesText"] = "Walk with Duroz and Kolgar to find help. Progress: I wish there was more I could do.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 200109 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194801, ["x"] = 0.578, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194805, ["x"] = 0.57, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70240] = { ["id"] = 70240, ["name"] = "Pain Management", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70240 }, ["description"] = "It is a good thing you brought him here when you did. I can tell he is in a great deal of pain, though he bears it well. So must we all when it comes time. I am afraid that it is age that ails him and not illness, but I may be able to relieve some portion of his suffering. Would you mind gathering some snapflowers, shallowlilies, and pure water from the garden nearby? I can create a pain medicine with these components, if you find enough.", ["objectivesText"] = "Gather 5 Milky Snapflowers , 3 Blooming Shallowlilies , and a Filled Life Pools Vial. Progress: Was the dragonspawn... willing to make anything?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198666, 198668, 198673, 200109 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194805, ["x"] = 0.57, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194800, ["x"] = 0.574, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70241] = { ["id"] = 70241, ["name"] = "The Bitter End", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70241 }, ["description"] = "It just happened. I--He was sleeping and I looked away and-- We came back here every day, he just wanted to sit with the whelps, I didn't know he-- <Kolgar's face is clearly tear-stained. He rubs his eyes with the back of his hand.> No, I knew. I knew. But I don't know what to do now. What do I do with him? Can you-- Can you find Bathoras ?", ["objectivesText"] = "Bring Bathoras to Duroz and Kolgar. Progress: Oh, greetings once more, <name>. I have been able to make a few more batches of that medicine with all the herbs you brought me. Duroz began refusing it earlier today, but I may be able to find other uses for it.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194801, ["x"] = 0.578, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194805, ["x"] = 0.57, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70242] = { ["id"] = 70242, ["name"] = "Life After Life", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70242 }, ["description"] = "I could sense that his friend bore a deep scar. Something in this place reopened it--perhaps so that it could heal cleanly this time. Now it is Kolgar's time to heal. In the terrace above us, you will find my friend Trellain working with the enchanters. Tell him that I require one of the vessels he uses in his work. He will give it to you freely.", ["objectivesText"] = "Collect an Inert Vessel from Trellain in the Ruby Lifeshrine. Progress: Were you able to find Trellain?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198701 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194805, ["x"] = 0.57, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194805, ["x"] = 0.57, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70244] = { ["id"] = 70244, ["name"] = "Nokhud Can Come of This", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "For thousands of years, the Teerai have guarded the Horn of Drusahl, our most sacred relic. By sacking this village, Balakar has betrayed everything it means to be Maruuk. There can be no redemption for him now. We must retake the Horn before Balakar can destroy it and rescue any Teerai who yet live. I am going with you to personally bring that false Khan to justice. The Nokhud will know the wrath of the Khanam Matra!", ["objectivesText"] = "Enter the village with Khanam Matra Sarest and reclaim it from the Nokhud. Progress: There is no time to lose! We must re-take the village and defend the Horn of Drusahl!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 194549, 197375, 197653 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.7375, ["y"] = 0.4305 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 40, ["flags"] = 0 } } },
[70268] = { ["id"] = 70268, ["name"] = "Memories Revived", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70268 }, ["description"] = "You found a partially destroyed diary . It appears to be written from the view point of a young black dragon woman, before the corruption. While the back part of it is illegible, skimming through the first part, a name stands out to you. Veritistrasz .", ["objectivesText"] = "Give Veritistrasz the Diary. Progress: Hello young one, nice to see you again.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198661 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194076, ["x"] = 0.578, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70319] = { ["id"] = 70319, ["name"] = "Nergazurai", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70319 }, ["description"] = "My uncle told me many tales of his battle with a hornstrider named Nergazurai. He told me of its fuchsia scales weaving through the hills of the plains as it seeks its prey, its razor-sharp talons and venomous bite. While I was out hunting I saw the flash, but it was too late; it left me with a nasty bite in my shoulder. He was as terrible as my uncle described, but I came out alive. I need to clean the infection from his bite. Please, collect the reagents I need. Time is of the essence.", ["objectivesText"] = "Bring an Ottuk Heart , a Rockfang Femur , a Hornstrider Scale , and a Vulture Gizzard to Muqur Rain-Touched in Timberstep Outpost. Progress: My fever grows worse, friend. I fear if I do not clean the infection soon, it will be the death of me.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191127, 191143, 191541, 198792, 198793, 198794, 198795 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194904, ["x"] = 0.845, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194904, ["x"] = 0.845, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.845, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70335] = { ["id"] = 70335, ["name"] = "Simple Excavation Tools", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70335, 70807, 70808, 70809, 70810, 70812, 70813, 70814, 70815, 70817, 70818, 70819, 70820, 70821, 70822, 70828, 70831, 70832, 70833, 70834, 70835, 72023, 72024, 72025, 72026, 72032, 72033, 72034, 72035, 72036, 72037, 72038, 72039, 72040, 72041, 72042, 72043, 72044, 72045, 72046, 72047, 72048, 72294, 72295, 72299, 72300, 72301, 72302, 72303, 72304, 72305, 72306, 72308, 72309 }, ["rewardItems"] = { 198387, 198717, 198718, 199746 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188265, ["x"] = 0.478, ["y"] = 0.82 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188265, ["x"] = 0.478, ["y"] = 0.82 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.82 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1380, ["name"] = "Dragonscale Expedition Renown", ["orderIndex"] = 2, ["flags"] = 0 } } },
[70337] = { ["id"] = 70337, ["name"] = "Emberwatch", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70337 }, ["series"] = { 65890, 65891 }, ["description"] = "Hail, outsider. The winds tell me of a group taking shelter in the ruins of Emberwatch. They seem only interested in the past while we centaur choose to live for the present under the grace of Ohn'ahra. Nonetheless, they are guests in our home. I have fashioned for them these wind chimes so they may hear Ohn'ahra's presence. May it bring their hearth some joy and comfort.", ["objectivesText"] = "Bring the Ohn'ir Wind Chimes to Emberwatch. Provided item:", ["rewardGold"] = 42450, ["rewardXP"] = 690, ["rewardItems"] = { 193355, 193357, 193375, 193601, 197407, 198078, 198079, 199174 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195239, ["x"] = 0.622, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190089, ["x"] = 0.66, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70338] = { ["id"] = 70338, ["name"] = "They Took the Kits", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70338 }, ["description"] = "If Sylvie is this distressed, that must mean it's her kits that are in there! While she was infected, the giants must have kit-napped her babies and she was too weak to save them. Kits are energetic at this age, hopefully they've all been quick enough to evade the giants until now... Here, make use of my invisibility charm-- Quickly, you must save them before they're eaten!", ["objectivesText"] = "Rescue the kits.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 197983, 198336, 198797, 200526 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192830, ["x"] = 0.646, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192830, ["x"] = 0.646, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70339] = { ["id"] = 70339, ["name"] = "In Tyr's Footsteps: The Ohn'ahran Plains", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70182, 70633 }, ["description"] = "Though you have done well in your first challenge, do not think you shall surpass all so easily. Keeper Tyr meant the Engine of Innovation to be only for those worthy enough to use it wisely. If you are undeterred, the next challenge shall be found in the Ohn'ahran Plains. I look forward to testing your capabilities, adventurer.", ["objectivesText"] = "Find the Second Challenge of Tyr in the Ohn'ahran Plains.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1370, ["name"] = "Tyr's Second Challenge", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 3, ["flags"] = 0 } } },
[70341] = { ["id"] = 70341, ["name"] = "Well-Earned Victory", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70650 }, ["description"] = "The smallest of things can contain the greatest of treasures. Take the essence to the Engine of Innovation.", ["objectivesText"] = "Return to the Engine of Innovation in Valdrakken.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195924, ["x"] = 0.662, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1370, ["name"] = "Tyr's Second Challenge", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 4, ["flags"] = 0 } } },
[70351] = { ["id"] = 70351, ["name"] = "Garden Party", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70351 }, ["description"] = "I've been tending to this garden for years, preparing for the day I'd finally accept my Lifecalling. Now that day is here! I love flowers and all trees and plants--even the bugs that live amongst them. I can feel nature's spirit--the Great Dragon Spirit--when I tend the garden. There's only one thing left to do. I'm going to invoke the Great Dragon Spirit, just like the legends. < Akora smiles brightly.> Meet me down in the garden by the pool where her bones rest. I'll explain more there.", ["objectivesText"] = "Speak to Akora in the Ruby Life Pools.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191012, ["x"] = 0.618, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190866, ["x"] = 0.602, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70370] = { ["id"] = 70370, ["name"] = "Occupation Examination", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2022, ["storyline"] = { 70370 }, ["description"] = "Hello! Are you interested in working with the Artisan's Consortium to earn plentiful profits and provide valuable goods and services to clients across Azeroth? Excellent! Which two skills have you trained in? ...Hmm? You have only one profession? What a missed opportunity! < Haephesta ponders for a moment.> I know! I will ask you a series of questions about your personality, and we will find out together which second profession best complements your first one! How does that sound?", ["objectivesText"] = "Take Haephesta 's personality quiz to find out your ideal profession. Progress: Quizzes solve everything!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 198222, 198223, 198224, 198549, 198550 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 }, { ["mapID"] = 2023, ["npcID"] = 195043, ["x"] = 0.718, ["y"] = 0.786 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 }, { ["mapID"] = 2023, ["npcID"] = 195043, ["x"] = 0.718, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13645 } }, ["questType"] = "profession" },
[70371] = { ["id"] = 70371, ["name"] = "Deathwingurlugull!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14092, ["mapID"] = 2092, ["storyline"] = { 66110, 66111, 66704, 70371, 71025, 71144 }, ["description"] = "Deathwingurlugull! Deathwingurlugull! Deathwingurlugull delgrbrrl!! Grrrooooooooom blarglg!! <You don't need a translation to know that they want you to bring down their murloc version of Deathwing. Before you can agree or disagree, the roars of a machine engine make their way toward you!>", ["objectivesText"] = "Get in the Hopper and defeat Deathwingurlugull! Progress: Deathwingurlugull delgrbrrl!!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14092 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2092, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 40, ["flags"] = 0 } } },
