[70374] = { ["id"] = 70374, ["name"] = "Himia, the Blessed", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70374 }, ["description"] = "The Elements lay claim to this land and do not welcome our intrusion. O, Elements, have you forgotten our protector--Air! Invisible, yet omnipresent and vital for all existence! Forgotten, as easy as you breathe it. After facing me, you will never forget again.", ["objectivesText"] = "Defeat the elements.", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 193202, 193206, 193207, 193483 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190950, ["x"] = 0.492, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70376] = { ["id"] = 70376, ["name"] = "Second Challenge of Tyr: Might", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["description"] = "<As you approach, an inscription on the statue lights up with a faint glow.> \"Wield the Keeper's power and show the undaunted determination of one who stands strong.\"", ["objectivesText"] = "Complete the second Challenge of Tyr in the Ohn'ahran Plains.", ["rewardGold"] = 842700, ["rewardXP"] = 8200, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 195924, ["x"] = 0.662, ["y"] = 0.554 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1370, ["name"] = "Tyr's Second Challenge", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 7, ["flags"] = 0 } } },
[70377] = { ["id"] = 70377, ["name"] = "Derelict Fashion", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70377 }, ["description"] = "<A disgusting set of sunglasses is dripping with slime, but they look extremely expensive. Someone is definitely missing these. This style is very hot right now.>", ["objectivesText"] = "Find the owner of the sunglasses. Progress: I cannot possibly be seen at the VIP area without my sunglasses! You see, I grabbed a glider, and was getting some A-MAZ-ING pictures. I looked below, and saw all of these tiny elementals the size of ants! I thought, hah, ant-size elementals: what a great photo-op. But when I got there, they were at least three times the size of ants. A muddy one chased me, but I am very fast. I hate to think of what has happened to my sunglasses...", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 200586 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 198062, ["x"] = 0.394, ["y"] = 0.478667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.478667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 200586 } },
[70414] = { ["id"] = 70414, ["name"] = "Shaky Grounds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70414 }, ["description"] = "In the name of Khaz'goroth, what goes on here? This magma works with a mind of its own, consuming these elemental cavestones from below. Tis more than chance causin' this... I aim to figure it out! Place these Shattering Totems next to each trapped elemental to free them!", ["objectivesText"] = "Place the Shattering Totems to free the trapped cavestones . Progress: Have ye freed them all?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198980, 200617 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 195234, ["x"] = 0.37, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 195234, ["x"] = 0.37, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70437] = { ["id"] = 70437, ["name"] = "To Tyrhold", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66675, 66847, 67073, 72380 }, ["description"] = "Centuries have passed since the flights last visited Tyrhold. Nevertheless, we must travel there and investigate if the Mother Oathstone still functions. Come, speak with me at the Seat of the Aspects. We must learn about the dangers we may face at Tyr's former stronghold.", ["objectivesText"] = "Meet Alexstrasza at the Seat of the Aspects. Progress: It is good to see you, <name>.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 71086, 190454, 197921, 206162 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187658, ["x"] = 0.574, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1333, ["name"] = "The Mother Oathstone", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 48, ["flags"] = 0 } } },
[70444] = { ["id"] = 70444, ["name"] = "The Fields of Ferocity", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70444 }, ["series"] = { 66459 }, ["description"] = "To the bravest Shikaar! Gather your best and head on over to the Fields of Ferocity . You could be crowned the fiercest of them all! Prove your might. Show us your best fight! Terms and conditions apply.", ["objectivesText"] = "Meet Gurgthock at the Fields of Ferocity .", ["rewardGold"] = 42450, ["rewardXP"] = 690, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
[70503] = { ["id"] = 70503, ["name"] = "The Vigilance of Tyr", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "Bodies, broken gear, uncontrolled titan energy. What a disregard for safety, and... and protocol! It looks like they found the stone and it was unstable, bursting into pieces. Fortunately, I'm particularly adept at repairing magical devices. But before I can reform the stone we need to collect each and every piece.", ["objectivesText"] = "Recover the fragments of the stone. Progress: I can't believe it. It's all here! Well done.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193350, ["x"] = 0.538, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193350, ["x"] = 0.538, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 5, ["flags"] = 0 } } },
[70507] = { ["id"] = 70507, ["name"] = "The Insight of Tyr", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "Did ya see Szar Skeleth on your way in? It's that ruined tower to the northeast. We've got a bit of a good news, bad news situation there. The good news is the stone's already been found. Bad news is it was found by the Sundered Flame, specifically a magic-using dracthyr named Makko. And they're using it to control gorlocs. Did I mention the dracthyr's misuse of the stone drove them mad? Well, good luck!", ["objectivesText"] = "Recover the Insight of Tyr . Progress: Turns out gorlocs don't make for good bodyguards, eh? I wonder how dangerous she could've been if she held on to her sanity.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191159, ["x"] = 0.4, ["y"] = 0.674 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191159, ["x"] = 0.4, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 7, ["flags"] = 0 } } },
[70509] = { ["id"] = 70509, ["name"] = "Third Challenge of Tyr: Persistence", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70621 }, ["description"] = "<It seems those who have reawakened with the Isles have not been kind to Keeper Tyr's creations. Perhaps finding the missing pieces of the statue would help.>", ["objectivesText"] = "Retrieve missing parts and repair the broken statue. Progress: <As you approach, you can feel the warmth of Titan's energy flowing through the statue once more.>", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 195737, ["x"] = 0.64, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1371, ["name"] = "Tyr's Third Challenge", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 8, ["flags"] = 0 } } },
[70510] = { ["id"] = 70510, ["name"] = "Victorious", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70881, 70899, 70900 }, ["description"] = "Once again I ask you to bring this essence to the Engine of Innovation.", ["objectivesText"] = "Return to the Engine of Innovation in Valdrakken.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 160335, 160338, 160341, 160344, 160373, 160376, 160379, 160382, 190453, 198982, 198983, 198984, 199197, 200108, 200120, 211279 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 195737, ["x"] = 0.64, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 9, ["flags"] = 0 } } },
[70621] = { ["id"] = 70621, ["name"] = "Third Challenge of Tyr: Persistence Embodied", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70509 }, ["description"] = "Your third challenge was meant to have you overcome unfavorable odds. It was to help show me your persistence in all matters. I believe fighting djaradin and fixing my statue with the expectation that I would issue you a challenge is more than sufficient to fulfill your victory condition. <You think you catch a small smile play across her lips.>", ["objectivesText"] = "Accept the Bottled Essence from Maiden of Inspiration .", ["rewardGold"] = 24100, ["rewardXP"] = 685, ["rewardItems"] = { 199197 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 195737, ["x"] = 0.64, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1371, ["name"] = "Tyr's Third Challenge", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 10, ["flags"] = 0 } } },
[70625] = { ["id"] = 70625, ["name"] = "Spellforged Creations", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70625 }, ["objectivesText"] = "Spellforged Creation slain", ["rewardXP"] = 5145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Spellforged Creation slain", ["amount"] = 1, ["type"] = 0, ["objectID"] = 194402, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[70627] = { ["id"] = 70627, ["name"] = "What of the Winterpelt Clan?", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70627 }, ["description"] = "We could join another clan... if we knew it to be safe. I worry the Primalists tempted other clans as they did ours. This \"Dragonscale Expedition\" tells me they have a clawhold near the Winterpelt clan. They may be tainted. Or they may heed our warning. With either truth, they need us. There is a \"furbolg expert,\" Sonova Snowden , in Theron's Watch. Please go to him and learn what he knows.", ["objectivesText"] = "Meet Sonova Snowden at Theron's Watch.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191123, ["x"] = 0.632, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70633] = { ["id"] = 70633, ["name"] = "Fueling the Engine", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70182, 70339 }, ["description"] = "You have done well to pass the first challenge that Keeper Tyr left behind. Though this is but the first step on your journey I have faith you shall do well. You have earned your chance at furthering yourself in unlocking the secrets of the Forge. Add the Bottled Essence to the Engine of Innovation and see what occurs.", ["objectivesText"] = "Use the Bottled Essence to empower the Engine of Innovation. Progress: <The Engine hums quietly as you approach>", ["rewardGold"] = 70225, ["rewardXP"] = 1365, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1368, ["name"] = "Spark of Ingenuity", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 11, ["flags"] = 0 } } },
[70647] = { ["id"] = 70647, ["name"] = "Oh Where, Oh Where Can He Be?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "<name>, I am glad to see you! I am worried sick and could use your help. Recently, I rescued an abandoned proto-drake whelp. I named him Lubbins because he is so lovely! I brought him here to care for him and hopefully find him a good home as someone's pet. But now he is missing, and I am concerned that he is lost or hurt. I need to keep watch over the rest of my little ones, otherwise I would go searching for him myself. Would you please look for him?", ["objectivesText"] = "Rescue Lubbins and bring him back to Jyhanna at the Little Scales Daycare in Valdrakken. Progress: I hope Lubbins is safe. I am terribly worried.", ["rewardGold"] = 147500, ["rewardXP"] = 4960, ["rewardItems"] = { 86143, 199175, 223625 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185563, ["x"] = 0.105, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185563, ["x"] = 0.105, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.105, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 0, ["flags"] = 0 } } },
[70648] = { ["id"] = 70648, ["name"] = "Firava the Rekindler", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["storyline"] = { 70648 }, ["rewardGold"] = 22600, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2VignetteID"] = 5372, ["db2VignetteName"] = "Firava the Rekindler" },
[70650] = { ["id"] = 70650, ["name"] = "In Tyr's Footsteps: The Waking Shores", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70341 }, ["description"] = "You have proven yourself well so far, and though I have great faith you are worthy of the Engine I still must challenge you as is my designation. Go to the Waking Shores and find my statue and you shall receive further instructions.", ["objectivesText"] = "Find the Third Challenge of Tyr in the Waking Shores.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1371, ["name"] = "Tyr's Third Challenge", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 12, ["flags"] = 0 } } },
[70697] = { ["id"] = 70697, ["name"] = "An Expert Opinion", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "Lubbins' wounds may have healed, but I am afraid his confidence may still be injured. I believe it is time to call on others for help. Far to the southwest in a remote section of the Azure Span there is a pet trainer named Patchu . She is one of the world's foremost experts on these matters. Please visit her, I am sure she can help Lubbins!", ["objectivesText"] = "Talk to Patchu in The Azure Span.", ["rewardItems"] = { 92683, 116421, 122457, 163036, 199175, 200519 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185563, ["x"] = 0.105, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196069, ["x"] = 0.138, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.105, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 1, ["flags"] = 0 } } },
[70703] = { ["id"] = 70703, ["name"] = "The Legacy of Tyrhold", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 67074, 67075, 67076, 67077, 67078, 67079, 67081, 67084, 68794, 70703 }, ["description"] = "Keeper Tyr did love his mysteries. Clearly, there is deeper meaning to the gift he gave us. As he most likely forged this scale at his former citadel, perhaps it will be the key to helping unlock its secrets. Go with Koranos to Tyrhold, <name>. As a trusted advisor and watcher of this land, I am sure he will have insight into this matter.", ["objectivesText"] = "Investigate the Silver Scale with Koranos at Tyrhold. Progress: Have you discovered something?", ["rewardGold"] = 154900, ["rewardXP"] = 2465, ["rewardItems"] = { 197845, 197862, 197863, 198038, 198355 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192480, ["x"] = 0.592, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1325, ["questLineOrder"] = 0 }, { ["id"] = 229, ["title"] = "Catching Up!", ["questLineID"] = 1325, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1325, ["name"] = "The Silver Purpose", ["orderIndex"] = 2, ["flags"] = 0 } } },
[70708] = { ["id"] = 70708, ["name"] = "Hollow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70708 }, ["description"] = "Feels like it's been years. Also feels like it's been minutes. I could use someone to talk to, if you have time. You wanna grab us a round of drinks? Get whatever you want. I'm paying.", ["objectivesText"] = "Have a drink with Kolgar. Progress: I know I owe you more than a drink, but I hope this will do for now.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 200129 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194801, ["x"] = 0.578, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194801, ["x"] = 0.578, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70721] = { ["id"] = 70721, ["name"] = "After My Ohn Heart", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70721 }, ["description"] = "There is a small pond by the Mirror of the Sky where Narman and I first met during my initiate training. Initiates travel up there to be closer to Ohn'ahra so they may feel the wind. I first saw him in the reflection of the water when a sudden breeze opened my eyes. It is the most beautiful sight in all of the plains. It will be the perfect place for our proposal.", ["objectivesText"] = "Help Windsage Dawa and Hunter Narman with their proposals.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 198105, 200597 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190192, ["x"] = 0.628, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 197011, ["x"] = 0.466, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70722] = { ["id"] = 70722, ["name"] = "What Lubbins Needs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "I think that I know what we gotta do, <name>. But first, let's talk about it! I even have a gift to give you after we're done! Fun, right?", ["objectivesText"] = "Speak with Patchu in Iskaara. Progress: Let's talk!", ["rewardItems"] = { 92683, 116421, 122457, 163036, 199175, 200519 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196069, ["x"] = 0.138, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196069, ["x"] = 0.138, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.138, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 2, ["flags"] = 0 } } },
[70730] = { ["id"] = 70730, ["name"] = "Shikaar Giver", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70730 }, ["description"] = "Oh, $p. Do you feel comfort under the sun? Do you feel safe under its bright caress? Does each new day represent hope for the future and a chance to live your life as you've always dreamt it? Then you know love as I do. Narman of Clan Shikaar is my sun. He is my warmth. He is my light. He is my hope. A man like him deserves a proposal worthy of stature. We must seek guidance from an Ohn.", ["objectivesText"] = "Help Windsage Dawa prepare for the perfect proposal. Progress: Narman deserves a gesture as great as he is.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 199919, 200258 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190192, ["x"] = 0.628, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190192, ["x"] = 0.628, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70732] = { ["id"] = 70732, ["name"] = "A Practice Bout", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "All right! Now that you used that stone on Lubbins, let's have a practice bout to test out his skills! There's a big ole Hornswog named Gwosh that lives on the shore to the north of here. Gwosh loves to fight! Well, play really. He's super good with other pets, too! It'll be a perfect playtime... I mean fight... for Lubbins.", ["objectivesText"] = "Defeat Gwosh in a pet battle. Progress: Gwosh is real gentle, but still fierce. I think he and Lubbins will have a fun bout! Just head up north of here and you'll find him.", ["rewardItems"] = { 92683, 116421, 122457, 163036, 199175, 200519 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196069, ["x"] = 0.138, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196069, ["x"] = 0.138, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.138, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 3, ["flags"] = 0 } } },
[70738] = { ["id"] = 70738, ["name"] = "The You-ga Class", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70738 }, ["description"] = "Everything was going so well, but now? Elementals are causing some, um, mild challenges. Our guests were enjoying the facilities when suddenly, all these elementals appeared! Those nasty fiends have disrupted everything. Probably even the new you-ga instructor. Oh yes, you-ga is a new type of stretching that helps you meditate at the same time. I am sure both teacher and students are so relaxed they do not even notice the elementals. Still, better to be safe than sorry. Please, look for them.", ["objectivesText"] = "Find the instructor and 6 you-ga students.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200586 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 194717, ["x"] = 0.404, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 194717, ["x"] = 0.404, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70739] = { ["id"] = 70739, ["name"] = "Bloodlines, Sweets, and Teerai", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70739 }, ["description"] = "I have hunted with khans, outrun our fastest bakar, and wrestled a full grown bruffalon bull bare-handed. As a hunter, I've nothing left to prove. However, as a partner, I still have much to learn. Windsage Dawa of Clan Ohn'ir is my heart and my joy. I wish only to prove worthy of his love, but I know nothing of traditions and rituals. I require the wisdom of the elders in Maruukai.", ["objectivesText"] = "Help Hunter Narman earn a traditional blessing for his marriage proposal. Progress: What if I am not good enough for Dawa's love?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 199918, 201044 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191924, ["x"] = 0.636, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191924, ["x"] = 0.636, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70740] = { ["id"] = 70740, ["name"] = "Steam Cleaning", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70740 }, ["description"] = "Xijan seems to think the elemental invasion on our beautiful spa is only a minor problem, but this surge of flame and steam needs to be brought under control immediately. We had booked musical acts to play in the lower area, but the elementals destroyed their gear. As we have never had such levels of elemental destruction in this area before, I suspect Primalist influences. If you want to help, clear the elementals on the east side of the lower spa. That is where the first events are scheduled.", ["objectivesText"] = "Kill 12 elementals in the lower spa.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200586 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196160, ["x"] = 0.404, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196160, ["x"] = 0.404, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70741] = { ["id"] = 70741, ["name"] = "Some Favorite Things", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70741 }, ["description"] = "<It looks like the you-ga class was interrupted, and the students' belongings are scattered everywhere. Collecting these items will certainly aid the Serene Dreams Spa.>", ["objectivesText"] = "Collect 6 missing belongings.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200586 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 194717, ["x"] = 0.404, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70743] = { ["id"] = 70743, ["name"] = "Precious Baby", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70743 }, ["description"] = "You there, $pr! Are you semi-competent? Do you have your priorities in check? Good! My precious Baby is missing. Save her immediately. Be quick about it, she can't fend for herself in these horrible conditions.", ["objectivesText"] = "Find Elzara 's Baby .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200586 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 194812, ["x"] = 0.404, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 194812, ["x"] = 0.404, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70744] = { ["id"] = 70744, ["name"] = "Look at the Bones!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70744 }, ["description"] = "<Surely the spa manager would appreciate if there wasn't blood everywhere...>", ["objectivesText"] = "Clean up 10 bits of mess.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200586 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 194717, ["x"] = 0.404, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70745] = { ["id"] = 70745, ["name"] = "Enforced Relaxation", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70745 }, ["description"] = "Those Primalists that you saw certainly do not seem like the leadership type to me. Who would be afraid of a little dog? Hah! So, if they mentioned Vadne, that sounds like their leader. She must be the one bringing in these elementals. We need to get rid of the summoner. They must be close by to be causing such trouble. Check the cave directly under us. I know it is where some of the less diligent employees like to take an extended break.", ["objectivesText"] = "Kill the elemental summoner.", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 200586, 256429 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196160, ["x"] = 0.404, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196160, ["x"] = 0.404, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70746] = { ["id"] = 70746, ["name"] = "Shades of Blue", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "You there, $p! It's good to see a friendly face in these parts. Telash and I were just discussing reports we've heard of... newcomers, in the area. <Emberthal lowers her voice.> Blue dragons. Given our... history, with the blues, Telash and I thought it necessary to assess the situation ourselves. Please, join us.", ["objectivesText"] = "Accompany Emberthal and Telash to Camp Antonidas. Progress: Keep your head clear and your wings ready, my friend.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 197023, ["x"] = 0.431333, ["y"] = 0.469333 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197023, ["x"] = 0.431333, ["y"] = 0.469333 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.431333, ["y"] = 0.469333 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 2, ["flags"] = 1 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 2, ["flags"] = 1 } } },
[70747] = { ["id"] = 70747, ["name"] = "The Azure Wizard", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "I do not have time to quibble with sorcerers. Go and treat with this \"Archmage\", $p. Learn what you may, and be on your guard always. They might be allies still or enemies yet... Our reports indicate there's a large archival complex to the south of here. That is where I'm going.", ["objectivesText"] = "Talk to Archmage Khadgar in Camp Antonidas. Progress: You appear uneasy, friend.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 197025, ["x"] = 0.431333, ["y"] = 0.469333 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192091, ["x"] = 0.466, ["y"] = 0.402 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.431333, ["y"] = 0.469333 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 3, ["flags"] = 1 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 3, ["flags"] = 1 } } },
[70750] = { ["id"] = 70750, ["name"] = "Aiding the Accord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "You there! Yes, I'm speaking to you. Who else do you see around here? < Therazal glances quickly at quite a few passers by.> Ignore them. They are not part of this request. It is you I've heard of, and you I wish to speak with! The Valdrakken Accord has asked me to seek out those who have shown they are making a name for themselves across the Isles, and those who seek to ensure our allies and their safety remain the highest priority. Do what you do best, friend. You shall be rewarded handsomely.", ["objectivesText"] = "Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: The tales of your exploits ring true, but what is it you bring me? Information, news? Get on with it.", ["rewardXP"] = 2125, ["rewardItems"] = { 190454, 192017, 200072, 200073, 201921, 201922, 201923, 201924, 202142, 202172, 205983, 210872 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 2, ["flags"] = 1 } } },
[70784] = { ["id"] = 70784, ["name"] = "The Abandoned Outpost", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "From what you mentioned, it appears the stone of Vigilance can be found at an abandoned station northeast of the Azure Archives. That must be Zelthrak Outpost. Meet up with me when you arrive, <name>, and we can find the stone together.", ["objectivesText"] = "Meet up with Naleidea near Zelthrak Outpost in the Azure Span.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193350, ["x"] = 0.538, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 4, ["flags"] = 0 } } },
[70785] = { ["id"] = 70785, ["name"] = "The City of the Dead", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "An ancient city of the dead can only mean one thing. The Veiled Ossuary off the coast of northern Thaldraszus. It's extensive, remote, and hard to approach. The perfect place to hide something. I'm not sure what we'll find there, <name>. But you can bet that it won't appreciate our presence.", ["objectivesText"] = "Meet up with Naleidea at the Veiled Ossuary in Thaldraszus.", ["rewardGold"] = 143880, ["rewardXP"] = 4925, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190855, ["x"] = 0.622, ["y"] = 0.182 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 8, ["flags"] = 0 } } },
[70787] = { ["id"] = 70787, ["name"] = "Caught In a Dusk Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["storyline"] = { 70787 }, ["rewardXP"] = 1415, ["rewardItems"] = { 199917 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "world" },
