[70822] = { ["id"] = 70822, ["name"] = "Lost Expedition Scouts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70335, 70807, 70808, 70809, 70810, 70812, 70813, 70814, 70815, 70817, 70818, 70819, 70820, 70821, 70822, 70828, 70831, 70832, 70833, 70834, 70835, 72023, 72024, 72025, 72026, 72032, 72033, 72034, 72035, 72036, 72037, 72038, 72039, 72040, 72041, 72042, 72043, 72044, 72045, 72046, 72047, 72048, 72294, 72295, 72299, 72300, 72301, 72302, 72303, 72304, 72305, 72306, 72308, 72309 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187700, ["x"] = 0.472, ["y"] = 0.834 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187700, ["x"] = 0.472, ["y"] = 0.834 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.834 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1380, ["name"] = "Dragonscale Expedition Renown", ["orderIndex"] = 0, ["flags"] = 0 } } },
[70837] = { ["id"] = 70837, ["name"] = "Follow the Clues", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70837 }, ["description"] = "< Investigator Erima reviews the map.> It is clear what the X scrawled over the Seat of the Aspects represents. But there is also a circle drawn around the Misty Vale. Perhaps this is the rebels' next target? Or a base of operations. Only one way to find out. Meet me at the Vale.", ["objectivesText"] = "Meet Investigator Erima at the Misty Vale.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196984, ["x"] = 0.565, ["y"] = 0.4365 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196416, ["x"] = 0.426, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.4365 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[70838] = { ["id"] = 70838, ["name"] = "Rebels With a Cause", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70838 }, ["description"] = "The rebel staging ground... we have been looking for this very place. How fortunate for us that their saboteur's carelessness led us here. I cannot believe my brethren would stoop to working with the Primalists. We cannot let this stand. Take out the rebels and their Primalist friends before they can cause any further chaos.", ["objectivesText"] = "Kill 10 rebels and Primalists. Progress: I trust these turncoats will pose no threat to you.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196416, ["x"] = 0.426, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196432, ["x"] = 0.425, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70842] = { ["id"] = 70842, ["name"] = "Detonation Locations", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70842 }, ["description"] = "I am sure that the rebels are documenting their plans for future attacks. We must find out what they are attempting to do before it happens. Search their camp for any marked maps like the one we found in Valdrakken.", ["objectivesText"] = "Collect Misty Vale maps. Progress: Were you able to recover the rebel plans?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196416, ["x"] = 0.426, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196432, ["x"] = 0.425, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70843] = { ["id"] = 70843, ["name"] = "Ruin the Runestones", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70843 }, ["description"] = "<This runestone is strikingly similar to the one a rebel tried to plant in Valdrakken. Though this stone is unfinished, you spy caches of completed runestones off in the distance. If you destroy these caches the rebels will not be able to put them to use.>", ["objectivesText"] = "Destroy caches of incendiary runestones. Progress: Brave of you to tinker with those strange stones.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196464, ["x"] = 0.435, ["y"] = 0.81 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196432, ["x"] = 0.425, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70845] = { ["id"] = 70845, ["name"] = "In Tyr's Footsteps", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70180 }, ["description"] = "Keeper Tyr planned for all eventualities. He suspected there would be a need to empower the craftspeople of the realm some day, thus he created the Engine of Innovation. It possesses the ability to create a unique material that can help an item achieve expertise beyond that of mortal ability. To ensure his engine would not be misused he created me to oversee any who sought its power. Only those worthy will be able to unlock the engine's full potential. Are you equal to the challenge?", ["objectivesText"] = "Find the First Challenge of Tyr in the Azure Span.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1368, ["name"] = "Spark of Ingenuity", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 13, ["flags"] = 0 } } },
[70849] = { ["id"] = 70849, ["name"] = "This Calls for a Specialist", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "Lubbins is doing lots better now, but I think he still needs some more help. A little bit ago I met a super smart Dragonscale Expedition explorer named Haniko who works with proto-drakes all the time. She's a pet trainer, too. I bet she could help Lubbins more! I think she was going to the Waking Shores. I bet if you go there you'll find her. I'm so happy I was able to help you! <she waves happily> Goodbye! Good luck, Lubbins.", ["objectivesText"] = "Talk to Haniko at the Wild Preserve in The Waking Shores.", ["rewardItems"] = { 92683, 116421, 122457, 163036, 199175, 200519 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196069, ["x"] = 0.138, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 196264, ["x"] = 0.62, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.138, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 71, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 4, ["flags"] = 0 } } },
[70850] = { ["id"] = 70850, ["name"] = "Maldra's in Hot Water", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70850 }, ["description"] = "Excellent work. While you were off disrupting things I was scouting the camp. I did not expect to find my old friend Maldra Flametongue. I knew she was missing, but the rumors said she had joined the rebels. From what I could see, though, she is their captive! We cannot leave her here. Rescue her from the dragonspawn holding her captive!", ["objectivesText"] = "Rescue Maldra from Orian Darkwater . Progress: Maldra is a dear friend. We cannot leave her here with these rebels!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196432, ["x"] = 0.425, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196432, ["x"] = 0.425, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70851] = { ["id"] = 70851, ["name"] = "Born to Be Wilder", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 71, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "There's a lot of information you need to know. Let's have a talk and then we can decide what's best for Lubbins.", ["objectivesText"] = "Learn what Lubbins needs from Haniko . Progress: There's a lot to cover. Let's talk.", ["rewardItems"] = { 92683, 116421, 122457, 163036, 199175, 200519 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 196264, ["x"] = 0.62, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 196264, ["x"] = 0.62, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 5, ["flags"] = 0 } } },
[70853] = { ["id"] = 70853, ["name"] = "A Friend for Lubbins", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 71, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "Like we talked about, Lubbins needs two things: a buddy and a battle. I think we can get him both at the same time. This area is a prime mating ground for Shyflys. If you look around a bit, you're sure to find a bunch. Remember, you need to weaken it before you can capture it with your trap. Come back when you have one. It might be a bit bruised after your battle, but I've got some battle-training stones that will fix 'em right up!", ["objectivesText"] = "Capture a Shyfly at the Wild Preserve in The Waking Shores. Progress: The Shyflys shouldn't be too hard to find, especially now that you know where to look.", ["rewardItems"] = { 92683, 116421, 122457, 163036, 199175, 200519 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 196264, ["x"] = 0.62, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 196264, ["x"] = 0.62, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 6, ["flags"] = 0 } } },
[70854] = { ["id"] = 70854, ["name"] = "So How Did It Go?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 71, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "You've done well, <name>. Lubbins is doing much better and is in excellent spirits. Jyhanna will want to know, so go back and give her the good news!", ["objectivesText"] = "Return to Jyhanna at the Whelp Daycare in Valdrakken.", ["rewardItems"] = { 92683, 116421, 122457, 163036, 199175, 200519 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 196264, ["x"] = 0.62, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185563, ["x"] = 0.105, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 71, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 7, ["flags"] = 0 } } },
[70856] = { ["id"] = 70856, ["name"] = "Kill it with Fire", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70856 }, ["description"] = "These vile spiders lay their eggs in corpses. And sometimes the living. We've seen several bodies of Sundered Flame who have fallen victim to them. We can't let those eggs hatch if we want to survive here and defeat the Sundered Flame. Take this torch. It is imbued with the power of air and fire. Point it in the direction of what you want scorched, and it will do the rest. The Tuskarr don't mess around with spiders. I came prepared.", ["objectivesText"] = "Destroy 10 Infected Corpses with the Flamethrower Torch .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191715, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 191715, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70858] = { ["id"] = 70858, ["name"] = "Back into the Action", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70858 }, ["description"] = "All right, the antidote is ready. I'll keep Alia steady. You pour what's in the vial into her mouth. I hope she will live... we'll need her magic to track down this artifact.", ["objectivesText"] = "Use the Ice Cold Antidote on Alia Sunsoar .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194747, 195468, 199928, 199930, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196254, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196501, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70859] = { ["id"] = 70859, ["name"] = "What the Guardian Beholds", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70859 }, ["description"] = "I appreciate your aid, <class>. I was the Kirin Tor mage who first discovered this artifact, Valthrux, and the Sundered Flame's plans. The retrieval and study of this supposedly sentient and powerful artifact is of the utmost importance, and mark my word, I shall be the one to do it. The Sundered Flame guess at its location, but I've used my magic to find a path for us. There is a corrupted guardian nearby that holds a magic shard connected to Valthrux. I can use it to find the rest of the artifact.", ["objectivesText"] = "Recover the Whispered Shard from Edavix, the Corrupted Guardian. Progress: Did you find the shard?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196501, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196501, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70874] = { ["id"] = 70874, ["name"] = "To Breach a Fire Wall", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70874 }, ["description"] = "The rebels inside the cavern have been imbued with an elemental blessing, allowing them to safely pass through the wall of flame. I can grant you that same boon. Do not worry; I have seen the blessing granted many times. It shouldn't be any problem to recreate it effectively.", ["objectivesText"] = "Receive Maldra's elemental blessing. Progress: How do you feel?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196562, ["x"] = 0.426, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196608, ["x"] = 0.425, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70875] = { ["id"] = 70875, ["name"] = "Worst of the Worst", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70875 }, ["description"] = "The rebels in the Emberslate Cavern have an unflinching loyalty to the Primalists, and are therefore the greatest threat to Valdrakken. Eliminate them, and any elementals they have unleashed.", ["objectivesText"] = "Kill 3 rebels and 4 elementals in Emberslate Cavern.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 43847, 43881, 43892, 43930, 43932, 118087, 118088, 118089, 118090, 200087, 200273, 200461, 200462, 200463, 204361, 205992 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196566, ["x"] = 0.424, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196566, ["x"] = 0.424, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70876] = { ["id"] = 70876, ["name"] = "Fracture the Foci", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70876 }, ["description"] = "If Maldra speaks the truth, the rebels are creating the runestones in the Emberslate Cavern. Given the nature of these devices, we know there must be Primalist foci involved. Destroy the foci. You will know them when you see them. The rebels cannot be allowed to create any more weapons of destruction.", ["objectivesText"] = "Destroy 4 Primalist Foci in Emberslate Cavern.", ["rewardGold"] = 262100, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196566, ["x"] = 0.424, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196566, ["x"] = 0.424, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70878] = { ["id"] = 70878, ["name"] = "Ring of Fire", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70878 }, ["description"] = "In the deepest recesses of the Emberslate Cavern, the Primalists erected a fiery portal from which they unleash elementals. I can seal it, but my actions will draw the ire of whatever is on the other side. Including the revenant Magmaticus the Primalists have been aiding. I will need your protection if we are to stop them.", ["objectivesText"] = "Protect Maldra Flametongue while she seals the Primalist portal.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196608, ["x"] = 0.425, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196566, ["x"] = 0.424, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70879] = { ["id"] = 70879, ["name"] = "Report on the Rebels", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70879 }, ["description"] = "I am impressed with what you have accomplished today. I hope you agree, <name>. We have successfully shut down the nefarious activities of these Primalist-allied rebels. For now at least. We will need to keep a close watch on any dissent going forward. Return to Captain Drine at your earliest convenience. She will want our full report.", ["objectivesText"] = "Meet Captain Drine at the top floor of the Seat of the Aspects.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196566, ["x"] = 0.424, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70881] = { ["id"] = 70881, ["name"] = "Fourth Challenge of Tyr: Resourcefulness", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70510, 70899, 70900 }, ["description"] = "The engine is close to reaching its full potential. All it requires now is a power core to process any essence put into it more efficiently. Tyr left the knowledge of such devices with Watcher Irideus. Go into the Halls of Infusion and find him. I am sure he will help you with whatever you need.", ["objectivesText"] = "Obtain a Power Core from Watcher Irideus and defeat the Primal Tsunami in the Halls of Infusion. Progress: You found Watcher Irideus?", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1372, ["name"] = "Tyr's Fourth Challenge", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 14, ["flags"] = 0 } } },
[70899] = { ["id"] = 70899, ["name"] = "Fifth Challenge of Tyr: Ingenuity", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70510, 70881, 70900 }, ["description"] = "As this was not how the Power Core was supposed to be obtained, it requires a re-attunement to the energies of the Engine. The resonance frequencies of the denizens of Tyrhold should bring the core to its full potential once more. Though I do not wish to sacrifice more of my brethren, I believe this is the only way this challenge may be completed.", ["objectivesText"] = "Attune Irideus' Power core with titanic energy from Tyrhold. Progress: How goes your challenge?", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 190453, 198355, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1373, ["name"] = "Releasing Ingenuity", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 15, ["flags"] = 0 } } },
[70900] = { ["id"] = 70900, ["name"] = "Innovating the Engine", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70510, 70881, 70899 }, ["description"] = "Tyr believed that the Engine of Innovation would be necessary for the battles to come. You have proven yourself worthy and overcome all the challenges set before you. You may now unlock the Engine's full potential.", ["objectivesText"] = "Insert the newly attuned Power Core into the Engine of Innovation. Progress: <The Engine hums quietly as you approach>", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1373, ["name"] = "Releasing Ingenuity", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 5, ["flags"] = 0 } } },
[70925] = { ["id"] = 70925, ["name"] = "Community Feast", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 70925 }, ["rewardItems"] = { 200095 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[70930] = { ["id"] = 70930, ["name"] = "All Tea, No Shadeleaf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70930 }, ["description"] = "Today is a celebration of tea - brewed, iced, and otherwise! Extravagant little cakes and biscuits too. But there is a rare ingredient of the Isles I feel could add a whole new dimension of flavor! Deep within the crawler-infested domain of the Shiverweb Vale is a bush laden with the most wondrously uplifting leaf: Coldsnap Sagittate. The Dragonscale Expedition was exploring that area recently. Perhaps one of them could assist?", ["objectivesText"] = "Speak with Lilial Dawnburst in Shiverweb Vale.", ["rewardGold"] = 42450, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185778, ["x"] = 0.516, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[70931] = { ["id"] = 70931, ["name"] = "Whispered Fragments", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70931 }, ["description"] = "I believe Valthrux is trying to communicate to us through the shard we recovered. We can use this to our advantage as long as we keep our minds guarded from the artifact's influence. I was wrong about the Sundered Flame. They have unfortunately collected several shard fragments already. Valthrux's whispers claim they're close to finding its location. Go and recover the shards from the Sundered Flame before they reach the artifact!", ["objectivesText"] = "Recover 40 Whispering Fragments from the Sundered Flame. Progress: The whispers... they're... louder now. Do you have the fragments?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196501, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196501, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70932] = { ["id"] = 70932, ["name"] = "The Life of Spice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70932 }, ["description"] = "To many, meat is essential for any true meal. But what is the essential for any true meat dish? Spice!! A spice that surpasses all others in terms of flavor, texture, and rarity lies within these Isles. Unfortunately, it can only be found on elementals that dwell in the depths of the Obsidian Stronghold. It's an area currently occupied by the Djaradin. Perhaps you can consult with a peculiar troll I met while passing through there. I believe his name was... Griftah .", ["objectivesText"] = "Speak with Griftah at the Obsidian Throne.", ["rewardGold"] = 42450, ["rewardXP"] = 355, ["rewardItems"] = { 197145, 197391, 197613, 203351 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189207, ["x"] = 0.255, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[70934] = { ["id"] = 70934, ["name"] = "Salamanther's Embrace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 2025, ["storyline"] = { 70934 }, ["objectivesText"] = "Glistening Salamanther Hides", ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Glistening Salamanther Hides", ["amount"] = 12, ["type"] = 0, ["objectID"] = 198300, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[70937] = { ["id"] = 70937, ["name"] = "What Valthrux Once Was", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70937 }, ["description"] = "< To'tik whispers to you.> I don't like this. Mysterious artifacts whispering promises of greatness does not sound good. But we can't just walk away... otherwise the Sundered Flame will get their hands on it. Whatever \"it\" is... I'm familiar with ruins like this. The blue dragons often left behind notes on their work. Keep your eyes open, and you may find some around. We can use whatever evidence you find to warn Alia and Kattigat.", ["objectivesText"] = "Find clues regarding what the artifact Valthrux really is. Progress: Did you find anything useful in the ruins?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191715, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 191715, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70941] = { ["id"] = 70941, ["name"] = "Fishing Holes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70871, 70936, 70939, 70940, 70941, 70942, 70943, 70944, 70945, 70948, 70950, 70952, 70953, 70954, 70955, 70956, 70959, 70960, 70961, 70962, 70963, 70964, 70966, 70967, 70968, 70969, 70971, 70972, 70976, 70977, 70978, 72279, 72280, 72281, 72291, 72292, 72318, 72319, 72320, 72321, 72322, 72323, 72324, 72325, 72326, 72327, 72385, 72386, 72387, 72388, 72389, 72390, 72391, 72392, 72393, 72394, 72395, 72584, 72632, 72633, 72634, 72635, 72636, 72637, 72638, 72639, 72640, 72641, 72642, 72875 }, ["description"] = "Hello again! Did you know I'm gonna be the bestest fisherman in the village? I caught a giant piranha once. It tried to eat my face! < Rowie looks around distractedly.> Oh yeah! I have a message for you. Nunvuq , back in Iskaara, wants to tell you about fishing holes .", ["objectivesText"] = "Speak to Nunvuq at Iskaara in The Azure Span. Progress: Are the fish biting?", ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197631, ["x"] = 0.455, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186554, ["x"] = 0.134, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1382, ["name"] = "Iskaara Tuskarr Renown", ["orderIndex"] = 4, ["flags"] = 0 } } },
[70946] = { ["id"] = 70946, ["name"] = "No One May Wield It", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70946 }, ["description"] = "What you found makes it sound like the artifact's power has doomed everyone who has used it so far. The dragonspawn who lived here killed each other over it. The Sundered Flame seem like they're also getting corrupted by its influence too. This isn't an artifact we need to recover. It's one that needs to be destroyed before it can harm anyone else. We must convince Alia and Kattigat.", ["objectivesText"] = "Convince Alia to destroy Valthrux. Progress: Let's hope this works...", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191715, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 191715, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70957] = { ["id"] = 70957, ["name"] = "The Sea Out West", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70957 }, ["description"] = "Enjoying the greenery around our little scenery, <name>? It reminds me of a dish I once tasted from a pair of dryad sisters and their kind treant friend. Sugarbough was their name! A resident of Shady Sanctuary on the western coast of the Plains. It was a medley of fresh herbs, veggies, and spices. At the heart of this dish was the most delicious layer of sea kelp you have ever tasted! What? Never tasted sea kelp before? Well you simply must seek some out. And bring back enough to share, please!", ["objectivesText"] = "Speak with Sugarbough at the Shady Sanctuary in the Ohn'ahran Plains.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186502, ["x"] = 0.285, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[70958] = { ["id"] = 70958, ["name"] = "Finest Fungi at the Feast", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70958 }, ["description"] = "Fine dining is all about using the finest techniques on the finest ingredients, naturally. The food composed for fine dining is oft locked behind wealth and means, but we would never allow that at The Ruby Feast! Morsel has informed me of a perfect ingredient for today's theme. One so rare, so exquisite, that it... does not exist yet! Tantalizing, no? The bronze have uncovered a portal to a dangerous future. One where a black truffle with untold flavor exists! You must go!", ["objectivesText"] = "Speak with Warden Captain Sinjoirmi at the Temporal Conflux in Thaldraszus .", ["rewardGold"] = 42450, ["rewardXP"] = 355, ["rewardItems"] = { 194553 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187025, ["x"] = 0.6045, ["y"] = 0.831 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[70965] = { ["id"] = 70965, ["name"] = "Wanted: Watcher's Golden Girdle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70965 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the Watcher's Golden Girdle for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. You may wish to start your search at our northern dig site, where Elementalist Taiyang has reported a malfunctioning Watcher causing trouble.", ["objectivesText"] = "Find the Watcher's Golden Girdle . Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191983, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 192000, 192001, 192003, 192004, 192005, 192006, 192007, 192009, 192011, 192012, 192013, 192014, 192037, 198490, 198529, 198532, 198695, 200117, 205423, 209837, 217242 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70970] = { ["id"] = 70970, ["name"] = "Good Intentions", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70970 }, ["description"] = "I may know where the artifact is. Alia was whispering frantically when you brought all the shards back. She kept saying something about a \"cave\" and how the spiders seemed attracted to it. There's no cave in the area in front of us... which leads me to believe there might be one deeper in the ruins. We'll stay here and keep your escape path open, <name>. Please save Alia and destroy this cursed artifact.", ["objectivesText"] = "Stop Alia Sunsoar and destroy the artifact Valthrux . Progress: Let's hope this works...", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110, 201290, 201292, 201293 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196520, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196520, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70981] = { ["id"] = 70981, ["name"] = "Savory Seas", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70981 }, ["description"] = "The smell of the sea! Do you smell it, <name>? Do you smell the multitude of minerals, laden with thick sea salt? Do you?? Suspiciously absent from the delights here today is a rare variety of fish I once tasted near the Iskaara's home in Azure Span. Two Tuskarr fellows were simply roasting one over a fire, and it filled that glacial tundra with the most savory aroma! See if you can not find one for us. I know our patrons will be just as ensorcelled by the sea's flavor as I was that day.", ["objectivesText"] = "Speak with Wayun in Whaler's Nook of the Azure Span.", ["rewardGold"] = 42450, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186212, ["x"] = 0.074, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[70986] = { ["id"] = 70986, ["name"] = "Private Shikzar", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 70986 }, ["objectivesText"] = "Private Shikzar defeated", ["rewardXP"] = 5465, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Private Shikzar defeated", ["amount"] = 1, ["type"] = 0, ["objectID"] = 196728, ["orderIndex"] = 0 } }, ["db2VignetteID"] = 5406, ["db2VignetteName"] = "Private Shikzar" },
[70987] = { ["id"] = 70987, ["name"] = "Hearts of Starch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70987 }, ["description"] = "What could be better than a meal you can carry while you explore? Street foods are the essence of busy cities this great world over. But not every meal is set for mobility. The core of great on-the-go cuisines is a starch that will hold strong while moving. Breads, potatoes, rices, and beyond are the heart of hand-sized dining. I would like to treat my Pandaren peer here to a flavorful specimen known as Leapmaize. Morsel introduced it to me when we first met near the titan ruins in the Waking Shores .", ["objectivesText"] = "Speak with Meliane Enorath at the Life Vault Ruins in the Waking Shores .", ["rewardGold"] = 42450, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189400, ["x"] = 0.652, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[70988] = { ["id"] = 70988, ["name"] = "The Egg's the Thing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70988 }, ["description"] = "\"All the world's an egg.\" That is how the saying goes, right? Eggs! They are the core of confections, and one of the great catalysts of culinary creation! They are the fat that puts acids, heats, and salts on their highest pedestals, to their highest potentials! Our Isles are teeming with fowl of immense strength, but the Breezehunters of the Plains lay eggs primed with flavor! They often nest on the Eastern side of the Plains, so ask around the outpost in Rusza'thar Reach.", ["objectivesText"] = "Speak with Ilana at Rusza'thar Reach in the Ohn'ahran Plains .", ["rewardGold"] = 42450, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 196161, ["x"] = 0.858, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[70989] = { ["id"] = 70989, ["name"] = "Part of a Pack", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70989 }, ["description"] = "Perhaps your bakar needs to be shown the proper way to hunt by his own kind. You may borrow some of our trained bakar. Take them and bring down the drake that circles the area. Let us see how Taivan behaves in a pack!", ["objectivesText"] = "Hunt the Ravenous Proto-Drake with Taivan and the pack of hunting bakar. Progress: Have you brought down that drake yet? My bakar should be more than enough for your quarry.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 63850, 63851, 63852, 198537 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 192629, ["x"] = 0.714, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 192629, ["x"] = 0.714, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70992] = { ["id"] = 70992, ["name"] = "Wanted: Lost Tuskarr Kite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70992 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the Lost Tuskarr Kite for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Some expedition members have reported seeing such a kite attached to a tuskarr transport along the western coast, but none have been able to reach it as the transport keeps it aloft and out of reach when traveling.", ["objectivesText"] = "Find the Lost Tuskarr Kite . Progress: Do you have something for the archives?", ["rewardItems"] = { 191983, 191984, 191988, 191989, 191990, 191992, 191993, 191995, 191996, 191997, 191998, 192000, 192001, 192003, 192004, 192005, 192006, 192007, 192013, 192014, 192033, 192037, 197937, 197954, 198490, 198529, 198532, 198695, 200162 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70994] = { ["id"] = 70994, ["name"] = "Drainage Solutions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70994 }, ["description"] = "Want the honor of assisting world-renowned Head Geologist of the Dragonscale Expedition? That's right. I'm exactly who you think I am. And I'm in a bind! I was perusing this river for new sedimentary samples, but then the water started to walk away with the most interesting pieces of silt! I have here my patented water entrapment device, but it's in desperate need of someone to march around and siphon those elementals into it. Think you're up to the task?", ["objectivesText"] = "Siphon 8 Glittery Streams in the cave east of the Life Vault Ruins.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 200747 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 196820, ["x"] = 0.705, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 196820, ["x"] = 0.705, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70995] = { ["id"] = 70995, ["name"] = "Wanted: Fenistrasza's Skull", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70995 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out Fenistrasza's Skull for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Some expedition members have reported seeing it in the possession of an outcast djaradin in the western mountains, but no one has been able to convince him to part with it yet.", ["objectivesText"] = "Find Fenistrasza's Skull . Progress: Do you have something for the archives?", ["rewardItems"] = { 191987, 191988, 191989, 191990, 191994, 191997, 192001, 192010, 192012, 192013, 192037, 197942, 198490, 198532, 198695, 199822, 200143 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70996] = { ["id"] = 70996, ["name"] = "A Little Kelp for My Friends", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70996 }, ["description"] = "Well gosh, it sure sounds like Grimtusk is in a pickle. I'd say I'm done with conflicts on the mainland, but... Frostbite and I have got a history. And a score to settle. Oh, fiddle! I can't leave the others here undefended... We've an issue with an elemental causing trouble at the beach. I'm the only one who can keep him at bay. Slippery fella... literally. Tell you what. If you will deal with the elemental for me, I'll mosey on over to Grimtusk's camp. Whaddaya say, champ?", ["objectivesText"] = "Defeat the Wild Kelp Elemental on Longclaw Island. Progress: How's it going? Did you get that slippery, slimy elemental yet?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196806, ["x"] = 0.012, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196806, ["x"] = 0.012, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.012, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71000] = { ["id"] = 71000, ["name"] = "Barst Recruited", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71000 }, ["description"] = "Well a deal's a deal. If Grimtusk needs a hand killing Frostbite once and for all, then I'm in. What hate I have left in me I reserve for Frostbite. Did Grimtusk tell you what happened? All of us who hunted with Grimtusk thought we were unstoppable. Until we met Frostbite. Frostbite didn't just defeat us. He humiliated us in front of everyone in the hideaway. We were all defeated and left bloodied and battered at the hideaway. Frostbite used us as an example. Now it's time for payback.", ["objectivesText"] = "Let Grimtusk know you've recruited Barst .", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196806, ["x"] = 0.012, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.012, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71009] = { ["id"] = 71009, ["name"] = "Elementary, My Dear Drakonid", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71009 }, ["description"] = "Grimtusk wants to take another crack at Frostbite, eh? I hate to turn him down, but I left that life behind for the life of a scholar. I'm trying to uncover the history--and make history. But I'm stumped by this esoteric riddle here in these ancient ruins. The riddle is this: if you touch a nearby crystal, it says \"follow the pattern.\" But I haven't the faintest idea what that means! Tell you what. If you can help me crack this riddle, I'll go help Grimtusk finish Frostbite off once and for all.", ["objectivesText"] = "Help Varsek solve the mystery of the Ancient Outlook. Progress: \"Follow the pattern.\" What could that mean?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196816, ["x"] = 0.21, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196838, ["x"] = 0.216, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.21, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71011] = { ["id"] = 71011, ["name"] = "Wanted: Torrential Lily", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71011 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the Torrential Lily for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Expedition members have reported seeing a powerful Primalist in Gelikyr Overlook of Thaldraszus with a magical flower pinned to her collar. It is unknown if that is the legendary Torrential Lily , but it is a good place to start your search.", ["objectivesText"] = "Find the Torrential Lily . Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191983, 191986, 191987, 191988, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192012, 192013, 192014, 192015, 192037, 197956, 197957, 198490, 198529, 198532, 198695, 200123, 205423, 209837, 217242 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[71012] = { ["id"] = 71012, ["name"] = "Varsek Recruited", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71012 }, ["description"] = "Seems like I'll be able to solve the mysteries of this place just fine in the future. Let's just never speak of this to Old Grimtusk , OK? I'll make my way to his hideaway. I think I'll enjoy taking out some pent up aggression on Frostbite.", ["objectivesText"] = "Let Grimtusk know you've recruited Varsek .", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196838, ["x"] = 0.216, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71013] = { ["id"] = 71013, ["name"] = "No Vengeance on an Empty Stomach", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71013 }, ["description"] = "Now that we've gotten back to what we aimed to do, we need to have a talk tusk to tusk. That gnoll Frostbite? The one you spoke to? We've got a history with him. This may take awhile to explain. You go and get some fish while I talk, pup. We need to feed everyone. They need their strength for what's next.", ["objectivesText"] = "Fish 3 Frozen Tail Darters within Grimtusk's Hideaway. Progress: It's hard work fishing out here. That's the point.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71014] = { ["id"] = 71014, ["name"] = "A Far Furbolg Friend", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71014 }, ["description"] = "Barst was one of the toughest furbolgs I've ever known. It says something about Frostbite that his pack beat him in a fight. Last I heard, Barst left for some island off the coast of Iskaara. Called it his \"retirement\" or some other garbage. Tell Barst it's time to get back into action. Oh, and don't be fooled by the way he talks. He'll tear you in two if you look at him wrong.", ["objectivesText"] = "Find Barst on Longclaw Island.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196806, ["x"] = 0.012, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71015] = { ["id"] = 71015, ["name"] = "All Brawn, No Brains", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71015 }, ["description"] = "Varsek is one of the toughest drakonids you'll ever meet. One of the dumbest ones too, but he'll never admit that. He got spooked after Frostbite and started re-evaluating his life or... something. Said he never got to study the ruins left behind by his ancestors. Ran off to be a \"scholar\". Get Varsek back here. He doesn't belong there anyhow!", ["objectivesText"] = "Find Varsek in the Ancient Outlook.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196816, ["x"] = 0.21, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71016] = { ["id"] = 71016, ["name"] = "Grimtusk's Sister", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71016 }, ["description"] = "Last is my sister, Naluki . She helps run the inn at Iskaara now. Just give her this letter. Don't open it.", ["objectivesText"] = "Deliver Grimtusk's letter to his sister, Naluki , in Iskaara.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196841, ["x"] = 0.356, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71017] = { ["id"] = 71017, ["name"] = "Naluki's Letter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71017 }, ["description"] = "Let me guess, Grim told you not to open the letter, right? Looks like you did as you were told. No wonder he trusts you so much! Give him this fish head for me. He'll know what it means.", ["objectivesText"] = "Deliver Naluki 's fishhead to Old Grimtusk .", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196841, ["x"] = 0.356, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71022] = { ["id"] = 71022, ["name"] = "Reign of the Ram", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71022 }, ["description"] = "Since the argali don't seem to have much respect for Taivan, we should see if he can handle the herd's ram next. He's the boss of all the argali here, and quite the stubborn thing. If Taivan can assert dominance over the ram, the herd will start obeying him. You can find him just over there, on the hill. Good luck, Taivan. If this doesn't work, I'm afraid there's not much hope for him being a herder!", ["objectivesText"] = "Command Taivan to confront the herd's Stubborn Ram . Progress: The herd's ram is on the hill just over there. Hopefully Taivan handles this task a little better.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 198537 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 192633, ["x"] = 0.49, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 192633, ["x"] = 0.49, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[71024] = { ["id"] = 71024, ["name"] = "Chaos and Commotion", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71024 }, ["description"] = "<name>! Did you hear the noise? There has been an incident on the bottom floor. One of my trusted investigators, Erima, was there first. He will require assistance gathering evidence while he tries to interview the crowd.", ["objectivesText"] = "Help Erima investigate the incident at the bottom floor of the Seat of the Aspects. Progress: May I see that map?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196984, ["x"] = 0.565, ["y"] = 0.4365 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5676, ["y"] = 0.4108 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[71027] = { ["id"] = 71027, ["name"] = "WANTED: Mara'nar the Thunderous", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71027 }, ["description"] = "Looking for a mighty hunter to take down a rampaging beast! A thunder lizard named Mara'nar the Thunderous worked his way from Thunderspine Thicket to Primordial Vale, disrupting local wildlife. It has electrified water, knocked down trees, and broken duck nests. This menace must be stopped. Slay him and bring one of his plates to Khansguard Jebotai as proof. May Ohn'ahra guide you.", ["objectivesText"] = "Slay Mara'nar the Thunderous in Primordial Vale and retrieve one of his plates. Progress: Hail, traveler.", ["rewardGold"] = 842700, ["rewardXP"] = 4150, ["rewardItems"] = { 200270 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187787, ["x"] = 0.418, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
[71135] = { ["id"] = 71135, ["name"] = "Loose Ends", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71135 }, ["description"] = "If there's anything I learned from my time out in the wilderness, it's that if you don't deal with an evil when you find it--if you don't break its bones and dig up its roots, it'll keep growing. And then it'll be harder to kill. These mountains were plagued with Frostbite 's existence when I was a young pup like you, and it will only get worse once he takes full control of the Snowhide tribe. I should have done something about him long ago, but we're the only ones who can right that mistake now.", ["objectivesText"] = "Confront Frostbite at the Snowhide Camp in the Azure Span . Progress: We cannot rest until Frostbite and the Snowhide gnolls have been dealt with.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 200220, 202201, 204254 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71141] = { ["id"] = 71141, ["name"] = "Gills with Gall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71141 }, ["description"] = "Kad'irsza is reckless, but she knows her crabs. The gorlocs have gone too far! I noticed the gorlocs going to Gurblbrblr for everything. Notably, he is instructing them to take crabs prisoner. We cannot allow this to continue, for the balance of life, and for the safety of those who tend it. Defeat Gurblbrblr. Remove their means of expanding beyond this river!", ["objectivesText"] = "Kill Gurblbrblr the Invader in Cliffdrip Camp. Progress: Do not permit the gorlocs to encroach on the wildlife!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193304, ["x"] = 0.596, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193304, ["x"] = 0.596, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[71152] = { ["id"] = 71152, ["name"] = "Back to the Main Hall", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66173, 66174, 66546, 66547, 66636, 67722, 69097, 71152 }, ["description"] = "Now that we've accessed the override consoles, we should be able to get past that barrier. I'll meet ye back in the main hall and we'll see this through!", ["objectivesText"] = "Rendezvous with Toddy in the main hall.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 193374, ["x"] = 0.572, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192820, ["x"] = 0.55, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1374, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1374, ["name"] = "In the Halls of Titans", ["orderIndex"] = 5, ["flags"] = 0 } } },
[71164] = { ["id"] = 71164, ["name"] = "Stolen Bandages", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 71164 }, ["objectivesText"] = "Medical Supplies", ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13647 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Medical Supplies", ["amount"] = 8, ["type"] = 2, ["objectID"] = 382043, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[71179] = { ["id"] = 71179, ["name"] = "Look to the Overlook", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71179 }, ["series"] = { 66468, 66470, 66471, 66472, 66473 }, ["description"] = "<name>, I have another task for you. There have been reports of Primalist activity near the Gelikyr Post that threaten our control of Tyrhold. Speak with Commander Thadezus and see how you can assist.", ["objectivesText"] = "Speak with Commander Thadezus at the Gelikyr Overlook.", ["rewardGold"] = 26915, ["rewardXP"] = 685, ["rewardItems"] = { 192795, 192808, 200670, 200671, 200672 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189174, ["x"] = 0.526, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5676, ["y"] = 0.4108 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[71182] = { ["id"] = 71182, ["name"] = "Wayward Archivists", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "You, dracthyr. Two of your kin have been searching the archives just south of here. I have yet to introduce myself, and would appreciate the company. If you have the time, I can meet you in the upper archive.", ["objectivesText"] = "Meet Sindragosa in the upper archive in the Azure Archives.", ["rewardGold"] = 42450, ["rewardXP"] = 1030, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197378, ["x"] = 0.424, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 19, ["flags"] = 0 } } },
[71195] = { ["id"] = 71195, ["name"] = "To Tame A Thunderspine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71195 }, ["description"] = "I guess this is Lizi's new favorite spot. She hasn't been interested in coming back home. After all, she is a wild beast. I have to tell you... I haven't spoken to Meluun since we saved Lizi. I know she was right, but I don't know how to approach her. She doesn't seem to approve of anything I do. I know I have to focus more on my training. Meluun makes a stomping good curry that Lizi would love. Do you think you could ask her for it? She's usually working in the Ohn's house west of the springs.", ["objectivesText"] = "Collect Meluun's Green Curry in the Ohn'iri Springs and 150 Dragon Isles Supplies . Progress: Did you talk to Meluun yet?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192615, 192636, 192658, 192799, 194966, 200598 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[71196] = { ["id"] = 71196, ["name"] = "To Tame A Thunderspine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71196 }, ["description"] = "I'm so happy that Lizi is safe and sound with us. However, her wounds are healing slower than expected. I hope that the magic inflicted upon her didn't cause permanent damage. Could you help me gather insect ichor? I know, it sounds gross! It's actually the base of many healing ointments.", ["objectivesText"] = "Collect 20 Fluorescent Fluid from insects around the Dragon Isles and 150 Dragon Isles Supplies . Progress: Have you returned with more ichor? I hate to see Lizi still in pain.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192615, 192636, 192658, 192799, 194966, 200598 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[71197] = { ["id"] = 71197, ["name"] = "To Tame A Thunderspine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71197 }, ["objectivesText"] = "Progress: Lizi is healed, but she's still nervous about leaving her spot. In the wild, she'd forage about a musken's weight of plants a day. It's impossible for me to do that! We need her to move out of the water and to the grasses. I'll keep trying to coax her out, but in the meantime, could you help me forage? I hear there are especially nutritious high-fiber leaves in the Emerald Gardens. Please bring back any you can find!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192615, 192636, 192658, 192799, 194098, 194966, 200598 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[71198] = { ["id"] = 71198, ["name"] = "To Tame A Thunderspine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71198 }, ["objectivesText"] = "Progress: Lizi's doing so much better. She's moving around with ease and consuming everything edible in sight. I learned today that thunderspines enjoy eating fish--especially piranhas! How fascinating! It is how they keep the piranha population in check at home. Will you go fish some? Mind your fingers!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192615, 192636, 192658, 192799, 194966, 200598 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[71199] = { ["id"] = 71199, ["name"] = "To Tame A Thunderspine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71199 }, ["objectivesText"] = "Progress: Everyone is curious about Lizi, but the truth is, she sticks out like a sore hoof. Lizi herself is starting to wander more and more, as if she's looking for something. She mostly rests by the water on the mud. I'm sure it's fine, but I know thunderspines like to make a bedding from grasses. I've got an idea better than grasses. Will you help me gather wool from the plains? I'll weave her a blanket and some toys.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192615, 192636, 192658, 192799, 194966, 200598 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[71209] = { ["id"] = 71209, ["name"] = "Beast of the Plains", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71209 }, ["description"] = "I think Lizi is ready to be a beast of the plains again. She's so friendly to you and I now, but I can tell she wants to return to the wild. One day, when I am a Windsage, I will explore all of the world beyond these springs. But first--my midseason initiate trials! How time flies. I made a saddle and reins from the wool you gathered. Lizi will be happy to come at your call. Please take her on all the adventures, $p.", ["objectivesText"] = "Accept Lizi's Reins .", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 192799 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[71212] = { ["id"] = 71212, ["name"] = "Attackin' the Brackenhide", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite", "rare" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71212 }, ["objectivesText"] = "Disrupt the Brackenhide", ["rewardXP"] = 5145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Disrupt the Brackenhide", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["db2QuestInfoID"] = 136, ["db2QuestInfoName"] = "Rare Elite World Quest" },
[71219] = { ["id"] = 71219, ["name"] = "The Wayward Waywatcher", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71219 }, ["series"] = { 66100, 66448 }, ["description"] = "It seems some of our younger Waywatchers have grown lax in their duties of late. Waywatcher Nori has asked me to check in on her younger sister Alvi, who is stationed at the mouth of the Passage of Time. Apparently her recent performance has been less than satisfactory. If you head east and happen to encounter Waywatcher Alvi , please remind her of the importance of her position, and let her know that her sister is rather worried about her.", ["objectivesText"] = "Find Waywatcher Alvi .", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 191308, 191317, 191405, 191852 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197533, ["x"] = 0.5015, ["y"] = 0.6195 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 191753, ["x"] = 0.546, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5015, ["y"] = 0.6195 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[71232] = { ["id"] = 71232, ["name"] = "Renown of the Dragon Isles", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "There is still much that must be done to aid the Dragon Isles. I would ask you speak with Koszaru . He has much information regarding who needs help within this land.", ["objectivesText"] = "Speak with Koszaru within Valdrakken.", ["rewardGold"] = 34100, ["rewardXP"] = 1190, ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 0, ["flags"] = 0 } } },
[71233] = { ["id"] = 71233, ["name"] = "Falling Water", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71233 }, ["description"] = "I love waterfalls. Want to know what's better than a waterfall? Two waterfalls. And the only thing better than that is... well, check out Three-Falls to the west of here and you'll see! The innkeeper there is quite nice.", ["objectivesText"] = "Talk to Willa at Three-Falls Lookout in the Azure Span .", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194613, ["x"] = 0.284, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190315, ["x"] = 0.188, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71234] = { ["id"] = 71234, ["name"] = "Nook News", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71234 }, ["description"] = "You there, <race>. You look well-travelled. My cousin Wayun was bringing a catch over from Whaler's Nook and mentioned that some... strange folk have set up camp over there. They appear to be behaving themselves, but would you mind checking in on Wayun ? He can be a bit salty.", ["objectivesText"] = "Visit Whaler's Nook in the Azure Span .", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193877, ["x"] = 0.14, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186212, ["x"] = 0.074, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.14, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71235] = { ["id"] = 71235, ["name"] = "Field Mages", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71235 }, ["description"] = "Lok'tar, <race>. If you have the time, we have two mages doing fieldwork nearby who I'm sure could use a hand. This is a dangerous land in the best of times. These are not the best of times.", ["objectivesText"] = "Check on the Kirin Tor mages near Slyvern Plunge in the Azure Span .", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189751, ["x"] = 0.658, ["y"] = 0.254 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192825, ["x"] = 0.646, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.254 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71238] = { ["id"] = 71238, ["name"] = "The Ruby Feast!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71238 }, ["description"] = "Attention to all aspiring culinarians! Does your heart desire the ultimate flavors of this world? Do you seek out opportunities for grand exploration? Are you willing to risk life and limb for complete strangers? If this is you, come speak with the eminently distinguished, world-renowned chef duo, Rumiastrasza and Morsel! Currently hosting The Ruby Feast in the city of Valdrakken !", ["objectivesText"] = "Speak with Chefs Rumiastrasza and Morsel at The Ruby Feast.", ["rewardGold"] = 4365, ["rewardXP"] = 355, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72023] = { ["id"] = 72023, ["name"] = "Dragon Isles Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70335, 70807, 70808, 70809, 70810, 70812, 70813, 70814, 70815, 70817, 70818, 70819, 70820, 70821, 70822, 70828, 70831, 70832, 70833, 70834, 70835, 72023, 72024, 72025, 72026, 72032, 72033, 72034, 72035, 72036, 72037, 72038, 72039, 72040, 72041, 72042, 72043, 72044, 72045, 72046, 72047, 72048, 72294, 72295, 72299, 72300, 72301, 72302, 72303, 72304, 72305, 72306, 72308, 72309 }, ["rewardItems"] = { 198863, 198865, 198866, 198867, 199472, 199473, 210501 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1380, ["name"] = "Dragonscale Expedition Renown", ["orderIndex"] = 1, ["flags"] = 0 } } },
[72067] = { ["id"] = 72067, ["name"] = "Relaxation Time!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72067 }, ["description"] = "You there! You look exhausted. Worn down. In extreme need of some R&R. I have just the thing! The Serene Dreams Spa is the place for you! Enjoy our new you-ga classes, they are AMAZING! Or perhaps a mud mask facial treatment is more your speed? I recommend both! To get to the spa, head north just out of the city!", ["objectivesText"] = "Go to the Serene Dreams Spa.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 200586 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197986, ["x"] = 0.478, ["y"] = 0.594667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 197670, ["x"] = 0.404, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.594667 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72068] = { ["id"] = 72068, ["name"] = "Aiding the Accord: A Feast For All", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies require your aid, <name>! Your efforts throughout the Isles have not gone unnoticed. Our trusted allies to the south, the Iskaara Tuskarr , seek to celebrate your accomplishments with a feast of all feasts! Journey to the lands of Iskaara whilst continuing your work alongside the allies of the Accord. When you reach the shimmering waters of the southern lands do not hesitate to participate in the celebrations!", ["objectivesText"] = "Travel to Iskaara in The Azure Span and participate in a Community Feast. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Back so soon? Where does the time go?", ["rewardXP"] = 2125, ["rewardItems"] = { 190454, 192017, 200072, 200073, 201921, 201922, 201923, 201924, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 3, ["flags"] = 1 } } },
[72122] = { ["id"] = 72122, ["name"] = "Erstwhile Ecologists", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72122 }, ["description"] = "The wounded are stabilized, but something still troubles me, <name>. A pair of dragonspawn ecologists had come to the outpost to study the wetlands. I haven't seen scale nor claw of them since the attack, and it's become worrisome. If you're venturing out, would you mind keeping an eye out, and making sure they're safe? And do take care. Rumor has it those wetlands are gorloc-infested.", ["objectivesText"] = "Check in on the wayward ecologists.", ["rewardGold"] = 1745, ["rewardXP"] = 175, ["rewardItems"] = { 191546, 191549 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 195303, ["x"] = 0.712, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186410, ["x"] = 0.744, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72189] = { ["id"] = 72189, ["name"] = "Garden Variety", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72189 }, ["description"] = "Are you enjoying the butterfly garden? You know, there's a much larger garden just to the south of here. An older drakonid by the name of Gryrmpech tends to it. He could always use an extra pair of hands. He has an 'assistant', but I've never actually seen him. I can't imagine he's of much help. If you stop by, be sure to let him know that Xina sent you.", ["objectivesText"] = "Speak with Gyrympech.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189364, ["x"] = 0.774, ["y"] = 0.6672 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.6672 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72190] = { ["id"] = 72190, ["name"] = "Reservoir Reservations", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72190 }, ["description"] = "<class>! I know someone who is in dire need of your skills. Tyrhold Reservoir has just been attacked by Primalists. I was lucky to make my escape when I did. I fear the others may not be so lucky. It's just to the north of here. Find Zuttiki , she'll be able to fill you in on the details. If she's still alive, that is.", ["objectivesText"] = "Find Zuttiki .", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 193043 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 198349, ["x"] = 0.255, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190527, ["x"] = 0.495, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.255, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72192] = { ["id"] = 72192, ["name"] = "Halls of Infusion: Entropy to Order", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72192 }, ["description"] = "The Primalists wish to bring elemental chaos back to this world and will stop at nothing to see their goal accomplished. I have received disturbing news that they have infiltrated the Halls of Infusion deep below Tyrhold. They attempt to disrupt the works of Keeper Tyr for their own nefarious purposes. Please, you must put an end to any Primalist threat within those sacred halls, <name>.", ["objectivesText"] = "Enter the Halls of Infusion and defeat the Primal Tsunami. You can access the Halls of Infusion solo by queuing for it in Follower Dungeons. Progress: Have you cleared the halls of Primalist threat, <name>?", ["rewardGold"] = 1123600, ["rewardXP"] = 10930, ["rewardItems"] = { 193725, 193726, 193731, 193735, 193738, 193743 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191369, ["x"] = 0.545, ["y"] = 0.4135 }, { ["mapID"] = 2112, ["npcID"] = 197206, ["x"] = 0.586, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191369, ["x"] = 0.545, ["y"] = 0.4135 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.4135 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "dungeon" },
[72193] = { ["id"] = 72193, ["name"] = "The Algeth'ar Academy", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14032, ["mapID"] = 2112, ["storyline"] = { 72193 }, ["description"] = "I understand that the Algeth'ar Academy is open to the world once more. Long ago, its sacred halls were only open to dragons, but in the years that have passed the Headteacher has seen the wisdom of welcoming any who wish to learn. She has asked for my recommendation on any promising new students. As a great ally to dragonkind, it would be an honor to have you attend our great academy. I leave the decision to enroll up to you, but I am sure Doragosa would love to at least give you a tour.", ["objectivesText"] = "Tour the grounds of Algeth'ar Academy. You can access Algeth'ar Academy solo by queuing for it in Follower Dungeons. Progress: I hope you enjoy your time at the Academy. It really is a remarkable place.", ["rewardGold"] = 1123600, ["rewardXP"] = 19030, ["rewardItems"] = { 193704, 193705, 193708, 193712, 193720, 193721 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187676, ["x"] = 0.609333, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187676, ["x"] = 0.609333, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.609333, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 14032 } }, ["questType"] = "dungeon" },
[72240] = { ["id"] = 72240, ["name"] = "The Obsidian Warders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 70050, 72240 }, ["description"] = "This Toddy's enthusiasm is admirable. But I hope it does not blind her to the dangers awaiting us in the Dragon Isles . Regardless, the Obsidian Warders are duty-bound to protect the expedition. I must speak with Wrathion and the Lord Commander about the mission ahead. My fellow dracthyr are exploring the city. Seek out Dervishian, my trusted lieutenant, and inform her that we are to rally at the docks. She will relay my orders to the rest.", ["objectivesText"] = "Deliver the scalecommander's orders to Dervishian and the Obsidian Warders. Progress: Ye think a dracthyr can fly faster than a gryphon?", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 192493, 199109, 199211, 199337, 199686, 199836, 199837, 199838, 199839, 202188 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 189603, ["x"] = 0.798, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 189077, ["x"] = 0.228, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.798, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 8, ["flags"] = 0 } } },
[72241] = { ["id"] = 72241, ["name"] = "Lessons From Our Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "I am Emberthal, a scalecommander of the dracthyr. Wrathion aided us after we awakened from our long stasis, and now it is my turn to help him. No doubt you have questions about my people and our history. Until recently, I did as well. But Nozdormu, the Timeless One, has revealed lost truths about the dracthyr. He granted me a vision of our origins... and why we were locked away. Let me tell you of the things I have seen.", ["objectivesText"] = "Speak with Scalecommander Emberthal . Progress: There is much we can learn from one another.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192795, ["x"] = 0.424, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192795, ["x"] = 0.424, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 32, ["flags"] = 0 } } },
[72246] = { ["id"] = 72246, ["name"] = "Serene Dreams", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72246 }, ["description"] = "Welcome to the Serene Dreams Spa! I must apologize. We are not able to admit new guests at this time due to circumstances beyond our control. Let me refer you to the Spa Manager, Xijan Thornpaw . He is qualified to answer all your questions.", ["objectivesText"] = "Speak to the spa manager.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 200586 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 197670, ["x"] = 0.404, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 194717, ["x"] = 0.404, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[72256] = { ["id"] = 72256, ["name"] = "The Dark Talons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 72256 }, ["description"] = "Naleidea is enthusiastic, but she's a historian, not a soldier. She knows nothing of the dangers we'll face in the Dragon Isles . Not that anyone needs to worry. After all, the Dark Talons will be protecting the expedition. I'm going to discuss mission logistics with Ebyssian and your Horde leaders. My lieutenant, Kodethi, is exploring the city along with the other dracthyr. Be a good soldier and let him know we are going to rally at the zeppelin tower. He'll relay my orders to the others.", ["objectivesText"] = "Deliver the Scalecommander's orders to Kodethi and the Dark Talons. Progress: Do you suspect that a dracthyr could outpace a boat over the entire trip to the Dragon Isles ? Exhaustion would take its toll, surely?", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 184786, ["x"] = 0.442, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 197279, ["x"] = 0.558, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 9, ["flags"] = 0 } } },
[72266] = { ["id"] = 72266, ["name"] = "The Waking Shores", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 65760, 65791, 65793, 65794, 65939, 65956, 65957, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66354, 66779, 66780, 66785, 66788, 66931, 68795, 68796, 68798, 68799, 70061, 72241, 72266, 77345 }, ["description"] = "The drakonid Sendrax is looking for help in aiding all of the newcomers within the Waking Shores .", ["objectivesText"] = "Meet with Sendrax within the Waking Shores .", ["rewardGold"] = 715, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2AdventureMapPoiID"] = 181, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 51, ["flags"] = 1 } } },
[72267] = { ["id"] = 72267, ["name"] = "Ohn'ahran Plains", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66340, 66344, 66783, 66784, 66848, 66948, 66969, 70174, 70185, 70195, 70220, 70229, 70244, 72267, 72429 }, ["description"] = "The green dragonflight needs the aid of adventurers. To do so, you must ally with the centaur of the plains. Ambassador Taurasza can be of aid.", ["objectivesText"] = "Meet Ambassador Taurasza in the Rubyscale Outpost.", ["rewardGold"] = 1230, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185878, ["x"] = 0.482, ["y"] = 0.885 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.885 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2AdventureMapPoiID"] = 182, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 54, ["flags"] = 1 } } },
[72268] = { ["id"] = 72268, ["name"] = "Azure Span", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "The Kirin Tor need all the help they can get tracking down the Blue Dragon Oathstone. Some of their mages have been spotted in the Ohn'ahran Plains looking for help.", ["objectivesText"] = "Speak with Masud the Wise within the Ohn'ahran Plains.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 197989 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185599, ["x"] = 0.716, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2AdventureMapPoiID"] = 183, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 51, ["flags"] = 1 } } },
[72269] = { ["id"] = 72269, ["name"] = "Thaldraszus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "Alexstrasza the Life-Binder is arranging a meeting of the Seat of the Aspects to discuss the threat of the Primalists. She has put out a call for any willing adventurers to come help.", ["objectivesText"] = "Travel to Valdrakken and meet with Alexstrasza the Life-Binder .", ["rewardGold"] = 1230, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2AdventureMapPoiID"] = 184, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 50, ["flags"] = 1 } } },
[72293] = { ["id"] = 72293, ["name"] = "Adventuring in the Dragon Isles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65436, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 66577, 66589, 66596, 67700, 69910, 69911, 69912, 69914, 69944, 70050, 70122, 70123, 70124, 70125, 70197, 70198, 72240, 72256, 72293 }, ["description"] = "Oh, I know what you can do! The Dragonscale Expedition has posted a very fine looking map of the Dragon Isles nearby. Their drawings are quite accurate and detailed, if I do say so myself. Sorry, you're not here for an art review. You should go check it out to see what areas of the Dragon Isles could use your help!", ["objectivesText"] = "Review the Scouting Map to choose an area within the Dragon Isles to support.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 210469 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 27, ["flags"] = 1 } } },
[72373] = { ["id"] = 72373, ["name"] = "Aiding the Accord: The Hunt is On", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies from the Ohn'ahran Plains have sent word-a request-for any and all who hunt these lands to lend their aid to their cause. Whilst continuing your efforts across these Isles, pay a visit to our allies at one of their hunting camps and assist in their efforts. There is much to be done. Best not delay.", ["objectivesText"] = "Assist the Maruuk on a Hunt within the Dragon Isles. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Has our renowned traveler returned with more news of success?", ["rewardXP"] = 2125, ["rewardItems"] = { 190454, 192017, 200072, 200073, 201921, 201922, 201923, 201924, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 4, ["flags"] = 1 } } },
[72374] = { ["id"] = 72374, ["name"] = "Aiding the Accord: Dragonbane Keep", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future. Now then, to business. A lingering djaradin threat moves upon the Waking Shores deep within the smoldering inferno of Dragonbane Keep. We must move to disrupt their advances. We await your return, <name>.", ["objectivesText"] = "Travel to The Waking Shores and lay siege to Dragonbane Keep. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Do you bring news of your success?", ["rewardXP"] = 2125, ["rewardItems"] = { 190454, 192017, 200072, 200073, 201921, 201922, 201923, 201924, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 5, ["flags"] = 1 } } },
[72380] = { ["id"] = 72380, ["name"] = "Together We Are Unstoppable", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14617, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66675, 66847, 67073, 70437 }, ["description"] = "<name>, you must tell Alexstrasza and Nozdormu what has happened. Khadgar and I will meet you at the Seat of the Aspects momentarily.", ["objectivesText"] = "Return to the Seat of the Aspects and inform Alexstrasza about what happened after the defeat of Raszageth in the Vault of the Incarnates. Progress: What has happened, <name>?", ["rewardGold"] = 1123600, ["rewardXP"] = 10930, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 14617 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 53, ["flags"] = 0 } } },
[72397] = { ["id"] = 72397, ["name"] = "Orientation: Dragonscale Basecamp", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72397 }, ["description"] = "Welcome to basecamp, $p. It took Toddy and me awhile to settle on the perfect site to establish camp, but I couldn't be happier with our selection. Easy access to ruins, proto-dragon breeding grounds, and of course the dragonflights. Why not take a few minutes to explore the camp and meet some of the suppliers helping to fuel the expedition?", ["objectivesText"] = "Meet the important suppliers in the Dragonscale Basecamp. Progress: Welcome to camp, <name>!", ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186869, ["x"] = 0.478, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187276, ["x"] = 0.472, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72406] = { ["id"] = 72406, ["name"] = "Orientation: Valdrakken", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72406 }, ["description"] = "Welcome to Valdrakken, $p. I am Unatos , Keeper of Renown for the Valdrakken Accord. In recognition of your assistance to the dragonflights, a number of suppliers around the city have been authorized to supply you with some of our finest wares. Why not take some time to familiarize yourself with their locations and wares?", ["objectivesText"] = "Meet the important Accord suppliers in Valdrakken. Progress: Welcome Valdrakken, <name>.", ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193015, ["x"] = 0.58, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193015, ["x"] = 0.58, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72411] = { ["id"] = 72411, ["name"] = "Cause Without a Rebel", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "Good to see you again, <name>! Alexstrasza doesn't think we can stop the rebels effectively through force, despite the successes you've had. To find other ways forward, Alexstrasza has called Maldra Flametongue here to talk about the rebellion and what drew her to it. Perhaps it would be helpful to join the conversation, and see what Maldra has to say. To avoid prying rebel eyes and ears, they will be meeting below us, on the second level of the Seat of the Aspects.", ["objectivesText"] = "Listen to Alexstrasza's conversation with Maldra Flametongue.", ["rewardGold"] = 280900, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 200754, ["x"] = 0.555, ["y"] = 0.3365 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5676, ["y"] = 0.4108 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 0, ["flags"] = 0 } } },
[72412] = { ["id"] = 72412, ["name"] = "Explosive Interruption", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "I managed to infiltrate a rebel camp, down in Scalewatch Cavern. It seemed like any other camp, except for frequent wagons coming into camp with their contents covered. Eventually, I was able to discreetly make my way to where the wagons would be unloaded. The rebels are stockpiling bombs, but it's even worse! They're piling the bombs against a pillar directly underneath the aqueduct from Tyrhold. Meet me down there, and we'll find a way to stop this!", ["objectivesText"] = "Meet Erima at Scalewatch Caverns.", ["rewardGold"] = 16980, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 200754, ["x"] = 0.555, ["y"] = 0.3365 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199397, ["x"] = 0.464, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.3365 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 1, ["flags"] = 0 } } },
[72413] = { ["id"] = 72413, ["name"] = "Irreconcilable Differences", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "I wish we never had to raise arms against fellow dragonkin, <name>. We should be allies, not enemies. Unfortunately, their leader, Agitator Zoralek , made the choice for us when he threatened the aqueduct. Fight your way inside the cave, and put a stop to Agitator Zoralek by any means necessary, before he can set off those bombs. Then bring back his detonator so we can secure it. Once we have that, the Scalesworn will be able to remove the bombs safely.", ["objectivesText"] = "Kill Agitator Zoralek and recover the detonator. Progress: Were you able to stop Zoralek? Is the aqueduct safe?", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 204407 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199397, ["x"] = 0.464, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199397, ["x"] = 0.464, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 2, ["flags"] = 0 } } },
[72414] = { ["id"] = 72414, ["name"] = "Know Prisoners!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "If Alexstrasza truly wants to find the causes of this rebellion, we need to hear out the rebels. To do that, we have to safely detain rebels who want to kill us. Well, you. That's much harder than resorting to violence, and more dangerous as well. But I've experienced this when I left the rebels. Orian Darkwater cast a spell to bind me totally. It worked, and I paid close attention. I've imbued that spell into a ring. You can use it to bind them safely. It should work, anyway!", ["objectivesText"] = "Use Maldra's Ring of Binding to detain 8 rebels.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 202855 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199396, ["x"] = 0.464, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199396, ["x"] = 0.464, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 3, ["flags"] = 0 } } },
[72415] = { ["id"] = 72415, ["name"] = "Rebel Rousing Writings", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "The rebels seem to have a lot of signs and flyers around the cave. They probably use it as a way to keep everyone aligned to their purpose, and motivated to fight. It's hard to keep a large group united around a cause - especially if you use detestable methods like bombing civilians or destroying a water source - without a steady stream of reinforcement. Let's get a bunch of their propaganda. It may tell us a lot about what they're thinking, or who's telling them what to think.", ["objectivesText"] = "Gather 5 pieces of rebel propaganda. Progress: Have you gotten a good sample of their writings?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 202698, 202699, 202700, 202701, 202702 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199396, ["x"] = 0.464, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199396, ["x"] = 0.464, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 4, ["flags"] = 0 } } },
[72416] = { ["id"] = 72416, ["name"] = "Temporary Accommodations", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "We've been sending the rebel prisoners to Steelcliff Rampart. It's the barracks where Valdrakken's city guard, the Scalesworn, are based. So there are plenty of guards to keep them from causing harm or escaping. Head over there and we'll see what the next steps are in putting a permanent stop to this rebellion.", ["objectivesText"] = "Go to Steelcliff Rampart.", ["rewardGold"] = 16980, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199396, ["x"] = 0.464, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199382, ["x"] = 0.388, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 5, ["flags"] = 0 } } },
[72417] = { ["id"] = 72417, ["name"] = "Persistent Dissidents", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "My goal is to see this rebellion brought to an end, with as little violence as possible. To do that, I need to understand the root causes of this rebellion. The rebels have clearly come to resent the Aspects and the dragonflights. And while we had to use force to protect Valdrakken, that hasn't brought about an end to the rebellion. I'd like you to speak to the prisoners, and ask why they rebelled. I'll accompany you to hear their reasons.", ["objectivesText"] = "Ask 5 dragonkin why they rebelled.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199382, ["x"] = 0.388, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 201211, ["x"] = 0.388, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 6, ["flags"] = 0 } } },
[72418] = { ["id"] = 72418, ["name"] = "Solicited Opinions", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "That was enlightening, to say the least. The rebels we talked to had a lot to say which I wouldn't have anticipated. I have my thoughts on the situation, but what did you think of their grievances? As neither a dragon nor dragonkin, you bring a certain objectivity to the matter.", ["objectivesText"] = "Discuss the rebels' grievances with Alexstrasza. Progress: Is there merit to what the dragonkin say, or only dereliction of duty?", ["rewardGold"] = 169800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 201211, ["x"] = 0.388, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 201211, ["x"] = 0.388, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 7, ["flags"] = 0 } } },
[72419] = { ["id"] = 72419, ["name"] = "Cleaning up the Cliffraff", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "<name>! Maldra has been going through the propaganda you retrieved, using ciphers she knew from her days as a rebel. She found a coded message that led her to another rebel camp, where Belaphon is stirring up rebellion among anyone she can. Maldra and Inspector Erima are already there - go join them and let's see if we can finally put a stop to this rebellion!", ["objectivesText"] = "Meet Maldra and Erima at the Rebellious Cliffs.", ["rewardGold"] = 16980, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200788, ["x"] = 0.388, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199301, ["x"] = 0.464, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 8, ["flags"] = 0 } } },
[72420] = { ["id"] = 72420, ["name"] = "Wreckonciliation", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "Captain Drine informed me that Alexstrasza wants this done as peacefully as possible. And I've heard Alexstrasza is considering granting the Dragonkin more rights. Or even freedom. Instead of fighting our way through all these rebels when peace may be on the horizon, let's spread the word! Tell the dragonkin here that things are changing. Perhaps some will lay down their arms or choose to leave. But be prepared to deal with those who insist on fighting.", ["objectivesText"] = "Inform 12 dragonkin of Alexstrasza's planned changes. Progress: Remember, each dragonkin you convince is a life you've saved.", ["rewardGold"] = 169800, ["rewardXP"] = 5465, ["rewardItems"] = { 203383, 203390 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199301, ["x"] = 0.464, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199301, ["x"] = 0.464, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 9, ["flags"] = 0 } } },
[72421] = { ["id"] = 72421, ["name"] = "The Quill to Power", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "<name>, we need to stop the quills from inciting the rebels long enough for us to be heard. Their leader, Belaphon, seems to be giving the quills a degree of autonomy with that glowing staff. Gather up as many as you can, so they can't keep reproducing her words. Once they're out of commission, we'll confront her directly - but we don't want the quills to scatter and continue spreading these messages.", ["objectivesText"] = "Gather 6 enchanted quills . Progress: How many quills have you found, <name>?", ["rewardGold"] = 169800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199391, ["x"] = 0.464, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199391, ["x"] = 0.464, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 10, ["flags"] = 0 } } },
[72422] = { ["id"] = 72422, ["name"] = "Stop the Presses", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "This is it, <name>. As the one propagating the ideas that drive the rebellion, if we can stop Belaphon, we'll see the end of the rebellion. Try to bind her with my ring, though you'll likely need to weaken her first. If she's willing to surrender, we'll bring her to Alexstrasza. I imagine the Queen of Dragons will have a lot of very choice words when they meet.", ["objectivesText"] = "Instigator Belaphon defeated. Progress: What word of the rebel leader, Belaphon?", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 203390 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199391, ["x"] = 0.464, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 200839, ["x"] = 0.765, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 11, ["flags"] = 0 } } },
[72429] = { ["id"] = 72429, ["name"] = "Orientation: Maruukai", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66340, 66344, 66783, 66784, 66848, 66948, 66969, 70174, 70185, 70195, 70220, 70229, 70244, 72267, 72429 }, ["description"] = "<As Sansok Khan signs, Okir vocalizes for her.> The Maruuk as a people are not staunchly against outsiders, but we do require any potential allies to prove their worth. As you meet the clans and aid in our ventures, word will spread of your support. On the lower level of the krutal on the hill you will find one of the Khanam Matra's daughters, who can help you see where you stand with our people. Be sure to introduce yourself.", ["objectivesText"] = "Meet the Keeper of Renown and Renown Quartermaster in Maruukai. Progress: I look forward to seeing how you contribute to the Maruuk.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191283, ["x"] = 0.6075, ["y"] = 0.386 }, { ["mapID"] = 2023, ["npcID"] = 195543, ["x"] = 0.634, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185179, ["x"] = 0.604, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6075, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 16, ["flags"] = 0 } } },
[72440] = { ["id"] = 72440, ["name"] = "Silver Mettle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72440, 72441, 72442, 72443, 72444, 72526 }, ["description"] = "I believe the Silver Scale may still be of some use to us. During my observations, I felt an... energy in it that transcends time and seems to be attuned to Tyr. It also has the same architecture as the disc. It stands to reason we may use the Silver Scale to collect one of Tyr's memories that he did not commit to the disc. Though it seems macabre, going to his tomb in Tirisfal may allow us to at least partially restore him. Alexstrasza can tell you more, $p.", ["objectivesText"] = "Venture into the Tomb of Tyr with the aid of the Aspects. Progress: I do not wish to startle the man with my... presence. Perhaps it would be best if you approached him first.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 198941, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1377, ["questLineOrder"] = 1 }, { ["id"] = 233, ["title"] = "Catching Up!", ["questLineID"] = 1377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1377, ["name"] = "Tyr's Fall", ["orderIndex"] = 0, ["flags"] = 0 } } },
[72441] = { ["id"] = 72441, ["name"] = "Breaching the Tomb", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 2025, ["storyline"] = { 72440, 72441, 72442, 72443, 72444, 72526 }, ["description"] = "Something recently activated the tomb's titan defense system. I had not seen titan constructs here before. I was investigating why they appeared when I was locked out of the tomb. Perhaps your mission awakened them. Should we intend to venture forth, we must disarm the new defenses. The glowing orbs flanking the doors might be the key. If only they weren't damaged...", ["objectivesText"] = "Disable the Titan Orbs at the entrance to the tomb.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 85 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1377, ["questLineOrder"] = 1 }, { ["id"] = 233, ["title"] = "Catching Up!", ["questLineID"] = 1377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1377, ["name"] = "Tyr's Fall", ["orderIndex"] = 1, ["flags"] = 0 } } },
[72442] = { ["id"] = 72442, ["name"] = "The Remains of Tyr", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 2025, ["storyline"] = { 72440, 72441, 72442, 72443, 72444, 72526 }, ["description"] = "As Nozdormu could sense power lingering in the scale, I can sense Tyr here. It is in the very stones of this place. I suspect the other constructs can sense it as well. They must have come here when Tyr was reforged. We must be on the right track. If something of his presence still remains, the scale should be able to gather it--with the help of this console. But the constructs may interpret our collection of Tyr's last memories as us trying to destroy them. Keep them away if they awaken.", ["objectivesText"] = "Defend Watcher Koranos from the constructs in the tomb.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 85 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1377, ["questLineOrder"] = 1 }, { ["id"] = 233, ["title"] = "Catching Up!", ["questLineID"] = 1377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1377, ["name"] = "Tyr's Fall", ["orderIndex"] = 2, ["flags"] = 0 } } },
[72443] = { ["id"] = 72443, ["name"] = "Tyr's Fall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 2025, ["storyline"] = { 72440, 72441, 72442, 72443, 72444, 72526 }, ["description"] = "This console will allow us to examine the scale's contents, but I do not know what we will find. The other titan servants here should leave us alone; accessing it should not be as disruptive as transferring what we sensed of Tyr. Something is making Travard uneasy. Be prepared for anything, $p. Place the Silver Scale in the console when you are ready to proceed.", ["objectivesText"] = "Use the Titan Console to witness Tyr's final memories. Progress: There is much we still do not know about Tyr.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 204474 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 85 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1377, ["questLineOrder"] = 1 }, { ["id"] = 233, ["title"] = "Catching Up!", ["questLineID"] = 1377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1377, ["name"] = "Tyr's Fall", ["orderIndex"] = 4, ["flags"] = 0 } } },
[72444] = { ["id"] = 72444, ["name"] = "A Sliver of Silver", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 2025, ["storyline"] = { 72440, 72441, 72442, 72443, 72444, 72526 }, ["description"] = "Tyr's final memories are in our hands. This is not a responsibility to be taken lightly. Let us take the Silver Scale to Nozdormu in Tyrhold. We will attempt to use the console there to awaken him. If he is whole again, there will be much to discuss.", ["objectivesText"] = "Escape the tomb and return to the Aspects at Tyrhold in Valdrakken. Progress: We will do whatever we must to restore Tyr.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 204686 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 198941, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1377, ["questLineOrder"] = 1 }, { ["id"] = 233, ["title"] = "Catching Up!", ["questLineID"] = 1377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1377, ["name"] = "Tyr's Fall", ["orderIndex"] = 5, ["flags"] = 0 } } },
[72519] = { ["id"] = 72519, ["name"] = "Temporal Two-ning", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "I see... They are falling through possibilities as well as time. Hurry, I have located another point in the timeline where we might catch them. It is... unusual, but do not let the strangeness of this world slow you down. Chronormu's fate is in your hands.", ["objectivesText"] = "Use Chrono Crystal on Eternus and Chromie in Azmerloth to stop them from falling through time.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192454, 192749, 194521 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 36, ["flags"] = 0 } } },
[72525] = { ["id"] = 72525, ["name"] = "Basic Cataloging Gear", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72525 }, ["series"] = { 65486, 69855, 69869, 69870 }, ["description"] = "Every expedition cataloger deserves their very own camera! You don't need to give yours a special name, but I highly encourage it. It's far more fun. Anyway, Pathfinder Jeb should be able to get you everything you need. I've yet to need a single thing that he hasn't brought along with him. He's incredible!", ["objectivesText"] = "Use the Expedition Supply Kit to research Cataloging Gear.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187707, ["x"] = 0.485, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187707, ["x"] = 0.485, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72526] = { ["id"] = 72526, ["name"] = "Keeper's Rest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 2025, ["storyline"] = { 72440, 72441, 72442, 72443, 72444, 72526 }, ["description"] = "I do not enjoy seeing others forged by Tyr disabled. They went through such effort to keep the tomb from collapsing, and now it will languish devoid of even what was left of Tyr's light. <Koranos gestures to the Silver Scale.> I hope whatever is in the scale is worth their destruction. Let us find another console to see what, if anything, is on the scale.", ["objectivesText"] = "Escape to the Darkwalk. Progress: We act in the service of Tyr. He would understand.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 85 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1377, ["questLineOrder"] = 1 }, { ["id"] = 233, ["title"] = "Catching Up!", ["questLineID"] = 1377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1377, ["name"] = "Tyr's Fall", ["orderIndex"] = 3, ["flags"] = 0 } } },
[72527] = { ["id"] = 72527, ["name"] = "No Such Thing as Bad Luck", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "Look, believe it or not, I'd be in the Isles already if it wasn't for unfinished business. Recent events have not been kind to me. I owe the Baron, and nobody owes the Baron for long. He will absolutely find and skin me if I don't pay up. I invested his money in these magic crystals, but their price just crashed on the market because of the front page ripper in the Booty Bay Journal. And the shipment of crystals is missing! Someone must be plotting my demise. Perhaps the Goodstitches will help me.", ["objectivesText"] = "Find Blixrez Goodstitch in Tan-Your-Hide Leatherworks in Booty Bay.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 258980, 258981, 258982 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.421333, ["y"] = 0.747333 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 29, ["flags"] = 0 } } },
[72529] = { ["id"] = 72529, ["name"] = "Information is King", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "Information ain't cheap. Outta everyone, Zeros should know that best. People have sighted dangerous crocolisks around Janeiro's Point. You know what I see? Money, money, money! Get me their precious skins and maybe I'll remember something important about those crystals Zeros is after. If that's too dangerous for your cup of tea, I might be open to other forms of payment too. You know, the most common form. <Blixrez folds his arms and waits expectantly.>", ["objectivesText"] = "Collect 3 Crocolisk Skins in Janeiro's Point, or give gold to Blixrez Goodstitch . Progress: Friendship is like a scale. It must remain balanced at all costs!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 8494, 193215, 201986 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 2846, ["x"] = 0.428, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 2846, ["x"] = 0.428, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 30, ["flags"] = 0 } } },
[72530] = { ["id"] = 72530, ["name"] = "Anyway, I Started Bribing", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "The scoundrel! I had a deal with Arty to market the crystals in the paper. Someone must've cut a bigger deal with him. Arty routinely inspects the Venture Company's working area on the shore. He always brings his own guards, but no one is immune to gold in Booty Bay. Take my last bit of gold. Go to the oil rigs and bribe the guards to look the other way before you confront Arty.", ["objectivesText"] = "Use the gold to bribe Arty's Hired Bodyguards and then confront Prospector Arty in Wild Shore. Progress: That's all the gold I got, so if you need to throw in some punches to sweeten the deal, be my guest.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 202271, 258999 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.421333, ["y"] = 0.747333 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 31, ["flags"] = 0 } } },
[72532] = { ["id"] = 72532, ["name"] = "Money, Money, Money!", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "Grub Redcut and his crew are notorious for their love of money. They'll do anything for it. I assume there is treasure to be had on his own ship, but just in case there isn't, there must be gold within their pockets. Will you do me the dirty business of collecting it? I won't question your negotiation tactics--just don't kill them! I'm not trying to start a serious blood feud today.", ["objectivesText"] = "Collect 1500 Gold Coins from Grub Redcut's pirates in the Southern Savage Coast. Progress: It's high time those pirates learned they can't terrorize anyone they please.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 161878, 204705 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.421333, ["y"] = 0.747333 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 33, ["flags"] = 0 } } },
[72533] = { ["id"] = 72533, ["name"] = "Crystals Shmystals", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "Grub. Redcut. < Zeros spits.> A sore, crusty loser, who thinks he's all tough because he's big and buff. He hates that someone like me can make more money than him. Believe it or not, I play the auction house fairly. I'm a saint compared to him! So Grub sold my crystals, eh? And then paid Arty to lie about them so no one would go looking for them. A fine plan. Grub must have something valuable on that ship of his. Well we're going to go take it. Search the ship thoroughly.", ["objectivesText"] = "Retrieve Grub Redcut's treasure from his ship in Southern Savage Coast. Progress: Please hurry! The Baron wasn't kidding about my scales--I'm a dragon, as you know, and my scales are worth quite a lot.", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 202281, 202284 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.421333, ["y"] = 0.747333 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 34, ["flags"] = 0 } } },
[72534] = { ["id"] = 72534, ["name"] = "Settled with the Baron", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "Ha...! You returned just in time. A minute later and you might've found a skinned dragon on your hands. Give him the treasure, quickly.", ["objectivesText"] = "Give the treasure to Baron Revilgaz. Progress: Give him the gold already, will you? Please!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 259014, 259015, 259016 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.421333, ["y"] = 0.747333 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 35, ["flags"] = 0 } } },
[72585] = { ["id"] = 72585, ["name"] = "Open Orientation", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "You have done much for the Dragon Isles, hero. There are many who are grateful for your contributions and want to welcome you more wholly into their communities. Go to them and orient yourselves with each group and their specialties. I think you will find that just as you have much to offer the Dragon Isles, many here have much they wish to offer you in return!", ["objectivesText"] = "Complete the Orientation quests in each major faction hub: Dragonscale Basecamp, Maruukai, Iskaara, and Valdrakken .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 1, ["flags"] = 0 } } },
[72650] = { ["id"] = 72650, ["name"] = "Warm Winds and Water", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "Kirygosa wrote me after leaving Stranglethorn some years ago. She said it was beautiful and balmy, but not very quiet. I presume--and hope--she has found peace in Pandaria. If I am honest with myself, I should not be surprised that she hasn't answered the Isles' call. Yet, we must do our duty and seek her out. If I am doubly honest with myself, I would have any excuse to see her again. Let us take a break from these chilly winds and visit the Jade Forest .", ["objectivesText"] = "Find Kirygosa in The Jade Forest in Pandaria.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 371, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 38, ["flags"] = 0 } } },
[72651] = { ["id"] = 72651, ["name"] = "Carp Care", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "The village carp bring fortune and peace. Their well-being reflects the health of the village. The carp thrive on special food made from worm meal and vegetable paste. It's not as unpleasant as it sounds, especially after we finish dehydrating it into neat little blocks. Here! Just toss it gently in the water near them. Their ponds also require cleaning, so please skim any debris you find.", ["objectivesText"] = "Feed the carp and clean their ponds of debris in Dawn's Blossom. Progress: Have you finished feeding the carp?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 203182, 258991, 258992, 258994 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.471667, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 39, ["flags"] = 0 } } },
[72652] = { ["id"] = 72652, ["name"] = "Self Care", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "How strange and wonderful it is to be in Kiry's own home. That being said, I can't help but notice it is an absolute mess in here. She spends all this time helping with the villagers, I have a feeling that she doesn't reserve time for herself. Typical Kiry... < Kalecgos sighs.> Would you mind tidying this place up a bit, $p? I'm sure she'd be glad for the help.", ["objectivesText"] = "Tidy Kirygosa's home. Progress: < Kalecgos is paying deep attention to Kirygosa.>", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 258988 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 201019, ["x"] = 0.480667, ["y"] = 0.428667 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 201019, ["x"] = 0.480667, ["y"] = 0.428667 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.480667, ["y"] = 0.428667 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 40, ["flags"] = 0 } } },
[72653] = { ["id"] = 72653, ["name"] = "Local Deliveries", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "I've been cultivating a new flower in this land. It's quite versatile, but the villagers and I are still refining its various uses. I just harvested my latest batch today. Will you help me deliver them?", ["objectivesText"] = "Deliver Wild Blue Yonders to villagers in Dawn's Blossom. Progress: Have you met my neighbors yet? Don't be shy about introductions. Everyone is pleased to meet outsiders that respect our traditions and way of life.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 203228 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.471667, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 41, ["flags"] = 0 } } },
[72654] = { ["id"] = 72654, ["name"] = "Up, Up, and Home", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "Honest work for an honest day. Thanks, $p. Why don't we have some tea and conversation at my home? Just tell me when you're ready.", ["objectivesText"] = "Fly with Kirygosa to her home.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 6948, 29804, 29806, 29807, 30400, 30523, 37227, 37380, 37514, 37548, 38675, 52594, 52663, 53355, 53373, 53386, 66898, 66899, 66900, 69217, 69223, 131709, 131855, 140255, 142054, 150733, 155341, 155343, 155519, 155521, 158943, 158944, 158945, 158946, 160219, 170514, 170515, 170516, 170517, 170518, 170519, 170520, 170521, 170522, 170523, 170524, 170525, 170526, 170527, 170528, 170529, 170530, 170531, 170532, 170533, 170534, 170535, 170536, 170537, 175576, 175656, 175657, 175658, 175659, 179657, 179765, 179774, 179888, 181372, 181475, 181556, 181732, 181909, 181979, 197399, 211353, 223625, 225894, 233056, 237812, 251103, 251104, 251108, 251115, 251118, 260312 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.471667, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 42, ["flags"] = 0 } } },
[72655] = { ["id"] = 72655, ["name"] = "A Drink with Kalecgos", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "< Kalecgos is quiet for a moment, a wistful look on his face.> I'd call upon Nozdormu to help us pass the time, but he'd tell me that I should be able to handle this. So... the Drunken Hozen. If Kiry recommends it, then let us go!", ["objectivesText"] = "Have a drink with Kalecgos in The Drunken Hozen. Progress: Peiji Goldendraft recommended the perfect brew for comradery. Hot barley tea! Please, have some.", ["rewardGold"] = 241020, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 201019, ["x"] = 0.480667, ["y"] = 0.428667 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 201019, ["x"] = 0.480667, ["y"] = 0.428667 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.480667, ["y"] = 0.428667 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 43, ["flags"] = 0 } } },
[72656] = { ["id"] = 72656, ["name"] = "Winterspring", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Haleh, Matron Protectorate, presides over Winterspring. Even after defeating the power hungry mage Umbranse, she continues to find and dispel danger in her homeland. As the last living consort of Malygos, she tirelessly upholds his legacy as a guardian of magic. Her return would greatly strengthen the blue dragonflight.", ["objectivesText"] = "Speak to Sindragosa for more information.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2AdventureMapPoiID"] = 186, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 44, ["flags"] = 0 } } },
[72657] = { ["id"] = 72657, ["name"] = "A Protector of Magic", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72657, 72659, 72660, 72661, 74354, 74356 }, ["description"] = "I am very curious about Haleh --she is one of the last living consorts of Malygos. I am grateful for her going to Malygos in his time of need. I will admit, I have spent some time spying on her. She is a blue dragon through and through. Studious, proud, and one of the more careful ones around magic. I do feel most suited to be the one to visit her about the call of the Isles. Take my portal when you are ready. I shall meet you there.", ["objectivesText"] = "Find Haleh in Winterspring in Kalimdor.", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 83, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1403, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 83, ["questLines"] = { { ["id"] = 1403, ["name"] = "Chapter 3C - Winterspring", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 45, ["flags"] = 0 } } },
[72659] = { ["id"] = 72659, ["name"] = "Test Subject", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 72657, 72659, 72660, 72661, 74354, 74356 }, ["description"] = "Today is day forty-one without finding a harmful artifact. I am further delighted to report that while you were away, a handful more proved harmless. Perhaps my hunt in Winterspring is almost concluded! Come to think of it... you have some magical ability, don't you? Or enough bravery to help me test some more artifacts? Do not be nervous. None of them will permanently hurt you. Artifacts with that kind of dangerous power were taken care of in my first year here.", ["objectivesText"] = "Test the artifacts Bottled Spirit, Icy Book, and Left Boot. Progress: Do take your time, <name>... there are only hundreds more to go.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 259009, 259011, 259012 }, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.4375, ["y"] = 0.5725 }, ["mapCandidates"] = { ["npc"] = { 83 }, ["zone"] = { 618 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1403, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 83, ["db2QuestSortName"] = "Suffusion Camps", ["questLines"] = { { ["id"] = 1403, ["name"] = "Chapter 3C - Winterspring", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 46, ["flags"] = 0 } } },
[72660] = { ["id"] = 72660, ["name"] = "Owl of a Sudden", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 72657, 72659, 72660, 72661, 74354, 74356 }, ["description"] = "While you were working, I was inspecting the totemic ruins you retrieved. There has always been something odd about the Hidden Grove. It used to be occupied by a robust population of harmless white hares. Now there are only maddened owlkin and strange totems... I put the pieces together. It is no masterpiece, but hopefully we can glean a stronger magical effect from the whole. Maybe it will even make us sprout some feathers and fur. You would think as a blue dragon I would enjoy the cold, but no.", ["objectivesText"] = "Test the Restored Owlkin Totem. Progress: I cannot remember the last time I had proper help. Thank you.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.4375, ["y"] = 0.5725 }, ["mapCandidates"] = { ["npc"] = { 83 }, ["zone"] = { 618 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1403, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 83, ["db2QuestSortName"] = "Suffusion Camps", ["questLines"] = { { ["id"] = 1403, ["name"] = "Chapter 3C - Winterspring", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 47, ["flags"] = 0 } } },
[72661] = { ["id"] = 72661, ["name"] = "A Wyrm Rest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 72657, 72659, 72660, 72661, 74354, 74356 }, ["description"] = "Oh dear. I have an idea. Speak to me when you are ready.", ["objectivesText"] = "Work with Sindragosa to cheer up Haleh. Progress: I fear Haleh has not been getting adequate rest.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 199404, ["x"] = 0.438, ["y"] = 0.571 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 199404, ["x"] = 0.438, ["y"] = 0.571 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.571 }, ["mapCandidates"] = { ["npc"] = { 83 }, ["zone"] = { 618 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1403, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 83, ["db2QuestSortName"] = "Suffusion Camps", ["questLines"] = { { ["id"] = 1403, ["name"] = "Chapter 3C - Winterspring", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 48, ["flags"] = 0 } } },
[72670] = { ["id"] = 72670, ["name"] = "Those We Left Behind", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 2817, ["mapID"] = 127, ["storyline"] = { 72670, 72674, 72679, 73090, 74783 }, ["description"] = "In attempting to defend their home against the fury of the blue dragonflight, Shandaral's mages condemned the souls of their people to an eternity of crystalline torment. Now their echoes wander aimlessly, reliving their civilization's doom again and again for more than ten thousand years. I have found that some of the shades yet retain a shred of sentience. Perhaps they can be reasoned with--convinced to free themselves from the mire of their own ancient fear and pass on at last.", ["objectivesText"] = "Ease the restless echoes of Shandaral.", ["rewardGold"] = 295000, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 127, ["source"] = "quest_giver", ["x"] = 0.914, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 127 }, ["zone"] = { 2817 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1399, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 127, ["questLines"] = { { ["id"] = 1399, ["name"] = "Chapter 2A - Crystalsong Forest", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 19, ["flags"] = 0 } } },
[72674] = { ["id"] = 72674, ["name"] = "A Shattered Legacy", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 2817, ["mapID"] = 127, ["storyline"] = { 72670, 72674, 72679, 73090, 74783 }, ["description"] = "Shandaral's reckless use of the crystal focus placed too much stress on the relic, causing it to shatter. Its fragments have been scattered amidst the crystalline permafrost. I can recreate the focus, but I will need you to collect enough of those shards to give me something to go on. You should be able to find them amidst the piles of crystal refuse scattered throughout the area. Take heed, <class>. Those shards may still hold fragments of the mages's memories from that fateful day.", ["objectivesText"] = "Retrieve the fragments of the Crystal Focus. Progress: Malygos's rage fed Shandaral's desperation. Now our flight's failure is frozen in crystal for the world to see.", ["rewardGold"] = 295000, ["rewardXP"] = 4925, ["rewardItems"] = { 202044 }, ["starts"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 127, ["source"] = "quest_giver", ["x"] = 0.914, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 127 }, ["zone"] = { 2817 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1399, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 127, ["questLines"] = { { ["id"] = 1399, ["name"] = "Chapter 2A - Crystalsong Forest", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 20, ["flags"] = 0 } } },
[72679] = { ["id"] = 72679, ["name"] = "An Arcane Requiem", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 2817, ["mapID"] = 127, ["storyline"] = { 72670, 72674, 72679, 73090, 74783 }, ["description"] = "The time is upon us, <name>. With your help, most of the restless echoes of Shandaral have been quelled. However, some yet remain whose rage and sorrow burns too brightly to be eased by mere words. Using the shards that you recovered, I have managed to recreate a facsimile of the crystal focus that brought Shandaral to ruin. Using it here should bring the anchored spirits to bear and give us an opportunity to grant them final rest. Be on guard. I do not know how their long-held sorrows will manifest.", ["objectivesText"] = "Grant the echoes of Shandaral their final rest. Progress: This will not be a happy ending--but it will be an ending all the same.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 258989 }, ["starts"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 127, ["source"] = "quest_giver", ["x"] = 0.914, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 127 }, ["zone"] = { 2817 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1399, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 127, ["questLines"] = { { ["id"] = 1399, ["name"] = "Chapter 2A - Crystalsong Forest", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 21, ["flags"] = 0 } } },
[72773] = { ["id"] = 72773, ["name"] = "Learning Ingenuity", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72773, 72783 }, ["description"] = "There are some goblins within Valdrakken that are investigating an abandoned titan device. Honestly, they're causing quite a disturbance. Some are concerned their investigation could cause more harm than good. The denizens of Valdrakken would appreciate you meeting these goblins to see if you can find a solution to their investigation. Without destroying part of our city.", ["objectivesText"] = "Meet Greyzik Cobblefinger within Valdrakken .", ["rewardGold"] = 169800, ["rewardXP"] = 5465, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196066, ["x"] = 0.845333, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 16, ["flags"] = 1 } } },
[72783] = { ["id"] = 72783, ["name"] = "Crafting Orders", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["description"] = "That's a nifty thing you got there from the titan device. Now hand it over! Just kiddin'! I wouldn't know the first thing about how to use that. Do you? Go talk to Mimzy Sprazzlerock. She's got a whole gig setup findin' folks to do something called \"crafting orders\". You put up the goods, someone takes 'em and crafts something for you. Simple, right? Go talk to Mimzy to check it out! And don't tell her I sent you.", ["objectivesText"] = "Speak with Head Clerk Mimzy Sprazzlerock to learn about Crafting Orders.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196066, ["x"] = 0.845333, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.845333, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 6, ["flags"] = 0 } } },
[72831] = { ["id"] = 72831, ["name"] = "Creative Solutions", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 72831, 72832, 72833, 73188, 74335 }, ["description"] = "I have always hoped that mages would once again walk the streets of Theramore. This, however, is not what I had in mind. If this Sullied Banner truly intends to reconstruct a working mana bomb, then they must be stopped--but I will not repeat the mistakes Malygos made. There must be a way to reason with them. I shall place an enchantment upon you that will allow you to subdue the mages without killing them. See to it that they cannot continue their ill-intended actions.", ["objectivesText"] = "Pacify the rogue mages of the Sullied Banner. Progress: These mages walk a dangerous path, but I do not believe that they are beyond redemption.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 199737, ["x"] = 0.649, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 199737, ["x"] = 0.649, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.649, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1400, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 70, ["questLines"] = { { ["id"] = 1400, ["name"] = "Chapter 2B - Theramore", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 22, ["flags"] = 0 } } },
[72832] = { ["id"] = 72832, ["name"] = "Aftershocks", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 72831, 72832, 72833, 73188, 74335 }, ["description"] = "These precocious whelps seem to be trying to recreate the very bomb that leveled Theramore. Predictably, they have yet to succeed. Still, I would rather not give them the chance to stumble into a more effective solution. If our dear Aspect wishes to avoid simply turning the whole lot of them into mana dust, then I suppose I can refrain from carpeting the ruin in spellfrost. Someone will need to go and repossess their banal attempts at ordinance, though. Do take care not to set them off, hmm?", ["objectivesText"] = "Teleport eight Prototype Mana Bombs . Progress: Do not dally, mortal. Those bombs may be prototypes, but even an accidental detonation could present issues.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 259002, 259003, 259004 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 199736, ["x"] = 0.656, ["y"] = 0.529333 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 199736, ["x"] = 0.656, ["y"] = 0.529333 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.529333 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1400, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 70, ["questLines"] = { { ["id"] = 1400, ["name"] = "Chapter 2B - Theramore", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 23, ["flags"] = 0 } } },
[72833] = { ["id"] = 72833, ["name"] = "Breaking the Cycle", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 72831, 72832, 72833, 73188, 74335 }, ["description"] = "With many of their rank-and-file captured, it is time to deal with the leader of this so-called Sullied Banner. I imagine Kalecgos wishes to take her alive. I have no such compunctions, but I am not a picky dragon. So long as we put a stop to her schemes, I care little what happens to her. His plan, though troublesome, seems to have worked thus far. I am willing to give him the benefit of the doubt, at least for a short while longer.", ["objectivesText"] = "Apprehend Turi Flickerflame. Progress: Act quickly, <class>. I do not want this gnome to slip away from us now.", ["rewardGold"] = 143880, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 199736, ["x"] = 0.656, ["y"] = 0.529333 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 199736, ["x"] = 0.656, ["y"] = 0.529333 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.529333 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1400, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 70, ["questLines"] = { { ["id"] = 1400, ["name"] = "Chapter 2B - Theramore", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 25, ["flags"] = 0 } } },
[72854] = { ["id"] = 72854, ["name"] = "Our Enemies Abound", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "Just when we get our feet back under ourselves, someone wants to knock us down again. There are people who still think that we don't deserve this home, and they're willing to kill us to get what they want. And some old grudges never go away. Somehow, the Scarlet Crusade, or what remains of it, has gotten a toehold on Fenris Isle. Go to the southern wall of the Ruins of Lordaeron. Deathstalker Commander Belmont has got eyes on them.", ["objectivesText"] = "Speak to Deathstalker Commander Belmont at the southern wall. Progress: This is why we can never let down our guard.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 186091, ["x"] = 0.638, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 199761, ["x"] = 0.612, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[72855] = { ["id"] = 72855, ["name"] = "To the Sepulcher", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "Faranell and Velonara already went to the Sepulcher to work on a piece of our plan. We can hold the wall for now with just a few deathguards and dark rangers, but we need someone who can hit the Scarlets where they are. Preferably without losing more of our own. Go to the Sepulcher and meet with Velonara. You are the sharpened tip of our poisoned blade.", ["objectivesText"] = "Meet Dark Ranger Velonara in the Sepulcher in Silverpine Forest.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 189865 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 199761, ["x"] = 0.612, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199768, ["x"] = 0.455, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 21, 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[72856] = { ["id"] = 72856, ["name"] = "Nothing Like the Classic", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "We of the Royal Apothecaries have synthesized many nuanced plagues in recent years, in keeping with our agreement with the Desolate Council not to... overdo it. But when it comes to rooting out Scarlet assailants, there really is nothing like the classic. The original plague that exists -- mostly -- only in the diseased tissue of surviving descendants. Go, gather up samples from this marvelous wildlife and bring them to me. I can put them to greater use.", ["objectivesText"] = "Collect 12 Plagued Flesh from nearby wildlife. Progress: I remember the days when we had unfettered license to experiment and brew as we wished... ah, perhaps one day again. Have you found those plague samples?", ["rewardGold"] = 289300, ["rewardXP"] = 6815, ["rewardItems"] = { 202187 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199767, ["x"] = 0.524, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199767, ["x"] = 0.524, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[72857] = { ["id"] = 72857, ["name"] = "Boom Weed", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "You've heard of Gloom Weed, you've heard of Doom Weed, now it's time for... Boom Weed ! That's right, another variety grows right here in Silverpine! And it can be used in combination with our alchemical formulas for a very incendiary outcome. Go and collect some for me. Just mind your eyebrows. You don't really need any eyebrows, do you?", ["objectivesText"] = "Collect 6 Boom Weed in Silverpine Forest. Progress: Have you found all the Boom Weed I need? I cannot wait to mix this up.", ["rewardGold"] = 289300, ["rewardXP"] = 6815, ["rewardItems"] = { 202186 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199767, ["x"] = 0.524, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199767, ["x"] = 0.524, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[72858] = { ["id"] = 72858, ["name"] = "Acid Beats Paper", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "While the Scarlet Crusade have taken Fenris Isle, they try to intimidate and cow our people in Silverpine Forest. We cannot let them win either by strength or by terror. When you collect materials for Faranell's concoction, destroy any slanderous propaganda you find.", ["objectivesText"] = "Use the Acid Rifle to destroy Notices to All Undead.", ["rewardGold"] = 289300, ["rewardXP"] = 6815, ["rewardItems"] = { 202182 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199768, ["x"] = 0.455, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199768, ["x"] = 0.455, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 5, ["flags"] = 0 } } },
[72859] = { ["id"] = 72859, ["name"] = "A Proper Disguise", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "Our plan is to send you to Fenris Isle, but first, you must look the part. We've scouted out a group of Scarlet solders training in Valgan's Field, supervised by a lieutenant. That lieutenant's armor should let you walk deep behind enemy lines, unnoticed. Take it from them, however you see fit. I don't need to know how.", ["objectivesText"] = "Slay Lieutenant Hawlsey at Valgan's Field and take their armor. Progress: Have you acquired your Scarlet disguise?", ["rewardGold"] = 578600, ["rewardXP"] = 8520, ["rewardItems"] = { 206929 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199793, ["x"] = 0.524, ["y"] = 0.380667 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199792, ["x"] = 0.454667, ["y"] = 0.415333 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.380667 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 6, ["flags"] = 0 } } },
[72860] = { ["id"] = 72860, ["name"] = "Fear is Our Weapon", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "The Scarlet Crusade is recruiting. Apparently, when you want to blame all your problems on someone else, people flock to the lies. But that's a choice that they're going to live to regret. We're not the problem here. THEY attacked OUR home. Take one of the banshees with you. Between the two of you, those recruits will be scared to death.", ["objectivesText"] = "Frighten Scarlet Recruits and slay them. Progress: Have you thinned out those Scarlet recruits ?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199792, ["x"] = 0.454667, ["y"] = 0.415333 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199792, ["x"] = 0.454667, ["y"] = 0.415333 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.415333 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[72861] = { ["id"] = 72861, ["name"] = "The Scarlet Spy", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "Now it's time to sneak you onto Fenris Isle. I know this armor isn't exactly what you want to wear, but it will help you move around without being noticed. Approach the isle on their level. No fancy sky maneuvers. Once you've put on the armor, find a way to get across the water. There's a quartermaster who can tell you where to go from there. From there, you know how to raise bedlam.", ["objectivesText"] = "Don your disguise and report to the Quartermaster Newlem on Fenris Isle.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 204799 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199792, ["x"] = 0.454667, ["y"] = 0.415333 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199806, ["x"] = 0.64, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.415333 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 8, ["flags"] = 0 } } },
[72862] = { ["id"] = 72862, ["name"] = "Among Us", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "We could use those recruits to bolster us, but those dreadful undead are harrying our supply lines! They will all be put in the ground permanently, soon enough. Could you check on our stockpiles to make sure we've got enough for your recruits? Of course the good stuff has already gone up to Fenris Keep for the Commander, but everyone has to eat. Well, almost everyone. Get a move on, lieutenant.", ["objectivesText"] = "Plant Explosive Plague and eliminate Scarlet Archmages without being discovered.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 17901, 17906, 31075, 31076, 31077, 31078, 34594, 34595, 35859, 35860, 35861, 35862, 45724, 46114, 61427, 61428, 61429, 88375, 94219, 94220, 128959, 129104, 138773, 138774, 138775, 138776, 174066, 204799, 211279, 237812, 237890, 237893, 269973 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199806, ["x"] = 0.64, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199879, ["x"] = 0.704, ["y"] = 0.182 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 9, ["flags"] = 0 } } },
[72863] = { ["id"] = 72863, ["name"] = "The Flight of the Banshee", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "With the island's defenses weakened and the cannons and mages silenced, we're ready to safely bring in our troops once more. You didn't think you would have to fight all of them by yourself, did you? I know you could, but leave some for the rest of us, too. When you're ready to call the others in, let me know.", ["objectivesText"] = "Speak to Velonara to call in the full force of the Forsaken.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199879, ["x"] = 0.704, ["y"] = 0.182 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199885, ["x"] = 0.702, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.704, ["y"] = 0.182 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 10, ["flags"] = 0 } } },
[72864] = { ["id"] = 72864, ["name"] = "Death to the Living", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "Now it's time for them to pay. They'll wish they never set foot in our lands and threatened our home. We will drive them out, we will drive them into the ground, and we will leave them to rot.", ["objectivesText"] = "Kill every Scarlet that has a beating heart.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199885, ["x"] = 0.702, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199893, ["x"] = 0.659, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 11, ["flags"] = 0 } } },
[72865] = { ["id"] = 72865, ["name"] = "This is the Hour of the Forsaken", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "We haven't seen the Scarlet Crusade put this many fresh soldiers on the field in a long time. And we know that they didn't get here on their own. Someone's guiding them. Someone who's fought Forsaken before. Someone I remember well. Come with me, and let's put an end to Commander Forsythe.", ["objectivesText"] = "Slay Scarlet Commander Forsythe in Fenris Keep. Progress: We are the Forsaken.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199893, ["x"] = 0.659, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199893, ["x"] = 0.659, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.659, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 12, ["flags"] = 0 } } },
[72866] = { ["id"] = 72866, ["name"] = "Return to Lordaeron", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "Let's get back behind the walls and meet the others. I think Belmont had the time of his unlife with you, getting to cut down Scarlets again. But this isn't the end of the Crusade. Even though they lost, they might still turn this into yet another way to recruit. We'll be ready if they ever come for us again. Or our neighbors. Come on, let's get back to the Ruins of Lordaeron.", ["objectivesText"] = "Take the portal to return to the Ruins of Lordaeron.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199893, ["x"] = 0.659, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 199922, ["x"] = 0.618, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.659, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 21, 2070 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 13, ["flags"] = 0 } } },
[72867] = { ["id"] = 72867, ["name"] = "I Am Forsaken", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "We have fought to win back our home. We have fought to keep it safe. Your courage and strength are inspirational to the Forsaken. And with you, we know we have our champion. Go, they want to see you.", ["objectivesText"] = "Receive the honor and accolades of the Forsaken. Progress: Go on, everyone's waiting to honor you.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 37963, 38005, 38047, 38109, 38134, 38135, 38176, 38177, 38178, 65479, 170073, 208475 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 199922, ["x"] = 0.618, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 199922, ["x"] = 0.618, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 14, ["flags"] = 0 } } },
[72872] = { ["id"] = 72872, ["name"] = "Culling the Deep", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "Have you seen these deepflayers before? Well, of course you have! You were almost eaten by one! They're getting a little too cozy to me and my people's settlement nearby, and need to be dealt with. Inside the cave, outside the cave, they're all over the place! That's why I came here in the first place. Since I can tell we'll be ramblin' round with each other for a bit, why not give me a hand?", ["objectivesText"] = "Kill 8 Deepflayers. Progress: Not bad, uplander! Have you dabbled in monster hunting before this?", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201587, ["x"] = 0.602, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 5, ["flags"] = 0 } } },
[72873] = { ["id"] = 72873, ["name"] = "It Was Not Enough", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "You're smellin' real down and out there, kid. Can't imagine what you been through to end up here. Well, it don't matter! We niffen ain't the sort to leave anyone behind. Especially not people who're about to be served up as a deepflayer's snack! This master sniffin' snout of mine can smell you didn't come down here to our Zaralek Cavern alone. What say we get you out of those crystals and find your friends!", ["objectivesText"] = "Follow Elder Honeypelt to find Wrathion and Sabellian.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 44785, 44788, 46723, 46800, 46824, 64533, 64534, 64535, 64536, 64537, 64538, 64539, 64540, 64541, 64542, 116404, 132305, 132306, 132308, 132309, 132310, 132311, 132312, 132314, 132316, 132317, 132319, 132320, 132321, 132322, 132323, 132325, 141933, 180901, 180902, 180903, 180904, 197890, 197894, 197898, 198609, 211279, 237812 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201587, ["x"] = 0.602, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 6, ["flags"] = 0 } } },
[72878] = { ["id"] = 72878, ["name"] = "Slime Time Live", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72878 }, ["description"] = "$p, if I could grab your ear again, my dear? Since making it back to Loamm, I've noticed that some of our incense pots have gone missing. Incense is what we use to mark our trade routes, and find our way back to Loamm. It's very important that we replace the missing incense as soon as possible. By the way, we make our incense from snail slime , so you're going to have to wrangle some snails first! Once you're done, Citros can help you out with the rest. Say hello to Marie Shellie for me!", ["objectivesText"] = "Lasso 8 Dripping Redolent Whelks to collect Snail Slime in Zaralek Cavern . Progress: Snail slime is the base that most of our incense is built upon.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 203442, 205980 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200054, ["x"] = 0.5728, ["y"] = 0.5488 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200055, ["x"] = 0.568, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5728, ["y"] = 0.5488 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72879] = { ["id"] = 72879, ["name"] = "Smells like Kith Spirit", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72879 }, ["description"] = "Well, it's not too often we see uplanders around here! Honeypelt must have a good reason for sending you my way, she doesn't trust just anyone with her incense. A kith's incense is their pride and joy. Each one smells unique, and we use them to identify each other. Making incense is a delicate business. Just head over to that cauldron and Marie Shellie and I will help ya out with whipping up some replacements.", ["objectivesText"] = "Make Niffen Incense with Citros . Progress: It's starting to smell really good!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200055, ["x"] = 0.568, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200055, ["x"] = 0.568, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72880] = { ["id"] = 72880, ["name"] = "Incense Gratification", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72880 }, ["description"] = "That's some real potent incense you made! Usually it takes time to get this good! Now, I've got some of my own brewing to do, so you're gonna have to go out and set those up by yourself. Once you're finished I'm sure Honeypelt will be mighty keen on hearing about it! Best follow up with her when you're done.", ["objectivesText"] = "Place 9 Missing Incense in Zaralek Cavern .", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 205249 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200055, ["x"] = 0.568, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200054, ["x"] = 0.5728, ["y"] = 0.5488 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72881] = { ["id"] = 72881, ["name"] = "A Swallow's Tale", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72881 }, ["description"] = "Uplander! I'm Effervesta , Lady Redolence to the niffen of Loamm--the daughter of their leader. No need for formalities though, you can just call me Effie! Keep this between you and me, but we're a bit behind on some shipments to Glimmerogg, and the Drogbar are definitely not happy one bit! You've already been so helpful to Elder Honeypelt... maybe you can give me a hand too? Our swallows keeper, Nevroll, might be able to dig up some dirt on the issue. Will you go talk to him, please?", ["objectivesText"] = "Speak with Swallows Keeper Nevroll in Zaralek Cavern .", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200053, ["x"] = 0.546, ["y"] = 0.546 }, { ["mapID"] = 2133, ["npcID"] = 204544, ["x"] = 0.569, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200056, ["x"] = 0.551, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72882] = { ["id"] = 72882, ["name"] = "Flown the Coop", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72882 }, ["description"] = "They're gone! Just... gone! The swallows, Nevroll, all of it! And now you say that Effervesta told you that we're behind on our shipment of swallow nests to the Drogbar? This is really bad, Uplander. If you want to help, you can start by bringing back as many birds as you can find. I'll see if I can scrape together any useable nests for the Drogbar in the meantime.", ["objectivesText"] = "Find 6 Lost Swallows in Zaralek Cavern . Progress: If Nevroll or the Drogbar show up before we find those birds, we're toast!", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 39337, 39383, 39435, 39455 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200056, ["x"] = 0.551, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200056, ["x"] = 0.551, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.551, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72883] = { ["id"] = 72883, ["name"] = "A Bitter Pill to Swallow", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72883 }, ["description"] = "<The corpse of a single cave swallow rests on the cavern floor. You should tell Cinnam.>", ["objectivesText"] = "Take the dead swallow to Cinnam. Progress: Oh no...", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200238, ["x"] = 0.578, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72884] = { ["id"] = 72884, ["name"] = "Expedition Effervesta", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72884 }, ["description"] = "My daughter's gone missing--we have to find her! As High Redolence, I may be the next target. $p, will you come with me? I can still smell her, faintly. She has to still be in Loamm somewhere. We have to hurry!", ["objectivesText"] = "Search for clues about Effervesta's whereabouts in Zaralek Cavern .", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.561333, ["y"] = 0.554667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72886] = { ["id"] = 72886, ["name"] = "Suss Out the Imposter", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72886 }, ["description"] = "Do I smell... Nevroll ? If he's the kidnapper, that must mean he's also behind the missing shipment! I don't think it's safe for me to go in there, $p. Please, rescue Effie!", ["objectivesText"] = "Defeat Nevroll and rescue Effervesta in Zaralek Cavern .", ["rewardGold"] = 619600, ["rewardXP"] = 4925, ["rewardItems"] = { 205250 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.561333, ["y"] = 0.554667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72900] = { ["id"] = 72900, ["name"] = "Keeper of the Ossuary", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2112, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Greetings, <name>. While I continue to search for the remaining blue dragons, I could use your aid in another matter. Alexstrasza and I plan on laying to rest the remaining essences of Malygos and Sindragosa. She has held on to their lingering essences after both were slain years ago. Senegos said there was a time where dragons would be laid to rest in the Veiled Ossuary. Unfortunately, the place is a mess. He's gone ahead to clean the area up with Stellagosa. Could you aid them?", ["objectivesText"] = "Meet Senegos in the Veiled Ossuary. Progress: Ah, here to help are we?", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 71086, 206162 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187676, ["x"] = 0.609333, ["y"] = 0.364 }, { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199923, ["x"] = 0.622, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.609333, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025, 2112 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 0, ["flags"] = 0 } } },
[72908] = { ["id"] = 72908, ["name"] = "Sight Beyond Sight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "I had not expected to find djaradin here, though it does not surprise me. Legends tell of their elders slumbering beneath the earth. It makes sense that some would delve underground in search of them. Their forces are heavily guarding this outer area. I recognize the magic their scouts are using--it is farsight, powered by those totems near them. I spotted a larger totem at the top of the nearby tower. If you can figure out how to power it, we can use it to search the caldera from afar.", ["objectivesText"] = "Inspect nearby Flamesight Totems to find a way to activate the Greater Flamesight Totem atop the guard tower. Progress: This tower provides the best vantage point in the caldera. If there is any evidence that Fyrakk came through here--or worse--we will see it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203385, 204586, 204594, 204602, 204610, 204694 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200080, ["x"] = 0.41, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199852, ["x"] = 0.354, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 26, ["flags"] = 0 } } },
[72909] = { ["id"] = 72909, ["name"] = "Legends of the Zaqali", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Because of our recent conflicts, I have been researching the djaradin. Our archives had little information on their elders. Legends say that they were once great warlords who now slumber beneath the earth. The djaradin believe they will awaken and lead them to a brutal victory against the dragonflights. We need to know what we are up against. There is an empty shrine just below us that resembles the ones housing the elders. We may find some answers there.", ["objectivesText"] = "Inspect the Zaqali belongings left near the Elder's shrine.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199852, ["x"] = 0.354, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199948, ["x"] = 0.302, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 27, ["flags"] = 0 } } },
[72910] = { ["id"] = 72910, ["name"] = "Know Thy Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "That djaradin called her people the \"Zaqali\"--but my troops did not report any information regarding a second active djaradin tribe in the Dragon Isles. I detest an unknown in war. We will need to learn what we can about them--and quickly--in order to assess their strengths and weaknesses. I have found the best way to know a culture is to examine how they make war. Slay any you find in the nearby area and take their armaments. I will expect your report.", ["objectivesText"] = "Gather 8 pieces of Zaqali equipment from Zaqali djaradin near the empty shrine. Progress: No detail about an enemy is insignificant. Everything can be used against them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203454, 204454, 204459, 204620, 204624, 204625, 204626, 204627, 204628, 204629, 204630 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199851, ["x"] = 0.354, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199949, ["x"] = 0.302, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 28, ["flags"] = 0 } } },
[72911] = { ["id"] = 72911, ["name"] = "Take Out the Head", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "While you and Ebyssian were away, I had an epiphany. That corrupted caldera is at the center of the Zaqali elder's slumbering prison and their war camps. Whatever is located within is the key to what the Primalists are planning. It is lightly guarded as well. Only a Primalist and a Zaqali priest. If we take them out, we can discover what I believe will be the truth behind all of this.", ["objectivesText"] = "Kill Shrinekeeper Qanosh and Earthrender Ku'siva .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199949, ["x"] = 0.302, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 29, ["flags"] = 0 } } },
[72912] = { ["id"] = 72912, ["name"] = "Consequences", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Shadowflame... Did Iridikron know this was here? Did he corrupt his brother? Or has Fyrakk fallen to the temptation? Only ignorance or arrogance tempts fools to seek it out, believing they can master dark forces that not even Neltharion could. It infected him, slowly, like a gangrenous lesion until finally he succumbed to madness. So too will Fyrakk. I will not take that risk with Sabellian. He was burned badly before I was able to fly you to safety. Let us assess the extent of the damage.", ["objectivesText"] = "Inspect Sabellian's injuries. Progress: I will not lose a single person to shadowflame. Not Sabellian. Not anyone.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 211279, 237812, 256334, 256335 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.463 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 30, ["flags"] = 0 } } },
[72913] = { ["id"] = 72913, ["name"] = "Battlefield Triage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Our situation is less than ideal, we will have to improvise. I can conduct flame to earth to create magma. Shadowflame could behave similarly. The Primalists are summoning earth elementals nearby. If we extract their cores, I can use them to contain the shadowflame infecting Sabellian's burn. The Zaqali's totems should already be attuned to the elements here. It will make the siphoning process much more efficient. Sabellian will need to come with us. I must keep an eye on him--for his sake.", ["objectivesText"] = "Collect 5 Vacant Elemental Cores and 1 Zaqali Flame Totem . Progress: We cannot delay. Shadowflame deteriorates both mind and body with insidious haste. I will do everything I can to halt it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203653, 203654 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.463 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 31, ["flags"] = 0 } } },
[72914] = { ["id"] = 72914, ["name"] = "Rushing Quality", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Look ahead! The djaradin have cleared away from the northeastern side of the caldera to augment their forces near the elders. There is an altar bordering the lava pool that appears safe for now. We can set up our spell components there. Let us hurry before the djaradin return.", ["objectivesText"] = "Cleanse the shadowflame from Sabellian's injury. Progress: Fyrakk and the elders can wait. If Sabellian is lost, we will fail regardless.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203682, 204386 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201581, ["x"] = 0.33, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 32, ["flags"] = 0 } } },
[72915] = { ["id"] = 72915, ["name"] = "Alliance of Convenience", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "The Primalists have a sizeable force of djaradin guarding them while they complete their work. Even in small numbers, djaradin prove to be formidable opponents when allowed to engage in battle on their own terms. It is far better to bring the fight to them, leaving as little time to react as possible. Take them out. We cannot have them encroaching on the space we have managed to carve out thus far.", ["objectivesText"] = "Kill 4 Zaqali djaradin guarding Igira's shrine. Progress: I am certain there will be no lack of djaradin this close to the elders' shrines.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 204616, 204617, 204618, 204619 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 33, ["flags"] = 0 } } },
[72916] = { ["id"] = 72916, ["name"] = "Shut Them Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Up ahead, the Primalists are working to awaken the Zaqali's final elder. When we used the farsight totem earlier, I observed that they were draining something from the elder. Now I realize it is likely an attempt to dispel the magic keeping the elder in stasis. They are using elemental cores to contain the magic in the same way we did to cleanse Sabellian. Fyrakk absorbing shadowflame is disastrous. We cannot add an elder awakening to that threat. We must halt their efforts.", ["objectivesText"] = "Destroy 3 Earthdrainer Conduits and 4 Extracted Elemental Cores . Progress: I cannot be certain if this will stop them entirely, but it will at least slow their progress.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201581, ["x"] = 0.33, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 34, ["flags"] = 0 } } },
[72917] = { ["id"] = 72917, ["name"] = "From Hell's Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "No longer can we allow Fyrakk to lie here peacefully, twisting himself with shadowflame and becoming a threat on par with Deathwing. We must act! Is it dangerous? Yes. But not to do anything would be catastrophic. I have ripped gronn apart with my bare claws before. Those battles were gambles, this one is not. Slaying a proto-dragon with a weapon meant for dragonslaying is obvious. It is logical. It is guaranteed. I will not tremble before an opportunity to end this now.", ["objectivesText"] = "Help Sabellian slay Fyrakk.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 204581, 204589, 204597, 204605 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199952, ["x"] = 0.295333, ["y"] = 0.495333 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199877, ["x"] = 0.41, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.295333, ["y"] = 0.495333 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 36, ["flags"] = 0 } } },
[72918] = { ["id"] = 72918, ["name"] = "No Dragon Left Behind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "I... cannot move so long as this spear remains in my side. But we need to follow Fyrakk's trail. < Ebyssian grunts sharply, his breathing labored, claws digging into the dirt.> Remove it. I can... bear the pain it will cause.", ["objectivesText"] = "Find a way to remove the spear from Ebyssian 's side. Progress: He did not leave me. I cannot leave him.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204388 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199877, ["x"] = 0.41, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199876, ["x"] = 0.412, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 37, ["flags"] = 0 } } },
[72919] = { ["id"] = 72919, ["name"] = "Raked Over the Coals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "The shadowflame has already corrupted Fyrakk irreparably. Every place in Zaralek darkened by his wings has been lit ablaze with shadowflame. We cannot leave it behind and let it fester--it will need to be extinguished while it is still kindling, lest we allow its corruption to take root. < Ebyssian coughs, then winces.> Sabellian and I cannot take to the air in this state. Disperse the flames with your drake. We will follow you below and meet you back at Loamm.", ["objectivesText"] = "Disperse 12 patches of shadowflame by dragonriding through them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199877, ["x"] = 0.41, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199958, ["x"] = 0.56, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 38, ["flags"] = 0 } } },
[72920] = { ["id"] = 72920, ["name"] = "The Endless Burning Sky", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Fyrakk must have breathed shadowflame upon the niffen on his way out of the cavern. There is too much fire for it to have merely sloughed off of him. He did this on purpose. < Ebyssian clenches his staff tightly. He looks weary for a moment. Only a moment.> We will save Loamm. All of Loamm. No more lives will be lost.", ["objectivesText"] = "Extinguish the fires consuming Loamm and rescue 5 Loamm villagers.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203707 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199958, ["x"] = 0.56, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201784, ["x"] = 0.56, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 39, ["flags"] = 0 } } },
[72921] = { ["id"] = 72921, ["name"] = "On the Trail Again", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Ah... the Veiled Ossuary. I was given the task to be a sort of gravekeeper, which included keeping wildlife away from the area. I had a rather fun spell split up within several tomes kept within this place to deal with such pests. The other blue dragons did not approve of my... reckless methods, so I had to keep the tomes hidden. Here, allow me to cast a spell on you to grant you the sight to find these old tomes. Once they are all gathered, we can cleanse this place of the invasive wildlife.", ["objectivesText"] = "Receive Senegos 's special sight, then recover the missing tomes. Progress: Did you find my old tomes?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 202240, 202241, 202242 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199923, ["x"] = 0.622, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199961, ["x"] = 0.638, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 1, ["flags"] = 0 } } },
[72922] = { ["id"] = 72922, ["name"] = "Fading Embers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "This is a difficult situation, my friend. Wounds and insecurities cannot be easily dismissed. Only time--and cooperation--can soothe the sting born of longstanding rivalries. But there are more urgent matters to address. If there is a large force of drakonids still loyal to the memory of Neltharion, this land is much more dangerous than any of us expected. Emberthal still pursues Sarkareth--alone. She must be made aware of the threats that surround her. We must find her and give her aid.", ["objectivesText"] = "Help Emberthal stop Sarkareth at the Brimstone Garrison.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 }, { ["mapID"] = 2133, ["npcID"] = 202995, ["x"] = 0.535, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 51, ["flags"] = 0 } } },
[72923] = { ["id"] = 72923, ["name"] = "A Whisper to Sabellian", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Our assault on Brimstone Garrison will not work without Sabellian and his relentless and mighty dragons. We must convince him that our objectives are aligned. If we appeal to him as a tactician and general, I'm sure he will help us... I hope. We will find him with his troops at the Djaradin Assault.", ["objectivesText"] = "Speak to Sabellian at the Djaradin Assault.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 52, ["flags"] = 0 } } },
[72924] = { ["id"] = 72924, ["name"] = "Appealing to the Black Prince", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Our assault will not be successful without the stealth and cunning of Wrathion and his Blacktalon agents. We must convince him to help us. Thankfully, I know in his heart he will not deny someone in need--especially if they flatter him. Let us go to Wrathion at the Obsidian Rest and try to sway him.", ["objectivesText"] = "Speak to Wrathion at the Obsidian Rest. Progress: I only hope that his temper has cooled by now.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 53, ["flags"] = 0 } } },
[72925] = { ["id"] = 72925, ["name"] = "With Our Powers Combined", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Emberthal is waiting for us in front of the Brimstone Garrison. Come, <name>. She will be pleased to see we have rallied the full might of the black dragonflight to aid her cause.", ["objectivesText"] = "Speak to Emberthal at the Brimstone Garrison.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 204447 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 54, ["flags"] = 0 } } },
[72926] = { ["id"] = 72926, ["name"] = "In the Right Hands", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "There are several weapons of historical value that I believed were lost to time. I would bet my talons that they are here at this garrison. The dragonspawn and drakonid loyally cling to the memory of my long-dead father. Misguided fools. They have access to my father's forges and weapons, and it is likely the very weapons I thought lost are stored nearby. If they find out what they have, they will use the weapons against us. They cannot remain in their claws.", ["objectivesText"] = "Retrieve the Ebon Eviscerator and the Resting Blade from the Brimstone Garrison. Progress: These fools must be parted with such powerful blades.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204184, 204877, 256197, 256205, 256213, 256221 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200101, ["x"] = 0.475333, ["y"] = 0.230667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200101, ["x"] = 0.475333, ["y"] = 0.230667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.230667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 55, ["flags"] = 0 } } },
[72927] = { ["id"] = 72927, ["name"] = "Finding Sarkareth", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Now that we have a foothold within the garrison, we can extend our search. We will hold off the forces of Aberrus here while you find Emberthal and aid her in reaching Sarkareth. We will join you as soon as we secure the front here.", ["objectivesText"] = "Meet Emberthal within the Aberrus Approach.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 58, ["flags"] = 0 } } },
[72928] = { ["id"] = 72928, ["name"] = "Wipe Them Out", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Do you know what I see when I gaze upon the Brimstone Garrison? Traitors. These soldiers believe themselves followers of the black dragonflight, yet they ignore us, the true heirs to Neltharion, and bend a knee to the specter of our malevolent father. This cannot be allowed to stand. Show them the error of their ways.", ["objectivesText"] = "Defeat the Brimstone forces loyal to Neltharion in the Brimstone Garrison. Progress: I know that I rule with an iron claw... but it is only because I see what must be done to preserve our people.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204193 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199973, ["x"] = 0.4572, ["y"] = 0.236 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199973, ["x"] = 0.4572, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4572, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 57, ["flags"] = 0 } } },
[72929] = { ["id"] = 72929, ["name"] = "Cracking His Shell", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "We have seen shields like this before. Sarkareth is drawing on the power of Aberrus to protect himself while he finds his way in. Cowardly, but clever. Disrupt the conduits that are supplying his shield power, and we should be able to reach him.", ["objectivesText"] = "Destroy the conduits generating the shield at the Aberrus Approach. Progress: We must bring that shield down!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 224807 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 59, ["flags"] = 0 } } },
[72930] = { ["id"] = 72930, ["name"] = "Stopping Sarkareth", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "This is our last chance, <name>. If we allow Sarkareth to slip in to Aberrus, he may gain power that puts him beyond our reach. We must stop him now!", ["objectivesText"] = "Defeat the Dreadful Defender at the Aberrus Approach.", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 204195, 205998 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 }, { ["mapID"] = 2133, ["npcID"] = 201728, ["x"] = 0.48, ["y"] = 0.12 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 60, ["flags"] = 0 } } },
[72931] = { ["id"] = 72931, ["name"] = "Forward Camp", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Since Sarkareth now wields the power of Aberrus's defenses, he has an army that will shield him from us. The next step for us will be to establish a stronghold inside the garrison. That way we can search it without interruption. Meet me there.", ["objectivesText"] = "Find Ebyssian in the Brimstone Garrison. Progress: I have full faith we will carve a path through the garrison.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 56, ["flags"] = 0 } } },
[72934] = { ["id"] = 72934, ["name"] = "Lest We Forget", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "We will be joined shortly by Kalecgos and Alexstrasza. Before then, I have a request. There was a tradition to have gravestones set before your death. It allowed you to choose where you would rest when you passed. It was the job of the caretakers to update the gravestones and deposit the lingering essence of arcana at the site. Before our guests join us, would you help me in this task? Take this list, and these graves. Update the existing graves and place the new ones.", ["objectivesText"] = "Update the gravestones of the departed blue dragons.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 35709, 71086, 132409, 258990 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199969, ["x"] = 0.666, ["y"] = 0.12 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.12 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 3, ["flags"] = 0 } } },
[72935] = { ["id"] = 72935, ["name"] = "Archives Return", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "It is not unusual that Malygos and Sindragosa would have such powerful memories. From what I understand, their deaths were particularly painful. Both slain by adventurers. It breaks my heart to think of Sindragosa enduring death not once, but twice after being raised by the Lich King. But enough of this old dragon's ramblings. Stellagosa and I will meet you back at the Azure Archives.", ["objectivesText"] = "Return to Kalecgos in the Azure Archives.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 248651 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 4, ["flags"] = 0 } } },
[72936] = { ["id"] = 72936, ["name"] = "Azuregos's Support", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Many blue dragons have returned, and many others have informed me of their plans to make their ways to the Isles. There are a few key members of the flight, however, that I have not heard from. One of them may be able to help: Azuregos , stationed within the Nexus in Northrend. You, myself, and Sindragosa will travel to meet Azuregos . He has ignored all of my attempts to contact him from afar. Thanks to the oathstone being empowered, Sindragosa can now travel further than ever before.", ["objectivesText"] = "Travel to the Nexus in Northrend to meet Azuregos .", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 199976, ["x"] = 0.225, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 114, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 5, ["flags"] = 0 } } },
[72937] = { ["id"] = 72937, ["name"] = "Unusual Disruptions", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Of course I can help track down the missing blue dragons. However, I have a mess on my hands that must be addressed first. Moments ago, several bursts of arcane energy swept through the Nexus, followed by attacks of strange arcane creations. I can create a method of tracking down the blue dragons if you can put down the locations of this wild arcana. Take this staff--do not break it--and use it on three locations within the Nexus. Oh, and prepare yourself for a fight.", ["objectivesText"] = "Put down strange arcane attackers in the Nexus. Progress: Do you need even more help? Just place the the staff at the disruption.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 205931, 258995, 258997, 258998 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 199976, ["x"] = 0.225, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 199976, ["x"] = 0.225, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 3537 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 6, ["flags"] = 0 } } },
[72938] = { ["id"] = 72938, ["name"] = "Archival Arrival", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "I have crafted a magical globe to help you find the remaining blue dragons. It should give you their rough locations. Now go. On top of everything else I was working on, I must now investigate these \"memories\" that attacked the Nexus. I shall get to the bottom of it.", ["objectivesText"] = "Return to the Azure Archives.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 204076 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 199976, ["x"] = 0.225, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 114, 2024 }, ["zone"] = { 3537 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 7, ["flags"] = 0 } } },
[72939] = { ["id"] = 72939, ["name"] = "Theramore", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72656, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72939, 72940, 73026, 73069, 73091, 73227, 73399, 73404, 73405, 73406, 75023 }, ["description"] = "According to Azuregos's notes, the blue dragon Surigosa was last seen investigating a sect of rogue mages known as the Sullied Banner. Surigosa's last missive stated that she intended to travel to the ruins of Theramore. Perhaps she uncovered traces of the Sullied Banner there. Either way, if Surigosa is to be found, Theramore seems the best place to search for her.", ["objectivesText"] = "Speak to Kalecgos about Surigosa's last known location.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 185, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 16, ["flags"] = 0 } } },
[72940] = { ["id"] = 72940, ["name"] = "Where in the World is a Lost Blue Dragon?", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Azuregos has narrowed down the locations of the missing blue dragons. Each of us will handle finding several of them. I would entrust you to aid us in finding a few others. Choose where you'd like to go first.", ["objectivesText"] = "Choose an area to investigate the missing blue dragons.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 206162 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 }, { ["id"] = 334, ["title"] = "The Azure Span", ["questLineID"] = 6125, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6125, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 0, ["flags"] = 0 } } },
[72942] = { ["id"] = 72942, ["name"] = "Veiled Trouble", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "I was hoping that we would find a way to dispel these strange arcane memories from what remains of Malygos and Sindragosa. It appears they've grown more out of control than I expected. Please, accompany some of the gathered blue dragons to the Veiled Ossuary and help Azuregos . Sindragosa and I will remain here, and investigate what to do about this situation.", ["objectivesText"] = "Investigate the arcane disturbances within the Veiled Ossuary.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200019, ["x"] = 0.662, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 53, ["flags"] = 0 } } },
[72946] = { ["id"] = 72946, ["name"] = "Veiled Ossuary Chaos", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Malygos and Sindragosa's essences have created this massive arcane disruption. Their memories are running around the Veiled Ossuary trying to drain the arcana out of the graves! Our combined efforts are merely keeping the energies at bay. We need the memories in the nearby area disrupted. Once they are dispelled, we should be able to remove this barrier to reach the essences inside.", ["objectivesText"] = "Weaken the arcane invader's control over the Veiled Ossuary. Progress: Hurry! We need to deplete the arcana in this area.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200019, ["x"] = 0.662, ["y"] = 0.122 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200019, ["x"] = 0.662, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.122 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 54, ["flags"] = 0 } } },
[72947] = { ["id"] = 72947, ["name"] = "Memories of Old", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Three incredibly powerful memories have formed throughout the Veiled Ossuary. Soon their energy will be so vast that they will be able to create their own arcane constructs... thus overwhelming this place. Take them down, so we can weaken this barrier and reach Malygos and Sindragosa's essences!", ["objectivesText"] = "Slay three powerful memories within the Veiled Ossuary. Progress: Have you handled those memories yet?", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200019, ["x"] = 0.662, ["y"] = 0.122 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200019, ["x"] = 0.662, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.122 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 55, ["flags"] = 0 } } },
[72948] = { ["id"] = 72948, ["name"] = "What Still Remains", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "The barrier is weakening, thanks to your aid. In a moment it will be broken down. Our main priority is recovering Malygos and Sindragosa's essences. Something has gone very wrong with laying them to rest. There are a few theories I have regarding their current state. We can speak about it as we enter. Let me know when you are ready.", ["objectivesText"] = "Go beyond the arcane barrier to recover Malygos and Sindragosa's essences. Progress: It seems the blue dragons still cannot leave behind our legacy.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 203183, 203184 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200019, ["x"] = 0.662, ["y"] = 0.122 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 201061, ["x"] = 0.67, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.122 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 56, ["flags"] = 0 } } },
[72949] = { ["id"] = 72949, ["name"] = "Swiftly to the Archives", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "I can hear the pained cries of rage and agony from these essences. I suspect this was triggered after attempting to put them to rest. They were dormant for a time, but the combined rage of both Malygos and Sindragosa merged together to create this phenomenon. Quickly, we must make for the Azure Archives and inform Kalecgos and Sindragosa of this! Together, we may be able to finally give them the peace that they deserve.", ["objectivesText"] = "Meet Kalecgos back within the Azure Archives.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 204076 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 201061, ["x"] = 0.67, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 57, ["flags"] = 0 } } },
[72950] = { ["id"] = 72950, ["name"] = "The Last Conflict", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Malygos and myself both suffered horribly violent ends. The remains of our essences have been trapped in an endless loop. They must be reformed, and broken out of that loop. To do so will require a tremendous amount of concentrated power. We will have to utilize every amount of arcane energy within the Azure Archives... along with all of the assembled blue dragons. It is the only chance we have to reform these spirits... and to put an end to their suffering.", ["objectivesText"] = "Subdue the restless spirits of Malygos and Sindragosa within the Azure Vault.", ["rewardGold"] = 289300, ["rewardXP"] = 4925, ["rewardItems"] = { 197134, 259000 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 201128, ["x"] = 0.392, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 59, ["flags"] = 0 } } },
[72951] = { ["id"] = 72951, ["name"] = "A Peaceful Farewell", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "It brightens my heart to see everyone reunited, and Malygos and Sindragosa at peace at long last. It is time that I give you all one last gift, something the blue dragons have not seen in quite some time. The peaceful passing of one of their own. It is my time, <name>. I should have flown beyond some time ago, but I could not leave with my kin still in disarray. Would you do an old dragon the honor of seeing me off on one last adventure?", ["objectivesText"] = "Speak with Senegos one last time.", ["rewardGold"] = 578600, ["rewardXP"] = 6155, ["rewardItems"] = { 205908, 205958, 205959, 205970, 259018, 259021, 259024, 259025 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 201125, ["x"] = 0.392, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 60, ["flags"] = 0 } } },
[72958] = { ["id"] = 72958, ["name"] = "Save-A-Mole", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "Perisimona told me about her life-mate, Tuberros , and what she knows about his disappearance. Tuberros was guiding a client from the Dragonscale Expedition around some ruins here. It sounds as though they may have run into the Sundered Flame. I would rather not go after the Sundered Flame myself. Doing so would announce my presence to Sarkareth. Will you aid us by finding and rescuing Tuberros and his client? Maybe then he can help guide us to Neltharion's vault.", ["objectivesText"] = "Find and save Tuberros and his uplander client.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204587, 204595, 204603, 204611 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200049, ["x"] = 0.6016, ["y"] = 0.6984 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200049, ["x"] = 0.6016, ["y"] = 0.6984 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.6016, ["y"] = 0.6984 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 16, ["flags"] = 0 } } },
[72959] = { ["id"] = 72959, ["name"] = "Whose Vault Is It Anyway?", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "I do not know what we will find in the vault or why Sarkareth wants access to it, but I hope we are not too late. Before we continue any further, Tuberros should lead Rannan and Perisimona back to Loamm. Come and talk to me once you are ready to move forward.", ["objectivesText"] = "Talk to Emberthal once you are ready to go.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200049, ["x"] = 0.6016, ["y"] = 0.6984 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201619, ["x"] = 0.625, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.6016, ["y"] = 0.6984 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 3, ["flags"] = 1 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 18, ["flags"] = 0 } } },
[72961] = { ["id"] = 72961, ["name"] = "Charging Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "Emberthal wanted this guy Sarkareth dealt with yesterday. I understand! I hate waiting too! This door is frustratingly hard to crack... But! I have a plan because I always have a plan! My recipe for success is being one step ahead of everyone else. It's worked for me so far! Sorta. So, about this plan... I might need your help!", ["objectivesText"] = "Gather 6 buzzing orb core for Rannan Korren . Progress: Were you able to get me some of those orbs?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204387, 204833 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200074, ["x"] = 0.625, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200074, ["x"] = 0.625, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 19, ["flags"] = 0 } } },
[72962] = { ["id"] = 72962, ["name"] = "Open That Door!", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "I am glad we are making progress but... I cannot shake a sense of foreboding of what awaits us inside. As Sarkareth learns about Neltharion, his intentions seem to get ever darker... I can only imagine what he is telling his people now--about me and about the other dracthyr. He will fracture our people forever. Talk to Rannan and see how much longer we have to wait. We can't waste more time.", ["objectivesText"] = "Talk to Rannan about his progress.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201619, ["x"] = 0.625, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200075, ["x"] = 0.627, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 20, ["flags"] = 0 } } },
[72963] = { ["id"] = 72963, ["name"] = "The Upper Hand", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "It troubles me that Dezran would sacrifice himself so willingly for Sarkareth... And that Amythora and Marithos would leave Dezran to save him. We both know the loss of waking in a new world. But Sarkareth wallows in the darkness of our past. I cannot let him continue to recruit our people. Sarkareth awaits in the next room. I do not wish to kill him, but we must bring him to justice. Let me know when you are ready.", ["objectivesText"] = "Defeat Scalecommander Sarkareth .", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204582, 204590, 204598, 204606 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202857, ["x"] = 0.63, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204571, ["x"] = 0.634, ["y"] = 0.746 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 22, ["flags"] = 0 } } },
[72964] = { ["id"] = 72964, ["name"] = "Singed", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "Standing here, seeing these two Sundered Flame before me, there is no more anger. I see the confusion in their eyes and how they look at each other... They are so uncertain of their future. They remind me of myself and the moment I emerged alone, my creche dead and forgotten by passing ages. I have to talk to them, <name>. Will you accompany me? As a friend?", ["objectivesText"] = "Talk to Marithos and Amythora . Progress: I want to help them... be there for them when no one was there for me.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 204571, ["x"] = 0.634, ["y"] = 0.746 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200064, ["x"] = 0.633333, ["y"] = 0.744667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.746 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 23, ["flags"] = 0 } } },
[72965] = { ["id"] = 72965, ["name"] = "Aspects of Our Legacy", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "I am proud to see that Emberthal is blossoming into a confident leader once more. Her people need her. But that Sarkareth found Oathbinder is a reminder of the horrors of Neltharion's legacy and the folly of following him. I have a feeling that we will discover more than his trinkets and whispers here in these caverns. Come. We have much to discuss. Let us go back to Loamm and see if my brothers have found a way to subdue Fyrakk.", ["objectivesText"] = "Meet Ebyssian in Loamm.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204585, 204593, 204601, 204609, 205991 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202670, ["x"] = 0.634, ["y"] = 0.746 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199849, ["x"] = 0.566, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.746 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 24, ["flags"] = 0 } } },
[72970] = { ["id"] = 72970, ["name"] = "Niffen and Goliath", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "I didn't just come all the way out here to save your sniffers, ya know! The deepflayers are vicious and stubborn, like obsidian ore. We've tried to lead them from our town by leaving out food and such, but they're all too keen to attack our sparrow caravans. It's the big'un ruling over them that'll be trouble. Want to pay me back? Let's you, me, and your cologne-scented friend hunt it down together. I've got the perfect bait we can use too!", ["objectivesText"] = "Slay the Deepflayer Broodmatron .", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 204588, 204596, 204604, 204612 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201587, ["x"] = 0.602, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201584, ["x"] = 0.590667, ["y"] = 0.377333 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 10, ["flags"] = 0 } } },
[72974] = { ["id"] = 72974, ["name"] = "Welcome to the City of Smells", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "Ain't it incredible, uplander! Now for the backbreaking labor. We've got to deliver this deepflayer meat to all my customers and collect their pay. I'd carry it all myself, but I'm just a poor, old, frail, gorgeous woman in need now, aren't I? <Honeypelt gives you an expertly practiced wink.> Why don't you handle it for me? Brynnsahce will do the heavy lifting while you take a little tour of the place. Put your best smell forward--we're a friendly sort!", ["objectivesText"] = "Deliver deepflayer parcels around Loamm and return to Elder Honeypelt with the profits. Progress: It'd be a waste not to keep those nostrils open here in Loamm!", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 204448, 204449, 204450, 204451, 204452, 204453, 204455, 204456, 204457, 204458 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200054, ["x"] = 0.5728, ["y"] = 0.5488 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200054, ["x"] = 0.5728, ["y"] = 0.5488 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5728, ["y"] = 0.5488 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 12, ["flags"] = 0 } } },
[72977] = { ["id"] = 72977, ["name"] = "Where the Flames Fell", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "The Aspects have requested our help. As protectors of the Isles and dragonkind, we are more than willing. I must locate Emberthal and ask her to join. I believe I can recruit her to our cause as long as we remain committed to hers against the Sundered Flame in the future. Meet Sabellian and Wrathion at the site of the Incarnates' devastation.", ["objectivesText"] = "Meet Sabellian and Wrathion in Cascades Canyon.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 201281, ["x"] = 0.6036, ["y"] = 0.4068 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201311, ["x"] = 0.872, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.6036, ["y"] = 0.4068 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 2, ["flags"] = 0 } } },
[72978] = { ["id"] = 72978, ["name"] = "Scar of Earth and Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "This centaur practically attacked us upon our arrival. He seems quite protective over this burning pile of ashes. I know you have worked alongside the Shikaar before. Would you speak to him? I would like to confirm what happened here. There is no chance that this is all a coincidence. If it connects to the Incarnates at all, we must learn all we can.", ["objectivesText"] = "Investigate the scene. Progress: Have you learned anything of value?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201311, ["x"] = 0.872, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201311, ["x"] = 0.872, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.872, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 3, ["flags"] = 0 } } },
[72979] = { ["id"] = 72979, ["name"] = "The Earth Gives Way", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "You may stay here to see what comes of this relic, or meet me afterward in Loamm. That is Honeypelt's home, which she offered us respite at while you were still in the cave. I would only ask that you check on Wrathion . He may be a ceaselessly buzzing pest, yes, but... these recent events force me to admit I care for his well-being too. There are only so many black dragons left. We must look out for each other.", ["objectivesText"] = "Speak with Wrathion .", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201589, ["x"] = 0.605, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201583, ["x"] = 0.59, ["y"] = 0.377333 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 8, ["flags"] = 0 } } },
[72980] = { ["id"] = 72980, ["name"] = "Brother's Keeper", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "By my scales, I needed that win! That blasted Incarnate swatting us like flies did a number on my ego, and I assume Sabellian feels no different. As infuriating as I find his lack of humor, groaning voice, and ugly shoes... I would ask that you check in on him. He is still family, after all, and I do not wish him to become dinner to these deepflayers. Meet Honeypelt and I outside these dreadful nests when you finish up with Sabellian .", ["objectivesText"] = "Speak with Sabellian .", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 252754 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201583, ["x"] = 0.59, ["y"] = 0.377333 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201589, ["x"] = 0.605, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.377333 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 9, ["flags"] = 0 } } },
[72981] = { ["id"] = 72981, ["name"] = "The Patience of Princes", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "The centaur's report of Primalist forces pushing into the underground after Fyrakk changes the situation. Wrathion and I believe it would be a tactical mistake to dawdle here any longer, waiting for Ebyssian and his devotee to arrive. We still wish for you to join us. If you are ready, then we three should proceed together.", ["objectivesText"] = "Delve underground and fell the Primalist blockade.", ["rewardGold"] = 929400, ["rewardXP"] = 7390, ["rewardItems"] = { 204389 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 200085, ["x"] = 0.874, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.874, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2184, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 4, ["flags"] = 0 } } },
[72988] = { ["id"] = 72988, ["name"] = "The Booty Bay Journal", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "You will not believe who I read about today in the Booty Bay Journal. What is that look, $p? I too enjoy light reading about world affairs. Booty Bay is fascinating! Regardless, I read about Zeros --he was once the captive of an evil mage who hated all blue dragons. He seems to have found his own way in the world since his rescue. A bit of advice for you, young one. Debt is a foolish thing to be in, especially in Booty Bay, and especially to the Baron. Let's retrieve him before the sharks do.", ["objectivesText"] = "Speak to Senegos to temporarily neutralize your standing with Booty Bay, and then find Zeros in Booty Bay in the Eastern Kingdoms.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186240, ["x"] = 0.588, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 210, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 36, ["flags"] = 0 } } },
[73026] = { ["id"] = 73026, ["name"] = "Booty Bay", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Land of pirates, swindlers, and raiders! Zeros, once just a captive whelpling, has built a mighty reputation as an auction house trader in one of the most cutthroat places on Azeroth. However, his recent investment blunder made the front page of the Booty Bay Journal. Rescue him before his debt is collected by the Baron.", ["objectivesText"] = "Speak to Senegos for more information.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186240, ["x"] = 0.588, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2AdventureMapPoiID"] = 189, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 37, ["flags"] = 0 } } },
[73036] = { ["id"] = 73036, ["name"] = "Medicinal Fungi", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "When we happened upon these poor souls, it was clear they were attacked by djaradin. The poison on those brutes' weapons is preventing me and their leader, Narvra, from healing them. I noticed peculiar mushrooms on some crystals nearby. I have seen their like before, and I may be able to fashion an antidote from them. Can you harvest some while Voraxian and I keep watch here?", ["objectivesText"] = "Collect 10 Drooping Mushroom Cuttings from the Viridian Throne. Progress: Do you have the cuttings? I'm not sure how long these poor people have.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 202873 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200298, ["x"] = 0.465, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200298, ["x"] = 0.465, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 0, ["flags"] = 0 } } },
[73037] = { ["id"] = 73037, ["name"] = "Healing Crystals", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "Greetings! Apologies if I seem... distracted. I have been beside myself worrying about my injured friends. But maybe you, gentle<class>, can assist us? Narvra needs aid in healing us. Shards from crystal elementals have healing properties. I feel terrible asking to harm a fellow elemental, but if you could... obtain some from them, that would greatly aid my friends. Don't worry--the elementals will regenerate in time. My friends' needs come first, however impolite our gathering methods may be.", ["objectivesText"] = "Collect 10 Viridian Heartcrystals from enemies in the Viridian Throne. Progress: Have you retrieved the crystals? I'm worried about Butterfingers; he's not doing well.", ["rewardGold"] = 289300, ["rewardXP"] = 4925, ["rewardItems"] = { 24129, 24130, 24131, 131819, 203012 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200291, ["x"] = 0.428667, ["y"] = 0.566 }, { ["mapID"] = 2133, ["npcID"] = 203176, ["x"] = 0.534667, ["y"] = 0.794667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 1, ["flags"] = 0 } } },
[73038] = { ["id"] = 73038, ["name"] = "A Room Without a View", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "This vault is of Black Dragon make which means its contents are my flight's property. Normally I would have suggested we venture in together, but I was not expecting aggressive watchers. I will protect Rupert while you search for artifacts for us to examine. To keep you safe, I will cast a spell on you I use when fighting the gronn.", ["objectivesText"] = "Recover artifacts from the Buried Vault. Progress: Did you find anything of interest?", ["rewardGold"] = 232300, ["rewardXP"] = 3695, ["rewardItems"] = { 203394, 203395, 203396 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200290, ["x"] = 0.4892, ["y"] = 0.6112 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200290, ["x"] = 0.4892, ["y"] = 0.6112 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4892, ["y"] = 0.6112 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 2, ["flags"] = 0 } } },
[73039] = { ["id"] = 73039, ["name"] = "Restless Death", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "What could lead someone to do this... I can perform a ritual that might aid these poor creatures passing on. Take these totems and place them along the river. With enough anchor points, I should be able to help them move on. We'll move ahead to look for a ritual site.", ["objectivesText"] = "Place anchor totems in the Acidbite Ravine to allow Narvra to start a cleansing ritual. Progress: Have you placed the anchor totems?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4655, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 7, ["flags"] = 0 } } },
[73040] = { ["id"] = 73040, ["name"] = "Bringing Disorder to Order", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "How incredibly rude! I know we did not bring gifts, but this is hardly the way to greet visitors! There is no excuse for such terrible manners! Scoundrels! Cads! Brutes! <Rupert coughs into his hand.> What I meant to say was these watchers appear to be a threat. Anyone who tunnels in here could be in danger. Would you be able to make this place safer by eliminating them?", ["objectivesText"] = "Eliminate 6 Enraged Watchers in the Buried Vaults.", ["rewardGold"] = 216900, ["rewardXP"] = 3695, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 203176, ["x"] = 0.534667, ["y"] = 0.794667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200291, ["x"] = 0.428667, ["y"] = 0.566 }, { ["mapID"] = 2133, ["npcID"] = 203176, ["x"] = 0.534667, ["y"] = 0.794667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.794667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 3, ["flags"] = 0 } } },
[73041] = { ["id"] = 73041, ["name"] = "Respite", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "Thank you for everything you have done for us. We've been able to get back on our feet now, and Butterfingers has cooked up a meal. We lost a member of our team and everyone is still a bit shaken... We could do with the morale boost of a good meal. Would you like to join us?", ["objectivesText"] = "Join the Dragonscale team in the Zaralek Cavern for a meal. Progress: Thank you, <name>. I think we needed that small break.", ["rewardGold"] = 154900, ["rewardXP"] = 2465, ["rewardItems"] = { 168846, 197855, 237812 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4655, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 4, ["flags"] = 0 } } },
[73042] = { ["id"] = 73042, ["name"] = "A Tower Yonder", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "$p, I... don't want to ask more of you, but could you help us finally complete our mission? We were ordered to investigate the Gaze of Neltharion. We were defeated on our first approach, but with an escort of two dragons and the mighty $p, I'm not as worried about the djaradin. I want us to move out soon. Could you scout out the tower first for us?", ["objectivesText"] = "Investigate the Gaze of Neltharion in the Sulfur Wastes. Progress: Did you scout out the tower?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204334 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4655, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 5, ["flags"] = 0 } } },
[73043] = { ["id"] = 73043, ["name"] = "A Ghastly Legacy", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "We need to give these creatures peace. While you are down there assisting Voraxian, please end their suffering. Even a temporary release from this existence will help relieve their burden. In the meantime, Narvra can work on her ritual.", ["objectivesText"] = "Eliminate 10 Ghostly Researchers and Failed Experiments in the Acidbite Ravine.", ["rewardGold"] = 289300, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200298, ["x"] = 0.465, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200298, ["x"] = 0.465, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 6, ["flags"] = 0 } } },
[73044] = { ["id"] = 73044, ["name"] = "Cataloging Horror", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "I... I need to bring the evidence of this insanity back to my flight. It may destroy us, but my people need to know what happened here. I borrowed some cataloging cameras from Tellywin. Can you join me in documenting these atrocities? I can provide you with a similar protection to that which I gave in the vault. I will leave any fighting to you; I cannot bring myself to cause any more suffering than my flight has already wrought. Let us be done with this as swiftly as possible.", ["objectivesText"] = "Use the Cataloging Camera to take pictures of experiment dumping sites in the Acidbite Ravine. Progress: I can barely believe what was done here...", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 204698 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200290, ["x"] = 0.4892, ["y"] = 0.6112 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4892, ["y"] = 0.6112 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 8, ["flags"] = 0 } } },
[73045] = { ["id"] = 73045, ["name"] = "Stain Removal", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "We can begin the ritual whenever you are ready. Let's help these spirits pass on.", ["objectivesText"] = "Complete the cleansing ritual. Progress: We need to complete this ritual, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 205254 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4655, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 9, ["flags"] = 0 } } },
[73046] = { ["id"] = 73046, ["name"] = "Cavernous Capers", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "While we wait for Veritistrasz and Narvra to nurse the rest of the camp back to health, I thought we might take a short jaunt. I sensed a cavern on our way here, and... I feel like I may need a bit of spelunking to take my mind off what just happened... Fancy joining me?", ["objectivesText"] = "Travel with Rupert from the Dragonscale Camp in the Zaralek Cavern . Progress: Well! I say! Gosh!", ["rewardGold"] = 70225, ["rewardXP"] = 1230, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200291, ["x"] = 0.428667, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203176, ["x"] = 0.534667, ["y"] = 0.794667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 10, ["flags"] = 0 } } },
[73047] = { ["id"] = 73047, ["name"] = "Terrestrial Tunneling", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73047 }, ["description"] = "I have to say that I am quite done with this place. Would you like to return to camp?", ["objectivesText"] = "Return to the Dragonscale Expedition camp in the Zaralek Cavern .", ["rewardGold"] = 77400, ["rewardXP"] = 1230, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 203176, ["x"] = 0.534667, ["y"] = 0.794667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200291, ["x"] = 0.428667, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.794667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[73069] = { ["id"] = 73069, ["name"] = "Sindragosa and Malygos's Rest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "The preparations are now complete. Kalecgos and Alexstrasza should be here soon with the remaining essences of Sindragosa and Malygos. Both suffered such violent ends. I heard even with his last breath, Malygos cursed Alexstrasza. And Sindragosa--she was slain ten thousand years ago by Nelthar... by Deathwing. Yet she was reanimated by the Lich King and slain by adventurers. I can only imagine the state this essence is in... Forgive my ramblings. Kalecgos and Alexstrasza should be here shortly.", ["objectivesText"] = "Observe Kalecgos and Alexstrasza putting Sindragosa and Malygos's remains to rest.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200007, ["x"] = 0.67, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 9, ["flags"] = 0 } } },
[73090] = { ["id"] = 73090, ["name"] = "Regrets in Crystal", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72670, 72674, 72679, 73090, 74783 }, ["description"] = "I have some idea of what Lanigosa might be doing in Crystalsong Forest, although I cannot imagine why she has taken it upon herself to do it. That forest conceals within it the ruins of Shandaral, a former highborne settlement and the site of one of the mortal race's first clashes with the blue dragonflight. If Lanigosa truly is in Crystalsong, then it may well have something to do with Shandaral. Seek her out there, <name>, and try to convince her to return to us.", ["objectivesText"] = "Speak to Lanigosa in Crystalsong Forest.", ["rewardGold"] = 280900, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 127, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1399, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 127, ["questLines"] = { { ["id"] = 1399, ["name"] = "Chapter 2A - Crystalsong Forest", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 26, ["flags"] = 0 } } },
[73091] = { ["id"] = 73091, ["name"] = "Crystalsong Forest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72656, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72939, 72940, 73026, 73069, 73091, 73227, 73399, 73404, 73405, 73406, 75023 }, ["description"] = "The blue dragon Lanigosa lent her aid to mortals during the most recent war against the Burning Legion. However, she failed to respond to the call of the Isles. Has something befallen her? Or has she simply chosen not to return? Whatever her reasons, Azuregos's globe seems to suggest that she was last seen in Crystalsong Forest.", ["objectivesText"] = "Speak to Kalecgos .", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 187, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 19, ["flags"] = 0 } } },
[73181] = { ["id"] = 73181, ["name"] = "Zeroing Debt", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "I do hope that is the last we see of the Baron. Truth be told, I respect his seat of power in Stranglethorn. We were lucky to find Zeros still alive. He must have developed quite the positive relationship with the Baron before all this nonsense, or else he would not have been given so much time. Let us return to the Archives.", ["objectivesText"] = "Return to the Azure Archives.", ["rewardGold"] = 28900, ["rewardXP"] = 615, ["rewardItems"] = { 204076 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 200478, ["x"] = 0.422, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186240, ["x"] = 0.588, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 210, 2024 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 32, ["flags"] = 0 } } },
[73188] = { ["id"] = 73188, ["name"] = "The Sullied Banner", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72831, 72832, 72833, 73188, 74335 }, ["description"] = "So long as there has been magic, there have been those willing to utilize it for nefarious ends. I am not certain what grievances these rogue mages hold that has prompted Surigosa to chase them down, but I am inclined to trust her judgment on the matter. Let us go to her, <name>; perhaps we can solve this rogue mage problem and convince Surigosa to return in a single turn.", ["objectivesText"] = "Find Surigosa in Theramore.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 199736, ["x"] = 0.656, ["y"] = 0.529333 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 70, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1400, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 70, ["questLines"] = { { ["id"] = 1400, ["name"] = "Chapter 2B - Theramore", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 27, ["flags"] = 0 } } },
[73227] = { ["id"] = 73227, ["name"] = "Jade Forest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Daughter of Malygos and Saragosa, Kirygosa survived the turbulent Nexus War that ripped away her life and family. Afterwards, Kirygosa sought a permanent summer in Stranglethorn. Finding warmth but not quite peace, she moved on to Dawn's Blossom, a small village nestled in the Jade Forest. The blue dragonflight would welcome her return.", ["objectivesText"] = "Speak to Kalecgos for more information.", ["rewardGold"] = 14390, ["rewardXP"] = 615, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2AdventureMapPoiID"] = 188, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 49, ["flags"] = 0 } } },
