[73405] = { ["id"] = 73405, ["name"] = "A Pair of Blue Dragons", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "I appreciate your aid so far, <name>. Where would you like to look next?", ["objectivesText"] = "Choose an area to investigate the missing blue dragons.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 }, { ["id"] = 334, ["title"] = "The Azure Span", ["questLineID"] = 6125, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 6125, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 4, ["flags"] = 0 } } },
[73406] = { ["id"] = 73406, ["name"] = "The Last Missing Blue Dragon", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "We've only one more blue dragon to locate now, <name>. Let's finish this, shall we?", ["objectivesText"] = "Choose an area to investigate the missing blue dragons.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 }, { ["id"] = 334, ["title"] = "The Azure Span", ["questLineID"] = 6125, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 6125, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 3, ["flags"] = 0 } } },
[73707] = { ["id"] = 73707, ["name"] = "TICKET: Glimmerogg Games", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73707 }, ["description"] = "<Written in sloppy handwriting that makes it almost impossible to read.> CONGRATULATIONS, LOAMM VISITOR! YOU'VE FOUND A TICKET TO THE BEST COMPETITION IN ZARALEK CAVERN : THE GLIMMEROGG GAMES! You'll find the games in the south of ZARALEK CAVERN . Just look for a bunch of happy drogbar! Don't miss our fun activities like... <The rest of the page is illegible except for the name \"Brogg.\">", ["objectivesText"] = "Pay a visit to Glimmerogg in the south of Zaralek Cavern .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201098, ["x"] = 0.438, ["y"] = 0.83 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.83 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[73708] = { ["id"] = 73708, ["name"] = "Pay to Play", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73708 }, ["description"] = "It doesn't matter if you were invited or if you just showed up. Drogbar, niffen, or <race>, everyone pays for the Glimmerogg Games! Even I did, and I'm runnin' this show! <Brogg points aggressively to a ticket of his own.> I know you can't pay in drogdollars, but you can pay in snacks for everyone. And we love mushrooms and fish! Bring Brogg some food, and we're square, okay?", ["objectivesText"] = "Collect 4 Glimmer Mushrooms and 4 Echoed Lurker Flesh near Glimmerogg. Progress: Have the fee in full? And no, can't pay later. Brogg had enough from deadbeats.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204803, 205169 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201098, ["x"] = 0.438, ["y"] = 0.83 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201098, ["x"] = 0.438, ["y"] = 0.83 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.83 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[73709] = { ["id"] = 73709, ["name"] = "Favor on the Side", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73709 }, ["description"] = "Brogg counts more people than fees today. It's not sitting well with me neither. I'm gonna blow my top! Sure, Glimmerogg is popular, but it's not all fun and games. We have rules and everyone must follow them. You look like someone who can read fine print and follow rules. If you get rid of the intruders that are cheating Brogg, I may have something for you.", ["objectivesText"] = "Uncover 6 intruders and kick them off the Glimmerogg Games.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201098, ["x"] = 0.438, ["y"] = 0.83 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201098, ["x"] = 0.438, ["y"] = 0.83 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.83 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[73710] = { ["id"] = 73710, ["name"] = "Rock By Rock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73710 }, ["description"] = "Ah, a challenger! So, you think you can defeat Storul Heavystone in his famous rock-lifting marathon challenge? HA! Silly uplander. No one can compare to Storul! No one has EVER matched my strength. But maybe you try. Defeat will teach you a valuable lesson: true strength comes from struggle! Or, Storul will have a new friend to spot him at the gym! Get it, brul!", ["objectivesText"] = "Complete Storul Heavystone 's weight lifting spree. Progress: What? You're not afraid to lose, are you? Don't let fear consume you before you start. Just do it, brul. Storul will give you a fair trial.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 25478, 25479, 25480, 38717, 39021, 39050, 39082, 53358, 53387, 53390, 56859, 56860, 56861, 56862, 56863, 56864, 56865, 56866, 61421, 61422, 61423, 61427, 61428, 61429, 64588, 64598, 64607, 64616, 64622, 64639, 67414, 131414, 157012, 198606, 200613, 211279, 226147, 232769, 232774, 232778, 232784, 237812, 257287 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201100, ["x"] = 0.45, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201100, ["x"] = 0.45, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[73711] = { ["id"] = 73711, ["name"] = "Marked Champion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73711 }, ["description"] = "You did good on Storul's challenge, but that does not make you a champion like him. To get on my level, you have to lift the greatest rock--not a real rock, a spirit one. You must face what every drogbar fears... and venerates! You must be blessed by the Carcaxas , The Great Daughter-Worm. But Carcaxas only bestow her mark on those who are DETERMINED and don't FEAR SMELLING BAD! Are you ready to take on this challenge? CAN YOU DO IT, BRUL!?", ["objectivesText"] = "Receive Carcaxas 's mark. Progress: Did you get your blessing from The Great Daughter-Worm? No? You're not visualizing hard enough. See yourself beating Carcaxas . Now go!", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 205251 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201100, ["x"] = 0.45, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201100, ["x"] = 0.45, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[74291] = { ["id"] = 74291, ["name"] = "Blue is My Favorite Color", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "Oh, Kiry's here! I wonder if she has made her decision. Please ask her for thoughts, $p.", ["objectivesText"] = "Speak to Kirygosa and then return to the Azure Archives.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204076, 258985, 258986, 258987 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 201019, ["x"] = 0.480667, ["y"] = 0.428667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.480667, ["y"] = 0.428667 }, ["mapCandidates"] = { ["npc"] = { 371, 2024 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 50, ["flags"] = 0 } } },
[74334] = { ["id"] = 74334, ["name"] = "Future Aspects", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "My brothers are not interested in investigating the Sundered Flame or helping Emberthal. It worries me that we are dividing our efforts, but I understand their motivation in considering our next steps against Fyrakk immediately. I will aid Emberthal as I promised, but perhaps we should ask for help from the local niffen...", ["objectivesText"] = "Suggest Honeypelt as a guide.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201366, ["x"] = 0.557, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201236, ["x"] = 0.594, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.557, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 0, ["flags"] = 1 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 15, ["flags"] = 0 } } },
[74335] = { ["id"] = 74335, ["name"] = "A Moment of Reflection", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 72831, 72832, 72833, 73188, 74335 }, ["description"] = "I do not understand what would drive Turi Flickerflame and her band of mages to attempt what they have done here today. But I do understand the pain of losing family. I understand the fear and regret that follows you wherever you go. I have much to think about. I imagine Kalecgos has much yet to do in the Dragon Isles--return there with him. I will follow soon... I need some time to think upon what happened here today.", ["objectivesText"] = "Return to Kalecgos in the Azure Span. Progress: Welcome back, <name>.", ["rewardGold"] = 289300, ["rewardXP"] = 4925, ["rewardItems"] = { 204076, 259005, 259006, 259008 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 199736, ["x"] = 0.656, ["y"] = 0.529333 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.529333 }, ["mapCandidates"] = { ["npc"] = { 70, 2024 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1400, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1400, ["name"] = "Chapter 2B - Theramore", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 28, ["flags"] = 0 } } },
[74354] = { ["id"] = 74354, ["name"] = "Artifacts Abound", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 72657, 72659, 72660, 72661, 74354, 74356 }, ["description"] = "It is... certainly bizarre to see Sindragosa, real in all but the flesh. Look, I appreciate that you have both come all this way for me. The Isles sounds delightful, but I have dedicated many years to cleaning up Winterspring . I am not about to leave a job unfinished. Magic is abound and unfortunately not all good. If you would like to help, The Hidden Grove is next on my list. Therein lie ruins of totems that still emanate with some sort of magic. Will you collect pieces of them?", ["objectivesText"] = "Collect 5 Totemic Ruins from the Hidden Grove. Progress: And that one, I suppose, is harmless enough...", ["rewardGold"] = 143880, ["rewardXP"] = 4925, ["rewardItems"] = { 203459 }, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.4375, ["y"] = 0.5725 }, ["mapCandidates"] = { ["npc"] = { 83 }, ["zone"] = { 618 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1403, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 83, ["db2QuestSortName"] = "Suffusion Camps", ["questLines"] = { { ["id"] = 1403, ["name"] = "Chapter 3C - Winterspring", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 51, ["flags"] = 0 } } },
[74356] = { ["id"] = 74356, ["name"] = "Back with the Blues", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 72657, 72659, 72660, 72661, 74354, 74356 }, ["description"] = "It seems I had a good idea. Now let us hope we can broach the subject of the Isles again. I am glad to see Haleh relaxed. She deserves it.", ["objectivesText"] = "Return to the Azure Archives.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 204076, 258979 }, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 199404, ["x"] = 0.438, ["y"] = 0.571 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.571 }, ["mapCandidates"] = { ["npc"] = { 83, 2024 }, ["zone"] = { 618 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1403, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["db2QuestSortName"] = "Suffusion Camps", ["questLines"] = { { ["id"] = 1403, ["name"] = "Chapter 3C - Winterspring", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 52, ["flags"] = 0 } } },
[74375] = { ["id"] = 74375, ["name"] = "Collating Their Research", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "It no longer matters how the Sundered Flame got here; now we need to know why. What is in this vault that Sarkareth is after? <name>, while you are in their camp, look for notes, research papers, journals--anything you can find that might reveal their intentions. Please bring whatever you find to me.", ["objectivesText"] = "Find out why the Sundered Flame expedition is in Zaralek Cavern . Progress: Were you able to learn anything yet?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204583, 204591, 204599, 204607, 204713 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200049, ["x"] = 0.6016, ["y"] = 0.6984 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200049, ["x"] = 0.6016, ["y"] = 0.6984 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.6016, ["y"] = 0.6984 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 17, ["flags"] = 0 } } },
[74393] = { ["id"] = 74393, ["name"] = "Report: Battlefield Ruins", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["series"] = { 72987, 75367 }, ["description"] = "Our situation is worse than we thought. Their dominance of the air keeps us at a disadvantage. They plan on freeing their powerful Elder from Aberrus. Allowing them to accomplish this could result in us permanently forfeiting control of this area. Seek out Field Commander Ignax in the Battlefield Ruins and see what can be done to turn the tide of this battle. We will join you shortly.", ["objectivesText"] = "Find Field Commander Ignax in the Battlefield Ruins.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200046, ["x"] = 0.5, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 43, ["flags"] = 0 } } },
[74521] = { ["id"] = 74521, ["name"] = "A Flame, Extinguished", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "Sarkareth is no more. His hubris left him vulnerable to the dark influences that have assaulted our flight for millennia. Just like Neltharion before him. I believe Emberthal seeks more answers than what Wrathion and Sabellian are able to give. She may need some assistance.", ["objectivesText"] = "Speak to Wrathion or Sabellian. Progress: Return to me if you'd like to help further.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201727, ["x"] = 0.48, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 62, ["flags"] = 0 } } },
[74522] = { ["id"] = 74522, ["name"] = "Remnants", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 2133, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "Some call me a miracle, you know. Yet my birth was anything but natural. I was crafted, much as the creatures in here were crafted. Many died painful, tragic deaths so that I could live. This... callousness towards the living is something I wish to eradicate. Take this, and use it to destroy any intact specimen tanks we encounter. Nothing deserves to suffer like this.", ["objectivesText"] = "Destroy 7 Specimen Tanks with the Blacktalon Napalm . Progress: We need to end this here.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 62513, 90906, 90907, 90908, 90909, 90910, 90911, 90912, 90913, 90914, 171335, 189544, 190189, 190341, 190342, 190344, 190345, 190346, 190350, 190352, 190353, 190354, 190356, 190357, 190360, 190361, 190364, 190365, 190368, 190369, 190370, 190372, 190605, 190632, 190633, 190634, 190635, 192423, 192425, 192450, 202039, 204271, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 63, ["flags"] = 0 } } },
[74523] = { ["id"] = 74523, ["name"] = "A Traitor's Due", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 2133, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "These sycophants shame themselves and the black dragonflight. It is clear that they are willing to die in service of my father's dark machinations. Let us not disappoint them.", ["objectivesText"] = "Defeat the Neltharion Loyalists. Progress: We will never erase this mark on our legacy. But there is no way forward while they yet live.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 64, ["flags"] = 0 } } },
[74525] = { ["id"] = 74525, ["name"] = "Honorbound", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 2133, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "<The djaradin's body is gaunt and wasted, its life energy siphoned away by the hungry machines that power this dark laboratory. Perhaps there are other djaradin imprisoned here that can be spared from this horror.>", ["objectivesText"] = "Free the imprisoned djaradin. Progress: The black dragonflight is defined by our actions, not our accomplishments.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 166299 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 65, ["flags"] = 0 } } },
[74538] = { ["id"] = 74538, ["name"] = "Blow It Up", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "Make no mistake, the djaradin are experienced dragon killers. But right now their ruthless tactics are overshadowed by the devastating power of their battlefield ballistae, capable of taking out any threat from a long distance. I have lost many good soldiers to these potent weapons. It is essential that we destroy the ballistae if we hope to level the playing field and take to the skies. It is possible that we may even be able to gain the upper hand in this war.", ["objectivesText"] = "Destroy the djaradin heavy weaponry in the Battlefield Ruins.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 35807, 35808, 35809, 35810, 35811, 35812, 61418, 61419, 61420, 72042, 72045, 87399, 154989, 211279, 257201, 257202, 257203, 257204, 264340 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 44, ["flags"] = 0 } } },
[74539] = { ["id"] = 74539, ["name"] = "Thinning Their Defenses", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "The Firecallers are a formidable force. Their powerful, lethal magic allows them to vaporize anything that comes near them. Their strategic positioning on high ledges makes them difficult to reach, but we cannot allow them to continue causing destruction among our forces. The fate of our forces depends on your success. Good luck!", ["objectivesText"] = "Neutralize Zaqali Flametongues in the Battlefield Ruins. Progress: Yes?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 45, ["flags"] = 0 } } },
[74540] = { ["id"] = 74540, ["name"] = "Intercepting Communications", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "<name>, we need intel, and we need it now. Somewhere within one of the djaradin's encampments, you will find their field general. He is a seasoned and formidable opponent, responsible for many attacks on our forces. According to our field agents, he may possess crucial military orders outlining their next offense and the locations of their new supply lines. It is imperative that we obtain these orders. We cannot allow the djaradin to gain the upper hand.", ["objectivesText"] = "Eliminate Warchanter Ronvath and obtain the Invasion Plans in the Battlefield Ruins. Progress: Report!", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 204074 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 46, ["flags"] = 0 } } },
[74542] = { ["id"] = 74542, ["name"] = "Air Superiority", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "<As Ignax looks up, you see a small smile appear on his face.> Few of my soldiers have experience fighting alongside dragons. What a glorious day. Their presence gives us confidence, <class>. Now we must put an end to the djaradin's advance once and for all.", ["objectivesText"] = "Defeat the djaradin forces and stop their advance in the Battlefield Ruins.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204193 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 47, ["flags"] = 0 } } },
[74557] = { ["id"] = 74557, ["name"] = "Investigating the Unknown", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "We can only assume that something ambushed the marching djaradin. Who could have done this? We should investigate it before we proceed.", ["objectivesText"] = "Investigate the origins and motivations of the creatures in the area.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 48, ["flags"] = 0 } } },
[74562] = { ["id"] = 74562, ["name"] = "Break Them Out", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "Cages, chains and transportation carts ... I think we all know where this leads. If the drakonids plan on capturing and enslaving the slitherdrakes, then they are no better than the djaradin. See what you can do to thwart their plans.", ["objectivesText"] = "Disrupt the poachers and stop them from capturing the slitherdrakes.", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 203330 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 49, ["flags"] = 0 } } },
[74563] = { ["id"] = 74563, ["name"] = "Worst of the Worst", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "Everything here suggests this is a well-coordinated effort. These slitherdrakes are almost like wild beasts. They will not stand a chance without our aid. Find whoever is leading their operation and put an end to this.", ["objectivesText"] = "Find and eliminate drakonid leading the poachers.", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 43847, 43881, 43892, 43930, 43932, 118087, 118088, 118089, 118090, 204361, 205992 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 50, ["flags"] = 0 } } },
[74783] = { ["id"] = 74783, ["name"] = "The Sound of Silence", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 2817, ["mapID"] = 127, ["storyline"] = { 72670, 72674, 72679, 73090, 74783 }, ["description"] = "It has been so many years since Shandaral has known true silence. With luck, our actions today will allow the echoes of this cursed place to fade. You are due back in the Isles, no doubt--and I think it is high time I fly there as well.", ["objectivesText"] = "Return to Kalecgos in the Azure Span.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 204076 }, ["starts"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 127, ["source"] = "quest_giver", ["x"] = 0.914, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 127, 2024 }, ["zone"] = { 2817 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1399, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1399, ["name"] = "Chapter 2A - Crystalsong Forest", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 24, ["flags"] = 0 } } },
[74787] = { ["id"] = 74787, ["name"] = "Come Snail Away", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74787 }, ["description"] = "Hmm. You ever mount a snail before? I've trained generations of racing snail champions, but now I've come across my toughest case yet. Problem is he's too crokin' big. Straight up barred from competition. It's a shame to keep such a prize specimen stuck in a bucket though. If you can help me train Slick up to be the speedster I know he is, we'll call him yours!", ["objectivesText"] = "Introduce yourself to Slick. Progress: The big guy's racing name is Big Slick in the City , but we just call him Slick.", ["rewardGold"] = 29500, ["rewardXP"] = 175, ["rewardItems"] = { 203708 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[74857] = { ["id"] = 74857, ["name"] = "Mouse Detective", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74857 }, ["description"] = "Normally I'd chase strangers off my property, but today's an exception. My sniffin' mouse has gone missing. It's not like Persii to ignore me when I call for her... I can't smell as good as other niffen, so I can't tend to the harvest without her help. Poor thing must be so scared, out there all on her own. Please, you gotta find Persii!", ["objectivesText"] = "Search for the missing mouse.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202597, ["x"] = 0.51, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[74858] = { ["id"] = 74858, ["name"] = "Agrulculture", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74858 }, ["description"] = "The niffen say that sniffin' mice have great noses. They can make their way through the caverns and track down the fastest racing snails. Even sniff out glow spores ready for harvest. But I have a good nose, too. Maybe I could even sniff out those glow spores ! Let's collect the harvest for the hermit. That will show him it's okay that his mouse friend isn't here--because I can fill in!", ["objectivesText"] = "Collect 6 Glow Spores . Progress: Sniffin' mice must make this a lot easier. But I don't mind hard work!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204377 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4875, ["y"] = 0.7735 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[74859] = { ["id"] = 74859, ["name"] = "Sporemoth Exterminator", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74859 }, ["description"] = "Looks like sporemoths are wrecking these crops. If they keep eating all the spores, the hermit won't have anything to harvest. We need to cull the sporemoths. That should help keep the harvest thriving--and show that I know how to take care of a farm.", ["objectivesText"] = "Kill 10 Sporemoths. Progress: If we don't keep the pests under control, the spores won't grow.", ["rewardGold"] = 289300, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4875, ["y"] = 0.7735 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[74860] = { ["id"] = 74860, ["name"] = "A Friendly Introduction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74860 }, ["description"] = "It's time to deliver the harvest to the hermit. When he sees what good work we did, maybe he'll hire me as a farmhand! I, uh... tried talking to him once before. Wanted to ask if he needed a helper. Doesn't seem to like guests, though. Especially drogbar. So I got nervous and ran off. You were looking for his mouse. Could you introduce us?", ["objectivesText"] = "Deliver the harvest and introduce Agrul to Yarren . Progress: You have to find Persii before it's too late!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202597, ["x"] = 0.51, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4875, ["y"] = 0.7735 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[74876] = { ["id"] = 74876, ["name"] = "The Buddy System", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74876 }, ["description"] = "Oh, hello there. Was I speaking my thoughts out loud again? I don't mean to trouble others with my problems, but... I'm a sniffenseeker, you see. We find unique and amazing places all over the cavern! But we have an important rule here in Loamm--we always follow the buddy system. Nobody digs alone! I've had the same buddy since we were pups, but she's too busy to dig anymore. I found this interesting new smell. Before, I had a buddy... Say, how do you feel about being a stand-in dig partner?", ["objectivesText"] = "Go on a dig adventure with Myrrit . Progress: Just let me know if you decide you'd like to go with me!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201426, ["x"] = 0.556, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201426, ["x"] = 0.556, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[74877] = { ["id"] = 74877, ["name"] = "Best Friends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74877 }, ["description"] = "Really, I have fun digging with you. I do! Please, don't take this badly, but... I miss my best friend. I don't blame her for being busy. She was kidnapped, and she is the princess! I know she doesn't have lots of time. I just wish... ...I don't know. Maybe I wish things were the way they used to be, when she wanted to dig with me.", ["objectivesText"] = "Set up a dig for Myrrit and Effervesta . Progress: It's Effervesta 's favorite snack...", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204791, 223424, 223441, 223456, 223464 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201426, ["x"] = 0.556, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202766, ["x"] = 0.5425, ["y"] = 0.573 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[74878] = { ["id"] = 74878, ["name"] = "Old Friends, Dear Friends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74878 }, ["description"] = "I don't want to give up on my best friend, but what if she doesn't want to be friends anymore? We've been dig buddies since we were tiny pups. Maybe it matters to me more than it does to her. What do I even say?", ["objectivesText"] = "Help Myrrit talk to Effervesta . Progress: Why is this conversation so difficult?", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202766, ["x"] = 0.5425, ["y"] = 0.573 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202766, ["x"] = 0.5425, ["y"] = 0.573 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5425, ["y"] = 0.573 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[74953] = { ["id"] = 74953, ["name"] = "The Heavy Crown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74953 }, ["description"] = "I was really down when Effervesta didn't come like she said she would. But I understand that she's so busy, what with being kidnapped and all of her duties. I don't blame her. I want to tell her how much that time meant to me when we were pups, though. That I'll be here for her if she ever needs me. Then at least she knows I'm still here. Can you help me get her attention long enough to say what I need to?", ["objectivesText"] = "Help create a time for Myrrit to talk to Effervesta . Progress: I don't want to bother her...", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201426, ["x"] = 0.556, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202766, ["x"] = 0.5425, ["y"] = 0.573 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75018] = { ["id"] = 75018, ["name"] = "Into the Dark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 2174, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "My Blacktalon forces continue to secure the laboratory, but I think we are done here, <name>. We have secured some slitherdrakes to take us down to the central platform. From there we can continue below, to where Sarkareth fell. I am certain Ebyssian and Emberthal will benefit from our presence.", ["objectivesText"] = "Meet with Ebyssian and Emberthal in the room at the bottom of the laboratory.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 26010, 26024, 26036, 38734, 39033, 39060, 39098, 62849, 62850, 62851, 131271, 131640, 184165, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2600, ["db2PoiUiMapID"] = 2174, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 66, ["flags"] = 0 } } },
[75023] = { ["id"] = 75023, ["name"] = "Memories of Sindragosa and Malygos", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "I admit, I forgot about this phenomenon. Blue dragons who meet violent ends occasionally have some lingering arcane energy. That energy may manifest in various ways once their essences are laid to rest. Luckily, it is a simple enough process to dispel them. Simply wave anything through the energy and it will dissipate. I shall investigate the essences of Sindragosa and Malygos within this gravestone while you handle that.", ["objectivesText"] = "Dispel the lingering memories of Sindragosa and Malygos. Progress: How strange that these memories still linger...", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 10, ["flags"] = 0 } } },
[75028] = { ["id"] = 75028, ["name"] = "All the Broken Pieces", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 2174, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "Emberthal is in mourning. In truth, she has been grieving for Sarkareth for some time now. The way forward is for her to determine. We can only be there to support her along the way. There are shards of Sarkareth's signet scattered all over this room. Would you gather them? I believe she would appreciate the gesture.", ["objectivesText"] = "Collect the shards of Sarkareth's signet. Progress: <Emberthal is in no mood to speak just yet.>", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2600, ["db2PoiUiMapID"] = 2174, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 67, ["flags"] = 0 } } },
[75029] = { ["id"] = 75029, ["name"] = "A Legacy, Reforged", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "Grief is a painful burden to bear. It warms my heart to see Emberthal emerge from her sorrow and focus on her people. The pain of her loss will ebb, in due time. We need to inform Alexstrasza and the others of what has transpired here... and of the future of the black dragonflight. With all that you have done to ensure that we have a chance at a future, I would like you to be there.", ["objectivesText"] = "Meet Ebyssian at the Seat of the Aspects in Valdrakken. Progress: We shall see you there, <name>.", ["rewardXP"] = 1770, ["rewardItems"] = { 206006 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 203011, ["x"] = 0.584, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 68, ["flags"] = 0 } } },
[75145] = { ["id"] = 75145, ["name"] = "In the Wake of the Ashes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "We did all we could. We will return to help them rebuild, but for now... the people of Loamm need time to mourn. Alexstrasza must be informed of what happened here today. She must be warned what has been unleashed upon the Dragon Isles. We will meet you at the Seat of the Aspects.", ["objectivesText"] = "Meet Ebyssian at the Seat of the Aspects in Valdrakken. Progress: Everyone must know what happened. It is the only way we can hope to prepare for the damage to come.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 204584, 204592, 204600, 204608, 205989 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201784, ["x"] = 0.56, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 203151, ["x"] = 0.5836, ["y"] = 0.3876 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 40, ["flags"] = 0 } } },
[75230] = { ["id"] = 75230, ["name"] = "Reconcilable Dissidents", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "My hope, <name>, is that our work to understand the rebels will allow us to find a path to peace. My concern is if we are not able to come to an understanding with Belaphon, other rebels may see her as a martyr for the cause. Whatever happens, you have my gratitude for your assistance throughout this rebellion.", ["objectivesText"] = "Listen to Alexstrasza's conversation with Instigator Belaphon. Progress: I hope Belaphon can see the way forward for Dragonkin.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 200839, ["x"] = 0.765, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 200839, ["x"] = 0.765, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 12, ["flags"] = 0 } } },
[75233] = { ["id"] = 75233, ["name"] = "Flesh to Bone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75233 }, ["description"] = "We found Skuttog near a cave to the north, by some nasty spiders. It seems like his skin is turning into bone. I can heal him, but I need venom from whatever bit him. Please help.", ["objectivesText"] = "Find the venom of the beast that bit Skuttog. Progress: Please hurry. He's almost a statue already.", ["rewardGold"] = 309800, ["rewardItems"] = { 204714, 204728, 204797, 204805, 204810, 204811, 205030, 205031 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 203378, ["x"] = 0.432, ["y"] = 0.84 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203378, ["x"] = 0.432, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75244] = { ["id"] = 75244, ["name"] = "Reunited Again", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Thanks to you, <name>, all of the blue dragons are accounted for. We can get back to caring for Azeroth's magic and making sure its power isn't abused. I believe a speech is in order. I would be honored if you would stay for it. We can head to the Nexus afterwards to see what Azuregos has discovered about Sindragosa and Malygos's arcane memories.", ["objectivesText"] = "Listen to Kalecgos 's speech. Progress: It is good to see so many blue dragons returned.", ["rewardGold"] = 28900, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 58, ["flags"] = 0 } } },
[75367] = { ["id"] = 75367, ["name"] = "The Obsidian Rest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["series"] = { 72987, 74393 }, ["description"] = "It is a miracle this outpost survived so long after Neltharion's... disappearance. For weeks now local scouts have reported increased djaradin activity in the area. They are amassing an army, and they are also becoming increasingly aggressive in their efforts to expand their territory. We must take every possible precaution and try to understand our enemy's motivations.", ["objectivesText"] = "Gather information and resources at the Obsidian Rest. Progress: These are trying times for all of us.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204819 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200046, ["x"] = 0.5, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200046, ["x"] = 0.5, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 42, ["flags"] = 0 } } },
[75417] = { ["id"] = 75417, ["name"] = "Symbol of Hope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "Champion--Ebyssian, Sabellian, and Wrathion have come to an agreement of who should lead, and are presenting a unified front. All three were quite eager to speak of your contributions and aid in Zaralek Cavern as well. It seems that they are also in agreement that they could not have succeeded without you. High praise indeed--and well deserved. Please, stay for a little longer. The other Aspects and I have matters to discuss, and I believe you should be here as well.", ["objectivesText"] = "Speak with Alexstrasza. Progress: Please, stay for a little longer. The other Aspects and I have matters to discuss, and I believe you should be here as well.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 69, ["flags"] = 0 } } },
[75419] = { ["id"] = 75419, ["name"] = "Sundered Flames", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "Did Neltharion keep this place as his hoard? No wonder that Sarkareth was looking for it. Neltharion's \"treasures\" litter every corner of it. There's no telling what Sarkareth has gotten his claws on here. Stay close!", ["objectivesText"] = "Find Sarkareth.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200075, ["x"] = 0.627, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204040, ["x"] = 0.63, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.627, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 21, ["flags"] = 0 } } },
[75440] = { ["id"] = 75440, ["name"] = "Satiating Sharpbeak", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75440 }, ["description"] = "Sheridon Hastle was our flight master and Sharpbeak 's rider. After his death, she won't let anyone touch her. <Narvra clutches her side in pain.> Or feed her. Rupert tried but... she just won't. The rest of us are too injured to move... I'm worried about her. Can you... ow... try? Someone new may get through to her. Her feed is in the bag by the tent. And... if you can get her to accept food, she might let you ride her.", ["objectivesText"] = "Feed Sharpbeak in the Dragonscale Camp in Zaralek Cavern . Progress: < Sharpbeak looks at you mournfully.>", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 205217 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200300, ["x"] = 0.402, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4655, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75462] = { ["id"] = 75462, ["name"] = "Mouse Rescuers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75462 }, ["description"] = "I feel bad for everything I did working for Malrogg . He was just so big and scary, I never felt like I had a choice... < Agrul slowly shakes his head.> No more excuses. We need to get that sniffin' mouse back home to Yarren . I was never strong enough to take on Malrogg alone. But you... You can save Persii .", ["objectivesText"] = "Kill Malrogg . Progress: Did you find that drogbar?", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 205253 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202597, ["x"] = 0.51, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4875, ["y"] = 0.7735 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75493] = { ["id"] = 75493, ["name"] = "Surveying the Riverbed", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Hope you brought your boots, 'cause this is gonna be a wet one! This river carries artifacts down from the mountains, and they wash up here in the silt. The centaur have found loads of stuff here over the years. We're here to take a deeper look and see if there's anything interesting below the surface.", ["objectivesText"] = "Speak with Roska to start the dig, then excavate artifacts from the riverbed.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210435 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 204094, ["x"] = 0.674, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 204643, ["x"] = 0.664, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 8, ["flags"] = 0 } } },
[75518] = { ["id"] = 75518, ["name"] = "The Body on the Banks", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "<The state of the corpse of this centaur woman is surprising. Her clothing is in a style unfamiliar to you, and her skin is emblazoned with intricate tattoos. Her body is intact, so it seems as though she could not have been dead long... or could she? Conditions here may have led to better preservation. Roska will want to have a look at this!>", ["objectivesText"] = "Speak to Roska to begin carefully excavating the centaur corpse. Progress: Nothing like silt, eh <name>? Never know what you'll find!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210435 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 204245, ["x"] = 0.664, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 204643, ["x"] = 0.664, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 9, ["flags"] = 0 } } },
[75604] = { ["id"] = 75604, ["name"] = "Antiquated Antics", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Well, there's two factors at play here, eh? We should do our due diligence and figure out who this was a statue of. But between you and me? I'm much more interested in learning about the jokesters that turned it into this work of art. I'm sure there's a historian of the black dragonflight somewhere near Aberrus. And why don't you poke around Loamm to see if there are any stories surrounding this kind of... artistic license.", ["objectivesText"] = "Find experts from both Loamm and the black dragonflight to weigh in on your find. Progress: <Roska looks pleased with your work.>", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 208055, ["x"] = 0.476, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 208055, ["x"] = 0.476, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 25, ["flags"] = 0 } } },
[75632] = { ["id"] = 75632, ["name"] = "A Dislocated Disc", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "As a gesture of good will, Eternus has pledged her assistance in finding the disc that contains Tyr's memories. The infinites have devices that can aid in divining its location. To quote Eternus , \"This is a mess Deios made. It is fair we help clean it up.\" I feel some responsibility as well after our attempt to wake Tyr with the Silver Scale. Meet Eternus at Tyrhold. She will brief you on her progress. Perhaps now our old friend will finally join us once more.", ["objectivesText"] = "Meet Eternus in Tyrhold.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 208198, 208200 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204574, ["x"] = 0.604, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 0, ["flags"] = 0 } } },
[75633] = { ["id"] = 75633, ["name"] = "We Have the Technology", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "During our... long discussion about how to find Tyr's disc, Chromie and I agreed that you were the right person to help us, <name>. But finding the location of Tyr's disc could be very dangerous and would likely require more than just your help. While I work here to narrow down what we need to find the disc, Chromie can give you more details.", ["objectivesText"] = "Ask Chromie about the plan to recover Tyr's memory disc.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204574, ["x"] = 0.604, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204577, ["x"] = 0.604, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 1, ["flags"] = 0 } } },
[75634] = { ["id"] = 75634, ["name"] = "Reforging the Tyr's Guard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "After the tomb was destroyed and the Silver Scale failed to bring Tyr back, I made the decision to rededicate my life to Tyr. And I made the even harder decision to leave the past behind and reforge Tyr's Guard. I had faith Tyr would need me again soon. And, after consulting with the Silver Hand, Koranos and I believe we have found four worthy Tyr's Guard recruits. Come with me to Brackenhide Hollow, and assist me in their final training. Then we can venture into the timeways to find Tyr's disc.", ["objectivesText"] = "Meet Travard at the Tyr's Guard camp in Brackenhide Hollow.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204577, ["x"] = 0.604, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 206221, ["x"] = 0.176, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 2, ["flags"] = 0 } } },
[75635] = { ["id"] = 75635, ["name"] = "For Tyr!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "Did they all complete their trials successfully? Good. I'm sure you played no small part in that. There's one final step we need to take before I can formally induct our recruits as full-fledged members of the Tyr's Guard: the Tyr's Guard initiation ceremony. It would make me proud if you stood with us on the steps of Tyrhold as I formally reforge the Tyr's Guard. Will you join us?", ["objectivesText"] = "Witness the induction ceremony of the Tyr's Guard on the steps of Tyrhold.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 199197, 201302, 201303, 201304, 201305, 201306, 201307, 201308, 201309, 208198, 237812 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 206221, ["x"] = 0.176, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208968, ["x"] = 0.598, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.176, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 8, ["flags"] = 0 } } },
[75636] = { ["id"] = 75636, ["name"] = "Tyrangulation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "The portals are ready. The sooner your team deploys those beacons, the sooner we can get the location of the disc. How you deploy your forces is up to you--and Travard.", ["objectivesText"] = "Protect Travard at the Temple of Order.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204667, ["x"] = 0.604, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206686, ["x"] = 0.604, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 10, ["flags"] = 0 } } },
[75637] = { ["id"] = 75637, ["name"] = "The Final Beacon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "Valunei and Talthis still aren't back. They must have had trouble with their beacon. We can't find the disc without it, and there's no way to help from here. We must lead the Tyr's Guard through their portal to help. Are you ready, <name>?", ["objectivesText"] = "Help the Tyr's Guard activate the Final Beacon. Progress: We must discover what was happened.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206682, ["x"] = 0.604, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204605, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 11, ["flags"] = 0 } } },
[75638] = { ["id"] = 75638, ["name"] = "Dislocated Disc Located", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "We were successful, <name>, but we barely made it back from our battle with the Black Empire. Eternus is still divining the location of the disc, and while she does, I'd like to ask a favor. I have unwavering faith in my recruits, but... I am worried about Valunei . I would speak to her, but I don't want it to appear as though I think she has failed us. Talk to her and make sure she's all right. It may also be a good idea to check in with the rest of Tyr's Guard as well.", ["objectivesText"] = "Check in with the Tyr's Guard. Progress: I'm worried about my recruits, but maybe I should be worried about myself. Reforming the Tyr's Guard has been a kind of catharsis. But I'm worried that it may be too much so. I was devastated by the loss of my comrades in the Tyr's Guard... I worry that I may be pushing them too hard. Or myself. I've been at this a long time, <name>. But to see Tyr alive once more... that gives me purpose. I just hope wisdom comes with my age, and I do right by my new recruits. And that they all come home.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 208200 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204605, ["x"] = 0.604, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204605, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 12, ["flags"] = 0 } } },
[75643] = { ["id"] = 75643, ["name"] = "Orientation: Loamm Niffen", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "I'm impressed. Elder Honeypelt speaks highly of you--and that's rare! Your friends Ebyssian and Emberthal admittedly made similar impressions with us after we caught their scent. They told me of your hunt for the fiery monster that's invaded Zaralek from the uplands. A worthy reason to become allies. But we'll need a bit more time to discuss it. Why not take a short break to meet with my people. Trade, leisure, travel--there's no shortage of ways to spend your time here in Loamm!", ["objectivesText"] = "Meet the Flight Master in Loamm. Progress: Smells around every corner, but nothing dangerous!", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 204522, ["x"] = 0.57, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 }, { ["mapID"] = 2133, ["npcID"] = 204522, ["x"] = 0.57, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 13, ["flags"] = 0 } } },
[75644] = { ["id"] = 75644, ["name"] = "Six Hundred Feet Under", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "That was just a taste of the niffen lifestyle. There's still far more to Loamm and even more from Zaralek Cavern . Continue exploring while you pursue the fiery monster, and let its scents continue to amaze you! For now, Ebyssian asked that I send you his way. Seems your companions are planning what to do next.", ["objectivesText"] = "Discuss the next plan of action with Ebyssian . Progress: There is much to discuss.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201366, ["x"] = 0.557, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.561333, ["y"] = 0.554667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 14, ["flags"] = 0 } } },
[75665] = { ["id"] = 75665, ["name"] = "A Worthy Ally: Loamm Niffen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75665 }, ["description"] = "Djaradin, dracthyr, and dragons! Oh my! You can't help but smell the danger in these here caverns. We sure could use some armed assistance. You scratch my back, and I'll make sure the kith scratch yours! We got loads of good stuff... for the right clientele. How about it? Get out there and bury the competition?", ["objectivesText"] = "Aid the niffen and their allies throughout Zaralek Cavern . Progress: Are our enemies six feet under?", ["rewardItems"] = { 205249, 205288, 205342, 205367, 205983, 205985 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[75694] = { ["id"] = 75694, ["name"] = "Aberrus, the Shadowed Crucible: Sarkareth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931, 72958, 72959, 72961, 72962, 72963, 72964, 72965, 72966, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 72987, 74334, 74375, 74393, 74494, 74521, 74522, 74523, 74525, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75018, 75028, 75029, 75145, 75367, 75417, 75419, 75643, 75644, 75694, 91691, 91695 }, ["description"] = "I have no interest in following my brothers within Aberrus, but I continue to care for their safety. Neltharion fell so deeply into madness that his secret stronghold is no doubt filled with any number of unspeakable dangers. Go with them, <name>. Stand with them. They will need your support in what is to come.", ["objectivesText"] = "Enter Aberrus, the Shadowed Crucible, and defeat Sarkareth. Progress: Aberrus holds mysteries and dangers alike. They must be dealt with, before any of them fall into the wrong hands.", ["rewardGold"] = 1239200, ["rewardXP"] = 2830, ["rewardItems"] = { 204682 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 }, { ["mapID"] = 2133, ["npcID"] = 201727, ["x"] = 0.48, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 }, { ["mapID"] = 2133, ["npcID"] = 201727, ["x"] = 0.48, ["y"] = 0.118 }, { ["mapID"] = 2112, ["npcID"] = 204287, ["x"] = 0.6056, ["y"] = 0.4176 }, { ["mapID"] = 2112, ["npcID"] = 214851, ["x"] = 0.603333, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "raid", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 61, ["flags"] = 0 } } },
[75707] = { ["id"] = 75707, ["name"] = "A Race to the Finish", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75707 }, ["description"] = "Everyone loves a good snail race! In the most exciting races, every snail has a chance to win. You can help a snail win by giving it treats. Watch how fast it makes them go! Grab a bag of treats and toss them in the path of the snails. See if you can get Brulee to win!", ["objectivesText"] = "Help Brulee win a race. Progress: Has your snail won the race?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 205119, 205121, 205123 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201099, ["x"] = 0.444, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201099, ["x"] = 0.444, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75729] = { ["id"] = 75729, ["name"] = "Attune to the Observer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Can you believe this used to be an observatory? Our records indicate that the dragonkin here were mapping heavenly bodies in an attempt to predict the future. How do you think they did it? I'm picking up a partial signature that matches the time window we're shooting for. Put on the Technoscryers and try to pinpoint the sources so we can dial it in.", ["objectivesText"] = "Technoscry for the three attunement relics. Progress: Without those attunement relics we won't be able to solve this mystery, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5515, ["name"] = "Technoscrying: Concord Observatory", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 12, ["flags"] = 0 } } },
[75859] = { ["id"] = 75859, ["name"] = "Aiding the Accord: Sniffenseeking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future. Now then, to business. Our niffen allies in Zaralek Cavern are always on the lookout for something new and exciting--or smelly. Join them on a dig through the many lost and forgotten caverns in their domain, and see what you find. We await your return, <name>.", ["objectivesText"] = "Travel to Zaralek Cavern and accompany Myrrit in Loamm on a dig underground. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Do you bring news of your success?", ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 202180, 203655, 204867, 205185, 205186, 205202, 205277, 205412, 205689, 205938, 205939, 205941, 205969, 205990, 206000, 206001, 206002 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 8, ["flags"] = 1 } } },
[75860] = { ["id"] = 75860, ["name"] = "Aiding the Accord: Researchers Under Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future. Now then, to business. Researchers of the Dragonscale Expedition are exploring the depths of Zaralek Cavern. They are asking for brave adventurers to help protect them from the many dangers in that area. We await your return, <name>.", ["objectivesText"] = "Travel to Zaralek Cavern and protect the Researchers Under Fire. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 204076, 207002, 208090, 208945, 208951, 208952 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 9, ["flags"] = 1 } } },
[75861] = { ["id"] = 75861, ["name"] = "Aiding the Accord: Suffusion Camp", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Ash blows from the south. A dark bargain has been made, <name>, between the djaradin of the Zaqali and Fyrakk. Their forces are building... something. We do not know what their goals are, but they have had no hesitation in displacing anyone and everything in their path. Please, <name>, we need champions like you to undermine these villains and deprive them of their resources. We await your return, <name>.", ["objectivesText"] = "Travel to a Suffusion Camp and loot a Secured Shipment. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", ["rewardXP"] = 12250, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 10, ["flags"] = 1 } } },
[75867] = { ["id"] = 75867, ["name"] = "A Link to the Past", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Okay, calibrations complete! Mine too, so I'll be able to see what you see. Let's head over to that telescope and we'll see what we see.", ["objectivesText"] = "Observe the events from the past. Progress: I wonder what we'll find?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5515, ["name"] = "Technoscrying: Concord Observatory", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 13, ["flags"] = 0 } } },
[75868] = { ["id"] = 75868, ["name"] = "A Window into the Future", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Those lenses are a wondrous integration of technology and arcane artifice. I'm sure we could learn much, and maybe even upgrade my own invention. But first we'll need to find it. You're a dragonrider, right? Can you fly up and recover the lens? It's possible the dreadsqualls still have it in one of their nests.", ["objectivesText"] = "Search Dreadsqualls nests to recover the lens. Progress: Did you recover the lens, <name>?", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 205455, 207460 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5515, ["name"] = "Technoscrying: Concord Observatory", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 14, ["flags"] = 0 } } },
[75885] = { ["id"] = 75885, ["name"] = "Get Rich Quick", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75885 }, ["description"] = "Uplander! I have a question for you. Do you want to wear an expensive hat like mine? Own the best snails in town? Enjoy the good life? If the answer is yes, you're ready to make more wealth than you've ever dreamed of! Ponzo style! Together we can both be rich! Of course I'm already rich, but you can be too! Just take these items I have here and show them around town. I'll cut you in for a share of the profits for every order you get.", ["objectivesText"] = "Get the citizens of Loamm to order some Ponzo 's Cream and Glimmerogg Timeshare Vouchers. Progress: Did you get any orders?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204985, 205188 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 204693, ["x"] = 0.58, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204693, ["x"] = 0.58, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75890] = { ["id"] = 75890, ["name"] = "The Clarion Call", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["series"] = { 75891, 76194 }, ["description"] = "Good to see you, <name>. I have a message from someone called Arko'narin Starshade . It reads... \"As a protector of the kaldorei, I must ask for you to meet me near the embassy in Stormwind. Tyrande has called the Wardens to action, and Maiev Shadowsong herself requested your aid in this matter as well.\" Arko'narin Starshade", ["objectivesText"] = "Speak with Arko'narin Starshade near the Stormwind Embassy in Stormwind City. Provided item:", ["rewardGold"] = 31900, ["rewardXP"] = 850, ["rewardItems"] = { 170063, 174077, 203176, 206942, 208476, 210054, 218105, 218118, 218119, 242520, 264334 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 207353, ["x"] = 0.525, ["y"] = 0.045 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.045 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 206942 } },
[75891] = { ["id"] = 75891, ["name"] = "Ancient Curses", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["series"] = { 75890, 76194 }, ["description"] = "Thank you for answering my call so quickly, <name>. Demonic corruption has seen a resurgence in Felwood recently. Tyrande sent out a contingent of Sentinels and one of her own priestesses to investigate the matter further. None have returned. Tyrande asked the Wardens to look into the matter--and Maiev has asked for your assistance personally. We need to make haste to Felwood, and see what Maiev has discovered.", ["objectivesText"] = "Meet Maiev Shadowsong in Felwood. Progress: May Elune guide us all to victory in this forsaken place.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 207353, ["x"] = 0.525, ["y"] = 0.045 } }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 202702, ["x"] = 0.372667, ["y"] = 0.549333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.045 }, ["mapCandidates"] = { ["npc"] = { 77, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 77, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[75918] = { ["id"] = 75918, ["name"] = "Fire Season", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923 }, ["description"] = "No doubt you have seen the destruction that Fyrakk continues to leave in his wake. While others fight him directly, my troops and I have been serving as the eyes and ears of the green dragonflight. Although Fyrakk's actions may seem erratic, there are trends to his strategies. We learned that he is to have a secret meeting with Vyranoth soon in Lunedane. This is a deviation from his recent tactics, and we need to know why. Given the danger, we would value your aid. Meet me in Lunedane.", ["objectivesText"] = "Meet Shandris at Lunedane in the Ohn'ahran Plains .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 205067, ["x"] = 0.502, ["y"] = 0.533 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 205068, ["x"] = 0.186, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.533 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5381, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5381, ["name"] = "The Coalition of Flames", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 0, ["flags"] = 0 } } },
[75919] = { ["id"] = 75919, ["name"] = "Dousing the Wards", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923 }, ["description"] = "Fyrakk and Vyranoth are already here. I spotted them near the overlook at the northeastern edge of Lunedane. Landing close to their location would reveal our presence, thus we are forced to begin our mission here. However, the bridge connecting this area to the overlook has been protected with fire magic. We will not be able to break through it. Fyrakk's Primalist allies appear to be maintaining the fire using wards set up around this area. If we destroy the wards, the fire should subside.", ["objectivesText"] = "Destroy 4 Warding Firestones. Progress: We need to bring that barrier down so we can get closer to the Incarnates. We cannot hear them from this far away.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 205068, ["x"] = 0.186, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5381, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5381, ["name"] = "The Coalition of Flames", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 1, ["flags"] = 0 } } },
[75920] = { ["id"] = 75920, ["name"] = "Eyes of Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923 }, ["description"] = "This area is swarming with far more Primalists than I expected. Fyrakk does not generally travel with guards, so I doubt the Primalists are here to accompany him. They seem to be trying to establish a foothold here. But why? Perhaps whatever the Incarnates are discussing will answer that question. In the meantime, let us thin out the Primalists guarding this area. We cannot risk having them in full force behind us as we cross the bridge.", ["objectivesText"] = "Kill 8 Burning Flamespeakers or Blazing Overseers . Progress: We will need to work quickly. We cannot risk drawing the attention of the Incarnates.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 205068, ["x"] = 0.186, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5381, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5381, ["name"] = "The Coalition of Flames", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 2, ["flags"] = 0 } } },
[75921] = { ["id"] = 75921, ["name"] = "Through the Flames", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923 }, ["description"] = "Druids of the Flame... <Shandris frowns deeply, eyes shut as she holds back her anger.> To think that they still exist. That any of our people would join Fyrakk and his-- <She stops, releases a heavy breath, and continues.> We have a mission to complete. We need to cross the bridge to get close enough to the Incarnates that we can overhear their conversation. I will shroud us so that we can move between the elementals still guarding the way forward.", ["objectivesText"] = "Collect 4 Smoldering Blossoms while crossing the bridge towards Fyrakk and Vyranoth. Progress: We need be as close to the Incarnates as we can. We cannot afford to miss a single word of their conversation.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 59529, 59530, 131310, 175470, 175471, 175472, 175473, 206598 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 205134, ["x"] = 0.218, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.218, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5381, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5381, ["name"] = "The Coalition of Flames", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 3, ["flags"] = 0 } } },
[75922] = { ["id"] = 75922, ["name"] = "Inflammatory Information", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923 }, ["description"] = "<Shandris whispers to you.> Do you see that up ahead? The Druids of the Flame have captured what appears to be a keeper--a guardian of nature, sacred to our people. If their power is already enough to... <Shandris shakes her head, then gestures at the dense shrubbery nearby.> Stay hidden with me and we will listen to the Incarnates, and perhaps discern what the druids intend to do with the keeper.", ["objectivesText"] = "Eavesdrop on Fyrakk and Vyranoth. Progress: I will hold off any reinforcements that come. Deal with the keeper!", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 205134, ["x"] = 0.218, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 205142, ["x"] = 0.216, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.218, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5381, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5381, ["name"] = "The Coalition of Flames", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 4, ["flags"] = 0 } } },
[75923] = { ["id"] = 75923, ["name"] = "Raise the Alarm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923 }, ["description"] = "So the Druids of the Flame have allied with Fyrakk to help him invade the Emerald Dream. They were able to turn that keeper to the flame with hardly any effort. Fyrakk must be bolstering their power, perhaps as payment for their aid in accessing the Dream. We need to mobilize troops immediately to find every Druid of the Flame on the Dragon Isles and stop them. Go to Captain Drine in Valdrakken and alert her. She will dispatch the drakonid. I will go to Merithra and handle things here.", ["objectivesText"] = "Deliver your report to Captain Drine at the Seat of the Aspects in Valdrakken.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 206353 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 205142, ["x"] = 0.216, ["y"] = 0.77 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 206041, ["x"] = 0.544, ["y"] = 0.4724 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5381, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5381, ["name"] = "The Coalition of Flames", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 5, ["flags"] = 0 } } },
[75950] = { ["id"] = 75950, ["name"] = "An Exemplar of Justice: Hadwin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "We've been out here for a good bit of time. Time enough for me to watch the gnolls around here. Gnolls are usually a nuisance, but the decay gnolls around Brackenhide Hollow... The decay doesn't just warp their bodies. It warps their minds too. Decaymonger Rotpaw is the worst of them. She's indiscriminate in who or what she spreads her decay to: the unwilling of her people, travelers, animals, children... If there's any justice in this world, she should be taken down.", ["objectivesText"] = "Help Hadwin defeat Decaymonger Rotpaw .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 204590, ["x"] = 0.176, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 204590, ["x"] = 0.176, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.176, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 4, ["flags"] = 0 } } },
[75951] = { ["id"] = 75951, ["name"] = "An Exemplar of Order: Talthis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "I know why Travard chose this area for our training. The decay here is... chaotic and disordered. Things that Tyr and the titans are not! The nearby gnolls revel in the decay. Revolting. They have taken over territory that was once occupied by the proud, noble, and civil tuskarr. The tuskarr have asked that relics they had to abandon are returned to them. Please help me fight the gnolls and retrieve the relics so the tuskarr can continue their rituals in Iskaara.", ["objectivesText"] = "Bring Talthis 5 Tuskarr relics. Progress: The gnolls had no right to those relics. They belong to the tuskarr.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 206204 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 204593, ["x"] = 0.175, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 204593, ["x"] = 0.175, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.175, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 5, ["flags"] = 0 } } },
[75952] = { ["id"] = 75952, ["name"] = "An Exemplar of Sacrifice: Nolaki", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "Much is said about how decay spreads through the air and ground. But it also spreads through the water. Slimes that live in the rivers and streams ooze pestilence. The water is toxic with it. But if we wade in and kill the big one, the poison in the water will diminish. It may poison me in the process, but I am going to kill one if it's the last thing I do. This place needs a purging. Are you with me, <name>?", ["objectivesText"] = "Help Nolaki defeat a massive slime.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 204592, ["x"] = 0.175, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 204592, ["x"] = 0.175, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.175, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 6, ["flags"] = 0 } } },
[75953] = { ["id"] = 75953, ["name"] = "An Exemplar of Compassion: Valunei", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "It makes my heart ache to see what the decay has done to some of the wildlife here... I cannot save all the creatures that live around Brackenhide Hollow, but I wish for my trial to at least save some. In a cave to the west, there is a family of bears that has recently been corrupted. I believe I can fight my way there and heal them. Will you help me, <name>?", ["objectivesText"] = "Protect Valunei from decay gnolls.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 204591, ["x"] = 0.176, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 204591, ["x"] = 0.176, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.176, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 7, ["flags"] = 0 } } },
[75985] = { ["id"] = 75985, ["name"] = "Rest Well, Warrior", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75985 }, ["description"] = "Shalkeel deserves to be seen off properly. I want to dress his burial area and say a few words. I know your time is precious, but would you take the shovel and bury his ashes while I perform the rites?", ["objectivesText"] = "Assist Khasar with Shalkeel's burial. Progress: If I were able to handle his ashes, I'd have poured them out over the stream he and I played in when we were children.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204461 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 202788, ["x"] = 0.87, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 202788, ["x"] = 0.87, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.87, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[76026] = { ["id"] = 76026, ["name"] = "Surveying the Tower", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Get a load of those rock formations! Surveying doesn't get much better than this. This tower has been here for ages. The black dragonflight used it for some seriously dark stuff, but that's not why we're here. After the dragons left, a troupe of niffen bandits took shelter in the ruins and robbed the place blind. But they left a bunch of trash everywhere. Imagine what we could learn about the niffen from that trash once we get digging!", ["objectivesText"] = "Speak with Roska to start the dig, then excavate artifacts from around the tower.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210834 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205413, ["x"] = 0.486, ["y"] = 0.484 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 208055, ["x"] = 0.476, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 23, ["flags"] = 0 } } },
[76032] = { ["id"] = 76032, ["name"] = "Hidden in the Midden", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "<This dragon statue is similar to others found in the region but has been covered in paint. Googly eyes, stink lines, whiskers, and all manner of other rude drawings decorate the otherwise-imposing stone. The paint looks old and is flaking in places but is not as old as the statue itself. Roska will want to have a look at this!>", ["objectivesText"] = "Carefully excavate the defaced dragon statue . Progress: Nothing like volcanic rock, eh <name>? Never know what you'll find!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210834 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 207931, ["x"] = 0.475, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 208055, ["x"] = 0.476, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 24, ["flags"] = 0 } } },
[76101] = { ["id"] = 76101, ["name"] = "Tougher Down Under", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 76101 }, ["description"] = "Quite a few uplanders have arrived since the cavern was split clean open! A friendly winged-one by the name of Vaskarn has been particularly helpful to us. She's made the guard's armor tougher and the monster hunter's weapons stronger. She's going to be plenty valuable if you plan on taking down more giant beasties here in Zaralek!", ["objectivesText"] = "Speak with Vaskarn .", ["rewardGold"] = 341600, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 }, { ["mapID"] = 2133, ["npcID"] = 204522, ["x"] = 0.57, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203404, ["x"] = 0.565, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.561333, ["y"] = 0.554667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 227, ["title"] = "Flightstones", ["questLineID"] = 5394, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5394, ["name"] = "Flightstones", ["orderIndex"] = 0, ["flags"] = 0 } } },
[76140] = { ["id"] = 76140, ["name"] = "Dawn of the Infinite", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 76140, 76141, 76142, 76143, 76144, 76145, 76146, 76147 }, ["description"] = "My vision is hazy, but there is no mistaking what I saw. A dark alliance opposes the bronze dragonflight. One I do not know if I shall be able to overcome... I ask you to meet me in Eon's Fringe, <name>. We will speak more of this threat there. If there is any who I would entrust with safeguarding our future, it is you.", ["objectivesText"] = "Meet Nozdormu at Eon's Fringe in Thaldraszus.", ["rewardGold"] = 77400, ["rewardXP"] = 1470, ["rewardItems"] = { 208415, 208417 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205706, ["x"] = 0.522, ["y"] = 0.794 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5408, ["name"] = "Dawn of the Infinites", ["orderIndex"] = 0, ["flags"] = 0 } } },
[76141] = { ["id"] = 76141, ["name"] = "Align in the Sand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76140, 76141, 76142, 76143, 76144, 76145, 76146, 76147 }, ["description"] = "So, the timeways, yeah? They're VERY misaligned. And you know how we bronzes hate that! So we need to realign time with these temporal hourglasses. Just plop them down throughout Eon's Fringe. But you know me, always needing to help! So I'll be placing another hourglass nearby. Meet me there when you're all done.", ["objectivesText"] = "Place the Temporal Hourglasses throughout the Shifting Sands in Thaldraszus. Progress: I never thought you would be the one making a mess of the timeways! Usually you're the one helping us get out of trouble, not in it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208415 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205706, ["x"] = 0.522, ["y"] = 0.794 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205707, ["x"] = 0.614, ["y"] = 0.796 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5408, ["name"] = "Dawn of the Infinites", ["orderIndex"] = 1, ["flags"] = 0 } } },
[76142] = { ["id"] = 76142, ["name"] = "On Borrowed Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76140, 76141, 76142, 76143, 76144, 76145, 76146, 76147 }, ["description"] = "I need you to fetch me some time-lost essence . The creatures around here are filled to the brim with the stuff. Snuff them out and then use this epoch extractor to collect their essence. We'll make good use of it for our next step! And yes, this is going to be a multi-step process. You know how crazy these time shenanigans get!", ["objectivesText"] = "Extract Time-Lost Essence from slain Time-Lost creatures in the Shifting Sands. Progress: What's this? Time-lost essence ? An epoch... extractor?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 139506, 139770, 206269, 206586, 224272, 224273, 224274, 237812 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205706, ["x"] = 0.522, ["y"] = 0.794 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205707, ["x"] = 0.614, ["y"] = 0.796 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5408, ["name"] = "Dawn of the Infinites", ["orderIndex"] = 2, ["flags"] = 0 } } },
[76143] = { ["id"] = 76143, ["name"] = "Chro-me?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76140, 76141, 76142, 76143, 76144, 76145, 76146, 76147 }, ["description"] = "One result of your \"time realignment\" is that it seems to have summoned... me? Well, alternate timeline versions of me. I've never seen so many Chromies in one place! And while they all may be cute, they're playing havoc on the local timeways. We need to trap them to synchronize their time signatures. Maybe then they'll be able to tell us what's going on!", ["objectivesText"] = "Trap Alternate Chromies in time stasis. Progress: I know it's not very polite to trap a fellow Chromie , but we need to synchronize their time signatures as soon as we can! I'm sure they'll all understand. I know I would! I think?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 206369 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205707, ["x"] = 0.614, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205707, ["x"] = 0.614, ["y"] = 0.796 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5408, ["name"] = "Dawn of the Infinites", ["orderIndex"] = 3, ["flags"] = 0 } } },
[76144] = { ["id"] = 76144, ["name"] = "Morchie Mayhem", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76140, 76141, 76142, 76143, 76144, 76145, 76146, 76147 }, ["description"] = "We need to get to the bottom of this \"future Chromie \" business. Just where is that dragon? She needs to explain herself! Let's start by inspecting one of her temporal hourglasses. Maybe that will give us a clue.", ["objectivesText"] = "Investigate the false Future Chromie . Progress: Oh, that Morchie! I've never met such a tricky, nasty Chromie in all my life.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205707, ["x"] = 0.614, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206149, ["x"] = 0.62, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5408, ["name"] = "Dawn of the Infinites", ["orderIndex"] = 4, ["flags"] = 0 } } },
[76145] = { ["id"] = 76145, ["name"] = "Who's That Chromie?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76140, 76141, 76142, 76143, 76144, 76145, 76146, 76147 }, ["description"] = "Morchie didn't just teleport herself away, she took all the other Chromies with her! I have a bad feeling about why... We have to follow and capture her. And question her! I want to know what she's up to.", ["objectivesText"] = "Capture Morchie and question her.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206149, ["x"] = 0.62, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205710, ["x"] = 0.612, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5408, ["name"] = "Dawn of the Infinites", ["orderIndex"] = 5, ["flags"] = 0 } } },
[76171] = { ["id"] = 76171, ["name"] = "Walking the Path of Tyr", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "Before they embark on their last training trial, it is a tradition that recruits first receive their Tyr's Guard gear. The highest-ranking Tyr's Guard officer would normally do this but... I would be honored if you would bestow their tabard and shield on them for their final trial instead.", ["objectivesText"] = "Distribute gear to the Tyr's Guard. Progress: The tabard and shield are important symbols of a new recruit's dedication to the Tyr's Guard.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 206476, 208198 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 206221, ["x"] = 0.176, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 206221, ["x"] = 0.176, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.176, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 3, ["flags"] = 0 } } },
[76176] = { ["id"] = 76176, ["name"] = "First Steps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "Now, let's get to work tracking down the disc. I can't believe that after thousands of years we are so close to seeing Tyr return, much less that I will have a hand in it. We should meet with Chromie and Eternus inside. They'll tell us what to do next.", ["objectivesText"] = "Meet Chromie and Eternus in Tyrhold.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208968, ["x"] = 0.598, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204668, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 9, ["flags"] = 0 } } },
[76194] = { ["id"] = 76194, ["name"] = "A Grim Portent", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 361, ["mapID"] = 77, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["series"] = { 75890, 75891 }, ["description"] = "Tyrande suspected there was something foul happening here in Felwood... and she was right. Her priestess, Kaylessa, was sent here to purify the moonwell from the fel corruption that plagues this land, in an effort to reclaim that which belongs to us. Now we have lost one of our sisters and the moonwell still remains corrupted. We cannot let this stand. We will finish what Kaylessa started, and heal the moonwell. Arko'narin has history with this place. I will let her tell you why we are here.", ["objectivesText"] = "Speak with Arko'narin Starshade to learn about Jaedenar. Progress: Have you spoken with Arko'narin yet, <class>?", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 77, ["npcID"] = 202702, ["x"] = 0.372667, ["y"] = 0.549333 } }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 202702, ["x"] = 0.372667, ["y"] = 0.549333 } }, ["coords"] = { ["mapID"] = 77, ["source"] = "quest_giver", ["x"] = 0.372667, ["y"] = 0.549333 }, ["mapCandidates"] = { ["npc"] = { 77 }, ["zone"] = { 361 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 77, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[76195] = { ["id"] = 76195, ["name"] = "Countering Corruption", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 361, ["mapID"] = 77, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["description"] = "I cannot thank you enough for your help with this, <name>. I knew I had to be here to help Nari when she told me about this mission. It seems as though my skills are needed, just as I thought. The magic here is foul and all-corrupting. It must be contained. Please, take this book and read the incantation within after putting the satyr around Jaedenar to rest. Jaedenar need not be a place of death and corruption any longer.", ["objectivesText"] = "Use the Incanter's Tome on 6 Feltouched satyr corpses. Progress: Please, <name>, you must make sure to cleanse the fel energies that seep from the satyr's corpses.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 207004 }, ["starts"] = { { ["mapID"] = 77, ["npcID"] = 202700, ["x"] = 0.3716, ["y"] = 0.5408 } }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 202702, ["x"] = 0.372667, ["y"] = 0.549333 } }, ["coords"] = { ["mapID"] = 77, ["source"] = "quest_giver", ["x"] = 0.3716, ["y"] = 0.5408 }, ["mapCandidates"] = { ["npc"] = { 77 }, ["zone"] = { 361 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 77, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[76196] = { ["id"] = 76196, ["name"] = "Mercy or Misery", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 361, ["mapID"] = 77, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["description"] = "This place... it was once so important to my family. That is why I agreed to come--and why Lysander wanted to come along as well. <Arko'narin glances over at Lysander before looking back at you.> Even after the horrors of Teldrassil, my brother still tries to do everything he can to help others. Much like you, <name>. Come. We must eliminate the threat that these power hungry cretins pose. I think you are just the kaldorei for the job.", ["objectivesText"] = "Slay cultists occupying Jaedenar in Felwood.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 77, ["npcID"] = 202701, ["x"] = 0.369667, ["y"] = 0.547 } }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 202702, ["x"] = 0.372667, ["y"] = 0.549333 } }, ["coords"] = { ["mapID"] = 77, ["source"] = "quest_giver", ["x"] = 0.369667, ["y"] = 0.547 }, ["mapCandidates"] = { ["npc"] = { 77 }, ["zone"] = { 361 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 77, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[76197] = { ["id"] = 76197, ["name"] = "A Glimpse of Terror", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 361, ["mapID"] = 77, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["description"] = "We will strike together on your command, <name>. <Maiev rolls her shoulders.> The last thing this fiend will see is our blades.", ["objectivesText"] = "Defeat Cultist Nethus . Progress: We must see this through, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 77, ["npcID"] = 202702, ["x"] = 0.372667, ["y"] = 0.549333 } }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 202702, ["x"] = 0.372667, ["y"] = 0.549333 } }, ["coords"] = { ["mapID"] = 77, ["source"] = "quest_giver", ["x"] = 0.372667, ["y"] = 0.549333 }, ["mapCandidates"] = { ["npc"] = { 77 }, ["zone"] = { 361 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 77, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 6, ["flags"] = 0 } } },
[76203] = { ["id"] = 76203, ["name"] = "Stepping into the Shadows", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 361, ["mapID"] = 77, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["description"] = "Their ranks have been thinned, and their corpses cleansed. You have done well. <Maiev shifts her weight, looking towards the path leading into Shadow Hold.> Come, <name>. We must find what lurks below and put an end to it.", ["objectivesText"] = "Navigate through Shadow Hold with Maiev Shadowsong , dealing with threats along the way. Progress: Not now, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 77, ["npcID"] = 202702, ["x"] = 0.372667, ["y"] = 0.549333 } }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 202702, ["x"] = 0.372667, ["y"] = 0.549333 } }, ["coords"] = { ["mapID"] = 77, ["source"] = "quest_giver", ["x"] = 0.372667, ["y"] = 0.549333 }, ["mapCandidates"] = { ["npc"] = { 77 }, ["zone"] = { 361 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 77, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 5, ["flags"] = 0 } } },
[76205] = { ["id"] = 76205, ["name"] = "Balancing the Scales", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 361, ["mapID"] = 77, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["description"] = "The time for subtlety is over. Lord Hel'nurath has made himself known to us... and I will not rest until I see him slain. <Maiev clenches her teeth.> Ready yourself, <name>. Together we will show these demons why they should fear the kaldorei.", ["objectivesText"] = "Slay enemies throughout Shadow Hold. Progress: We will not rest until Shadow Hold has been cleansed of this foul corruption!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 77, ["npcID"] = 202702, ["x"] = 0.372667, ["y"] = 0.549333 } }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 202702, ["x"] = 0.372667, ["y"] = 0.549333 } }, ["coords"] = { ["mapID"] = 77, ["source"] = "quest_giver", ["x"] = 0.372667, ["y"] = 0.549333 }, ["mapCandidates"] = { ["npc"] = { 77 }, ["zone"] = { 361 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 77, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[76206] = { ["id"] = 76206, ["name"] = "Heart of the Issue", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 361, ["mapID"] = 77, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["description"] = "I can't believe how much Nari has been through. This perversion of our history, our culture... my family... <Lysander glances at his sister.> These demons came in here from somewhere. I'm certain the source of their invasion lies in the depths of our barrow den. You and I can put a stop to it. I won't let this place haunt her any longer, <name>.", ["objectivesText"] = "Disrupt 4 Portals to the Twisting Nether in the depths of Shadow Hold.", ["rewardGold"] = 286500, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 77, ["npcID"] = 202700, ["x"] = 0.3716, ["y"] = 0.5408 } }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 202701, ["x"] = 0.369667, ["y"] = 0.547 } }, ["coords"] = { ["mapID"] = 77, ["source"] = "quest_giver", ["x"] = 0.3716, ["y"] = 0.5408 }, ["mapCandidates"] = { ["npc"] = { 77 }, ["zone"] = { 361 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 77, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 8, ["flags"] = 0 } } },
[76207] = { ["id"] = 76207, ["name"] = "Wardens' Wrath", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 361, ["mapID"] = 77, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["description"] = "Lord Hel'nurath's hubris gave me an opportunity to study what he's doing. I think I found a way to give us an opening to strike. <Arko'narin glances at her brother.> I fear this will take a lot out of Lysander. But I know he'll give it everything he has. Perhaps... perhaps my perceptions have been misplaced. It is time to put my... our demons to rest.", ["objectivesText"] = "Defend Lysander as he works to disrupt Lord Hel'nurath's ritual.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 77, ["npcID"] = 202701, ["x"] = 0.369667, ["y"] = 0.547 } }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 202700, ["x"] = 0.3716, ["y"] = 0.5408 } }, ["coords"] = { ["mapID"] = 77, ["source"] = "quest_giver", ["x"] = 0.369667, ["y"] = 0.547 }, ["mapCandidates"] = { ["npc"] = { 77 }, ["zone"] = { 361 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 77, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 9, ["flags"] = 0 } } },
[76212] = { ["id"] = 76212, ["name"] = "A Mark For A Protector", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 361, ["mapID"] = 77, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["description"] = "Traditions should not hold us back, <name>. They should inform the future. <Maiev looks at Lysander before turning her gaze back to you.> I have let my perceptions hold me back as well. No more. I am tired of seeing rifts between our people, regardless of what they use to better themselves or the world. It is time I give Lysander his marking. The kaldorei are no strangers to change. Our traditions should adapt to our lives, not define them.", ["objectivesText"] = "Observe Lysander's facial marking ceremony.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 77, ["npcID"] = 208151, ["x"] = 0.36, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 209141, ["x"] = 0.525, ["y"] = 0.045 } }, ["coords"] = { ["mapID"] = 77, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 77, 84 }, ["zone"] = { 361 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 10, ["flags"] = 0 } } },
[76213] = { ["id"] = 76213, ["name"] = "Honor of the Goddess", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["description"] = "Today is a day of celebration, <name>. And a day of new beginnings. Arko'narin and Lysander have reminded me that the kaldorei are no strangers to change. I forget, sometimes, how long I was away, and just how much my kin have progressed in my absence. <Maiev looks up to the sky.> Lysander celebrates this day, but your service also deserves to be recognized. Come, <name>.", ["objectivesText"] = "Learn the meaning of Ama'shan from Maiev Shadowsong .", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 208785, 208879, 248401 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 209140, ["x"] = 0.527, ["y"] = 0.043 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 209140, ["x"] = 0.527, ["y"] = 0.043 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.527, ["y"] = 0.043 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 11, ["flags"] = 0 } } },
[76276] = { ["id"] = 76276, ["name"] = "A Changed Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66218, 66223, 76276 }, ["description"] = "The arrival of Amirdrassil brings great change to Azeroth. Its roots are finding a home in the soil beneath even as its branches stretch skyward to taste the air. This is an auspicious moment, but we must not forget our allies from the Isles. Visit with those nearby to ensure they are safe and sound.", ["objectivesText"] = "Check on nearby Dragon Isles residents. Progress: Amirdrassil has safely arrived, but we must make sure our allies are also safe and sound.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 209806, 209915, 209916 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 206397, ["x"] = 0.148, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 206397, ["x"] = 0.148, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.148, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 273, ["title"] = "Lorewalking: Training", ["questLineID"] = 5740, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5740, ["name"] = "11.1.7 Lorewalking - Training (LAS)", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 59, ["flags"] = 0 } } },
[76280] = { ["id"] = 76280, ["name"] = "New Moon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "With these offerings and water from the Well of Eternity, we have all that we need. Speak with me when you are ready to begin the ritual.", ["objectivesText"] = "Speak with Tyrande Whisperwind in the Central Encampment to begin the ritual. Progress: Amirdrassil...", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 63, ["flags"] = 0 } } },
[76281] = { ["id"] = 76281, ["name"] = "Something Worth Celebrating", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "At long last... let us celebrate all that we have overcome, and the hope that burns brightly amongst these gathered kaldorei. Come, join the festivities.", ["objectivesText"] = "Serve tables at the celebration in Bel'ameth. Progress: Have you thoroughly enjoyed yourself, Champion?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 206849, ["x"] = 0.542, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 64, ["flags"] = 0 } } },
[76282] = { ["id"] = 76282, ["name"] = "A Disquieting Feeling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "Ah, <name>! You're just the person I was looking for. I'm a little concerned about Khadgar. I don't think it's anything dire, but he doesn't seem to be enjoying himself like everyone else--he just seems... distracted. I don't want to pry, but perhaps you could bring him a drink for me? He may open up to you.", ["objectivesText"] = "Bring Khadgar a drink in Bel'ameth. Progress: Were you able to cheer up Khadgar, <name>?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 208221, 209316, 209317, 209318, 209319, 209322, 209323, 209324, 209326, 209912, 209913, 209914 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 209042, ["x"] = 0.542, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 209042, ["x"] = 0.542, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 66, ["flags"] = 0 } } },
[76283] = { ["id"] = 76283, ["name"] = "Andu-falah-dor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "My mother asked for us all to meet her by the moonwell. It has been long enough. We should not keep her waiting. Speak with me there.", ["objectivesText"] = "Speak with Merithra in Bel'ameth.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 208067, 210920 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 206849, ["x"] = 0.542, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 208763, ["x"] = 0.508, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 67, ["flags"] = 0 } } },
[76317] = { ["id"] = 76317, ["name"] = "Call of the Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76318, 76319, 76320 }, ["description"] = "A great tree grows within the Dream. Soon, it will emerge in Azeroth. But before it does, we must protect it from Fyrakk's forces. We must band together and see it through its verdant birth. Join me and the others in the Ancient Bough. Together, we will travel into the Emerald Dream .", ["objectivesText"] = "Meet Merithra within the Ancient Bough in the Ohn'ahran Plains.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 206353, 208047, 208067, 208181, 210246, 210412, 210704, 210730, 210757, 210847 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187590, ["x"] = 0.186, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187590, ["x"] = 0.186, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 6, ["flags"] = 0 } } },
[76318] = { ["id"] = 76318, ["name"] = "Emerald Welcome", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76317, 76319, 76320 }, ["description"] = "We protected the tree by guarding all entrances to the Emerald Dream . Now Fyrakk has found allies to open the way for him. I will do the same for you and our allies. The green dragonflight cannot do this alone. Through this portal, we will enter the Dream together. We must protect that realm and all that grows within it.", ["objectivesText"] = "Enter the Emerald Dream through the portal in Ancient Bough. Progress: There is much to be done.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 210412 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187590, ["x"] = 0.186, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206425, ["x"] = 0.694, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023, 2200 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 7, ["flags"] = 0 } } },
[76319] = { ["id"] = 76319, ["name"] = "Feast or Flaming", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76317, 76318, 76320 }, ["description"] = "Already Fyrakk damages the fabric of the Dream. I can feel it burning, as if flames were consuming my scales. And I know that simmering agony is only a fraction of what my son felt when Fyrakk tormented him. But we have a potent weapon against this fire. Our faerie drakes and dragons consume what does not belong here. They are excellent allies, if a bit difficult to manage. Now they need our help. Use this. Clear the skies of encroaching flame.", ["objectivesText"] = "Dragonride or ride the Faerie Drake to consume fiery patches in the Dream. Progress: The Dream is my home and the home of my flight. I will not let it fall to fire.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206425, ["x"] = 0.694, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206510, ["x"] = 0.642, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 8, ["flags"] = 0 } } },
[76320] = { ["id"] = 76320, ["name"] = "Wild Gods in Our Midst", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76317, 76318, 76319 }, ["description"] = "The Emerald Dream is the home of nature's Wild Gods. We will need their strength and their power to counteract the damage that Fyrakk has brought to this realm. The first to seek out is Goldrinn . The ancient wolf has a fondness for Azeroth and mortals, so he is sure to aid us. Others may need more convincing. I will meet you nearby in the Fields of Reverie, where dryads and keepers reside.", ["objectivesText"] = "Seek out Wild Gods and allies within the Emerald Dream .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206510, ["x"] = 0.642, ["y"] = 0.582 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206583, ["x"] = 0.626667, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2254, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 9, ["flags"] = 0 } } },
[76321] = { ["id"] = 76321, ["name"] = "Burning Assault", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["description"] = "The Druids of the Flame are opening a way into the Dream for Fyrakk's forces. Every moment, more of them enter. We must stop this rising tide before it becomes a flood.", ["objectivesText"] = "Slay Primalists, Djaradin, and Druids of the Flame. Progress: Fyrakk's forces must be cut down before they can establish a hold on the Dream.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206583, ["x"] = 0.626667, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206688, ["x"] = 0.628, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.626667, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 10, ["flags"] = 0 } } },
[76322] = { ["id"] = 76322, ["name"] = "The Face of Our Enemies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["description"] = "Powerful foes lurk among the enemies Fyrakk summoned into the Emerald Dream . I have not seen Cassaphine since she came up out of the barrows. Find her, and assist our allies by striking down these leaders.", ["objectivesText"] = "Defeat Fyrakk's powerful lieutenants and secure the battlefield. Progress: It saddens me to see the children of the Dream so twisted.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206583, ["x"] = 0.626667, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206688, ["x"] = 0.628, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.626667, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 11, ["flags"] = 0 } } },
[76323] = { ["id"] = 76323, ["name"] = "Amirdrassil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76324, 76325, 76326, 77283, 77818 }, ["description"] = "This tree has grown peacefully in the Emerald Dream since it was planted here. We have watched over it and nurtured it. And now, just when it is about to leave the cradle of this realm and enter Azeroth, our enemies see it as a means to further their own plans. It is so much more. Come. Let us go to Amirdrassil.", ["objectivesText"] = "Meet Merithra at the base of Amirdrassil.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 206960, 208047, 210180, 210916 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206806, ["x"] = 0.589333, ["y"] = 0.615333 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206809, ["x"] = 0.538, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.589333, ["y"] = 0.615333 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 13, ["flags"] = 0 } } },
[76324] = { ["id"] = 76324, ["name"] = "Lost to the Flame", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76323, 76325, 76326, 77283, 77818 }, ["description"] = "The Druids of the Flame pose more of a threat than I realized. Not only do they let Fyrakk and his forces pour into the Dream, but they also tempt the Dream's denizens to the flame! We cannot dwell on how this happened. It pains me greatly, but Elder Cassaphine must be stopped. Go with Tyrande and... end the dryad.", ["objectivesText"] = "Defeat Elder Cassaphine at the base of Amirdrassil.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 209924, 209938 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206809, ["x"] = 0.538, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206979, ["x"] = 0.508, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 14, ["flags"] = 0 } } },
[76325] = { ["id"] = 76325, ["name"] = "Between Fyrakk and a Hard Place", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76323, 76324, 76326, 77283, 77818 }, ["description"] = "I hear approaching wings and smell shadowflame. Fyrakk is here. < Merithra 's anger is quiet but terrible.> Gerithus' pain will not go unanswered.", ["objectivesText"] = "Speak to Merithra and prepare for Fyrakk's attack.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206979, ["x"] = 0.508, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206979, ["x"] = 0.508, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 15, ["flags"] = 0 } } },
[76326] = { ["id"] = 76326, ["name"] = "Home in the Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76323, 76324, 76325, 77283, 77818 }, ["description"] = "Fyrakk has withdrawn from Amirdrassil, but that only increases my concern. He must have another target within the Emerald Dream . We must convene with the others at the base of the tree. Tyrande and the kaldorei have established a camp. I need to speak with Alexstrasza to determine our next step.", ["objectivesText"] = "Meet Merithra at the central encampment beneath Amirdrassil.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206979, ["x"] = 0.508, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 16, ["flags"] = 0 } } },
[76327] = { ["id"] = 76327, ["name"] = "Eye of Ysera", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Galenori's report is deeply troubling. The Eye's temple is my seat of power here in the Dream. From it, I commune with the Eye's energies and monitor the health of the Dream and its denizens. The Eye's power flows throughout the Dream, and helps Amirdrassil grow. If the djaradin take control of it, they could pervert its nature and stunt the growth of the tree. My daughter knows the Eye's importance. I will follow her lead--and so should you.", ["objectivesText"] = "Take the portal from Amirdrassil into the Eye of Ysera .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206408, ["x"] = 0.518, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206416, ["x"] = 0.531, ["y"] = 0.2885 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 35, ["flags"] = 0 } } },
[76328] = { ["id"] = 76328, ["name"] = "A New Brute", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Galok is but another one of Fyrakk's minions. I will not be baited by his bluster. The fire orb must be his doing. Its magic threatens to overwhelm the Eye. Ysera is channeling a shield from inside the temple, but it doesn't seem to be as effective as we expected. Now, I must confront Galok. Use my magic to bolster our casters if they weaken. The defense must not fall!", ["objectivesText"] = "Use The Dreamer's Essence on 5 Emerald Preservers. Then, meet Ysera inside the temple in the Eye of Ysera . Progress: With haste, <name>! Our defenders are in pain.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208124, 209912, 209913, 209914 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206416, ["x"] = 0.531, ["y"] = 0.2885 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.531, ["y"] = 0.2885 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 36, ["flags"] = 0 } } },
[76329] = { ["id"] = 76329, ["name"] = "In and Out Scout", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Bodwin reports that Galok is not the only new threat to the Eye. The djaradin forces below are led by two others--a warrior and a mage. It is unwise to engage them directly in their own, well-established base. But I am certain they are a part of Galok's plan of attack. Please gather more information from these djaradin leaders. We need to know how best to counteract their attacks. Bodwin can grant you stealth so that you may move unseen in the camp.", ["objectivesText"] = "Spy on the djaradin leaders in Slagfell Hold. Progress: What have you seen?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 53429, 53432, 80768, 80769, 80770, 80771, 80772, 121653, 121654, 121655, 121672, 130276, 130277, 130278, 130279, 131365, 143488, 169482, 169483, 169485, 188011, 188017, 188025, 188033, 209917, 209918, 210016, 210235, 210236, 211279, 228439, 228440, 228441, 228442, 237812 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 38, ["flags"] = 0 } } },
[76330] = { ["id"] = 76330, ["name"] = "Disarm Specialist", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Bodwin's scouting sortie returned more key information. The djaradin plan to use suffused weapons to turn the tide of the battle. We must dispatch their smiths and destroy their weapons. Targeting both will weaken and slow them. Then we will have time to consider our next move. You will be in great danger on this mission. Take this. Throwing it onto enemies will temporarily put them to sleep. Use it so that you may avoid becoming overwhelmed in combat. Good luck, $p.", ["objectivesText"] = "Kill 6 Suffusion Shapers and destroy 8 Suffused Supplies. Progress: Tread carefully, <name>. Igira will have your head if you are caught.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208184 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 39, ["flags"] = 0 } } },
[76331] = { ["id"] = 76331, ["name"] = "Merithra's Gambit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "We are ready as we can be. Our guard is in place, and our trap ripe to spring. The emerald preservers' magic is linked to Ysera's. Upon your signal, they will simultaneously drop the magical defense. This is what Galok's been waiting for. His forces will swoop in like carrion birds. We await your word, <name>.", ["objectivesText"] = "Tell Ysera to drop the magical defense. Progress: Here we go.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 42, ["flags"] = 0 } } },
[76332] = { ["id"] = 76332, ["name"] = "Putting Roots Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Our trap is many-layered. Plant these seeds around town. Our gardeners have already prepared the soil. These plants will be effective tools to poisoning our enemy. Handle them carefully, for some may sprout sooner than later. Also, Kiya Featherpaw, our umbraclaw keeper, has an idea to mobilize the very strong creatures. Go speak with her. Finally, meet with Somnikus to give everyone the signal that battle is imminent.", ["objectivesText"] = "Plant seeds in 8 Tilled Soil and speak to Kiya Featherpaw. Then, speak with Somnikus. Progress: Our trap will work, I know it. Make haste, <name>. Even with my mother's and my strength...It is like some part of her is holding back her attunement. I dare not dwell on it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209910 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 41, ["flags"] = 0 } } },
[76333] = { ["id"] = 76333, ["name"] = "Triple Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Galok is here. All is going according to plan then. We will put an end to him and any of his lieutenants.", ["objectivesText"] = "Slay Galok Wingslicer and his djaradin lieutenants The Anvil and Moltenbinder . Progress: We may have the stronger ground, but don't underestimate any of them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209894 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206416, ["x"] = 0.531, ["y"] = 0.2885 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 44, ["flags"] = 0 } } },
[76334] = { ["id"] = 76334, ["name"] = "Good Counsel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Galok is a coward. He refuses to engage us directly until he is sure of success. We do not have the resources to attack his base. But if we cannot go to him, maybe we can entangle him in our own territory. I am confident we can prepare a trap here for Galok and his forces. My plan is not without risks, and controlling the playing field will be our key advantage. The question remains... how do we lure them here?", ["objectivesText"] = "Discuss Merithra 's plan with the green dragonflight. Progress: I must understand everyone's perspectives, especially for a maneuver this big.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 40, ["flags"] = 0 } } },
[76335] = { ["id"] = 76335, ["name"] = "Might of the Forest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Use the traps you have laid to your advantage, <name>. Defeat every monster that dares threaten us!", ["objectivesText"] = "Eliminate the djaradin threat in the Eye of Ysera. Activate traps to help you in battle. Progress: We must protect the Dream!", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206416, ["x"] = 0.531, ["y"] = 0.2885 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 43, ["flags"] = 0 } } },
[76336] = { ["id"] = 76336, ["name"] = "Flight and Fight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "We have secured the land beneath our feet... now for the skies. Galok flies from us, but he is weakened. The time to strike is now.", ["objectivesText"] = "Slay 25 Fireswarm Shalewings flying above the Eye of Ysera by striking them with your dragonriding mount.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209888 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206416, ["x"] = 0.531, ["y"] = 0.2885 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.531, ["y"] = 0.2885 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 45, ["flags"] = 0 } } },
[76337] = { ["id"] = 76337, ["name"] = "The Ember Still Smolders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "I... almost cannot believe this worked. I am ever grateful for everyone's trust and faith. We could not have won this battle without the help of our allies and the flight. But the fight is far from over. Based on the intel we have gathered, Fyrakk and his minions are preparing an even greater assault. Their bases stand strong and terrifyingly close to the Dream's Hope, bastion of Amirdrassil. The Eye might have only been a distraction. We will regroup at Amirdrassil with the rest of our allies.", ["objectivesText"] = "Regroup with Merithra at Amirdrassil.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 208067, 210847 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 46, ["flags"] = 0 } } },
[76342] = { ["id"] = 76342, ["name"] = "Light 'Em Up!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "After Vyranoth left, Fyrakk put all four of the Claws of Vyranoth on different tasks. He left me in charge of this camp and told me to keep the portals open at all costs. The Druids of the Flame are empowering the portals for the Primalist's reinforcements to come through. We should close those portals and thin out their ranks.", ["objectivesText"] = "Weaken the Primalist encampment in the Primalist Stronghold. Progress: The Primalists will only multiply in numbers if we do not hinder them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 29735, 35884, 35885, 35886, 35887, 36888, 36937, 36938, 38213, 44018, 44039, 44041, 44042, 44043, 65482, 122637, 124634, 124635, 124636, 124637, 124638, 139693, 140610, 140611, 140612, 140613, 140614, 140615, 140616, 140617, 155656, 157829, 158667, 159124, 159152, 159153, 159154, 159155, 181368, 181377, 181612, 181745, 182487, 182496, 182505, 182514, 183744, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184842, 184843, 185717, 207101, 209883, 209889, 211279, 220161, 223432, 223472, 224817, 237812, 242241, 246813, 246815, 246936, 247234, 247915, 248027, 248028, 248029, 248053, 248247, 248555, 248556, 248557, 248558, 248559, 248560, 248561, 248562, 249400, 249780, 251257, 251724, 251725, 251726, 251727, 251728, 251729, 251730, 251731, 251732, 251733, 251734, 251821, 253467, 254267, 254579, 254878, 257143, 264675, 265106, 265631 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206619, ["x"] = 0.368, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206619, ["x"] = 0.368, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 27, ["flags"] = 0 } } },
[76343] = { ["id"] = 76343, ["name"] = "Best Laid Plans", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "Fyrakk may be brash, but he is not a fool. If we are to save the Dream, we must undermine his plans as quickly as possible. At their core, the Primalists are unorganized. Infiltrate their camp and search for any clues or information. The more information we have, the sooner we can take down Fyrakk once and for all.", ["objectivesText"] = "Collect 4 clues in the Primalist Stronghold.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 153735, 153736, 153785, 153786, 153806, 153807, 153820, 153821, 153845, 153846, 153902, 153903, 153936, 153937, 153952, 153953, 154001, 154002, 154014, 154015, 154039, 154040, 154738, 154741, 194524, 194527 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206612, ["x"] = 0.368, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206612, ["x"] = 0.368, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 28, ["flags"] = 0 } } },
[76344] = { ["id"] = 76344, ["name"] = "Primalist Directive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "Terro was another one of Vyranoth's claws. He never wanted to attack the Dream, and some of the Primalists who served him may feel the same. See if you can convince them to join our side. I can put a mark of Vyranoth on you so Terro's troops will not attack you... right away.", ["objectivesText"] = "Convince 5 of Terro's Primalists to side with Vyranoth. Progress: Terro never wanted to attack the Dream. It was against his nature.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206619, ["x"] = 0.368, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210178, ["x"] = 0.395, ["y"] = 0.228 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 29, ["flags"] = 0 } } },
[76345] = { ["id"] = 76345, ["name"] = "Finding Terro", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "I had no idea my old guard would be willing to return to my side. I am... I am happy to see them. When I chose to go to Alexstrasza, I told no one. I simply left. But we must learn more about Fyrakk's plan before pursuing personal matters. Let us see what else Buri can tell us.", ["objectivesText"] = "Uncover more information about Fyrakk's plan in the Emerald Dream . Progress: If we could just find the other Claws...", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 209915, 209916 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206612, ["x"] = 0.368, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210178, ["x"] = 0.395, ["y"] = 0.228 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 30, ["flags"] = 0 } } },
[76347] = { ["id"] = 76347, ["name"] = "Power, Eruption, and Lies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "Buri told me that Lethka plans to ignite Cinder Summit, and Vyranoth pursued her. Lethka revealed herself because she knew that Vyranoth would go after her. The power in Cinder Summit can destroy this barrier, or Vyranoth . We have to go after them.", ["objectivesText"] = "Slay Lethka at Cinder Summit.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209885, 209926 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208725, ["x"] = 0.335, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210733, ["x"] = 0.336, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 33, ["flags"] = 0 } } },
[76348] = { ["id"] = 76348, ["name"] = "Big Bright Beautiful Barrier", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "Buri? Vyranoth? Once she left us at the mercy of Fyrakk, we had no choice but to follow him. I do not know what his plan is, but he ordered me and these Primalists to bring down this barrier. We have made little progress, but Vyranoth will want us to slow him down. Some fragments of the barrier have chipped away. If you collect them, we can channel their energy back into the shield. Can I trust you to undo the damage that I have done?", ["objectivesText"] = "Collect 6 Barrier Fragments in the Emerald Dream .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209895, 209896, 209897, 209898 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208378, ["x"] = 0.276, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208725, ["x"] = 0.335, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 32, ["flags"] = 0 } } },
[76384] = { ["id"] = 76384, ["name"] = "The Bloom Begins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "I sense a change on the wind. Like the dawning rays of the sun. Like petals before they unfurl. A great swelling energy, right at the heart of the Emerald Dream . The Bloom. It has begun.", ["objectivesText"] = "Witness Amirdrassil begin to bloom. Progress: A bloom so beautiful, yet it brings such dread. Can we truly prevail?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 47, ["flags"] = 0 } } },
[76385] = { ["id"] = 76385, ["name"] = "Hazardous Horticulture", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "We may be outnumbered, but this is my domain. And I have a way of evening our odds. Take this pouch of seeds. Plant them throughout Wildfire Canyon and the Dream's faerie dragons will transform them into treants. With luck, they will draw attention from our front lines and bolster our ground forces.", ["objectivesText"] = "Plant 6 Dream Seeds across Wildfire Canyon. Progress: Hopefully the faerie dragons are small enough to go unnoticed by Fyrakk's forces.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208551, ["x"] = 0.388, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208551, ["x"] = 0.388, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 49, ["flags"] = 0 } } },
[76386] = { ["id"] = 76386, ["name"] = "A Clash of Ice and Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "The Primalists have erected great flame wards throughout their encampment. Yet we know not why. I have asked our ground forces to investigate, but they are blocked at every turn. Two fire elementals in particular stand against us, empowered by Fyrakk's shadowflame. You must clear the area of enemies. I have imbued this scale with my magic. Use it to weaken the elementals and any other who stands in your way.", ["objectivesText"] = "Slay Calderamor , Ignarion , and 15 Wildfire enemies. Progress: Even in the heat of battle, the Primalists continue to empower those flame wards. But to what end? We must clear the way so that our forces can investigate.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208544, 209906, 209929 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208553, ["x"] = 0.388, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208553, ["x"] = 0.388, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 50, ["flags"] = 0 } } },
[76387] = { ["id"] = 76387, ["name"] = "Defense of the Ancients", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "Fyrakk's forces at Skystone Falls are already threatening to overwhelm us. I fear not even the combined might of the Sentinels and Ancients can hold out against them. The Ancients are bearing the brunt of the offensive. We have reports of djaradin attempting to capture them for some unknown purpose. We cannot allow Igira to succeed in whatever nefarious plan she has in mind. You must seek out the Ancients on the battlefield and free any who are captured.", ["objectivesText"] = "Free the Ancients at Skystone Falls. Progress: The Ancients may be few, but they battle fiercely for our cause. Go, <name>. Help them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209887 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208552, ["x"] = 0.388, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208552, ["x"] = 0.388, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 51, ["flags"] = 0 } } },
[76388] = { ["id"] = 76388, ["name"] = "Fighting Fire With Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "The notes you found, combined with Merithra's reconnaissance, have revealed Ashendir's plan. The flame wards that surround the Wellspring Temple are blocking our reinforcements. Our allies will distract Fyrakk while you and I slip behind enemy lines to destroy the wards. The skies are filled with drakes, and I must fend them off. Once you find a flame ward and thin out its defenses, signal me to destroy it.", ["objectivesText"] = "Clear out Skyfire Turrets and mark Primalist Flame Wards.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 155159, 155162, 209898 }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208568, ["x"] = 0.35, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 53, ["flags"] = 0 } } },
[76389] = { ["id"] = 76389, ["name"] = "The Age of Mortals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "Once again, the mortal races have come together to defend a World Tree. It is only fitting then that we bolster their efforts with a relic from that past battle. The Horn of Cenarius . I entrust the horn to you, <name>. Use it to bestow the blessings of Cenarius to our allies. With luck, it will allow us to break through Fyrakk's forces and open a path to the temple. And do not forget to lend your strength as well. Every enemy felled is one fewer between us and Fyrakk.", ["objectivesText"] = "Blow the Horn of Cenarius while next to heroes of Azeroth and slay Fyrakk's forces.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 208752, 209899 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208568, ["x"] = 0.35, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 54, ["flags"] = 0 } } },
[76398] = { ["id"] = 76398, ["name"] = "Aerial Supremacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "The dragonflights have arrived. The skies are ours to reclaim! And you shall help us tip the scales. Mount your drake and target the enemies above. You need only swoop in and take their forces by surprise. Your drake shall handle the rest.", ["objectivesText"] = "Slay 15 enemy proto-drakes flying above the Field of Flames by striking them with your dragonriding mount. Progress: The faster we can take down Fyrakk's aerial forces, the faster we can make our way to the temple and put a stop to this madness.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208567, ["x"] = 0.35, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208567, ["x"] = 0.35, ["y"] = 0.354 }, { ["mapID"] = 2200, ["npcID"] = 208573, ["x"] = 0.35, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 55, ["flags"] = 0 } } },
[76401] = { ["id"] = 76401, ["name"] = "Echo of the Firelands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "We have finally broken through the enemy's ranks, yet the Prophet of the Flame now bars our path. And he has unleashed his full power. The Prophet must be defeated if we have any hope of making our way to the temple. I ask you to face him, champion. We shall hold back his forces as you do so. The end is in sight. Let us finally finish this war.", ["objectivesText"] = "Defeat the Prophet of the Flame.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 209931 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208572, ["x"] = 0.35, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206921, ["x"] = 0.28, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 56, ["flags"] = 0 } } },
[76402] = { ["id"] = 76402, ["name"] = "Amirdrassil, the Dream's Hope: Fyrakk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923, 76276, 76280, 76281, 76282, 76283, 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326, 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 76342, 76343, 76344, 76345, 76347, 76348, 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76402, 76403, 76416, 76433, 76434, 76435, 76436, 76437, 76441, 76442, 76443, 76532, 77178, 77200, 77201, 77283, 77329, 77436, 77780, 77781, 77818, 78643, 78646, 78865, 92875 }, ["description"] = "Fyrakk may have entered the temple, but our fight has not ended. Thanks to your efforts, we have broken through his forces. There is still time to stop him. You must gather your allies and follow Fyrakk into the Wellspring Temple. We will cover your flank. Know that it is not only Amirdrassil that you protect this day, <name>. All of Azeroth will burn if Fyrakk claims the World Tree. He must be stopped, here and now. This is our final stand.", ["objectivesText"] = "Enter Amirdrassil, the Dream's Hope, and defeat Fyrakk. Progress: Once, Fyrakk sought to free dragonkind. He raged a war against us for that very ideal. What drove him to seek domination instead? Was it the need for revenge? The desire for power? The same fire that burns can also renew. Yet Fyrakk's flames would swallow the whole world.", ["rewardGold"] = 1239200, ["rewardXP"] = 2830, ["rewardItems"] = { 206960, 208047, 210180, 210916 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206921, ["x"] = 0.28, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208503, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "raid", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 57, ["flags"] = 0 } } },
[76403] = { ["id"] = 76403, ["name"] = "Mayhem Incarnate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "We need to uncover exactly what Fyrakk's plan is. He is holding his forces away from the tree, but we do not know why. I can do some scouting, but direct conflict with Fyrakk would not help our cause right now. Follow me further into the Dream. There is a Primalist encampment to the north. Let us start there, so we can put an end to this madness.", ["objectivesText"] = "Speak with Vyranoth near the Primalist encampment.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208506, ["x"] = 0.508, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206612, ["x"] = 0.368, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 26, ["flags"] = 0 } } },
[76407] = { ["id"] = 76407, ["name"] = "Not Today, Fate", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "Eternus intends to show us what happened. I think she also seeks to change the past. Normally, I would not entertain this idea, but understanding the infinites is the only way forward.", ["objectivesText"] = "Enter the Time Rift to witness the past. Progress: Eternus has something to show us--I expect we will learn a great deal about her.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 207106, ["x"] = 0.655, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 206971, ["x"] = 0.375333, ["y"] = 0.835333 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 71, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 2, ["flags"] = 0 } } },
[76416] = { ["id"] = 76416, ["name"] = "Forward Unto Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "Amirdrassil draws power from the Wellspring Temple in preparation for its bloom. The barrier protecting the temple will not last much longer under Fyrakk's assault. I have sent messengers all across Azeroth asking for reinforcements, but none have yet arrived. Something blocks their path into the Dream. For now, we must rely on the forces we have. I ask you to travel to the Verdant Pass. If there is anyone I would have by my side, it is you.", ["objectivesText"] = "Meet Alexstrasza at the Verdant Pass.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208503, ["x"] = 0.508, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208550, ["x"] = 0.388, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 48, ["flags"] = 0 } } },
[76419] = { ["id"] = 76419, ["name"] = "Violence Will Solve It", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "Do you not agree that Moraidormi can be saved? We infinites often save those we think suffered needlessly--worthy or not. Supposedly, Mori died too close to the Caverns of Time just east of us. Using too much time magic here could have... consequences. But this should be quick. Chrono-Lord Deios was in possession of artifacts that could forcefully rewind time. The bronze dragonflight has them now. We will rewind time and then destroy Vexemia . Simple.", ["objectivesText"] = "Rewind time and defend Moraidormi from Vexemia 's attack. Progress: This will be easy. Which makes one wonder why the bronze dragonflight did not do it before!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 207634, ["x"] = 0.376, ["y"] = 0.835333 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 207634, ["x"] = 0.376, ["y"] = 0.835333 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.835333 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne", ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 3, ["flags"] = 0 } } },
[76420] = { ["id"] = 76420, ["name"] = "Butterfly Effects", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "We were overwhelmed by her companions. Moraidormi was still killed. I need another strategy, one that will actually protect her. She is what matters. Go rewind time, including our actions. After the rewind, I will hold time in place. Then we can try to make defenses for her.", ["objectivesText"] = "After rewinding time, create defenses for Moraidormi and test them. Progress: What else can we do?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 208099 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 207634, ["x"] = 0.376, ["y"] = 0.835333 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 207634, ["x"] = 0.376, ["y"] = 0.835333 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.835333 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne", ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 4, ["flags"] = 0 } } },
[76421] = { ["id"] = 76421, ["name"] = "The Fate We Make", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "We just need to be stronger and faster! We cannot leave it like this, not with the eggs also destroyed. I will come up with another idea. Restart time, and... < Eternus sighs.> Perhaps I will listen to Nozdormu. He keeps telling me I have \"missed\" something...", ["objectivesText"] = "Rewind history again and see what Nozdormu has to say. Progress: Doing nothing makes no sense to me, but I will be patient. For now.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 207634, ["x"] = 0.376, ["y"] = 0.835333 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 207634, ["x"] = 0.376, ["y"] = 0.835333 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.835333 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne", ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 5, ["flags"] = 0 } } },
[76422] = { ["id"] = 76422, ["name"] = "Infinity and Beyond", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "If we continue to look into the past, we miss out on the present--or even the future. Let us return to Thaldraszus . Do not worry about these time fracture elementals. They too will heal with time. As we all do.", ["objectivesText"] = "Return to the present to check in with Chromie . Progress: I hope this experience can bring us together.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 162690, 204076, 210024 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 206971, ["x"] = 0.375333, ["y"] = 0.835333 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 207106, ["x"] = 0.655, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.375333, ["y"] = 0.835333 }, ["mapCandidates"] = { ["npc"] = { 71, 2025 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["db2QuestSortName"] = "Nightborne", ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 6, ["flags"] = 0 } } },
[76423] = { ["id"] = 76423, ["name"] = "No Limits", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "After confronting the infinites and, well, myself--we have had a lot to think about. Eternus, one of the infinites, has apparently been thinking a lot too. The infinites want to change Nozdormu into his infinite form, Murozond. We don't want that. And after learning about Nozdormu , I think Eternus may be persuaded to not want that either. I've set up a meeting between Nozdormu and Eternus to get them talking. But I want someone else there... in case something goes wrong.", ["objectivesText"] = "Check on Eternus and Nozdormu .", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 210024 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206086, ["x"] = 0.592, ["y"] = 0.815 }, { ["mapID"] = 2025, ["npcID"] = 208035, ["x"] = 0.654, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 207106, ["x"] = 0.655, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 0, ["flags"] = 0 } } },
[76433] = { ["id"] = 76433, ["name"] = "Ashen Soil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "It seems the Druids of the Flame wasted no time in seeking to expand their influence. Deep within these barrow dens, some manner of corruption has taken root. It will spread if left unchecked, consuming the entire den before expanding outwards to threaten the rest of the dream. Time is short, <name>. Delve into the barrow, seek out the sources of the spreading flame, and excise them before the smoldering embers can grow and spread.", ["objectivesText"] = "Find and excise the source of the barrow den's flame corruption. Progress: Make haste. These flames grow brighter by the moment.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206247, ["x"] = 0.514, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206247, ["x"] = 0.514, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 19, ["flags"] = 0 } } },
[76434] = { ["id"] = 76434, ["name"] = "Not Yet Lost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "The flame did not take root here on a whim. No doubt there are servants of the Firelands cloistered within, trying to spread their flame to the creatures that reside within these barrows. We must do what we can to save those who can still be saved, and mete out swift justice to the heretics that lurk within.", ["objectivesText"] = "Rescue the denizens of the Sor'theril Barrow Den. Progress: If even one soul remains languishing within these dens, we must do everything we can to save them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209917, 209918, 210235, 210236 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206247, ["x"] = 0.514, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206247, ["x"] = 0.514, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 20, ["flags"] = 0 } } },
[76435] = { ["id"] = 76435, ["name"] = "The Smoldering Copse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "Andi'thur tells me of smoke rising from a grove to the west. Norana's new allies are not exactly the subtle sort. I do not care what her motivations are. I will not allow her to set another inch of this land ablaze. Ride for the western groves. However the Druids of the Flame plan to seek their so-called rebirth, we will do all we can to stop them.", ["objectivesText"] = "Investigate the Smoldering Copse.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206247, ["x"] = 0.514, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207160, ["x"] = 0.392, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 21, ["flags"] = 0 } } },
[76436] = { ["id"] = 76436, ["name"] = "A Scrap of Hope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "It is only a matter of time before Fyrakk's forces decimate our own. And then there will be nothing stopping him from entering the Wellspring Temple. If the Prophet of the Flame is responsible for blocking our reinforcements from entering the Dream, there must be some record or communication of his plan. We just have to find it. Search for any communications amongst Fyrakk's forces at Skystone Falls. If we can disrupt their efforts in some way, we might have a chance to turn the tide.", ["objectivesText"] = "Collect 8 Scraps of Parchment from Fyrakk's forces at Skystone Falls. Progress: If Fyrakk enters the Wellspring Temple, it is not just Amirdrassil that will burn. All of Azeroth will burn with it.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 210023 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208550, ["x"] = 0.388, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208550, ["x"] = 0.388, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 52, ["flags"] = 0 } } },
[76437] = { ["id"] = 76437, ["name"] = "Burning Ground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "We allowed ourselves to be distracted. We thought the Druids of the Flame had followed us into the Dream, when clearly they arrived before we did. With Amirdrassil so close at hand, we cannot allow them to plant their ashen roots here. Release their prisoners. Ransack their supplies. Do whatever you can to ensure that this burning corruption does not spread further.", ["objectivesText"] = "Disrupt the Smoldering Copse. Progress: We must act quickly. The further this flame-blighted ground spreads, the more danger our allies will face in the days to come.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209903, 209905, 209908, 209909 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207160, ["x"] = 0.392, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207160, ["x"] = 0.392, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 22, ["flags"] = 0 } } },
[76441] = { ["id"] = 76441, ["name"] = "Grim Reprisal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "The Druids of the Flame will not allow you to proceed unfettered once your intentions here become clear. They are my kin, my brothers and sisters under Elune... But they seek to undo all that we have toiled for. Their machinations would condemn countless lives to an all-consuming inferno. I won't allow it. We cannot allow it. Disrupt their rituals. Destroy their supplies. If they raise their blades against you, cut them down.", ["objectivesText"] = "Disrupt the Smoldering Copse. Progress: Take heed. These druids' zealotry fuels their reckless ends. Should they identify you as an enemy, they will not show mercy.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207160, ["x"] = 0.392, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207160, ["x"] = 0.392, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 23, ["flags"] = 0 } } },
[76442] = { ["id"] = 76442, ["name"] = "Forlorn Hope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "You've arrived just in time. Norana lurks just beyond the ridge. She appears to be taking part in some manner of ritual - alongside a man who appears to be their leader. These are powerful druids, and their strength is amplified by their ties to the Firelands. Taking the blade to all of them at once would be foolish. Still, the least we can do is disrupt their ritual. If we send them scattering, we buy ourselves time - and an opportunity to press the advance elsewhere.", ["objectivesText"] = "Interrupt the Flame Druids' ritual.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 209900 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207160, ["x"] = 0.392, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211193, ["x"] = 0.36, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 24, ["flags"] = 0 } } },
[76443] = { ["id"] = 76443, ["name"] = "The Looming Cinder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "The Druids of the Flame are nothing more than allies of convenience to Fyrakk and his ilk. Nevertheless, they present a dire threat to the well-being of Amirdrassil, to say nothing of the rest of the Dream. The victory we earned here today was hard-fought, but it only served to stem the tide. No doubt the Prophet and the Priestess have already reunited with their erstwhile allies. We should return to Merithra . She needs to know of this.", ["objectivesText"] = "Return to Merithra at Amirdrassil.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 208067, 210730 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211193, ["x"] = 0.36, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 25, ["flags"] = 0 } } },
[76460] = { ["id"] = 76460, ["name"] = "A Dragon in Hand is Worth Two in the Roost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2025, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "Ah, <name>, so wonderful to see you! You have arrived just in time. I was tasked with seeking out potential allies to aid with the protection of the world tree. Your accomplishments speak for themselves--your help in this matter would be greatly appreciated. What do you say, up for some diplomacy?", ["objectivesText"] = "Talk to Wrathion about his potential allies. Progress: I'm quite excited to meet these new dragons.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 207350, ["x"] = 0.474, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 207350, ["x"] = 0.474, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 0, ["flags"] = 0 } } },
[76461] = { ["id"] = 76461, ["name"] = "Draconic Diplomacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2025, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "I suspect Vyranoth might also be interested in recruiting new dragons to our cause... but she'll need a little convincing. I just so happen to be very good at convincing. I'll speak with Vyranoth, and we'll meet you in Valdrakken once she's decided to join us.", ["objectivesText"] = "Talk to Prince Mordenaku at the Petitioners Concourse in Valdrakken. Progress: The netherwing are a fascinating flight.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 207350, ["x"] = 0.474, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 207350, ["x"] = 0.474, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 1, ["flags"] = 0 } } },
[76462] = { ["id"] = 76462, ["name"] = "Cavern Cleaning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 634, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "This cave is adequate. It has a commanding view of the surrounding land, and is highly defensible. But the state of it is not acceptable. I will place an enchantment upon you. When you draw near to the smaller spiders, it will freeze them, allowing us to relocate them. The sacs and larger spider will need to be addressed with more... finality. See that it is done.", ["objectivesText"] = "Clean out the spiders in the cave above the Sand-Lost Sanctum in Thaldraszus. Progress: Have you finished?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 207351, ["x"] = 0.51, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 207351, ["x"] = 0.51, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 2, ["flags"] = 0 } } },
[76463] = { ["id"] = 76463, ["name"] = "Delectable Delicacies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "Of course we will take care of the netherwhelps. However, we might run low on snacks. The beetles close by are a delicious treat for the little ones. Can you bring me back some juicy beetle bits ? Only the best for the little darlings!", ["objectivesText"] = "Retrieve 10 Juicy Beetle Bits from Juicy Beetles in the Ruby Lifepools in Waking Shores. Progress: The whelps just love to gobble up those beetle bits.", ["rewardGold"] = 280900, ["rewardXP"] = 1060, ["rewardItems"] = { 208060 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 3, ["flags"] = 0 } } },
[76464] = { ["id"] = 76464, ["name"] = "The Thorignir", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 634, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "The Thorignir of Stormheim have the strength and power to greatly aid us in defending Amirdrassil, but they have yet to come to the Dragon Isles. I suspect this... Odyn has interfered with their journey. We will go and speak with their matriarch. Wrathion tells me her brood is amenable to your kind, and to assisting others. We will investigate.", ["objectivesText"] = "Speak with the Thorignir Broodmother. Progress: We will find out why this brood of storm drakes did not heed the call of the Isles.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 207351, ["x"] = 0.51, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 207351, ["x"] = 0.51, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 7, ["flags"] = 0 } } },
[76465] = { ["id"] = 76465, ["name"] = "Dragon Keeping", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 634, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "First he opposes dragonkind, then he enslaves them, denying them their birthrights. We shall visit these so-called \"Halls of Valor,\" defeat any who oppose us, and liberate the storm drakes from that which binds them. Come along.", ["objectivesText"] = "Speak to Vyranoth and complete the Storm the Halls of Valor scenario. Progress: These dragons will be freed.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 14344, 206156, 208067, 210959 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 207351, ["x"] = 0.51, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208506, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 634, 2200 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 8, ["flags"] = 0 } } },
[76530] = { ["id"] = 76530, ["name"] = "Unliving Summons", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "We need you in Tirisfal, <name>. Come quickly. There's a new situation brewing just outside the Ruins of Lordaeron, and it's not looking pretty. I'll get you up to speed when you arrive.", ["objectivesText"] = "Report to Lilian Voss in the Ruins of Lordaeron.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 186091, ["x"] = 0.638, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 186091, ["x"] = 0.638, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[76532] = { ["id"] = 76532, ["name"] = "Assault on the Wellspring", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "Terro gave his life to protect the Dream. Which means we must see it through. Vyranoth should be able to handle Lethka, we must find Suzska . I hope Lethka did not attack her first. We should start looking near the Wellspring. Meet me there so we can continue our search.", ["objectivesText"] = "Spy on the Wellspring of Life with Buri . Progress: Come on, let's head to the Wellspring.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210178, ["x"] = 0.395, ["y"] = 0.228 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208378, ["x"] = 0.276, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.228 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 31, ["flags"] = 0 } } },
[76564] = { ["id"] = 76564, ["name"] = "The Tools of the Dragonkillers", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "If you're going to go after a dragon, who better to employ than the Djaradin? Let's see what we can find, <name>.", ["objectivesText"] = "Locate the three attunement relics. Progress: Without those attunement relics we won't be able to solve this mystery, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5516, ["name"] = "Technoscrying: Igira's Watch", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 38, ["flags"] = 0 } } },
[76566] = { ["id"] = 76566, ["name"] = "The Dryad Garden", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76566 }, ["description"] = "$p, there is a situation I am personally concerned about. A garden cared for by my kin, the dryads, has suffered from growing pains amidst Amirdrassil's growth. An overwrought druid currently tends the garden, but I suspect he will need more assistance than he has requested. Please assist him in his task on my behalf.", ["objectivesText"] = "Speak with Ethidris Creekward in the Root-Bound Sanctuary.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209318, ["x"] = 0.508, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76567] = { ["id"] = 76567, ["name"] = "Grousing Garden", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76567 }, ["series"] = { 76568, 76569, 76570 }, ["description"] = "The sanctuary has been overrun! The roots of the World Tree have grown alongside this garden, but it seems the wildlife have grown uncomfortable with the change. Please help them get out their restless energy. Perhaps tired out, they will relax in this space again.", ["objectivesText"] = "Tire out 8 wildlife in the Root-Bound Sanctuary. Progress: <Ethidris winces and rubs his shoulder.> You would think being a bear would lend oneself resistance to being knocked around by deer.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76568] = { ["id"] = 76568, ["name"] = "Pineshrew Panic", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76568 }, ["series"] = { 76567, 76569, 76570 }, ["description"] = "With the garden in such disarray, the pineshrews here are hoarding seeds. Important seeds. Seeds we've spent a lot of time caring for and teaching. A gentle shake will release the seeds properly. Please hurry before they run off with any more!", ["objectivesText"] = "Shake out 20 Pineshrew seeds in the Root-Bound Sanctuary. Progress: Ordinarily, pineshrews shake out collected seeds across the Dream to promote variety and growth. It's a beautiful cycle. If you have a few hours, I have a lesson prepared about pineshrew migration habits.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76569] = { ["id"] = 76569, ["name"] = "Druid-Guardian Conference", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76569 }, ["series"] = { 76567, 76568, 76570 }, ["description"] = "Typically, the druid assigned to a dryad sanctuary would guide a newborn dryad until they were ready to take on a position of their own. Unfortunately, it is difficult to separate a dryad from whoever she imprints on. <Ethidris sighs and rubs his eyes.> Which she has made very clear. Regardless, tell me about yourself. Perhaps you will be just as apt a caretaker as I would have been.", ["objectivesText"] = "Speak with Ethidris Creekward about raising a dryad in the Root-Bound Sanctuary. Progress: <Ethidris furrows his brow at Dionaessa.> Among so many other things happening right now, there's a new dryad to raise.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 211371 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76570] = { ["id"] = 76570, ["name"] = "The Family Business", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76570 }, ["series"] = { 76567, 76568, 76569 }, ["description"] = "I was charged with imparting knowledge on every dryad seed. Dionaessa will have retained all of my teachings, but she will be unpracticed in implementing them. Since it seems you are practiced at completing tasks, you will show Dionaessa the ropes. A group of lashers have grown strangely restless in the Twisting Wood just outside the garden. Collect some of their hearts so we can discern what has happened.", ["objectivesText"] = "Collect 6 Lasher Hearts in the Twisting Wood near the Root-Bound Sanctuary. Progress: The druid Creekward told me lashers tend to lie in wait for their prey. I'm glad these are not. Makes the fight more interesting!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 208732 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76571] = { ["id"] = 76571, ["name"] = "Growth Experience", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76571 }, ["description"] = "Dionaessa's connection to Cenarius gives her the ability to grow plants, but she needs space to practice. The stirred-up wildlife here will be in your way. The Twisting Wood nearby will have plenty of space with far fewer hooves. <Melyrine smiles. Her eyes shine with intensity.> If she gets poisoned by a podling, don't worry. Dryads are immune to poison. You are not.", ["objectivesText"] = "Have Dionaessa grow 3 flowers in the Twisting Wood. Progress: Do you smell that? <Dionaessa scrunches up her face.> The druid Creekward did not describe lashers and podlings as smelling so foul. I have been misled!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207781, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76572] = { ["id"] = 76572, ["name"] = "A Poisonous Promotion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76572 }, ["description"] = "Guardian! These podlings have been poisoning the lashers, and now they have twisted that mandragora! If we do not stop it, it will spread the poison to the garden. This must be what had the wildlife in the garden so disturbed. They were on the verge of invasion! Let us kill it. This is what you have prepared me for--a dire quest!", ["objectivesText"] = "Defeat the Sickened Growth in the Twisting Wood.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 208067 }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209788, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76576] = { ["id"] = 76576, ["name"] = "An Unlikely Proposal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Tuskarr artifacts, underground, deep in Djaradin territory? If we didn't find it ourselves I wouldn't believe it. What do you think they were doing down here? Ok looks like the nexus point is right here in this cave. Let's get to the bottom of this!", ["objectivesText"] = "Observe the Scene from the past. Progress: I wonder what we'll find?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5516, ["name"] = "Technoscrying: Igira's Watch", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 39, ["flags"] = 0 } } },
[76593] = { ["id"] = 76593, ["name"] = "The Best Intentions", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "Not only did they beat him--they put him in shackles too! What's worse is... I probably would have done the same... We will not be able to carry Marithos out of here with this weight chained to him. The key must be around the camp somewhere. Try to find it, <name>, while I keep him comfortable.", ["objectivesText"] = "Look for a key to Marithos's shackles in the Lonely Falls. Progress: We must free Marithos from his bonds.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 208014 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207819, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 207819, ["x"] = 0.748, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 3, ["flags"] = 0 } } },
[76594] = { ["id"] = 76594, ["name"] = "Dracthyr Down", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "What was done to Marithos goes beyond what simple healing can fix. If we expect him to fly out of here, he will need extra care. Thankfully, there are herbs nearby that may give his healing a boost--enough to get him standing, anyway. Look around and collect some of the Wingfoil nearby, <name>.", ["objectivesText"] = "Look for Wingfoil herbs in the Lonely Falls. Progress: Have you found that Wingfoil ? Marithos cannot fly without it.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 208004 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207819, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 207819, ["x"] = 0.748, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 4, ["flags"] = 0 } } },
[76595] = { ["id"] = 76595, ["name"] = "Urgent Exfiltration", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "The Sundered Flame here are not going to take Quartermaster Doros's death well... They are going to come looking for me. Marithos and Amythora are vulnerable. We cannot let them find us. Secure the perimeter and keep the Sundered Flame away from Amythora and Marithos.", ["objectivesText"] = "Keep the Sundered Flame away from Amythora and Marithos. Progress: If they find us, I do not think the Sundered Flame loyalists will take prisoners.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 204076 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207820, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 207820, ["x"] = 0.748, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 5, ["flags"] = 0 } } },
[76597] = { ["id"] = 76597, ["name"] = "On New Wings", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "I am glad that Winglord Dezran arrived when he did. If he had not, this would have gone... very differently. We must take Marithos back to Valdrakken so he can recuperate, but once I have debriefed Dezran, we will send an envoy to help re-introduce them to our people. They have suffered. We have suffered. Perhaps now we can all heal. Follow me back to Valdrakken. We have much to discuss.", ["objectivesText"] = "Talk to Emberthal in Valdrakken.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 250912 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207820, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207790, ["x"] = 0.232, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 6, ["flags"] = 0 } } },
[77098] = { ["id"] = 77098, ["name"] = "Getting to Ground", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "He needs to be healed--now. We're too out in the open here. Sundered Flame loyalists could ambush us at any time. Let's find cover somewhere so we can assess his wounds. Cover me!", ["objectivesText"] = "Get Marithos to safety in the Azure Span .", ["rewardGold"] = 210675, ["rewardXP"] = 7135, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 208236, ["x"] = 0.74, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 207820, ["x"] = 0.748, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 1, ["flags"] = 0 } } },
[77163] = { ["id"] = 77163, ["name"] = "Seeing Reason", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "They seem to know that Sarkareth is gone, but because their missions were so far from Zaralek Cavern, it looks like they never heard how he met his demise. We should talk to them. Maybe if they knew why so many of their brethren now follow me they would become Ebon Scales again. Or not... <Emberthal sighs.> This could backfire catastrophically, but I feel like we must try. Quartermaster Doros seems to be in command here. Go and speak to him, <name>. I do not think he would listen to me...", ["objectivesText"] = "Confront Quartermaster Doros in the Lonely Falls. Progress: Find Quartermaster Doros . If you can talk to him, we might be able to avoid a conflict.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202711 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207820, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 207820, ["x"] = 0.748, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 2, ["flags"] = 0 } } },
[77166] = { ["id"] = 77166, ["name"] = "A Practical Test", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Now that you know how to use the device, we will put your skills to the test. I have attuned your Technoscryers to a valuable item hidden somewhere on this island. Provided you can find it, we will use it to view a scene from the past and deduce how it got there. It is time for science! Put... the goggles... on! Resume your scrying!", ["objectivesText"] = "Use the Technoscryers to find the hidden object. Progress: Have you found that hidden object, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.305333 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5466, ["name"] = "Azerothian Archives - Tutorial", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 5, ["flags"] = 0 } } },
[77176] = { ["id"] = 77176, ["name"] = "I Can See Through Time!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Okay, the Technoscryers should be calibrated. I have made the same adjustments to my own pair, so we can view the same phenomena. Are you ready? Put... them on... again! This time, we will use the Observation mode.", ["objectivesText"] = "Observe events from the past. Progress: I wonder what we will find?", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.305333 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5466, ["name"] = "Azerothian Archives - Tutorial", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 6, ["flags"] = 0 } } },
[77178] = { ["id"] = 77178, ["name"] = "Tactical Withdrawal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "We have stopped this attack on the barrier, but Fyrakk will find a way through. $p, we need to return to Alexstrasza and Merithra and tell them his plans for the Wellspring. Return as soon as possible. It is more urgent than ever to stop Fyrakk.", ["objectivesText"] = "Return to Alexstrasza in the Central Encampment.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 208047, 210757, 210954, 211370 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210733, ["x"] = 0.336, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208503, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 34, ["flags"] = 0 } } },
[77195] = { ["id"] = 77195, ["name"] = "A Dragon's Eye View", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2025, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "I believe I know just the location for the Netherwing to roost. It has a wonderful view and is quite secluded. I'd like to show our guest some of the sights of Valdrakken before we go. Meet you there?", ["objectivesText"] = "Travel to the cave above the Sand-Lost Sanctum in Thaldraszus. Progress: Really, the view from the cave is quite remarkable.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 206156 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 207350, ["x"] = 0.474, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 207350, ["x"] = 0.474, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 4, ["flags"] = 0 } } },
[77197] = { ["id"] = 77197, ["name"] = "A Whelping Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2025, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "Well done, <name>. Now we must ensure the whelps of the netherwing have the best opportunities to grow and flourish. Let us speak to Mother Elion . I know she would relish the opportunity to care for the young of a new flight. Can you meet us at the Ruby Lifeshrine?", ["objectivesText"] = "Meet Mother Elion at the Ruby Lifeshrine in the Waking Shores.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 207350, ["x"] = 0.474, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 5, ["flags"] = 0 } } },
[77198] = { ["id"] = 77198, ["name"] = "Home in Time for Tea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2022, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "I must admit, I did not expect to be altering the future of my flight when I arrived. But it feels as though we belong here. Perhaps this is the call they spoke of... Regardless, I am looking forward to some rest. Wrathion mentioned retiring to the Roasted Ram Inn. Can you meet us there?", ["objectivesText"] = "Meet Wrathion, Mordenaku , and Vyranoth in the Roasted Ram Inn in Valdrakken. Progress: I am looking forward to some rest.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 211353 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 207352, ["x"] = 0.615, ["y"] = 0.687 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 207352, ["x"] = 0.615, ["y"] = 0.687 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.687 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 6, ["flags"] = 0 } } },
[77200] = { ["id"] = 77200, ["name"] = "Offerings for the Well", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "Amirdrassil has been ushered into this world by the denizens of the Dream. Now we must ensure its roots are bathed in the waters of Elune by creating a new moonwell. So many of my people have brought us to this moment. Each should have a part in this dedication. Go, speak to the kaldorei gathered here, and see if they have offerings for the ceremony.", ["objectivesText"] = "Gather offerings from night elves in the Central Encampment. Progress: Have you collected all the offerings for the ceremony?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 45579, 208221, 208230, 208231, 208232 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 61, ["flags"] = 0 } } },
[77201] = { ["id"] = 77201, ["name"] = "A Personal Offering", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "$p. You have done so much for our people. I would have you participate in this ceremony and provide an offering of your own, should you wish it. Let me know what it is that you would like to put forward and it will be done.", ["objectivesText"] = "Speak with Tyrande Whisperwind in Central Encampment to choose an offering. Progress: Are you certain of your offering?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 961, 3412, 5391, 9545, 9551, 9557, 9567, 9580, 10641, 85205, 208879, 209604 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 4, ["flags"] = 1 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 62, ["flags"] = 1 } } },
[77209] = { ["id"] = 77209, ["name"] = "Seed Legacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77209 }, ["description"] = "For years I worked with Denalan in Teldrassil. His research will be the foundation of how we will restore these seeds. The first step: we must coax them back to life, allowing them to grow into vibrant blossoming plants. I have located suitable patches of soil where the plants can take root and grow, revealing their true potential. We will plant one small, one plump, and one gigantic seed to observe how the quality of the seed can sprout different growth.", ["objectivesText"] = "Plant a seed at each of the Dreamsoil patches. Progress: Have you planted the seeds?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 210014, 210050 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[77231] = { ["id"] = 77231, ["name"] = "Technoscrying 101", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Through a near-perfect blend of technology and arcane enchantment, I have developed a way to analyze the psychometric properties of objects. Wearing these goggles, you can see the data as dynamic simulacra! Simple, yes? I call it... the Psychometric Visuo-Auditory Discrete Waveform Analysis and Viewing Device! For the layperson, we're calling them \" Technoscryers .\" Trademark and patent pending. Here, try them on!", ["objectivesText"] = "Learn to use the Technoscryers . Progress: I have given you the Technoscryers . Please! Put them on!", ["rewardGold"] = 210675, ["rewardXP"] = 7135, ["rewardItems"] = { 208084 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.305333 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5466, ["name"] = "Azerothian Archives - Tutorial", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 4, ["flags"] = 0 } } },
[77254] = { ["id"] = 77254, ["name"] = "Aiding the Accord: Time Rift", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "The Bronze Dragonflight have long labored in secret, dealing with temporal anomalies nearly as quickly as they're able to manifest. It would appear, however, that the anomalies have gotten a bit too big as of late. That's where you come in. You can find Soridormi leading an effort against a particularly nasty set of Time Rifts just to the east of Valdrakken . Aid her in whatever way she deems necessary.", ["objectivesText"] = "Travel to the Tyrhold Reservoir and assist Soridormi in dispelling a Time Rift. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Do you bring news of your success?", ["rewardXP"] = 14275, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 204076, 207002, 207030, 207582, 207583, 207584, 208090, 208945, 208951, 208952 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 11, ["flags"] = 1 } } },
[77267] = { ["id"] = 77267, ["name"] = "Excavation 101", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "So, you want to learn how to excavate artifacts? You came to the right orc! Turns out being able to shape the earth is useful when you're trying to get stuff out of the ground. And given how much the elements affect our work, it helps having an elemental to lend a hand. But you don't have to be a shaman to master excavation. I've got the elements covered. I'll just walk you through the detail work.", ["objectivesText"] = "Meet with Roska outside to learn about excavation. Progress: What do you think? Having fun yet?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210956 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5466, ["name"] = "Azerothian Archives - Tutorial", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 1, ["flags"] = 0 } } },
[77268] = { ["id"] = 77268, ["name"] = "Hands-On Experience", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Great job on that small find! Now, are you ready for something big? More often than not, shaking up the small stuff will shake up something even BIGGER just below the surface. Another little rumble, and we'll have a major find on our hands, I can feel it. A major find works almost the same as the smaller ones with a couple extra steps. Why don't you tackle this one too? It'll be good practice for ya. Don't worry! I can guide you through it.", ["objectivesText"] = "Unearth the major find, then speak to Roska to begin excavating it. Progress: Rare to find big stuff like that up here! Zenata might be up to her tricks again.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210956 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5466, ["name"] = "Azerothian Archives - Tutorial", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 3, ["flags"] = 0 } } },
[77283] = { ["id"] = 77283, ["name"] = "A Multi-Front Battle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326, 77283, 77818 }, ["series"] = { 76323, 76324, 76325, 76326, 77818 }, ["description"] = "The kaldorei have set up a temporary base beneath the boughs of Amirdrassil. With hope and hard work, this encampment will become permanent when the tree enters our world. Feel free to acquaint yourself with the provisions available. Then return to me.", ["objectivesText"] = "Meet Saelienne in the Central Encampment. Progress: Have you found what you needed here in camp?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 208067, 210050, 257352 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 17, ["flags"] = 0 } } },
[77310] = { ["id"] = 77310, ["name"] = "Memory of the Dreamer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77310 }, ["description"] = "In the Dream, memories can live on in unusual ways. Memories are not always linear. And memories that are not of your own can become yours. Perhaps you were drawn to this place by the presence of the once-Dreamer. Or perhaps you were drawn to this place because of my great friend. Come, won't you see? Rest here and let the magic of the Dream wash over you.", ["objectivesText"] = "Rest at the Eye of Ysera.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 210954, 211370 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210022, ["x"] = 0.586, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208713, ["x"] = 0.586, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77311] = { ["id"] = 77311, ["name"] = "Healing Helper", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77311 }, ["description"] = "Gracus sent word for Ysera to come and see him. We arrived and found him in a dire condition. Our efforts to heal him so far have proved fruitless. But now that you are here, you can assist. Gracus is of the Dream. Perhaps infusing his roots with something grown here will be the final thing we need to restore him.", ["objectivesText"] = "Use the Root Restoration Fruit to help heal Gracus. Progress: Gracus' condition is dire. We must do what we can to try to help.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208884 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208713, ["x"] = 0.586, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208713, ["x"] = 0.586, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77312] = { ["id"] = 77312, ["name"] = "Nature Persists", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77312 }, ["description"] = "Admittedly, I do not know what to do next. If he is to rest here... flowers would be lovely. The podlings in this area have been hiding among the flowers. Retrieve seeds from them, Champion, and I will make them bloom. I think Gracus will like the flowers.", ["objectivesText"] = "Collect 6 Sprouted Seedlings from Sneaky Podlings. Progress: There must be something more that we... No. Ysera seems certain.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208676 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208713, ["x"] = 0.586, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208713, ["x"] = 0.586, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77313] = { ["id"] = 77313, ["name"] = "A Solemn Summons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77313 }, ["description"] = "It is as I feared. It is Gracus' time. Healing him would never have worked. The world beyond already calls to him. Although he has such peace, those that care for him will still grieve. He will still be dearly missed. Not everyone is granted a chance to say goodbye. We must ensure that in this case, they are.", ["objectivesText"] = "Inform Gracus' loved ones. Progress: I am grateful we can give them this opportunity to say goodbye.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208714, ["x"] = 0.586, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208714, ["x"] = 0.586, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77314] = { ["id"] = 77314, ["name"] = "Requiem in a Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77314 }, ["description"] = "As one life ends so too will a life begin. We must remind those that love Gracus of this, <name>. Plant seeds around Gracus. My sister can handle the rest. This place will not only represent an end but also a beginning of new life.", ["objectivesText"] = "Plant 6 flowers around Gracus. Progress: These flowers will bloom around Gracus and serve as a reminder of all he helped to grow during his life.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 210954 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208714, ["x"] = 0.586, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208714, ["x"] = 0.586, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77315] = { ["id"] = 77315, ["name"] = "Ancient Memories", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77315 }, ["description"] = "Those dark memories cannot be allowed to fester in the Dream. Unleashing them was necessary. Gracus needed to let go. But if they linger, they may become malevolent. Defeat the memory that haunts him most so that Gracus can slumber at last.", ["objectivesText"] = "Kill the Lingering Torment .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 208067, 211370 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208714, ["x"] = 0.586, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208714, ["x"] = 0.586, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77316] = { ["id"] = 77316, ["name"] = "Trouble at the Tree", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77316 }, ["description"] = "<name>! Merithra needs your help. Some nasty trickster spriggans followed us into the Dream and now they're causing all sorts of havoc! Like the most important thing of all, stealing top secret super important supplies. It's urgent you stop them and get the supplies back.", ["objectivesText"] = "Retrieve 6 Very Important Tree Supplies from Spriggans. Progress: If we don't get those supplies back from those pesky spriggans, we'll be so behind schedule!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208977 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77317] = { ["id"] = 77317, ["name"] = "Hatted Hibernation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77317 }, ["description"] = "I'll let you in on a secret, these crates? They're prank supplies! People are so serious around here. What's better than a little prank to lift everyone's spirits? You could put some of these fun hats on some of the sleeping druids because what's more fun than a surprise hat? Be careful though, their connection to the dream could make anything happen!", ["objectivesText"] = "Put 6 silly hats on Dreaming Druids . Progress: Napping in the Dream... I wonder what they're dreaming about!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208985, 210755 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77318] = { ["id"] = 77318, ["name"] = "Merithra Says", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77318 }, ["description"] = "Some druids are volunteering to help tend to the tree and set up camp. But they're so sad! < Lady Moonberry grows a mischievous grin.> We have to give them a reason to smile. You can give them some orders that remind them to have fun. But there's no way they'll take orders from you. That's why I got this costume for you. With this and a little spell they'll for sure listen to you!", ["objectivesText"] = "Give instructions to 5 druids while disguised as Merithra. Progress: You're clearly a master prankster but you'll have to be a master actor as well. A costume and a spell can only do so much.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208067, 210996, 210997 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77325] = { ["id"] = 77325, ["name"] = "To the Archives!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Are you a scholar, historian, or a high-minded intellectual? Do you enjoy heavy, mindless labor in exchange for gold? Then take hold of your future, and join the newly budding ranks of the Azerothian Archives!* <Your eyes move to the fine print near the parchment's edge.> *Temporary offices are located at the Algeth'ar Academy in northern Thaldraszus.", ["objectivesText"] = "Speak with Lead Archivist Eadweard Dalyngrigge at Algeth'ar Academy.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 204076, 224784, 229354, 237812, 239118, 244865, 248651 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5466, ["name"] = "Azerothian Archives - Tutorial", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 0, ["flags"] = 0 } } },
[77327] = { ["id"] = 77327, ["name"] = "Nirobin and the Office", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2023, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Perhaps there is more to investigate, but I need time to go over our findings here first. Our colleague, Nirobin , the one arcane projecting himself into the headquarters, should be ready for your assistance by now. He's got his own office at the Academy in Thaldraszus that he tends to squirrel himself away in. I'm positive he'll be there... Mostly because he never leaves it.", ["objectivesText"] = "Speak with Nirobin at his office in Thaldraszus.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 204643, ["x"] = 0.664, ["y"] = 0.46 }, { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205967, ["x"] = 0.585, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023, 2025 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5470, ["name"] = "Azerothian Archives - Research Site & Wrap Up", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 15, ["flags"] = 0 } } },
[77328] = { ["id"] = 77328, ["name"] = "Back to Headquarters!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Eadweard called for your return to the main office after I'd finished with you... er, this experiment, I mean. I'm sure it has to do with pomp, circumstance, reward, and what have you. If any of that entices you, then best hurry before his bag of goodies runs dry to all the other recent recruits.", ["objectivesText"] = "Meet with Eadweard Dalyngrigge at Algeth'ar Academy in Thaldraszus.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205967, ["x"] = 0.585, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5470, ["name"] = "Azerothian Archives - Research Site & Wrap Up", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 19, ["flags"] = 0 } } },
[77329] = { ["id"] = 77329, ["name"] = "Auspicious Gathering", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "As you know, Amirdrassil is no ordinary tree. Tyrande Whisperwind and the rest of the kaldorei have been preparing to properly welcome it with a ceremony of their own, and establish a new moonwell. I am certain that Tyrande would want you there for the dedication. Let us join them at the Central Encampment.", ["objectivesText"] = "Speak with Tyrande Whisperwind in the Central Encampment.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 206397, ["x"] = 0.148, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.148, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2023, 2239 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 60, ["flags"] = 0 } } },
[77331] = { ["id"] = 77331, ["name"] = "Graduation Day", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "You've turned out to be quite a fine member of our high-skilled crew of rag tags and diggers of dirt. Between the sites you've broken ground on with Roska, Zenata, and Nirobin, as well as the larger one in Traitor's Rest, the varied histories collected by these Dragon Isles have never been more ripe for the harvest. There will always be work and companionship here when you desire it. We hope you'll join us on other continents as well. ...When we receive appropriate funding, that is.", ["objectivesText"] = "Receive congratulations from your Azerothian Archivist peers. Progress: Worry not. I've already written to our benefactors of your efforts.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5470, ["name"] = "Azerothian Archives - Research Site & Wrap Up", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 43, ["flags"] = 0 } } },
[77339] = { ["id"] = 77339, ["name"] = "Data Recovery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "After a lot of rigorous training, the time has come! Travard believes the Tyr's Guard is ready to recover the disc of Tyr from the Nighthold. Meet us at Tyr's Rest, the new Tyr's Guard headquarters. It's just south of Tyrhold. We will finally make Tyr whole again!", ["objectivesText"] = "Meet Travard at the Tyr's Guard headquarters.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 210255, 210321 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208703, ["x"] = 0.608, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208701, ["x"] = 0.605, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 0, ["flags"] = 0 } } },
[77340] = { ["id"] = 77340, ["name"] = "Infiltrating the Nighthold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "The information from our beacons suggests that Elisande has locked the disc away in Astromancer's Rise. It is a place of learning, and the inside will have minimal protection. I have opened a portal where you and the Tyr's Guard will have the least resistance... except for Elisande and whatever guards are under her employ. All of you are on your own once you get there, so try not to muck it up.", ["objectivesText"] = "Retrieve the Disc of Tyr from Elisande in the Nighthold. Progress: I wonder what Tyr is like? I bet he's super nice!", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 210255, 210321 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208832, ["x"] = 0.604, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208835, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 2, ["flags"] = 0 } } },
[77341] = { ["id"] = 77341, ["name"] = "Logotyrapy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "Dear $p, It seems wrong to say this of someone as mighty as Tyr, but I am worried about him. When he arrived at Tyr's Rest, he spent many days talking with us. We all asked him many questions, learning about the titans, ancient history, and his philosophy. But recently, Tyr has been speaking less, and the answers he does give are shorter and some have an edge to them. I'm not sure what's wrong, but something is different. Will you come speak with him? For Tyr, Valunei", ["objectivesText"] = "Speak with Tyr at Tyr's Rest. Progress: Tyr seems restless. Perhaps you could talk to him, <name>?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 208199, 208826, 210255, 210321 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208839, ["x"] = 0.608, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 6, ["flags"] = 0 } }, ["startItems"] = { 208826 } },
[77342] = { ["id"] = 77342, ["name"] = "Disc Delivery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "You have recovered the disc? Good. At last, we can awake Tyr. The disc must be placed in the console so it can attune to the Silver Scale and pass on to Tyr. I believe you should do the honors, $p.", ["objectivesText"] = "Insert the Disc of Tyr into the titan console. Progress: Did you place the disc in the titan console?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 208798 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208834, ["x"] = 0.604, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208834, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 3, ["flags"] = 0 } } },
[77343] = { ["id"] = 77343, ["name"] = "A Tyrful Reunion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "This is incredible, seeing our friend back after so many thousands of years. So much has happened since we last spoke. The world has changed. Our loss of Tyr was before even the Sundering. But there will be time to discuss all those things later. For now, it's simply good to be with our friend. Stay with us, will you, $p, while we reconnect?", ["objectivesText"] = "Listen to the Aspects' conversation with Tyr. Progress: One moment, <name>--I want to hear what Tyr and the aspects are saying!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208833, ["x"] = 0.604, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208800, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 4, ["flags"] = 0 } } },
[77344] = { ["id"] = 77344, ["name"] = "Time to Process", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "Tyr is back after thousands of years. I don't even know how many thousands. His world has changed more than we can even imagine. He's going to have many questions and need answers. Meanwhile, there's nothing any of the Tyr's Guard would rather do than talk with Tyr. Tyr's Rest seems like the perfect place to give him time, answer questions, and process those answers. Would you ask him to join us there?", ["objectivesText"] = "Invite Tyr to join the Tyr's Guard at Tyr's Rest. Progress: We certainly live in interesting times, <name>...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 208550, 208826 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208800, ["x"] = 0.604, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208839, ["x"] = 0.608, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 5, ["flags"] = 0 } } },
[77345] = { ["id"] = 77345, ["name"] = "The Need For Higher Velocities", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "Sometimes you'll need to travel longer distances. If you don't need to travel up and over any obstacles using Surge Forward is the easiest way to maintain a good forward speed to prevent yourself from plummeting out of the sky. Follow the rings again to your destination and use Surge Forward when prompted to maintain your speed. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Fly through the rings and land in the target area. Progress: Well done, <name>.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 208182 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193287, ["x"] = 0.576, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 183141, ["x"] = 0.575, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 18, ["flags"] = 0 } } },
[77377] = { ["id"] = 77377, ["name"] = "To Tyrhold! For Tyr!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "We recovered. We trained. And now it's time to face Elisande. Come with us to Tyrhold where Nozdormu, Chromie, and Eternus are waiting to send us to the Nighthold. We will get that disc, and Tyr will finally be with us once more.", ["objectivesText"] = "Speak with Eternus in Tyrhold.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208701, ["x"] = 0.605, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208832, ["x"] = 0.604, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 1, ["flags"] = 0 } } },
[77417] = { ["id"] = 77417, ["name"] = "What Makes an Infinite", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "Eternus clearly has something she wishes to impart to us. I am unsure where this conversation will lead. But I trust Chromie. If she believes that Eternus can be swayed, I trust her judgment. When you are ready, I will see what she has to say.", ["objectivesText"] = "See what Eternus has to reveal. Progress: I am interested in learning what Eternus wishes to say.", ["rewardGold"] = 70225, ["rewardXP"] = 2380, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 207106, ["x"] = 0.655, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 207106, ["x"] = 0.655, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 1, ["flags"] = 0 } } },
[77433] = { ["id"] = 77433, ["name"] = "Excavation: Riverbed", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "There's a Riverbed near Maruukai in Ohn'ahran Plains that's teeming with local lore about a lost caravan! Meet me there as quick as you can! And wear your best, old, mud-ready boots!", ["objectivesText"] = "Meet Roska Rocktooth at the Riverbed dig site in Ohn'ahran Plains.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 204094, ["x"] = 0.674, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2023, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 7, ["flags"] = 0 } } },
[77434] = { ["id"] = 77434, ["name"] = "Technoscrying: Observatory", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "My dowsing rods have been pointing towards a set of Drakonid ruins atop a cliff in Waking Shores. I know not what we'll find, but it's never wise to question the whims of my inventions. They're always 97% correct. Always.", ["objectivesText"] = "Meet Zenata at the Concord Observatory in Waking Shores.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.305333 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 11, ["flags"] = 0 } } },
[77436] = { ["id"] = 77436, ["name"] = "The Burning Barrow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "Fyrakk's forces have already set their plans in motion. We are one step behind, and we need to catch up quickly if we are to properly protect Amirdrassil. While you were on your way here, we received word of suspicious-looking figures entering one of the nearby barrow dens. Tyrande already went to investigate. Seek her out and lend her your aid.", ["objectivesText"] = "Find Tyrande near the Sor'theril Barrow Den.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206247, ["x"] = 0.514, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 18, ["flags"] = 0 } } },
[77484] = { ["id"] = 77484, ["name"] = "Technoscrying: Igira's Watch", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Of all places, my sensors are indicating a site of interest beneath the surface in Zaralek Cavern. Best bring a weapon for this excursion. My preliminary scouting indicated a elevated presence of both lava and djaradin.", ["objectivesText"] = "Meet Zenata at Igira's Watch in Zaralek Cavern.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 208084 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.305333 }, ["mapCandidates"] = { ["npc"] = { 2025, 2133 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 37, ["flags"] = 0 } } },
[77486] = { ["id"] = 77486, ["name"] = "Excavation: Gaze of Neltharion", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "A Niffen colleague of mine gave me the underground info about an underground tower. It's decrepit and smack-dab in the middle of Zaralek between Loamm, the Djaradin, and that ghastly lab of Neltharion's. Grab your favorite shovel and meet me there!", ["objectivesText"] = "Meet Roska Rocktooth at the Gaze of Neltharion in Zaralek Cavern.", ["rewardGold"] = 34100, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 205413, ["x"] = 0.486, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2025, 2133 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 22, ["flags"] = 0 } } },
[77662] = { ["id"] = 77662, ["name"] = "A Call to Aid", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77662 }, ["description"] = "Ah, so you are $p? Hm, I suppose Lilian consorts with heroes of all sorts now... Lilian sent me with a message. She and Shandris have been tasked with tracking a powerful Druid of the Flame. He continues to elude them, but with your assistance, they believe they can corner him and his dryad conspirators. Seek them out if you are able to aid them.", ["objectivesText"] = "Meet with Shandris and Lilian in the Lushdream Crags.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 208937 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209516, ["x"] = 0.5, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209083, ["x"] = 0.496, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77664] = { ["id"] = 77664, ["name"] = "One Last Step", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77664 }, ["description"] = "This operation would not have come this far without Lilian's aid. We may not have much in common, but Lillian is a... dependable ally. After fighting side-by-side in the Dream, we have an odd kinship that was forged by this mission. Together, we will finish this. With the stones in our hands, it is now safe to take out Raelas and end his little crusade. Onward.", ["objectivesText"] = "Eliminate Raelas Firewind .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 208937, 210957 }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209799, ["x"] = 0.552, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77665] = { ["id"] = 77665, ["name"] = "Bound to You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77665 }, ["description"] = "I haven't worked with Shandris long, but... it's unusual for her to act like that. But it doesn't matter. While she deals with logistics, you and I should go ahead and find a way to cleanse these stones. Maybe Shae'lune knows what to do next.", ["objectivesText"] = "Ask Shae'lune about the cleansing the stones.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 159, 4540, 63784, 63785, 63786, 84080, 84081, 84082, 84083, 84084, 142054, 172230, 198012, 208937, 211279, 233056, 237812 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209082, ["x"] = 0.552, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209328, ["x"] = 0.552, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77673] = { ["id"] = 77673, ["name"] = "Under the Surface", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77673 }, ["description"] = "I knew coming into this that Shandris likes to work alone, but letting us know where she's going would be nice. Not a great turn in our professional relationship. Keeper Sillas won't speak to me... We should take a look around the camp. Maybe she left a note or some clue... maybe in her mission log? Take a look, and see if you can get anything out of Sillas. I'll wait here in case she comes back.", ["objectivesText"] = "Find clues regarding Shandris' whereabouts.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 1973, 208937 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209328, ["x"] = 0.552, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209323, ["x"] = 0.51, ["y"] = 0.473 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77674] = { ["id"] = 77674, ["name"] = "Wounds of the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77674 }, ["description"] = "It's all making sense now. I believe the missing dream spirit bonded with her--like Cyanthesa said. It's making Shandris relive traumatic moments from her life. It's not malicious, but the spirit and Shandris are feeding off each others' fears. We have to bring her back to the camp. Shae'lune might be able to help her. Talk to her. I look like the enemy right now. But maybe she'll talk to you.", ["objectivesText"] = "Talk to Shandris and help her back to the camp.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208937 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209323, ["x"] = 0.51, ["y"] = 0.473 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209328, ["x"] = 0.552, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.473 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77675] = { ["id"] = 77675, ["name"] = "A Better Future, Together", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77675 }, ["description"] = "<name>, we need to work with Shae'lune and help her perform the purification ritual on Shandris. Shae'lune says she's only done it on objects before--not people. There is some... risk involved. But I've come to know Shandris. She'd do the same for me. Talk to Shae'lune and follow her instructions.", ["objectivesText"] = "Help Shae'lune perform the separation ritual on Shandris. Progress: I will help Shandris as best I can. It's the least I can do for another soldier.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208067, 208937, 209050, 209051, 209054, 211366 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209328, ["x"] = 0.552, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209328, ["x"] = 0.552, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77739] = { ["id"] = 77739, ["name"] = "Smother the Flames", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77739 }, ["description"] = "Lilian and I have been shadowing Raelas Firewind and have uncovered his plan. He has manipulated the Sisters of the Flame to bind spirits from the Dream to magical spirit stones. With Raelas's blessing, these stones became powerful tools of corruption, allowing these fallen dryads to twist the Dream and its denizens. We will start our purge with the dryads--they have the stones. Then we will end Raelas. The hunt begins, $p.", ["objectivesText"] = "Help Shandris and Lilian retrieve the spirit stones from the Sisters of Flame dryads. Progress: Bring me all four spirit stones. We must keep them close so they do not fall into the wrong hands.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 208770, 208937, 209428, 209429, 209430 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209083, ["x"] = 0.496, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77780] = { ["id"] = 77780, ["name"] = "A Blossom Witnessed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "Amirdrassil has bloomed beyond the confines of the Dream. Let us venture to the Dragon Isles and see where this new World Tree has taken root.", ["objectivesText"] = "Speak with Merithra at the Ancient Bough in the Ohn'ahran Plains. Progress: It is magnificent!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 208067 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211634, ["x"] = 0.276, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 206397, ["x"] = 0.148, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2023, 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 0, ["flags"] = 1 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 58, ["flags"] = 0 } } },
[77781] = { ["id"] = 77781, ["name"] = "A Different Enthusiasm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "I noticed the festivities have drawn the attention of a few spriggans from Ardenweald. They are curious creatures with... interesting tastes. Their pranks have been more than disruptive. Please root them out so the celebration may continue in peace.", ["objectivesText"] = "Reveal 6 Spriggan Pranksters in Bel'ameth. Progress: Have you discovered all of them? I have already heard a middling rumor that I suspect they spun up.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 206849, ["x"] = 0.542, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 206849, ["x"] = 0.542, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 65, ["flags"] = 0 } } },
[77802] = { ["id"] = 77802, ["name"] = "What Do I Call You?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77802 }, ["description"] = "Guardian! Or... teacher! Parent? I want you to tell me what to call you. The other dryads will ask me who my druid is now that I am working in the garden on my own. I want to tell them that I do not have a druid. I have you! Tell me what title you prefer.", ["objectivesText"] = "Speak with Dionaessa to choose a title in the Root-Bound Sanctuary. Progress: I have heard so many titles from the druid Creekward. I am certain we can come up with something far more interesting.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 210958 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209788, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209788, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77818] = { ["id"] = 77818, ["name"] = "The Cruel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326, 77283, 77818 }, ["series"] = { 76323, 76324, 76325, 76326, 77283 }, ["description"] = "Primalists, djaradin, and Druids of the Flame all work together against us. But I can sense that this is not the last of them. Something powerful is trying to come through this portal. Let us try to seal them out for as long as we can.", ["objectivesText"] = "Help Merithra close the flaming portal.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 26007, 26021, 26033, 28040, 28041, 28042, 37209, 37419, 37523, 37541, 131272 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206688, ["x"] = 0.628, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206806, ["x"] = 0.589333, ["y"] = 0.615333 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 12, ["flags"] = 0 } } },
[77869] = { ["id"] = 77869, ["name"] = "Return to the Echo Isles", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "<name>, there appears to be trouble in the Echo Isles. Rokhan has requested your help.", ["objectivesText"] = "Meet with Rokhan in the Echo Isles.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 211446, 218105, 218118, 218119, 242520 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 213791, ["x"] = 0.325, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 210198, ["x"] = 0.61, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 85, 463 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[77871] = { ["id"] = 77871, ["name"] = "De Old Loa", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "Bwonsamdi does not be visiting in person without a good reason. Listen to all he has to say. Den we think, den we act.", ["objectivesText"] = "Hear Bwonsamdi's message to the Darkspear trolls and find a solution. Progress: What Bwonsamdi be saying is very serious. Mueh'zala worship is a bloody one.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 210092, ["x"] = 0.602, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 214839, ["x"] = 0.6005, ["y"] = 0.6535 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[77874] = { ["id"] = 77874, ["name"] = "De Loa of de Past", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "We need to be findin' de old loa and call dem back. There must be a way to find where dey went. If we can find de old loa, we can host a Trial of the Loa to reconnect with their power. Bwonsamdi said dey are still out there. I think he be dropping a hint for us...", ["objectivesText"] = "Find a guide to one of the lost loa by making a proper effigy, and follow the guide.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 214839, ["x"] = 0.6005, ["y"] = 0.6535 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 210238, ["x"] = 0.832, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.6005, ["y"] = 0.6535 }, ["mapCandidates"] = { ["npc"] = { 50, 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[77877] = { ["id"] = 77877, ["name"] = "One with the Loa", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "Pieces of Lukou be scattered. But her heart be deep inside the ogre mound. De shadows can take us there. Quietly. Quickly. Speak to me when you are ready.", ["objectivesText"] = "Talk to Kevo to be taken inside the Mosh'Ogg Ogre Mound. Progress: Kevo ya Siti wants to bring us inside the mound.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 222666, ["x"] = 0.65, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 210091, ["x"] = 0.663333, ["y"] = 0.459 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 6, ["flags"] = 0 } } },
[77879] = { ["id"] = 77879, ["name"] = "Stalking the Stalker", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "If dis loa be huntin' here, he may have seen us already. Since we don't know for sure, let's split up. I be hunting for him, while ya get his attention. Jani says the loa has been taking the offerings meant for Hakkar, the loa of blood. But we don't know WHY. Collect some and see if he wants them. If his motive is something else... we be knowin' soon enough.", ["objectivesText"] = "Collect 6 Offerings to Hakkar to attract the loa. Progress: < Kevo ya Siti examines your offerings.>", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 211350, 237859, 237865, 237871, 237880 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 210238, ["x"] = 0.832, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 209891, ["x"] = 0.818, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.832, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[77880] = { ["id"] = 77880, ["name"] = "Looking for Lukou", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "Dis be the last place Kevo ya Siti sensed Lukou. We be needing to ask around, see who knows where she might have gone.", ["objectivesText"] = "Ask about Lukou and follow the trail to find her. Progress: With enough information, we can track Lukou down.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 210091, ["x"] = 0.663333, ["y"] = 0.459 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 210091, ["x"] = 0.663333, ["y"] = 0.459 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.663333, ["y"] = 0.459 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 5, ["flags"] = 0 } } },
[77881] = { ["id"] = 77881, ["name"] = "There is Another", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "If Mueh'zala be involved... I will help. But for a loa trial fit to push Mueh'zala out, we will need another. Our sister loa is also lost. We were a team, her and I, until disagreement pushed us apart. Lukou is the loa of regeneration. She be the ideal loa to balance against death. I owe her an apology. You are here, and it be time. I last sensed her presence near the small settlement of Bambala. I be meeting you there.", ["objectivesText"] = "Go to Bambala to seek out Lukou.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 209891, ["x"] = 0.818, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 222657, ["x"] = 0.635, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.818, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[77882] = { ["id"] = 77882, ["name"] = "Stolen but Not Forgotten", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "There be many pieces missin' from dis altar. We be needing to repair it so dat Lukou is not angered when she returns, Lukou must see dat we are on her side.", ["objectivesText"] = "Collect 8 altar fragments from around the Mosh'Ogg Ogre Mound. Progress: We need all the pieces you can find.", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 210592 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 210091, ["x"] = 0.663333, ["y"] = 0.459 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 210091, ["x"] = 0.663333, ["y"] = 0.459 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.663333, ["y"] = 0.459 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[77894] = { ["id"] = 77894, ["name"] = "Heart of Lukou", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "I was hoping we'd be getting more pieces than dis, but we make do with what we got, eh? Call Lukou to de altar. Hopefully she will answer.", ["objectivesText"] = "Summon and speak with Lukou at the altar. Progress: We're close!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 210091, ["x"] = 0.663333, ["y"] = 0.459 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 210091, ["x"] = 0.663333, ["y"] = 0.459 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.663333, ["y"] = 0.459 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 9, ["flags"] = 0 } } },
[77896] = { ["id"] = 77896, ["name"] = "A Sleepy Search", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77896 }, ["description"] = "In our fight against Fyrakk's forces, a group of my fellow druids went out in search for a quiet and safe place to rest. But with Fyrakk's forces closing in on their location... I have to start planning for another assault, I can't split my time as much as I wish. I last saw them heading south to a cave by the shore. Please, I just need to make sure they're safe.", ["objectivesText"] = "Check up with the sleeping druids.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 210864 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210133, ["x"] = 0.502, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210164, ["x"] = 0.58, ["y"] = 0.774 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77898] = { ["id"] = 77898, ["name"] = "Honor and Tribute", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "It be time to return home. Let us welcome dese loa to the Echo Isles. Their positive influence should make short work of Mueh'zala's presence. Go ahead, I be right behind ya.", ["objectivesText"] = "Set up the loa altars at Darkspear Hold. Progress: The offerings need to be set exactly right.", ["rewardGold"] = 322100, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 210091, ["x"] = 0.663333, ["y"] = 0.459 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 210086, ["x"] = 0.597333, ["y"] = 0.654667 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.663333, ["y"] = 0.459 }, ["mapCandidates"] = { ["npc"] = { 50, 463 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 10, ["flags"] = 0 } } },
[77899] = { ["id"] = 77899, ["name"] = "The Rush'kah", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "When we make de rush'kah, we recreate de shape of the loa as we be seein' dem in our mind. By knowing the shape of de loa, we better understand who dey are. But de mask be shaped by our hands, so when de loa sees it, dey know what we expect dem to be. If the loa don't bless the mask, we expect dem to be something dey will not be. If de loa bless de mask, dey like what we see in dem and a bargain can be struck. We could just write a contract, but it is easier to lie with words than with your hands.", ["objectivesText"] = "Make a rush'kah. Progress: De rush'kah be important in bonding with the loa.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 210830 }, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 210086, ["x"] = 0.597333, ["y"] = 0.654667 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 223215, ["x"] = 0.594, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.597333, ["y"] = 0.654667 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 11, ["flags"] = 0 } } },
[77900] = { ["id"] = 77900, ["name"] = "The Loa Trials", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "When de loa bless the rush'kah, de trials will begin. Loa be giving tasks to teach us. Once de trials start, dey don't stop for nobody! Let's go to de altar together. Witch Doctor Tzadah will lead us in de ritual. She be Master Gadrin's apprentice, but be showin' real initiative in helping out on the trial.", ["objectivesText"] = "Start the trial at the Altar of Darkspear Loa. Progress: It is time to begin de trial.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 223215, ["x"] = 0.594, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 212784, ["x"] = 0.589, ["y"] = 0.6465 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 320, ["title"] = "Lorewalking: Loa", ["questLineID"] = 6023, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 6023, ["name"] = "Lorewalking: Loa", ["orderIndex"] = 22, ["flags"] = 0 } } },
[77901] = { ["id"] = 77901, ["name"] = "Retraining the Trainees", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "Your witch doctor is trying to twist the trial to empower Mueh'zala. Many will be enthralled by this power, but we still stand with the Darkspear. I had a different trial in mind. Now, we adapt. Free your fellow trolls from his sacrificial magic. Dis charm will help them, but you must weaken them first. Try not to sacrifice dem.", ["objectivesText"] = "Extract 8 shadows from lost trainees after weakening them. Progress: Use the charm on the trainees after you weaken them!", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 211000 }, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 210260, ["x"] = 0.5752, ["y"] = 0.5844 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 213638, ["x"] = 0.577, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.5752, ["y"] = 0.5844 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 320, ["title"] = "Lorewalking: Loa", ["questLineID"] = 6023, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 6023, ["name"] = "Lorewalking: Loa", ["orderIndex"] = 23, ["flags"] = 0 } } },
[77902] = { ["id"] = 77902, ["name"] = "Ritual Recovery", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "Dat witch doctor has stolen de trial. She mocks us, trying to eat de life of living things to free Mueh'zala. We still have influence over it, though. Together, we will overwhelm her evil circles. When you find a circle, call upon me, and we will push death aside.", ["objectivesText"] = "Remove 3 ritual circles with Lukou 's aid.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 205981, ["x"] = 0.578, ["y"] = 0.626667 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 213638, ["x"] = 0.577, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.626667 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 320, ["title"] = "Lorewalking: Loa", ["questLineID"] = 6023, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 6023, ["name"] = "Lorewalking: Loa", ["orderIndex"] = 24, ["flags"] = 0 } } },
[77903] = { ["id"] = 77903, ["name"] = "De Power of Death", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "De trial can't be stopped after it starts, but we won't let Tzadah use our people or our loa to aid Mueh'zala. If we be doing nothing, even more Darkspear could be swayed to find power in Mueh'zala. I'll look for a way to breach Tzadah's protective energy, you stop the spirits from taking over our home!", ["objectivesText"] = "Kill Mueh'zala's summoned spirits.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 174485, 174486, 174487, 174488, 174659, 174660, 174661, 174662 }, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 212784, ["x"] = 0.589, ["y"] = 0.6465 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 213638, ["x"] = 0.577, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.589, ["y"] = 0.6465 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 320, ["title"] = "Lorewalking: Loa", ["questLineID"] = 6023, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 6023, ["name"] = "Lorewalking: Loa", ["orderIndex"] = 25, ["flags"] = 0 } } },
[77905] = { ["id"] = 77905, ["name"] = "Avatar of Mueh'zala", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "It be down to dis moment: working with our loa to save de soul of de Darkspear. See if Jani has found anything. Hopefully, his item will let you get close enough to Tzadah's effigies to destroy dem. That should give us a chance to strike the Witch Doctor herself. I'll occupy her attention with Kevo ya Siti's aid, but watch out for her guardians. Dey won't let you destroy her effigies without a fight.", ["objectivesText"] = "Collect Jani's blessing and then travel with Lukou to the top of the pillars to defeat Tzadah's protection totems. Progress: Tzadah is a disgrace to the Darkspear.", ["rewardGold"] = 683200, ["rewardXP"] = 8520, ["rewardItems"] = { 211133 }, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 213638, ["x"] = 0.577, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 212782, ["x"] = 0.585, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.577, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 320, ["title"] = "Lorewalking: Loa", ["questLineID"] = 6023, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 6023, ["name"] = "Lorewalking: Loa", ["orderIndex"] = 26, ["flags"] = 0 } } },
[77906] = { ["id"] = 77906, ["name"] = "De Darkspear Loa", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "Dat was not a traditional trial, but we only keep tradition if it be helping de tribe. It be our strength: to adapt to what comes. It be time to shed de past and honor those most important to us. De Darkspear was never de largest tribe, nor de strongest. We endure because we choose our path, and our allies, well. Dese loa and you all worked and sacrificed not just to help Bwonsamdi, but to protect de souls of de Darkspear. Dat be why we honor our loa... and you.", ["objectivesText"] = "Destroy Mueh'zala's altar and add Jani's. Progress: The effigies need to reflect our favored loa.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 211446, 218105, 218118, 218119 }, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 212782, ["x"] = 0.585, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 213669, ["x"] = 0.588, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 17, ["flags"] = 0 } } },
[77911] = { ["id"] = 77911, ["name"] = "Build-a-Blanket", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77911 }, ["description"] = "I am unable to rest! I have spent all my energy in battle, but there is too much noise and the ground is too hard for me to sleep... I know! It pains me to ask this, but I need to rest so I can go back out and fight. Could you feed two birds with one seed for me? Take out the enraged lashers and retrieve their leaves so I can make a blanket to rest on.", ["objectivesText"] = "Collect 6 Velvety Lasher Leaves from lashers. Progress: For the Emerald Dream , it sure is quite chaotic here.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208930, 210864 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210164, ["x"] = 0.58, ["y"] = 0.774 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210164, ["x"] = 0.58, ["y"] = 0.774 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.774 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77922] = { ["id"] = 77922, ["name"] = "Fluffy Filler Retrieval", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77922 }, ["description"] = "There is no way I could rest without something soft to sleep on. Luckily, the dream has some sage so plush, that it would even put roc feathers to shame! It would be a perfect filling! Could you collect some sage around the area for me to rest on?", ["objectivesText"] = "Collect 8 Silky Sage . Progress: The sage should be soft enough to make a comfortable place to sleep. Thank you for your assistance.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208931, 210864 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210164, ["x"] = 0.58, ["y"] = 0.774 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210164, ["x"] = 0.58, ["y"] = 0.774 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.774 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77948] = { ["id"] = 77948, ["name"] = "Burning Out", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77948 }, ["description"] = "Please, I know how this looks, but we are on the same side! My siblings and I intended to defect from the Flame together. However, none of them have escaped or met up with me since I left, and it's been days! I fear the worst. Do you think I would be begging for aid, alone and unarmed, if I was not honest? Please, find them. They are all I have left.", ["objectivesText"] = "Find Solarys's siblings in the Smoldering Copse.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 118, 53361, 53367, 53379, 56715, 56716, 56717, 93146, 120313, 127853, 131314, 131850, 152626, 152984, 153501, 153502, 153503, 153504, 156682, 198059, 198607, 200453, 204075, 204673, 204732, 204733, 204737, 204738, 204739, 204740, 204742, 204743, 204744, 204750, 204752, 204753, 204758, 204759, 204761, 204764, 204766, 204769, 204772, 204774, 204776, 204780, 204781, 204785, 204787, 204896, 204897, 204898, 208067, 209903, 209908, 210633, 211279, 226193, 226194, 232877, 237812, 246815, 246936, 247820, 249400, 251821, 254267, 254579, 256196, 256204, 256212, 256220, 264675 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210196, ["x"] = 0.512, ["y"] = 0.635333 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210196, ["x"] = 0.512, ["y"] = 0.635333 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.635333 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77955] = { ["id"] = 77955, ["name"] = "Heated Hearthstone Hustle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77955 }, ["description"] = "Wait, my hearthstone! I can't sleep without my hearthstone. A djaradin stole it during our last battle. It stays warm perpetually and I always sleep with it. I hate that I must ask more of you, but could you get my hearthstone? The djaradin that stole it should be near Fyrakk's army, just north of here.", ["objectivesText"] = "Retrieve the Heated Hearthstone from the Stonewarmer. Progress: My eyes grow tired, but my body is still awake...", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 208949 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210164, ["x"] = 0.58, ["y"] = 0.774 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210164, ["x"] = 0.58, ["y"] = 0.774 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.774 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77958] = { ["id"] = 77958, ["name"] = "Sleepy Druid in Emerald Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77958 }, ["description"] = "Why can I still not fall asleep, even with a heated blanket? < Thaalean curses the air then sighs.> This is embarrassing to request, but my mother used to sing me a lullaby before I slept back in Teldrassil, may I ask you to do the same? Any lullaby will do, I just want to rest peacefully.", ["objectivesText"] = "Sing a lullaby for sleepy druid.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 208067, 210864, 210952 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210164, ["x"] = 0.58, ["y"] = 0.774 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210133, ["x"] = 0.502, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.774 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[77978] = { ["id"] = 77978, ["name"] = "A Passed Torch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77978 }, ["description"] = "<Strategic documents are scattered around Lyandris. Notes detailing experiments and future assault locations covering many of them.> <It would be of great use to your allies to find more of these documents. Thinning out the Flame's numbers wouldn't hurt either.>", ["objectivesText"] = "Collect documents and kill Druids of the Flame within the Smoldering Copse. Progress: What is it?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209048, 210921 }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210196, ["x"] = 0.512, ["y"] = 0.635333 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.635333 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78041] = { ["id"] = 78041, ["name"] = "Sky Mother's Ire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78041 }, ["description"] = "We received reports that the Druids of the Flame have established another staging ground just south of the Eye of Ysera. Unfortunately for them, their incursion point has disrupted the local winged wildlife and drawn the ire of the Mother of Flight. Speak with Aviana and lend her your aid. We will need her eyes and wings in the battle to come.", ["objectivesText"] = "Seek out Aviana .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 208775, 210645 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209318, ["x"] = 0.508, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210587, ["x"] = 0.658, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78042] = { ["id"] = 78042, ["name"] = "Aviana's Assessment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78042 }, ["description"] = "< Aviana 's eyes narrow as she watches the Druids of the Flame far below.> Q'onzu may be content with letting these heretics destroy the very fabric of the Dream, but I am not. Bring me scraps of their armor stained with blood as proof of your deed. Do not hold back, <name>. Remember what these heathens are capable of.", ["objectivesText"] = "Collect 20 Bloodied Armor Scraps . Progress: Every minute they are left uncontested, another portion of the Dream is lost to their heinous acts.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208775, 209875, 210645 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210587, ["x"] = 0.658, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210587, ["x"] = 0.658, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78043] = { ["id"] = 78043, ["name"] = "Q'onzu's Quandary", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78043 }, ["description"] = "You again! Well, you must be here to help, correct? Absolutely you are. Why would you not? This development is so exciting. What could these desolating druids be up to? Fortunately, a few of my friends have infiltrated the druids. I'm sure they have quite the story to tell. Go forth, my curious companion and bring back exciting news!", ["objectivesText"] = "Speak to the Flame-Disguised Dreamkin to gather intel on the Druids of the Flame. Progress: Change has come to the dream and yet we are so quick to snuff it out. How unnaturally boring.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208775, 209952, 210645 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210585, ["x"] = 0.658, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210585, ["x"] = 0.658, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78044] = { ["id"] = 78044, ["name"] = "Appalling Pollen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78044 }, ["description"] = "This cinder pollen doesn't evoke interesting change. It consumes all until nothing, but ash remains. It brings... uniformity. And I find that to be tragically stale. I'm all for change, no matter the origin. But if THIS change stymies all future possibilities for further change, then it must be stopped. If creatures of the dream have been infected by this pollen, then they must be extinguished. This is not a flame that can be allowed to grow.", ["objectivesText"] = "Reveal and kill 10 Cinderpollen Beasts. Progress: Bringing about change to the dream through fire is a fascinating concept - life and fire can coexist! < Q'onzu 's expression hardens as they shudder.> But this change is not that.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208775, 210176, 210645 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210585, ["x"] = 0.658, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210585, ["x"] = 0.658, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78045] = { ["id"] = 78045, ["name"] = "Uproot the Cause", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78045 }, ["description"] = "< Aviana 's gaze remains locked on Q'onzu for a moment, her brow furrowed.> While I don't see eye to eye with Q'onzu's fascination for change, their incessant inquiry has unveiled a more deep-seated plot than originally suspected. Putting down the wildlife won't mean much if we don't tear out the root of the cause. Locate the burning ashphodels in the glade below and tear them out.", ["objectivesText"] = "Collect 8 Uprooted Ashphodels . Progress: If the ashphodels are allowed to spread their foul pollen unchecked, then the rest of the dream is in grave danger. < Aviana grimaces.>", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208775, 210136, 210645 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210587, ["x"] = 0.658, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210587, ["x"] = 0.658, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78046] = { ["id"] = 78046, ["name"] = "Overseer Oversight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78046 }, ["description"] = "Those research notes you brought Q'onzu made mention of the ones behind these foul experiments. The overseer, the one named Chardryn, has been under our noses this whole time. He oversees their research station below us. If we are to permanently end their terrible experiments and disrupt their progress, then he must be made an example of.", ["objectivesText"] = "Slay Overseer Chardryn . Progress: If Chardryn and his insane herbologists are allowed to carry out biological warfare here in the dream, then Amirdrassil and all of Azeroth is at risk. We cannot allow these sycophants of fire to remain alive.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 208047, 208775, 210645, 210727, 211369 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210587, ["x"] = 0.658, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210587, ["x"] = 0.658, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78064] = { ["id"] = 78064, ["name"] = "Q'onzu's Perception", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78064 }, ["description"] = "You have many questions and I have many worries. Such pressing worries. An interloper, a rude disrupter of our joyous day. How I worry so. If only someone could confront this trespasser. Wait, you could do it for me! It's a win-win, you go confront the trespasser and I answer your questions. I've tracked them down to a cave in the north. Surely you can handle them.", ["objectivesText"] = "Find and confront the interloper in Q'onzu 's nest. Progress: I can sense the interloper causing a disturbance in my nest!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208775, 210645 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210524, ["x"] = 0.346, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210524, ["x"] = 0.346, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78065] = { ["id"] = 78065, ["name"] = "The Q'onzu Query", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78065 }, ["description"] = "Champion, I understand we were unable to convince Q'onzu to join us. However, we need all the aid we can gather. You must discover why they refuse to aid us and convince them of the right path. Q'onzu and I have a rather strained relationship. Your efforts could bear more fruit. I hear Q'onzu has built a nest near Shiversnap Grove. Would you go and approach them?", ["objectivesText"] = "Approach Q'onzu again and ask what they've been up to.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 208775, 210645, 210727 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209318, ["x"] = 0.508, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210646, ["x"] = 0.348, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78066] = { ["id"] = 78066, ["name"] = "The Answers You've Earned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78066 }, ["description"] = "Ah, that's much better. Now I can think. What did you want, again? Oh yes! Questions. Ask away, if you must.", ["objectivesText"] = "Get answers about Q'onzu .", ["rewardGold"] = 79250, ["rewardXP"] = 1415, ["rewardItems"] = { 208067, 208775, 210645, 211374 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210524, ["x"] = 0.346, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211821, ["x"] = 0.346, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78068] = { ["id"] = 78068, ["name"] = "An Artificer's Appeal", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 103, ["storyline"] = { 78068 }, ["description"] = "<name>, I received an item for you from Grand Artificer Romuul . Romuul wished for you to listen to the message before proceeding to the Exodar.", ["objectivesText"] = "Meet Grand Artificer Romuul in the Exodar.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 210454, 218105, 218118, 218119, 242520 }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 210340, ["x"] = 0.548444, ["y"] = 0.797111 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.548444, ["y"] = 0.797111 }, ["mapCandidates"] = { ["npc"] = { 103 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[78069] = { ["id"] = 78069, ["name"] = "Reviving Tradition", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3557, ["mapID"] = 103, ["storyline"] = { 78069 }, ["description"] = "The Prophet wished to personally ask for your help with the Tishamaat. But since he is working elsewhere, I asked you first to jumpstart our task. My colleague and I have been working on a special project. And since the Prophet has declared today the Tishamaat, we will unveil it at the celebration! For this, I need the emitter, but it needs an overhaul. We only have time for a hot wiring. Get some filament and a soldering tool from the crates nearby, <name>. Then maybe I can wire it to an array.", ["objectivesText"] = "Help Romuul finish repairing the Holographic Emitter. Progress: I regret not having apprentices in times like this.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 210167, 210168 }, ["starts"] = { { ["mapID"] = 103, ["npcID"] = 210340, ["x"] = 0.548444, ["y"] = 0.797111 } }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 210340, ["x"] = 0.548444, ["y"] = 0.797111 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.548444, ["y"] = 0.797111 }, ["mapCandidates"] = { ["npc"] = { 103 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[78070] = { ["id"] = 78070, ["name"] = "Pressing Deadlines", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3557, ["mapID"] = 103, ["storyline"] = { 78070 }, ["description"] = "During this Tishamaat, Ataanya and I will present our project's schematics. Ataanya is High Artificer of Shattrath. Her father was my late mentor, the famed Exarch Hataaru. Hataaru's hoofplates are hard to fill, but Ataanya has more than done so. She has the schematics, and she should be here when they are presented. But she is not responding to my messages. Ataanya seldom leaves the city, but surely she can make an exception for the Tishamaat. Perhaps you can reason with her.", ["objectivesText"] = "Speak to Ataanya in Shattrath City.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 210454 }, ["starts"] = { { ["mapID"] = 103, ["npcID"] = 210340, ["x"] = 0.548444, ["y"] = 0.797111 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 208494, ["x"] = 0.386, ["y"] = 0.466667 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.548444, ["y"] = 0.797111 }, ["mapCandidates"] = { ["npc"] = { 103, 111 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[78071] = { ["id"] = 78071, ["name"] = "Rush Order", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 78071 }, ["description"] = "My schematics speak for themselves. Each calculation has been verified. It is respectful of all building codes. I even included a layout of the channels that the power grid must follow. Romuul knows the project. He already signed off on everything. He can explain it to the masses himself. I do not need to waste my valuable time traveling to the Exodar for this ridiculous holiday. My apprentice will give you the schematics on a data crystal. Take it and leave.", ["objectivesText"] = "Speak to Beruun. Perhaps he knows a way to convince Ataanya to leave Shattrath. Progress: We will do what we can for Ataanya.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 210181, 224818 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 208494, ["x"] = 0.386, ["y"] = 0.466667 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 208496, ["x"] = 0.386, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.466667 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[78072] = { ["id"] = 78072, ["name"] = "An Old Wound", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 78072 }, ["description"] = "<Beruun whispers to you.> There are ways, I'm sure you know, for the draenei to speak to the dead. It's not the same as having a loved one back but... Hataaru's ashes were taken to Auchindoun after the soulpriests reclaimed the temple. Maybe they might know a way to help Ataanya with her loss?", ["objectivesText"] = "Speak to the soulpriests at Auchindoun.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 208496, ["x"] = 0.386, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 108, ["npcID"] = 210578, ["x"] = 0.375, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 108, 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[78073] = { ["id"] = 78073, ["name"] = "Lingering Scars", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 78073 }, ["description"] = "I believe we may be able to help. But perhaps you could aid me first... When we received word that the Tishamaat was upon us, we hurried to prepare our most tortured spirits for the journey to the Exodar. The celebration's sacraments may help them rest peacefully. However, they must consent to being moved. So, we must commune with and soothe them first. Will you help calm these spirits? Afterward, I will take you to where Hataaru is entombed and give you what you seek.", ["objectivesText"] = "Help Exarch Maladaar commune and soothe the spirits of Auchindoun. Progress: Your kindness may help these spirits find peace in death.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 108, ["npcID"] = 210578, ["x"] = 0.375, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 108, ["npcID"] = 210581, ["x"] = 0.415, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 108 }, ["zone"] = { 3519 } }, ["questType"] = "standard" },
[78074] = { ["id"] = 78074, ["name"] = "To See Clearly", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 78074 }, ["description"] = "Fortunately, not all of the fallen entombed here in Auchindoun suffer as these three do. Some ease gracefully into death, like soil settling after a rainfall. Exarch Hataaru is one such soul. Thanks be to the Light that he rests easy. Come, I will show you to his tomb.", ["objectivesText"] = "Visit Exarch Hataaru's tomb and then return to Ataanya in Shattrath. Progress: <Ataanya crosses her arms tightly, not looking at you or Beruun.>", ["rewardGold"] = 331700, ["rewardXP"] = 6815, ["rewardItems"] = { 210189 }, ["starts"] = { { ["mapID"] = 108, ["npcID"] = 210581, ["x"] = 0.415, ["y"] = 0.616 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 210569, ["x"] = 0.388, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.616 }, ["mapCandidates"] = { ["npc"] = { 108, 111 }, ["zone"] = { 3519 } }, ["questType"] = "standard" },
[78075] = { ["id"] = 78075, ["name"] = "Moving Past", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 78075 }, ["description"] = "My mother died on a colony planet. My father and I helped each other move past that, but when he died in the siege of Shattrath, watching the walls of his greatest accomplishment crumble to dust... There was no one left for me. So I worked. And now I have the schematics of my own Shattrath. A better Shattrath. <Ataanya clenches the lens in her fist then exhales in resignation.> I'll go to the Exodar--but if Romuul says one word about it, I will make him eat his soldering tool.", ["objectivesText"] = "Return to Grand Artificer Romuul in the Exodar.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 210454 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 210569, ["x"] = 0.388, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 210562, ["x"] = 0.555, ["y"] = 0.795 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 103, 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[78076] = { ["id"] = 78076, ["name"] = "Emergency Efforts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3557, ["mapID"] = 103, ["storyline"] = { 78076 }, ["description"] = "<name>! Velen told me I may find you here. He needs your assistance. The satyr that infest a nearby island have been ambushing draenei traveling for the Tishamaat. Velen and I have been attempting to solve the problem quietly. He does not wish to mobilize the vindicators and alarm his people on a day of sacrament. But, despite our efforts, the attacks have continued. The event may need to be canceled if we cannot get the demons under control. Come with me so we may end this threat.", ["objectivesText"] = "Use the Argussian Mana Ray to fly to Bloodmyst Isle with Chieftain Hatuun .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 103, ["npcID"] = 210563, ["x"] = 0.544, ["y"] = 0.7716 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 210390, ["x"] = 0.52, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.7716 }, ["mapCandidates"] = { ["npc"] = { 103, 106 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[78077] = { ["id"] = 78077, ["name"] = "Beneath the Skin", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 78077 }, ["description"] = "Arzaal and I are of the same mind. We must know the strength of these satyr before we attempt to drive them back with force. Else we may be walking into a fight we cannot win. I can learn much about my enemies by observing what damage they leave in their wake. The wildlife here was corrupted by the Exodar's lingering energies, but I suspect the demons' presence made it worse. Collect bones from the local wildlife for me. Studying them may give us some clues.", ["objectivesText"] = "Collect 8 Pitted Bones from corrupted wildlife. Progress: Remember, you are putting them out of their misery.", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 210239 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 210391, ["x"] = 0.52, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 210391, ["x"] = 0.52, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[78078] = { ["id"] = 78078, ["name"] = "Assessing the Enemy", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 78078 }, ["description"] = "The Legion may be one entity, but it is vast. The demons that comprise it are as varied as the innumerable worlds they have conquered. But I have had no dealings with satyr. From what the Prophet has told me, they seem disorganized. Intelligent certainly, but feral in their malevolence. I am inclined to believe their recent attacks are random, but perhaps not. Bring me the totems they have scattered across Bloodmyst. I may be able to ascertain what, if anything, their end goal is.", ["objectivesText"] = "Collect 6 Satyr Totems . Progress: I would prefer to know the capabilities of the satyr before engaging them.", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 210238 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 210588, ["x"] = 0.52, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 210588, ["x"] = 0.52, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[78079] = { ["id"] = 78079, ["name"] = "Excision", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 78079 }, ["description"] = "I cannot in good conscience gather the draenei for the Tishamaat if we are threatened this close to home. If one of the man'ari is using the satyr to orchestrate these attacks, or to distract us from some larger foul purpose, then they must be rooted out immediately. We will divide our efforts to look for signs of the enemy. Arzaal will search the northern satyr camp. You, Hatuun, and myself will search the closer camp.", ["objectivesText"] = "Meet Velen and Hatuun in Nazzivian to search for signs of man'ari presence in the area.", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 210390, ["x"] = 0.52, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 210600, ["x"] = 0.422, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[78080] = { ["id"] = 78080, ["name"] = "At the Source", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 78080 }, ["description"] = "Can you hear that? The silence? The area is empty. Not even the rabid wildlife dare approach the camp. I do not see any immediate cause, but the fel resonance here is overwhelming. I sense it was woven by man'ari hands, but I'm being blocked from probing more deeply. Something is being hidden. It must be the cloaking magic Hatuun reported from the other camp that hinders me. I can dispel it, but I cannot guarantee what we will find when I do.", ["objectivesText"] = "Discover the source of the fel concentration in Axxarien and destroy it. Progress: This ends here!", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["rewardItems"] = { 25913, 25914, 25915, 36878, 36879, 36880, 36881, 36882, 36883, 52595, 52621, 52633, 66908, 66909, 66910, 131282, 142054, 155392, 155393, 155394, 155395, 155448, 159975, 193666, 193671, 198606, 211279, 237812, 245616 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 210598, ["x"] = 0.422, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 210605, ["x"] = 0.415, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[78081] = { ["id"] = 78081, ["name"] = "Pain Recedes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 78081 }, ["description"] = "With Sironas slain once again, Bloodmyst will finally be able to heal. Her influence was no doubt anchoring the corruption to the land. It is another reason to celebrate today. But it is not the true reason I called Hatuun and Arzaal to Azeroth. I would have them attend the Tishamaat with us. The sacrament asks us to reflect on the past and commit to a better future. The unity of our efforts epitomizes that. I will bring them to the Exodar. Please join us when you are ready.", ["objectivesText"] = "Meet with Prophet Velen in the Exodar.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 210454 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 210605, ["x"] = 0.415, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 214021, ["x"] = 0.55, ["y"] = 0.806 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 103, 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[78082] = { ["id"] = 78082, ["name"] = "A Burden Shared", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3557, ["mapID"] = 103, ["storyline"] = { 78082 }, ["description"] = "The Tishamaat was once a solitary holiday. Each eredar would inscribe a stone with a painful memory we carried. We would reflect on what that memory could teach us then commit to moving forward with that wisdom. At last, the stones are dissolved in the Flame of Reprieve, symbolically removing the weight from our souls. Today, the Tishamaat will be celebrated not in solitude, but as a community. Gather the stones of those who would trust you with them then take them to the flame.", ["objectivesText"] = "Collect 10 Memory Stones, create your own Memory Stone, and then dissolve the stones in the Flame of Reprieve. Progress: For many, this is the first Tishamaat they have participated in. For others, it is a distant memory.", ["rewardGold"] = 312800, ["rewardXP"] = 6815, ["rewardItems"] = { 210538, 210575, 210576, 210577, 210578, 210579, 210580, 210581, 210584, 210586 }, ["starts"] = { { ["mapID"] = 103, ["npcID"] = 214021, ["x"] = 0.55, ["y"] = 0.806 } }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 212387, ["x"] = 0.6452, ["y"] = 0.8708 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.806 }, ["mapCandidates"] = { ["npc"] = { 103 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[78083] = { ["id"] = 78083, ["name"] = "Our Path Forward", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3557, ["mapID"] = 103, ["storyline"] = { 78083 }, ["description"] = "Ah, I believe I hear the Prophet calling the attendants before the stage. I am curious to see what he and Romuul plan to announce now that everyone is gathered. We should make haste, yes?", ["objectivesText"] = "Speak to Prophet Velen to begin the ceremony. Progress: The future is ours.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 210455, 211313, 237812 }, ["starts"] = { { ["mapID"] = 103, ["npcID"] = 212387, ["x"] = 0.6452, ["y"] = 0.8708 } }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 212402, ["x"] = 0.5504, ["y"] = 0.8084 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.6452, ["y"] = 0.8708 }, ["mapCandidates"] = { ["npc"] = { 103 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[78162] = { ["id"] = 78162, ["name"] = "Q'onzu's Distraction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78162 }, ["description"] = "Truly your questions are important to me. Alas, I am simply too distracted. These podlings--nasty little ones. I'm sure you've seen them. They're encroaching upon my nest and just a total nuisance. Bothering myself and my friends? The nerve! Here's my feather. Why don't you go change these nuisances into something less bothersome.", ["objectivesText"] = "Weaken 8 podlings, then use Q'onzu's Faerie Feather to change them into Faerie Dragons. Progress: I can still hear the annoying sounds of those podlings. It's torture.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 137663, 208775, 210227, 210645 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210524, ["x"] = 0.346, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210524, ["x"] = 0.346, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78163] = { ["id"] = 78163, ["name"] = "Q'onzu's Qualification", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78163 }, ["description"] = "You seek an audience with Q'onzu but bring no offerings? One does not just walk up and speak to the loa of Change, I'm afraid. You must first prove you are worth their time. The friends of Q'onzu have been granted one hundred questions by the loa themself! You must prove your wit and answer each of them true. Return to me if you answer all one hundred. Then perhaps you'll earn an audience.", ["objectivesText"] = "Answer Q'onzu 's 100 questions.", ["rewardGold"] = 286500, ["rewardXP"] = 1415, ["rewardItems"] = { 137663, 208775, 210645, 211373 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210646, ["x"] = 0.348, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210524, ["x"] = 0.346, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78170] = { ["id"] = 78170, ["name"] = "Nurturing Ageless Seeds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78170 }, ["description"] = "The growth of these seeds is a delicate balance, requiring constant nurturing. I've found that Ageless Dewdrops , gathered from around this area, hold a special energy that can awaken the dormant potential within these seeds. If you could collect some dewdrops and apply them to the plants, we can unlock their full potential.", ["objectivesText"] = "Nurture each of the seed we planted with Ageless Dewdrops . Progress: Have you given the Ageless Dewdrops to the blossoming seeds?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 210050, 211406, 211410 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[78171] = { ["id"] = 78171, ["name"] = "Blossoms of the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78171 }, ["description"] = "With your help, these seeds have grown into magnificent plants. However, the most exciting part is yet to come. Each of these plant's blossoms contain a treasure trove of information about their history and the magic that binds them to the world tree. By studying these blossoms, we can better understand the lineage of each plant. Gently collect the blossoms that have fallen and return them to me.", ["objectivesText"] = "Collect 3 Dreamseed Blossoms. Progress: Have you collected the three blossoms?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 208066, 210050, 210052 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78172] = { ["id"] = 78172, ["name"] = "Mysterious Seeds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78172 }, ["description"] = "<These mysterious seeds might be of interest to Sylvia Whisperbloom .>", ["objectivesText"] = "Deliver the seeds to Sylvia Whisperbloom at the Wildling Garden. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 210050 }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["startItems"] = { 210050 } },
[78177] = { ["id"] = 78177, ["name"] = "To Gilneas", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 84, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "The time has come to reclaim my kingdom, champion. The Forsaken have left the land, as promised. However, in their absence it seems the Scarlet Crusade have decided to move in and use the city as their own personal stronghold. I mean to move them out. Join me in retaking Gilneas.", ["objectivesText"] = "Travel to Keel Harbor in the Ruins of Gilneas. Progress: Gilneas will be ours once more.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 54987, 54988, 54989, 54990, 55011, 62837, 62838, 62839 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 214538, ["x"] = 0.339, ["y"] = 0.155667 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.339, ["y"] = 0.155667 }, ["mapCandidates"] = { ["npc"] = { 21, 84 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 1, ["flags"] = 0 } } },
[78178] = { ["id"] = 78178, ["name"] = "To Gilneas", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78178, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78597, 79137 }, ["description"] = "<name>, we've received word of an offensive occurring soon in Gilneas. We have been working with the Alliance to return Gilneas to the Gilneans. Unfortunately, the Scarlet Crusade have taken up residence in the city. We wish to provide assistance in purging the Scarlet's and return the Gilneans lands to them. Lilian and I want you to join us in this operation.", ["objectivesText"] = "Travel to Gilneas in Eastern Kingdoms to assist with retaking Gilneas City for the Gilneans. Progress: Thank you for coming to help, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 54987, 54988, 54989, 54990, 55011, 62837, 62838, 62839 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210965, ["x"] = 0.428, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 0, ["flags"] = 0 } } },
[78180] = { ["id"] = 78180, ["name"] = "A Crusade of Red", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Calia will lead the Forsaken army in a distracting assault to the North. I'd like you to meet up with Lilian and me in the city. There's a secret tunnel that will give us access to the south. From there, we can open the south gate and let our forces in while the Scarlets are distracted with Calia's troops. There's a group of Scarlet Crusade currently skulking about the entrance to that secret tunnel. Care to take them out?", ["objectivesText"] = "Kill 10 Scarlet Crusade Members in Aderic's Repose. Progress: These Scarlets are a blight upon the land.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 1, ["flags"] = 0 } } },
[78181] = { ["id"] = 78181, ["name"] = "Aderic's Retort", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "The scouts report that the Scarlet Crusade at Aderic's Repose are being encouraged to tamper with the graves of my people by one Scarlet in particular. Too many Gilneans gave their lives defending this land. I will not let their sacrifice be... defiled in this manner! Take out their leader, and send them a message they won't soon forget.", ["objectivesText"] = "Slay Consecrator Hennas in Aderic's Repose. Progress: Is she dead, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 217, ["npcID"] = 210904, ["x"] = 0.5, ["y"] = 0.4424 } }, ["ends"] = { { ["mapID"] = 217, ["npcID"] = 212187, ["x"] = 0.495, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 217, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.4424 }, ["mapCandidates"] = { ["npc"] = { 217 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 2, ["flags"] = 0 } } },
[78182] = { ["id"] = 78182, ["name"] = "Knee-High", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Tess and Voss are waiting for you at the end of the tunnel. Once you arrive, the three of you will open the south gate from the inside, and let our forces into the city. Head through the tunnel to meet them. Take this torch, the way is infested with vermin. I'll ready our forces to storm the gate the moment it is opened.", ["objectivesText"] = "Make your way through the secret tunnel in Aderic's Repose to Gilneas City.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 217, ["npcID"] = 212187, ["x"] = 0.495, ["y"] = 0.569 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 217, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 21, 217 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 3, ["flags"] = 0 } } },
[78183] = { ["id"] = 78183, ["name"] = "Scarlet Blood", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Looks like they've filled the city with their most experienced forces. Don't worry, I have plenty of experience taking them down... personally. We'll whittle their numbers down one by one.", ["objectivesText"] = "Kill 12 Scarlet forces. Progress: Are you done?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210964, ["x"] = 0.426, ["y"] = 0.727 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.727 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 4, ["flags"] = 0 } } },
[78184] = { ["id"] = 78184, ["name"] = "Smokepowder and Mirrors", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Opening the gate is all well and good, but we'll need to clear a way for our forces to advance first. Our scouts reported that the Crusade has explosives that they've stashed in the area. Surely they won't mind if we borrow some?", ["objectivesText"] = "Collect 8 Scarlet Explosives . Progress: Hmm?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 211248 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 5, ["flags"] = 0 } } },
[78185] = { ["id"] = 78185, ["name"] = "Hounds of War", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "I think we've had enough fun on our own, yes? The Scarlets stationed near the city's chapel seem to be the most elite of their forces. I believe we'll find whoever is leading them there, but going alone is unnecessarily dangerous. Time to bring the true might of Gilneas and take our city back. My forces stand ready to charge!", ["objectivesText"] = "Open the gates to Gilneas City. Progress: My people stand ready.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 6, ["flags"] = 0 } } },
[78186] = { ["id"] = 78186, ["name"] = "Crushing the Crusade", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "The most powerful members of the Scarlet Crusade will be defending the nest of their leader, <name>. That's where I come in. Nothing like a little distraction to take an enemy down swiftly. Just let me know where and when to strike.", ["objectivesText"] = "Kill 12 Scarlet Crusade members in the Gilneas City chapel courtyard.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210964, ["x"] = 0.426, ["y"] = 0.727 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.727 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 7, ["flags"] = 0 } } },
[78187] = { ["id"] = 78187, ["name"] = "Artillerist Arsonist", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "The chapel seems to be their base, and it is well defended--they've set up multiple defenses throughout the courtyard. The troops would have an easier time sieging if we could get some of them out of the way. Remember those explosives we gathered? Now is when they come in handy.", ["objectivesText"] = "Plant 6 explosives.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 8, ["flags"] = 0 } } },
[78188] = { ["id"] = 78188, ["name"] = "Righteous Fire, Righteous Fury", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Only one person remains standing between us and our city. Ready yourself--this won't be an easy fight.", ["objectivesText"] = "Slay the leader of the Scarlet Crusade. Progress: Is she dead?", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 9, ["flags"] = 0 } } },
[78189] = { ["id"] = 78189, ["name"] = "Beginning a New Dawn", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Much has changed since we had to leave this city. Both the land, and my people. Bear witness, <name>, to the future of Gilneas.", ["objectivesText"] = "Listen to Genn Greymane 's conversation with Tess.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211788, 211873 }, ["starts"] = { { ["mapID"] = 217, ["npcID"] = 210904, ["x"] = 0.5, ["y"] = 0.4424 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 217, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.4424 }, ["mapCandidates"] = { ["npc"] = { 21, 217 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 10, ["flags"] = 0 } } },
[78206] = { ["id"] = 78206, ["name"] = "Emerald Bounty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78206 }, ["description"] = "There are so many more species to locate and study. As you explore the Dream, you will find more seeds known as Dreamseeds. Please, nurture them to continue our studies, and enjoy the bounty they share with you! You will find Dreamseeds all over, but many are hoarded by powerful creatures around the Dream. Additionally, you should keep an eye out for the surge of life energy we call an Emerald Frenzy. It will be a source of many Emerald Dewdrops, which will help in nurturing Dreamseeds.", ["objectivesText"] = "Partake in the Emerald Frenzy to earn Emerald Dewdrops and contribute a Dreamseed to sprout new growths. Progress: Have you helped further our research?", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 208047, 208066, 208067, 210050 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78262] = { ["id"] = 78262, ["name"] = "It Starts With a Stone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78262 }, ["description"] = "This land holds so many secrets. And even more power! And you... we both know you enjoy unraveling secrets and collecting marvelous gear. And when you're ready to unlock the power of gear you find in this new land, come visit Cuzolth and me. We are experimenting and will be able to upgrade your gear by the time you come back. Please bring me some Flightstones and a new item so I can show you how these upgrades work.", ["objectivesText"] = "Acquire 50 Flightstones by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Cuzolth and upgrade a piece of Season 3 equipment using Flightstones . Progress: Can you feel the power? The excitement of knowing you can now take on even more daring adventures?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211328, ["x"] = 0.498, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211328, ["x"] = 0.498, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5505, ["name"] = "10.2 Upgrade System Tutorial", ["orderIndex"] = 0, ["flags"] = 0 } } },
[78271] = { ["id"] = 78271, ["name"] = "Dreaming of Crests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78271 }, ["description"] = "Now that you've learned the fundamentals, you can easily upgrade lower-level gear. Sooner than later, though, you will find better gear that requires various types of Dreaming Crests to upgrade. Much like Flightstones, these Crests are rewarded through many different activities. Dreaming Crests have four tiers, and more dangerous tasks reward you with higher-tier crests. Go and help with tasks, down formidable foes, find treasures, and bring me a few handfuls of Whelpling's Dreaming Crests!", ["objectivesText"] = "Acquire 15 Whelpling's Dreaming Crests by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Vaskarn . Progress: I foresee great results with these Dreaming Crests.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 210180, 210917 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211328, ["x"] = 0.498, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211328, ["x"] = 0.498, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78319] = { ["id"] = 78319, ["name"] = "The Superbloom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78319 }, ["description"] = "Amirdrassil is growing and needs nourishment. Dear old Sprucecrown has a ritual to bloom life around the tree, but our enemies have taken note. We need all the help we can get. During the ritual, Sprucecrown will draw on the magic of the Dream to grow Dreamfruit. Consuming these will grant you amazing powers. Only a few of these powerful and delicious fruits can appear. Keep an eye out for them! Pray lend a hand, hero, and the dream will reward you aplenty.", ["objectivesText"] = "Participate in the Superbloom and consume the Dreamfruit that appear. Progress: Even the tallest of us needs a little help around the roots, now and then.", ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 211389, 211411, 211413, 211414 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208474, ["x"] = 0.491333, ["y"] = 0.636667 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208474, ["x"] = 0.491333, ["y"] = 0.636667 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.491333, ["y"] = 0.636667 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78381] = { ["id"] = 78381, ["name"] = "Dreams Unified", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78381 }, ["description"] = "Another incredible find, <name>! This half of a Spark of Dreams could prove useful in your crafting endeavors if you could unite it with a sister piece. Set out in search of another Splintered Spark of Dreams and combine them.", ["objectivesText"] = "Find another Splintered Spark of Dreams . Progress: Have you located another Splintered Spark of Dreams ?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 206271, 208396, 210872 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5510, ["name"] = "Spark of Dreams", ["orderIndex"] = 0, ["flags"] = 0 } } },
[78386] = { ["id"] = 78386, ["name"] = "Emerald Reawakening", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78386 }, ["description"] = "< Melsysra drops a slightly damp note into your hand.> <name>, we found a way to bring creatures into the dream. Speak to me if you'd like to know more! - Elianna", ["objectivesText"] = "Talk to Elianna in the Central Encampment.", ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211962, ["x"] = 0.496, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211209, ["x"] = 0.502, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78427] = { ["id"] = 78427, ["name"] = "Great Crates!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78427 }, ["description"] = "The assault on the Dream grows ever stronger. We are in desperate need of trade goods and supplies to support the defense effort. Even just one crate could make the difference on the front line. Vashonir can assist you with packing the shipments. Then bring the shipment to me. Elune watch over you, defender of the Dream.", ["objectivesText"] = "Pack 1 Shipment of Goods with Vashonir in the Central Encampment. Progress: Vashonir will assist in preparing the shipments for you.", ["rewardItems"] = { 188658, 189143, 190311, 190312, 190313, 190314, 190316, 190321, 190327, 190329, 190394, 190395, 190396, 191460, 191461, 191462, 191464, 191465, 191466, 191467, 191468, 191469, 191470, 191471, 191472, 192852, 192853, 192855, 192856, 192857, 192858, 192859, 192860, 192861, 192862, 192863, 192865, 192866, 192867, 192868, 192869, 192870, 192871, 193050, 193208, 193210, 193211, 193213, 193214, 193215, 193216, 193217, 193218, 193222, 193223, 193224, 193251, 193255, 193258, 193259, 193922, 194123, 194124, 194730, 194966, 194967, 194968, 194969, 194970, 197742, 197745, 197746, 197747, 197748, 197756, 197757, 208067, 210041, 210050 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211240, ["x"] = 0.525333, ["y"] = 0.624667 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211240, ["x"] = 0.525333, ["y"] = 0.624667 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.624667 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78428] = { ["id"] = 78428, ["name"] = "Crate of the Art", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78428 }, ["description"] = "Our stockpiles have taken a grave hit, $p. We need to replenish our reserves as soon as possible, lest the enemy gain the upper hand. We will need far more supplies than we previously envisioned. Once again, Vashonir can assist you with packing the shipments. Please return to me with five crates of goods. Elune, watch over you.", ["objectivesText"] = "Pack 5 Shipments of Goods with Vashonir in the Central Encampment. Progress: Be sure to ask Vashonir to help you prepare the shipments!", ["rewardItems"] = { 188658, 190313, 190316, 190321, 190327, 190329, 190396, 191461, 191465, 191468, 191471, 192853, 192857, 192860, 192863, 192867, 192869, 193050, 193210, 193214, 193217, 193223, 193251, 193255, 193258, 193259, 193922, 194123, 194124, 194730, 194966, 194967, 194968, 194969, 194970, 197742, 197745, 197746, 197747, 197748, 197756, 197757, 208047, 210041 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211240, ["x"] = 0.525333, ["y"] = 0.624667 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211240, ["x"] = 0.525333, ["y"] = 0.624667 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.624667 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78430] = { ["id"] = 78430, ["name"] = "Mean Green Infusion Machine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78430 }, ["description"] = "Pleased to meet you. I am Elianna , a Dream Researcher. A strange phenomenon has recently been detected in the Dream. Fragments of dream magic are being left behind by the creatures here. I'm curious to know the effects of such magic in concentrated doses. But I need someone to extract it for me. There are some problematic lashers and podlings to the south of here. Several of them should be enough for a lesser infusion.", ["objectivesText"] = "Kill 6 podlings and lashers in the Emerald Dream . Progress: Have you brought me enough Dream energy?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 205160 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211209, ["x"] = 0.502, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211209, ["x"] = 0.502, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78431] = { ["id"] = 78431, ["name"] = "Green Dream Team", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78431 }, ["description"] = "Most interesting! I was able to concentrate the Dream energy you brought me. With this, we can perform the infusion! Go ahead, I'll watch.", ["objectivesText"] = "Perform a Lesser Dream Infusion . Progress: Go on! I want to see you infuse Rithro.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 205160, 210776 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211209, ["x"] = 0.502, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211209, ["x"] = 0.502, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78444] = { ["id"] = 78444, ["name"] = "A Worthy Ally: Dream Wardens", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78444 }, ["description"] = "So much change to that which should be unchanging... Rarely has the Dream seen such turmoil. It is meant to be a place of peace. Of life. Champion, we need all the help we can get. I bid you go forth and bring aid to the expanse of the Dream. I have no doubt the Dream will share its plenty with you in return.", ["objectivesText"] = "Aid the Dream Wardens and their allies throughout the Emerald Dream . Progress: Do take some time to stop and smell all that blooms throughout the Dream. It will enrich your life.", ["rewardItems"] = { 208396, 210225, 210421, 210872, 211416 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208143, ["x"] = 0.502, ["y"] = 0.616 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208143, ["x"] = 0.502, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.616 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[78446] = { ["id"] = 78446, ["name"] = "Aiding the Accord: Superbloom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "As life blooms within the Emerald Dream, the budding World Tree Amirdrassil blooms with it. The Ancient Sprucecrown's ritual empowers mighty life energies all around the tree, encouraging its growth. The more hands there to help protect and nourish Amirdrassil, the better its bloom will be! Please lend your aid to Sprucecrown on his journey.", ["objectivesText"] = "Travel to the Emerald Dream and assist Sprucecrown in creating a Superbloom. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: I do hope you don't suffer from allergies.", ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 206353, 208181, 210412, 211389, 211411, 211413, 211414 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 13, ["flags"] = 1 } } },
[78447] = { ["id"] = 78447, ["name"] = "Aiding the Accord: Emerald Bounty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "The Emerald Dream suffers at the forces of the Incarnate Fyrakk. In its turmoil, some of its seeds have trouble taking root. In exploring the Dream, I am certain you shall collect some special seeds. Plant them in soil and nourish them into a bloom, and I hear they will share bountiful gifts with you. Go forth and help life blossom in the Emerald Dream!", ["objectivesText"] = "Travel to the Emerald Dream and plant 3 Dreamseeds of any quality in Emerald Bounty soil. Dreamseeds can be acquired from most activities in the Dream. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: I wonder what gifts a flower can bestow?", ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 208181 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 14, ["flags"] = 1 } } },
[78596] = { ["id"] = 78596, ["name"] = "Summons to Lord Greymane", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Greetings, Lord Greymane has requested your presence at Stormwind Harbor to assist him with a matter regarding Gilneas. That is all I am able to say. Good luck, <name>.", ["objectivesText"] = "Meet with Genn Greymane at Stormwind Harbor.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211788, 211873 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 212899, ["x"] = 0.6248, ["y"] = 0.7212 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 214538, ["x"] = 0.339, ["y"] = 0.155667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.6248, ["y"] = 0.7212 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 0, ["flags"] = 0 } } },
[78597] = { ["id"] = 78597, ["name"] = "Clandestine Movements", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 85, ["storyline"] = { 78178, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78597, 79137 }, ["description"] = "<name>, Lilian Voss and Calia Menethil have requested your presence for a clandestine operation involving Gilneas. They will brief you in full when you arrive.", ["objectivesText"] = "Meet with Lilian and Calia in Pyrewood Village in Silverpine Forest. Progress: Excellent, we've been waiting for you.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211788, 211873 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 212916, ["x"] = 0.523333, ["y"] = 0.886 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210964, ["x"] = 0.426, ["y"] = 0.727 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.523333, ["y"] = 0.886 }, ["mapCandidates"] = { ["npc"] = { 21, 85 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 11, ["flags"] = 0 } } },
[78643] = { ["id"] = 78643, ["name"] = "Fair Skies and Strong Winds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2112, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923, 76276, 76280, 76281, 76282, 76283, 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326, 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 76342, 76343, 76344, 76345, 76347, 76348, 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76402, 76403, 76416, 76433, 76434, 76435, 76436, 76437, 76441, 76442, 76443, 76532, 77178, 77200, 77201, 77283, 77329, 77436, 77780, 77781, 77818, 78643, 78646, 78865, 92875 }, ["series"] = { 78865, 92875 }, ["description"] = "It has been a long road for us all, $p. But after persevering through hardship and strife, dragonkind stands poised to enter a new age. Before you leave for your next adventure, my fellow Aspects and I wish to thank you for all you have done for us.", ["objectivesText"] = "Speak with Alexstrasza at the Seat of the Aspects in Valdrakken . Progress: The Dragon Isles stand in your debt.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 212981, 213003, 213004, 213005, 213006, 213007, 213008, 213009, 213010, 213011, 213012, 213013, 213160 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 }, { ["mapID"] = 2239, ["npcID"] = 216309, ["x"] = 0.51, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112, 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 68, ["flags"] = 0 } } },
[78646] = { ["id"] = 78646, ["name"] = "Fire Watch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "My mother seems unable to fully attune with the Eye. Perhaps it senses her ties to Ardenweald... Her shield is but a fraction of the Eye's power. If she was fully attuned, she could completely quench our foes' flames. But we cannot idly wait. We still need more information about Galok and his plan of attack. Bodwin indicates there is new flurry of activity in Igira's base of operations. With Bodwin's help, we can investigate without being seen.", ["objectivesText"] = "Regroup with Merithra at the edge of Eye of Ysera, overlooking Slagfell Hold.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 37, ["flags"] = 0 } } },
[78762] = { ["id"] = 78762, ["name"] = "Your First Find", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "We've got a find on our hands! Looks like this might be one of my books from undergrad. Hah! Now, your job is to get all that dirt off of it, but you have to be careful. The artifacts we handle are very fragile, and the only thing worse than them staying in the ground is them breaking on the way out. Empowering your elemental will only get you halfway. You'll need to use your environment to keep things in balance so that it's safe to excavate.", ["objectivesText"] = "Practice excavating on the Outdated Geology Textbook . Progress: What do you think? Having fun yet?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210956 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 2, ["flags"] = 0 } } },
[78821] = { ["id"] = 78821, ["name"] = "Blooming Dreamseeds", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78821 }, ["description"] = "The Emerald Dream is about the harmony and balance of nature. For Amirdrassil to bloom, we need a rich variety of plants growing alongside the world tree. Plant seeds wherever you find fertile soil.", ["objectivesText"] = "Plant dreamseeds in the Emerald Dream . Progress: How's the planting going?", ["rewardItems"] = { 211376, 211394 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 212797, ["x"] = 0.498, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 212797, ["x"] = 0.498, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[78861] = { ["id"] = 78861, ["name"] = "Aiding the Accord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 15, ["flags"] = 1 } } },
[78863] = { ["id"] = 78863, ["name"] = "A Place Beneath the Boughs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 78863 }, ["description"] = "Thanks to you and all the mortals who defended the Emerald Dream, a new World Tree now grows in the Dragon Isles. Amirdrassil 's boughs will be a haven of peace and tranquility, and a place of respite for the kaldorei souls lost at Teldrassil. Tyrande Whisperwind and Shandris Feathermoon are at the tree now. They would share words with you.", ["objectivesText"] = "Meet Tyrande and Shandris in Amirdrassil .", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 212981, 213003, 213004, 213005, 213006, 213007, 213008, 213009, 213010, 213011, 213012, 213013, 213160 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 216067, ["x"] = 0.512667, ["y"] = 0.606667 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112, 2239 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[78864] = { ["id"] = 78864, ["name"] = "The Returning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 78864 }, ["description"] = "It is a time of reflection and change, $p. For the world, and for my people. My mother and I have been discussing the roads that led us here... and where those roads will lead in the years to come. Come, let us speak.", ["objectivesText"] = "Speak with Shandris Feathermoon .", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 211279, 212981, 213003, 213004, 213005, 213006, 213007, 213008, 213009, 213010, 213011, 213012, 213013, 213160, 251022 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 216067, ["x"] = 0.512667, ["y"] = 0.606667 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 216067, ["x"] = 0.512667, ["y"] = 0.606667 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.512667, ["y"] = 0.606667 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard" },
[78865] = { ["id"] = 78865, ["name"] = "Siblings Until the End", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923, 76276, 76280, 76281, 76282, 76283, 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326, 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 76342, 76343, 76344, 76345, 76347, 76348, 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76402, 76403, 76416, 76433, 76434, 76435, 76436, 76437, 76441, 76442, 76443, 76532, 77178, 77200, 77201, 77283, 77329, 77436, 77780, 77781, 77818, 78643, 78646, 78865, 92875 }, ["series"] = { 78643, 92875 }, ["description"] = "Some time ago, Vyranoth received an unexpected summons... from Iridikron. You will want to hear what he had to say.", ["objectivesText"] = "Speak with Vyranoth to hear about her meeting with Iridikron. Progress: Iridikron had much to say...", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 212981, 213003, 213004, 213005, 213006, 213007, 213008, 213009, 213010, 213011, 213012, 213013, 213160 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 214051, ["x"] = 0.5576, ["y"] = 0.3684 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 214051, ["x"] = 0.5576, ["y"] = 0.3684 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5576, ["y"] = 0.3684 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 69, ["flags"] = 0 } } },
[78875] = { ["id"] = 78875, ["name"] = "The Unkillable", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "I'm bettin' dat ogre Mai'Zoth is behind all dis. He should have died long ago, but his magics still be strong. He be using the altar's centerpiece as a conduit to drain Lukou's power. Recover the centerpiece and prove he's not so unkillable when he doesn't have a loa hostage.", ["objectivesText"] = "Recover the altar centerpiece from Mai'Zoth. Progress: Did you prove Mai'Zoth isn't unkillable?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 210593 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 210091, ["x"] = 0.663333, ["y"] = 0.459 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 210091, ["x"] = 0.663333, ["y"] = 0.459 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.663333, ["y"] = 0.459 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 8, ["flags"] = 0 } } },
[79009] = { ["id"] = 79009, ["name"] = "The Harbinger", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "We are in need of your aid once more, champion. A mysterious figure moves within the shadows. The Harbinger... Let us speak in the Chamber of the Guardian. I've asked Alleria to meet us there as well.", ["objectivesText"] = "Meet Khadgar and Alleria in the Chamber of the Guardian in Dalaran. Progress: A Radiant Song, a Dark Heart, and this mysterious Harbinger... What could it all mean?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 211279, 223988, 225547 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 0, ["flags"] = 0 } } },
[79010] = { ["id"] = 79010, ["name"] = "Door to the Ren'dorei", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 7502, ["mapID"] = 971, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "If this investigation involves the Void, it would be wise to consult the void elves. We must head to Telogrus Rift and report the situation. I'll speak with Umbric. He'll be able to mobilize the Riftwalkers to our cause.", ["objectivesText"] = "Follow Alleria to Telogrus Rift.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 140192 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 2, ["flags"] = 0 } } },
[79011] = { ["id"] = 79011, ["name"] = "Riftwalker Reports", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 9415, ["mapID"] = 971, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "The Riftwalkers are tasked with investigating all void activity that appears on Azeroth. A most vital duty, given how dangerous this dark force can be. And I speak from experience. Many of them were sent out on assignment to investigate recent fluctuations. I've been told they just arrived back, but have yet to hear their reports. Would you check in on them while I speak with Alleria?", ["objectivesText"] = "Gather reports from Riftwalkers in Telogrus Rift. Progress: Let me know when you have those Riftwalker reports.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9415 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 3, ["flags"] = 0 } } },
[79012] = { ["id"] = 79012, ["name"] = "Cracks in the Void", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 9415, ["mapID"] = 971, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "Telogrus Rift has always been extremely sensitive to cosmic shifts. It makes for a rather precarious homestead, but the void elves have... few options available to us. The recent influx in void energies has resulted in unstable rifts opening sporadically. And with so many investigating Azeroth, I'm having trouble finding Riftwalkers to deal with them. Could you close any unstable void rifts you find along your path?", ["objectivesText"] = "Close 5 Unstable Void Rifts in Telogrus Rift. Progress: Normally the Riftwalkers would be the ones to mend these sort of anomalies. But I wouldn't want to distract from their current investigations.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9415 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 4, ["flags"] = 0 } } },
[79013] = { ["id"] = 79013, ["name"] = "Galakrond's Unrest", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 9415, ["mapID"] = 115, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "Galakrond's Rest. Where the Dark Heart was first empowered by Iridikron. We don't know what power the relic holds, but we do know that the Harbinger now wields it. And now one of our Riftwalkers is missing, right where it all began. I don't believe this is a coincidence, <name>. Let's travel to Northrend and search the area.", ["objectivesText"] = "Meet Alleria at Galakrond's Rest in Dragonblight.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 214634, ["x"] = 0.566, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 9415 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 5, ["flags"] = 0 } } },
[79014] = { ["id"] = 79014, ["name"] = "Walk a Mile in Her Shadows", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "I don't often work with the Riftwalkers. I prefer to handle missions alone. Still, I will not abandon one of them. I cannot yet sense the Riftwalker's presence. Our best path forward is to retrace her steps. Which means following the shadows.", ["objectivesText"] = "Uncover the void presence at Galakrond's Rest in Dragonblight.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 187898 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 214634, ["x"] = 0.566, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 120, ["npcID"] = 214759, ["x"] = 0.415, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 115, 120 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 120, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 6, ["flags"] = 0 } } },
[79015] = { ["id"] = 79015, ["name"] = "Dark Descension", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 67, ["mapID"] = 120, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "What are these void spawn doing here? Could it be the Harbinger's doing? Some power of the Dark Heart? Well. I do not mean to stand idly by. We must confront the Riftwalker. I don't think she will see reason now, but perhaps she can tell us something.", ["objectivesText"] = "Confront the missing Riftwalker. Progress: What would the Harbinger want with Ulduar?", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 120, ["npcID"] = 214759, ["x"] = 0.415, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 120, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 120 }, ["zone"] = { 67 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 120, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 7, ["flags"] = 0 } } },
[79016] = { ["id"] = 79016, ["name"] = "Legacy of the Void", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 67, ["mapID"] = 882, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "Make no mistake, <name>. I know this is a trap. But if there's any chance this leads us to the Harbinger, we must take that risk. Be at the ready. We venture forth.", ["objectivesText"] = "Travel to the Triad's Conservatory in Eredath.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 214645, ["x"] = 0.225, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 67 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 8, ["flags"] = 0 } } },
[79017] = { ["id"] = 79017, ["name"] = "The Path Taken", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "These apparitions before us. I believe they're... memories. My memories. Is this the Harbinger's doing? Or mine? We need to explore. Discover why we were led here.", ["objectivesText"] = "Witness Alleria's memories in Eredath. Progress: Suddenly, this all feels rather personal. The Harbinger must have a grievance against me. Or at least an... interest. Hm.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 214645, ["x"] = 0.225, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 9, ["flags"] = 0 } } },
[79018] = { ["id"] = 79018, ["name"] = "And Be One Traveler, Long I Stood", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 8701, ["mapID"] = 971, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "I sense another memory ahead. While I'm loath to play along with the Harbinger's game, it's the only path forward for us. Still, we have faced just as many dangerous memories as peaceful ones. Prepare yourself.", ["objectivesText"] = "Investigate the final memory at the Triad's Conservatory in Eredath.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 10, ["flags"] = 0 } } },
[79019] = { ["id"] = 79019, ["name"] = "Defend Telogrus Rift", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 9415, ["mapID"] = 971, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "No. Not the ren'dorei. Not Telogrus Rift. Not today. <Alleria tightens her grip on her bow.> These ethereal forces are the same we encountered in Ulduar. The Harbinger must command them. I'll go ahead. Engage the enemies here.", ["objectivesText"] = "Defend Telogrus Rift. Progress: My people can defend themselves, but even they will struggle against such an overwhelming force. We must aid them.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 128827 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9415 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 11, ["flags"] = 0 } } },
[79020] = { ["id"] = 79020, ["name"] = "Null and Void", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 9415, ["mapID"] = 971, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "We must defeat that loathsome apparition of Turalyon. The abomination's presence is intolerable. If left unchecked, it may destroy what remains of Telogrus Rift. I will end it with my own hands.", ["objectivesText"] = "Defeat the Corrupted Memory of Turalyon in Telogrus Rift.", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 213269, 213561, 217711, 217712, 217713, 217714 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9415 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 12, ["flags"] = 0 } } },
[79021] = { ["id"] = 79021, ["name"] = "Radiant Warnings", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 9415, ["mapID"] = 629, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "So she goes by Harbinger now, does she? How fitting. I no longer feel her presence, but make no mistake. Xal'atath's nefarious games continue. And Alleria is now a pawn upon her board. As are you, champion of fate.", ["objectivesText"] = "Deliver Locus-Walker 's warning to Khadgar in Dalaran. Progress: Telogrus Rift should no longer tempt Xal'atath. For now.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 213561 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9415 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 13, ["flags"] = 0 } } },
[79137] = { ["id"] = 79137, ["name"] = "The Wall Between Us", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78178, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78597, 79137 }, ["description"] = "I know this fight was not ours, <name>. But I thank you for your assistance. It was with the Alliance's assistance that Lordaeron was cleansed and the favor has now been returned. I do not think I can hope for peace. Instead, I will hope that these efforts have led to at least an understanding of the plights of both Gilneans and the Forsaken. Let us meet with Lilian in Pyrewood Village. This celebration is not for us.", ["objectivesText"] = "Speak with Lilian and Calia in Pyrewood Village.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211788, 211873 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210965, ["x"] = 0.428, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210964, ["x"] = 0.426, ["y"] = 0.727 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 12, ["flags"] = 0 } } },
[79223] = { ["id"] = 79223, ["name"] = "Finally, An Archivist!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "So you've got your bearings now? You've felt the dirt? You've smelled the history? Why not celebrate this glorious moment of above average success with... a cap! That's right! Take this token to our beloved provisioner, Aristta. She'll be happy to provide you with one of our all-purpose caps to signify your elevation to Archivist from naive passerby.", ["objectivesText"] = "Purchase an Archivist's Buckled Cap from Provisioner Aristta. Progress: The cap suits you quite well!", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 212371 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 20, ["flags"] = 0 } } },
[80385] = { ["id"] = 80385, ["name"] = "Last Hurrah: Dragon Isles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "You've become quite popular with our allies, <name>! To the south the Iskaara Tuskarr need your help with their community feast. To the west the Maruuks have requested your aid with their hunts. To the north the Obsidian Outcasts request your help reclaiming Dragonbane Keep. Sounds like you have a full day ahead of you! Best of luck.", ["objectivesText"] = "Assist the Tuskarr with their community feast, the Maruuk with their Hunt, and help reclaim Dragonbane Keep. Progress: We're lucky to have you on our side, <name>.", ["rewardItems"] = { 217109 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3342 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 16, ["flags"] = 1 } } },
[80386] = { ["id"] = 80386, ["name"] = "Last Hurrah: Zaralek Caverns and Time Rifts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies are once again requesting your aid, <name>. In the Zaralek caverns the Dragonscale Expedition needs you to protect their researchers. We're also concerned with the Zaqali invasions in the Ohn'ahran Plains and Azure Span. Meanwhile, the Bronze Dragonflight has asked for you to help them deal with temporal anomalies to the east of Valdrakken . Hurry <name>, time is of the essence.", ["objectivesText"] = "Protect the Researchers under Fire, loot a Secured Shipment from a Suffusion Camp, and assist Soridormi in dispelling a Time Rift. Progress: Do you bring news of your success?", ["rewardItems"] = { 213089, 217110 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3342 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 17, ["flags"] = 1 } } },
[80388] = { ["id"] = 80388, ["name"] = "Last Hurrah: Emerald Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "The druids call for aid! Energy from the Emerald Dream is spreading across the Dragon Isles, please help them investigate it. They also ask you travel to the Emerald Dream and assist Sprucecrown in creating a Superbloom. Some of the druids also wish for you to plant Dreamseeds in the Emerald Dream. Please help them, <name>.", ["objectivesText"] = "Gather one hundred Dreamsurge Coalescence across the Dragon isles, assist Sprucecrown in creating a Superbloom, and plant 3 Dreamseeds of any quality in the Emerald Dream. Dreamseeds can be acquired from most activities in the Emerald Dream. Progress: How are the druids doing?", ["rewardItems"] = { 207026, 217111 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3342 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 18, ["flags"] = 1 } } },
[80389] = { ["id"] = 80389, ["name"] = "Last Hurrah", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["rewardItems"] = { 217109, 217110, 217111 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 19, ["flags"] = 1 } } },
[81654] = { ["id"] = 81654, ["name"] = "The Harbinger", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "We are in need of your aid once more, champion. A mysterious figure moves within the shadows. The Harbinger... Let us speak in the Chamber of the Guardian. I've asked Alleria to meet us there as well.", ["objectivesText"] = "Meet Khadgar and Alleria in the Chamber of the Guardian in Dalaran. Progress: A Radiant Song, a Dark Heart, and this mysterious Harbinger... What could it all mean?", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211279, 223988, 225547 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 221491, ["x"] = 0.846, ["y"] = 0.254667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.254667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 14, ["flags"] = 0 } } },
})
